function bot(h,c){if(h<11)h=11;const col=C[c];const p='M 5.5 6 C 5.5 6, 0 7, 0 11 L 0 '+(h-2)+' Q 0 '+h+', 2 '+h+' L 12 '+h+' Q 14 '+h+', 14 '+(h-2)+' L 14 11 C 14 7, 8.5 6, 8.5 6 Z';return '<svg width="14" height="'+h+'" aria-hidden="true" style="overflow:visible;display:block;"><rect x="4" y="0" width="6" height="2.5" rx="0.5" fill="'+col+'"/><rect x="5.5" y="2.5" width="3" height="3.5" fill="'+col+'"/><path d="'+p+'" fill="'+col+'"/><rect x="2" y="'+(h-h*0.35)+'" width="10" height="2.5" fill="rgba(255,255,255,0.28)"/></svg>';}

function renderGrid(target,data,tiers){
const m=VK[tabState[target]];
const period=target==='backbar'?tabState.backbarPeriod:tabState.shelfPeriod;
document.getElementById(target+'-grid').innerHTML=tiers.map(function(t){
return '<div class="bb-row"><div class="tier-lbl">'+t.n+'</div>'+CAT.map(function(cat){
const adj=PERIOD_ADJ[cat][period][m];
return '<div class="cell">'+data[t.k][cat].map(function(cl){
return '<div class="cluster"><div class="bottles">'+cl.b.map(function(b){return bot(Math.round(b[m]*adj),b.c);}).join('')+'</div><div class="clust-lbl">'+cl.l+'</div></div>';
}).join('')+'</div>';
}).join('')+'</div>';
}).join('');
}

function renderBackbar(){renderGrid('backbar',BACKBAR_DATA,BACKBAR_T);renderTable('backbar');}
function renderShelf(){renderGrid('shelf',SHELF_DATA,SHELF_T);renderTable('shelf');}

function renderTable(target){
const data=target==='backbar'?BACKBAR_DATA:SHELF_DATA;
const tiers=target==='backbar'?BACKBAR_T:SHELF_T;
const tierHead=target==='backbar'?'Tier':'Shelf position';
const period=target==='backbar'?tabState.backbarPeriod:tabState.shelfPeriod;
let rows='';
tiers.forEach(function(t){
CAT.forEach(function(cat){
const clusters=data[t.k][cat];
const adj=PERIOD_ADJ[cat][period];
clusters.forEach(function(cl){
const bs=cl.b;
const n=bs.length;
const avg=function(f){return (bs.reduce(function(a,b){return a+b[f]*adj[f];},0)/n).toFixed(1);};
const dots=bs.map(function(b){return '<span class="growth-dot" style="background:'+C[b.c]+';" title="'+b.c+'"></span>';}).join('');
const catName=cat.charAt(0).toUpperCase()+cat.slice(1);
rows+='<tr><td class="tier">'+t.n+'</td><td>'+catName+'</td><td class="clust">'+cl.l+'</td><td class="num">'+n+'</td><td class="num">'+avg('s')+'</td><td class="num">'+avg('v')+'</td><td class="num">'+avg('p')+'</td><td class="num">'+avg('k')+'</td><td><span class="growth-dots">'+dots+'</span></td></tr>';
});
});
});
document.getElementById(target+'-table').innerHTML='<table><thead><tr><th>'+tierHead+'</th><th>Category</th><th>Cluster</th><th class="num">Bottles</th><th class="num">Share</th><th class="num">Vel</th><th class="num">Prem</th><th class="num">Comp</th><th>R12 growth</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

// ===== TABLE RENDERERS FOR FLIPPED VIEWS =====

function renderWaterfallTable(){
const period=document.getElementById('wf-period').value;
const labels=PERIOD_LABELS[period];
const cats=[{k:'w',n:'Whiskey'},{k:'v',n:'Vodka'},{k:'t',n:'Tequila'},{k:'r',n:'Rum'},{k:'all',n:'All spirits'}];
let rows='';
cats.forEach(function(c){
const d=WATERFALL_DATA[period][c.k];
const ending=d.prior+d.pod+d.velocity+d.priceMix;
const netChange=ending-d.prior;
const netPct=(netChange/d.prior)*100;
const dc=netChange>=0?'pos':'neg';
const pc=d.pod>=0?'pos':'neg';
const vc=d.velocity>=0?'pos':'neg';
const mc=d.priceMix>=0?'pos':'neg';
rows+='<tr><td class="clust">'+c.n+'</td><td class="num">'+fmtMoney(d.prior)+'</td><td class="num '+pc+'">'+fmtContrib(d.pod)+'</td><td class="num '+vc+'">'+fmtContrib(d.velocity)+'</td><td class="num '+mc+'">'+fmtContrib(d.priceMix)+'</td><td class="num">'+fmtMoney(ending)+'</td><td class="num '+dc+'">'+fmtContrib(netChange)+'</td><td class="num '+dc+'">'+(netChange>=0?'+':'')+netPct.toFixed(1)+'%</td></tr>';
});
document.getElementById('wf-table').innerHTML='<table><thead><tr><th>Category</th><th class="num">'+labels.prior+'</th><th class="num">POD</th><th class="num">Velocity</th><th class="num">Price/Mix</th><th class="num">'+labels.current+'</th><th class="num">Net Δ</th><th class="num">%Δ</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

function renderLeadLagTable(){
const period=document.getElementById('ll-period').value;
const fmt=function(s){return (s>=0?'+':'')+s;};
const cls=function(s){return s>0?'pos':(s<0?'neg':'');};
let rows='';
Object.keys(DIV_LL).forEach(function(div){
const d=DIV_LL[div];
const w=d.scores.w[period],v=d.scores.v[period],t=d.scores.t[period],r=d.scores.r[period];
rows+='<tr><td class="clust">'+d.abbr+'</td><td>'+d.name+'</td><td class="tier">'+REGION_LL[d.region].name+'</td><td class="num '+cls(w)+'">'+fmt(w)+'</td><td class="num '+cls(v)+'">'+fmt(v)+'</td><td class="num '+cls(t)+'">'+fmt(t)+'</td><td class="num '+cls(r)+'">'+fmt(r)+'</td></tr>';
});
document.getElementById('ll-table').innerHTML='<table><thead><tr><th>Code</th><th>Division</th><th>Region</th><th class="num">Whiskey</th><th class="num">Vodka</th><th class="num">Tequila</th><th class="num">Rum</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

function renderQualityTable(){
const cats=[{k:'whiskey',n:'Whiskey'},{k:'vodka',n:'Vodka'},{k:'tequila',n:'Tequila'},{k:'rum',n:'Rum'},{k:'all',n:'All spirits'}];
const fmt=function(v){return (v>=0?'+':'')+v.toFixed(1)+'%';};
const fmtDelta=function(v){return (v>=0?'+':'')+v.toFixed(1);};
const cls=function(v){return v>0?'pos':(v<0?'neg':'');};
let rows='';
cats.forEach(function(c){
const d=QUALITY_DATA[c.k];
rows+='<tr><td class="clust">'+c.n+'</td><td class="num '+cls(d.r12)+'">'+fmt(d.r12)+'</td><td class="num '+cls(d.delta_r12)+'">'+fmtDelta(d.delta_r12)+'</td><td class="num '+cls(d.ytd)+'">'+fmt(d.ytd)+'</td><td class="num '+cls(d.delta_ytd)+'">'+fmtDelta(d.delta_ytd)+'</td><td class="num '+cls(d.cm)+'">'+fmt(d.cm)+'</td><td class="num '+cls(d.delta_cm)+'">'+fmtDelta(d.delta_cm)+'</td></tr>';
});
document.getElementById('q-table').innerHTML='<table><thead><tr><th>Category</th><th class="num">R12</th><th class="num">Δ R12</th><th class="num">YTD</th><th class="num">Δ YTD</th><th class="num">CM</th><th class="num">Δ CM</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

function renderAccelBarsTable(){
const f1v=document.getElementById('f1').value;
const f2v=document.getElementById('f2').value;
const f1Label=document.querySelector('#f1 option[value="'+f1v+'"]').text;
const f2Label=document.querySelector('#f2 option[value="'+f2v+'"]').text;
const a1=ACCEL[f1v],a2=ACCEL[f2v];
let rows='';
CAT_LABELS.forEach(function(cat,i){
const v1=a1[i],v2=a2[i];
const c1cls=v1>=0?'pos':'neg';
const c2cls=v2>=0?'pos':'neg';
const sameDir=(v1>=0)===(v2>=0);
const accel=Math.abs(v2)>Math.abs(v1);
let signal;
if(!sameDir)signal='⚡ inflection';
else if(v1>=0)signal=accel?'↑ accelerating':'→ steady';
else signal=accel?'↓ deepening':'→ steady';
rows+='<tr><td class="clust">'+cat+'</td><td class="num '+c1cls+'">'+(v1>=0?'+':'')+v1+'%</td><td class="num '+c2cls+'">'+(v2>=0?'+':'')+v2+'%</td><td class="tier">'+signal+'</td></tr>';
});
document.getElementById('accel-bars-table').innerHTML='<table><thead><tr><th>Category</th><th class="num">'+f1Label+'</th><th class="num">'+f2Label+'</th><th>Signal</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

function renderAccelLinesTable(){
const f3v=document.getElementById('f3').value;
const f4v=document.getElementById('f4').value;
const d3=LD[f3v],d4=LD[f4v];
const f3Label=document.querySelector('#f3 option[value="'+f3v+'"]').text;
const f4Label=document.querySelector('#f4 option[value="'+f4v+'"]').text;
const keys=['whiskey','vodka','tequila','rum'];
let rows='';
CAT_LABELS.forEach(function(cat,i){
const a3=d3[keys[i]],a4=d4[keys[i]];
const cur3=a3[a3.length-1],old3=a3[0],delta3=cur3-old3;
const cur4=a4[a4.length-1],old4=a4[0],delta4=cur4-old4;
rows+='<tr><td class="clust">'+cat+'</td><td class="num">'+cur3.toFixed(1)+'%</td><td class="num '+(delta3>=0?'pos':'neg')+'">'+(delta3>=0?'+':'')+delta3.toFixed(1)+'%</td><td class="num">'+cur4.toFixed(1)+'%</td><td class="num '+(delta4>=0?'pos':'neg')+'">'+(delta4>=0?'+':'')+delta4.toFixed(1)+'%</td></tr>';
});
document.getElementById('accel-lines-table').innerHTML='<table><thead><tr><th>Category</th><th class="num">'+f3Label+'<br><span style="font-weight:400;text-transform:none;color:#6b7280;">latest</span></th><th class="num">Δ vs start</th><th class="num">'+f4Label+'<br><span style="font-weight:400;text-transform:none;color:#6b7280;">latest</span></th><th class="num">Δ vs start</th></tr></thead><tbody>'+rows+'</tbody></table>';
}

function renderTrajectoriesTable(){
const metrics=[{key:'velocity',name:'Velocity'},{key:'activation',name:'Activation'},{key:'premiumidx',name:'Premium idx'},{key:'pricemix',name:'Price/Mix'},{key:'podeff',name:'POD eff'}];
let rows='';
['whiskey','vodka','tequila','rum'].forEach(function(catKey,i){
let row='<tr><td class="clust">'+CAT_LABELS[i]+'</td>';
metrics.forEach(function(m){
const M=METRIC_BARS[m.key];
const v=M.data[i];
let display='',cls='';
if(M.type==='positive'){display=v.toFixed(M.decimals)+(M.unit||'');}
else if(M.type==='centered'){display=v.toFixed(M.decimals);cls=v>=M.center?'pos':'neg';}
else if(M.type==='signed'){display=(v>=0?'+':'')+v.toFixed(M.decimals)+(M.unit||'');cls=v>=0?'pos':'neg';}
row+='<td class="num '+cls+'">'+display+'</td>';
});
row+='</tr>';
rows+=row;
});
document.getElementById('trajectories-table').innerHTML='<table><thead><tr><th>Category</th>'+metrics.map(function(m){return '<th class="num">'+m.name+'</th>';}).join('')+'</tr></thead><tbody>'+rows+'</tbody></table>';
}

