function premiumPlot(pts,mode){
const w=720,h=400,padL=50,padR=20,padT=20,padB=46;
const xMin=0,xMax=20,yMin=0,yMax=20;
function mx(x){return padL+(x-xMin)/(xMax-xMin)*(w-padL-padR);}
function my(y){return padT+(yMax-y)/(yMax-yMin)*(h-padT-padB);}
let s='<svg viewBox="0 0 '+w+' '+h+'" class="scatter-svg">';
[5,10,15].forEach(function(v){
s+='<line class="grid-line" x1="'+padL+'" y1="'+my(v)+'" x2="'+(w-padR)+'" y2="'+my(v)+'"/>';
s+='<line class="grid-line" x1="'+mx(v)+'" y1="'+padT+'" x2="'+mx(v)+'" y2="'+(h-padB)+'"/>';
});
s+='<line stroke="#6b7280" stroke-width="1.5" stroke-dasharray="5,4" x1="'+mx(0)+'" y1="'+my(0)+'" x2="'+mx(xMax)+'" y2="'+my(yMax)+'"/>';
s+='<text x="'+mx(18.5)+'" y="'+my(17.5)+'" font-size="10" fill="#6b7280" font-style="italic" text-anchor="end">45° tier-neutral</text>';
s+='<line class="axis-line" x1="'+padL+'" y1="'+(h-padB)+'" x2="'+(w-padR)+'" y2="'+(h-padB)+'"/>';
s+='<line class="axis-line" x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(h-padB)+'"/>';
[0,5,10,15,20].forEach(function(v){
s+='<text class="axis-label" x="'+(padL-6)+'" y="'+(my(v)+3)+'" text-anchor="end">'+v+'%</text>';
s+='<text class="axis-label" x="'+mx(v)+'" y="'+(h-padB+14)+'" text-anchor="middle">'+v+'%</text>';
});
s+='<text class="axis-label" x="'+padL+'" y="'+(padT+12)+'" font-weight="500">revenue share</text>';
s+='<text class="axis-label" x="'+(w-padR)+'" y="'+(h-padB+32)+'" text-anchor="end" font-weight="500">9L volume share →</text>';
s+='<text class="quadrant-label" x="'+(padL+12)+'" y="'+(padT+30)+'">premium-skewed (revenue > volume)</text>';
s+='<text class="quadrant-label" x="'+(w-padR-12)+'" y="'+(h-padB-12)+'" text-anchor="end">value-skewed (volume > revenue)</text>';
pts.forEach(function(p){
const x=p.x,y=p.y,x0=p.x0,y0=p.y0;
const diff=y-x;
const color=diff>0.5?TEAL:diff<-0.5?CORAL:NEUTRAL;
if(mode==='traj'){
const dx=mx(x)-mx(x0),dy=my(y)-my(y0);
const len=Math.sqrt(dx*dx+dy*dy);
if(len>2){
const ux=dx/len,uy=dy/len;
const hx=mx(x)-ux*3,hy=my(y)-uy*3;
s+='<line x1="'+mx(x0)+'" y1="'+my(y0)+'" x2="'+hx+'" y2="'+hy+'" stroke="'+color+'" stroke-width="1.5" opacity="0.75"><title>'+p.l+'</title></line>';
s+='<polygon points="'+mx(x)+','+my(y)+' '+(mx(x)-ux*5-uy*2)+','+(my(y)-uy*5+ux*2)+' '+(mx(x)-ux*5+uy*2)+','+(my(y)-uy*5-ux*2)+'" fill="'+color+'"/>';
s+='<text x="'+(mx(x))+'" y="'+(my(y)-9)+'" font-size="9" fill="#5f6368" text-anchor="middle">'+p.l+'</text>';
}else{
s+='<circle cx="'+mx(x)+'" cy="'+my(y)+'" r="5" fill="'+color+'" opacity="0.85" stroke="#fff" stroke-width="1.2"><title>'+p.l+'</title></circle>';
s+='<text x="'+(mx(x))+'" y="'+(my(y)-9)+'" font-size="9" fill="#5f6368" text-anchor="middle">'+p.l+'</text>';
}
}else{
s+='<circle cx="'+mx(x)+'" cy="'+my(y)+'" r="6" fill="'+color+'" opacity="0.9" stroke="#fff" stroke-width="1.5"><title>'+p.l+' · vol '+x.toFixed(1)+'% · rev '+y.toFixed(1)+'%</title></circle>';
s+='<text x="'+(mx(x))+'" y="'+(my(y)-10)+'" font-size="9" fill="#5f6368" text-anchor="middle">'+p.l+'</text>';
}
});
if(mode==='drift'){
const centroids={whiskey:[[6.2,7.4],[6.5,8.1],[6.8,8.9]],vodka:[[8.4,7.2],[8.8,7.6],[9.4,7.9]],tequila:[[4.6,6.8],[5.4,7.6],[6.4,8.6]],rum:[[7.8,7.2],[7.6,7.0],[7.4,6.8]]};
const cat=document.getElementById('pr-cat').value;
const cents=centroids[cat];
for(let i=0;i<cents.length-1;i++){
const x1=mx(cents[i][0]),y1=my(cents[i][1]),x2=mx(cents[i+1][0]),y2=my(cents[i+1][1]);
s+='<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="'+NAVY+'" stroke-width="2.5"/>';
}
cents.forEach(function(c,i){
s+='<circle cx="'+mx(c[0])+'" cy="'+my(c[1])+'" r="6" fill="'+NAVY+'" stroke="#fff" stroke-width="1.5"/>';
s+='<text x="'+(mx(c[0])+10)+'" y="'+(my(c[1])+3)+'" font-size="10" font-weight="500" fill="'+NAVY+'">'+(i===0?'5y ago':i===cents.length-1?'now':(cents.length-1-i)+'y ago')+'</text>';
});
}
s+='</svg>';
return s;
}

