// Render the price-tier ladder (current + 5yr ago + shift badges)
function renderTierLadder(cat){
const data = PREM_TIER_MIX[cat] || PREM_TIER_MIX.all_spirits;
const cur = data.current, prior = data.prior;
function bar(mix){
return '<div class="tier-ladder-bar">' +
'<div class="tier-ladder-seg tier-ladder-seg-value" style="width:' + mix.value + '%;">' + (mix.value >= 8 ? mix.value + '%' : '') + '</div>' +
'<div class="tier-ladder-seg tier-ladder-seg-premium" style="width:' + mix.premium + '%;">' + (mix.premium >= 8 ? mix.premium + '%' : '') + '</div>' +
'<div class="tier-ladder-seg tier-ladder-seg-superpremium" style="width:' + mix.super + '%;">' + (mix.super >= 8 ? mix.super + '%' : '') + '</div>' +
'<div class="tier-ladder-seg tier-ladder-seg-prestige" style="width:' + mix.prestige + '%;">' + (mix.prestige >= 8 ? mix.prestige + '%' : '') + '</div>' +
'</div>';
}
function shift(key, label){
const d = cur[key] - prior[key];
const cls = d > 0.4 ? 'up' : (d < -0.4 ? 'down' : '');
const sign = d > 0 ? '+' : (d < 0 ? '\u2212' : '\u00b1');
return '<span class="tier-ladder-shift-item ' + cls + '">' + label + ' ' + sign + Math.abs(d).toFixed(0) + 'pt</span>';
}
const html = '<div class="tier-ladder">' +
'<div class="tier-ladder-row"><span class="tier-ladder-row-label">Current</span>' + bar(cur) + '</div>' +
'<div class="tier-ladder-row"><span class="tier-ladder-row-label">5yr prior</span>' + bar(prior) + '</div>' +
'<div class="tier-ladder-shift">' + shift('value', 'Value') + shift('premium', 'Premium') + shift('super', 'Super-prem') + shift('prestige', 'Prestige') + '</div>' +
'</div>';
document.getElementById('prem-tier-ladder').innerHTML = html;
// Takeaway
const prestige_shift = cur.prestige - prior.prestige;
const value_shift = cur.value - prior.value;
let takeaway;
if(prestige_shift >= 2 && value_shift <= -2){
takeaway = '<span class="em-pos">Clean trade-up pattern.</span> Prestige and super-premium have grown <strong>+' + (prestige_shift + (cur.super - prior.super)).toFixed(0) + 'pt</strong> in 5 years; value has contracted <strong>' + value_shift.toFixed(0) + 'pt</strong>. Volume isn\'t leaving the category \u2014 it\'s climbing the ladder.';
}else if(value_shift > 1){
takeaway = '<span class="em-neg">Migration down the ladder.</span> Value tier has expanded <strong>+' + value_shift.toFixed(0) + 'pt</strong> while higher tiers contracted. Consumers are trading off, not up.';
}else if(Math.abs(prestige_shift) < 1 && Math.abs(value_shift) < 1){
takeaway = '<span style="color:#6b7280;font-weight:700;">Mix is roughly stable.</span> No significant tier rotation over 5 years. The category isn\'t premiumizing or deflating \u2014 it\'s holding shape.';
}else{
takeaway = 'Modest tier rotation. Prestige <strong>' + (prestige_shift > 0 ? '+' : '') + prestige_shift.toFixed(0) + 'pt</strong>, value <strong>' + (value_shift > 0 ? '+' : '') + value_shift.toFixed(0) + 'pt</strong>.';
}
document.getElementById('prem-tier-takeaway').innerHTML = takeaway;
}

// Render driver decomposition — vol growth vs pod growth at each tier
function renderDriverDecomp(cat){
const d = PREM_DRIVERS[cat] || PREM_DRIVERS.all_spirits;
const tiers = [['Value','value'],['Premium','premium'],['Super-prem','super'],['Prestige','prestige']];
const all = tiers.flatMap(function(t){ return [d[t[1]].vol, d[t[1]].pod]; });
const maxAbs = Math.max.apply(null, all.map(Math.abs).concat([1]));
function bar(val){
const w = Math.min(100, (Math.abs(val) / maxAbs) * 92);
const cls = val < 0 ? 'neg' : (val > 0 ? 'vol' : '');
const sign = val > 0 ? '+' : (val < 0 ? '\u2212' : '');
return '<div class="driver-bar-block"><div class="driver-bar-fill ' + cls + '" style="width:' + w + '%;"></div><span class="driver-bar-num">' + sign + Math.abs(val).toFixed(1) + '%</span></div>';
}
function podBar(val){
const w = Math.min(100, (Math.abs(val) / maxAbs) * 92);
const cls = val < 0 ? 'neg' : (val > 0 ? 'pod' : '');
const sign = val > 0 ? '+' : (val < 0 ? '\u2212' : '');
return '<div class="driver-bar-block"><div class="driver-bar-fill ' + cls + '" style="width:' + w + '%;"></div><span class="driver-bar-num">' + sign + Math.abs(val).toFixed(1) + '%</span></div>';
}
let html = '<div class="driver-panel">';
tiers.forEach(function(t){
html += '<div class="driver-row">' +
'<span class="driver-row-label">' + t[0] + '</span>' +
'<div class="driver-row-bars">' + bar(d[t[1]].vol) + podBar(d[t[1]].pod) + '</div>' +
'</div>';
});
html += '<div class="driver-legend">' +
'<span class="driver-legend-item"><span class="driver-legend-swatch" style="background:rgba(29,110,82,0.45);"></span>9L volume</span>' +
'<span class="driver-legend-item"><span class="driver-legend-swatch" style="background:rgba(78,121,167,0.45);"></span>POD</span>' +
'</div></div>';
document.getElementById('prem-driver').innerHTML = html;
// Takeaway — compare highest tier's vol vs pod
const prestige = d.prestige;
const ratio = prestige.pod !== 0 ? prestige.vol / prestige.pod : 0;
let takeaway;
if(ratio > 1.6){
takeaway = '<span class="em-pos">Consumer-led premiumization.</span> Prestige volume is growing <strong>' + ratio.toFixed(1) + '\u00d7</strong> faster than distribution. The pull is coming from drinkers, not from retailers stocking new SKUs. Action: lean into shelf expansion at the premium+ tier.';
}else if(ratio > 1.0 && prestige.vol > 0){
takeaway = 'Balanced pull. Volume growth and distribution growth at the prestige tier are roughly in lockstep, suggesting a mature premium trend.';
}else if(prestige.vol < 0){
takeaway = '<span class="em-neg">Even prestige is contracting.</span> No tier is showing healthy growth. The category isn\'t premiumizing \u2014 it\'s deflating across the board.';
}else{
takeaway = 'Distribution-led. POD growth is keeping pace with volume \u2014 retailers are adding premium SKUs but velocity per door is flat. Watch for over-distribution risk.';
}
document.getElementById('prem-driver-takeaway').innerHTML = takeaway;
}

// Render channel split — off-prem vs on-prem premium index
function renderChannelSplit(cat){
const d = PREM_CHANNEL[cat] || PREM_CHANNEL.all_spirits;
const max = Math.max(d.offprem, d.onprem, 1.5);
const offW = (d.offprem / max) * 100;
const onW = (d.onprem / max) * 100;
const neutralPos = (1.0 / max) * 100;
const gap = ((d.onprem - d.offprem) * 100).toFixed(0);
const html = '<div class="channel-split">' +
'<div class="channel-split-row">' +
'<div class="channel-split-row-head"><span>Off-premise</span><span class="channel-split-row-val">' + (d.offprem*100).toFixed(0) + '</span></div>' +
'<div class="channel-split-bar"><div class="channel-split-fill offprem" style="width:' + offW + '%;"></div><div class="channel-split-neutral-line" style="left:' + neutralPos + '%;"></div></div>' +
'</div>' +
'<div class="channel-split-row">' +
'<div class="channel-split-row-head"><span>On-premise</span><span class="channel-split-row-val">' + (d.onprem*100).toFixed(0) + '</span></div>' +
'<div class="channel-split-bar"><div class="channel-split-fill onprem" style="width:' + onW + '%;"></div><div class="channel-split-neutral-line" style="left:' + neutralPos + '%;"></div></div>' +
'</div>' +
'</div>';
document.getElementById('prem-channel').innerHTML = html;
// Takeaway
let takeaway;
const both_premium = d.offprem >= 1.1 && d.onprem >= 1.1;
const both_value = d.offprem < 1.0 && d.onprem < 1.0;
if(both_premium){
takeaway = '<strong>Both channels premium-skewed.</strong> Off-prem ' + (d.offprem*100).toFixed(0) + ', on-prem ' + (d.onprem*100).toFixed(0) + '. Gap of <strong>+' + gap + 'pt</strong>. The category has structural pricing power everywhere it sells.';
}else if(both_value){
takeaway = '<strong>Value-skewed in both channels.</strong> Off-prem ' + (d.offprem*100).toFixed(0) + ', on-prem ' + (d.onprem*100).toFixed(0) + '. Even on-premise hasn\'t pulled this category into a premium position. A re-positioning story has to come from outside the existing distribution.';
}else if(d.onprem > 1.1 && d.offprem < 1.0){
takeaway = '<strong>Premium on-prem, value off-prem.</strong> Gap of <strong>+' + gap + 'pt</strong>. On-premise is the leading indicator \u2014 brands premiumize at the bar 12\u201318 months before it shows up at retail.';
}else{
takeaway = '<strong>Neutral skew.</strong> Off-prem ' + (d.offprem*100).toFixed(0) + ', on-prem ' + (d.onprem*100).toFixed(0) + '. Channel gap of +' + gap + 'pt. The category sits near tier-neutral in both channels.';
}
document.getElementById('prem-channel-takeaway').innerHTML = takeaway;
}

// Render category leaderboard
function renderPremLeaderboard(selectedCat){
function renderSpark(values){
const W = 60, H = 18;
const minV = Math.min.apply(null, values), maxV = Math.max.apply(null, values);
const range = (maxV - minV) || 1;
const xOf = function(i){ return (i / (values.length - 1)) * (W - 2) + 1; };
const yOf = function(v){ return 1 + (1 - (v - minV) / range) * (H - 2); };
const path = values.map(function(v, i){ return (i === 0 ? 'M ' : 'L ') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1); }).join(' ');
const last = values[values.length - 1];
const first = values[0];
const color = last > first ? '#245d45' : (last < first ? '#b8402b' : '#6b7280');
return '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" class="prem-lb-spark"><path d="' + path + '" fill="none" stroke="' + color + '" stroke-width="1.4" stroke-linecap="round"/><circle cx="' + xOf(values.length-1).toFixed(1) + '" cy="' + yOf(last).toFixed(1) + '" r="1.8" fill="' + color + '"/></svg>';
}
const html = '<div class="prem-leaderboard">' +
PREM_MOMENTUM.map(function(row, i){
const idxCls = row.idx >= 1.1 ? 'premium' : (row.idx < 0.95 ? 'value' : '');
const tCls = row.r24_change > 0.5 ? 'up' : (row.r24_change < -0.5 ? 'down' : 'flat');
const tSign = row.r24_change > 0 ? '+' : (row.r24_change < 0 ? '\u2212' : '\u00b1');
const tGlyph = row.r24_change > 0.5 ? '\u25B2 ' : (row.r24_change < -0.5 ? '\u25BC ' : '');
const sel = row.key === selectedCat ? ' selected' : '';
return '<div class="prem-lb-row' + sel + '" data-cat="' + row.key + '">' +
'<span class="prem-lb-rank">' + (i + 1) + '</span>' +
'<span class="prem-lb-name">' + row.name + '</span>' +
'<span class="prem-lb-idx ' + idxCls + '">' + (row.idx*100).toFixed(0) + '</span>' +
'<span class="prem-lb-trend ' + tCls + '">' + tGlyph + tSign + Math.abs(row.r24_change).toFixed(1) + 'pt</span>' +
renderSpark(row.spark) +
'</div>';
}).join('') + '</div>';
document.getElementById('prem-leaderboard').innerHTML = html;
// Wire row clicks to switch the category
document.querySelectorAll('#prem-leaderboard .prem-lb-row').forEach(function(r){
r.addEventListener('click', function(){
const newCat = r.dataset.cat;
const sel = document.getElementById('pr-cat');
if(sel){ sel.value = newCat; if(typeof renderPremium === 'function') renderPremium(); }
});
});
}

// Render the actionable insights box
function renderPremInsights(cat, region){
const fn = PREM_INSIGHTS[cat] || PREM_INSIGHTS.all_spirits;
const items = fn(region);
const html = '<div class="prem-insights-eyebrow">What this means \u00b7 actionable takeaways</div>' +
'<div class="prem-insights-head">Three lines that should make it into the next portfolio review</div>' +
'<div class="prem-insights-list">' +
items.map(function(t){ return '<div class="prem-insights-item">' + t + '</div>'; }).join('') +
'</div>';
document.getElementById('prem-insights').innerHTML = html;
}


function renderPremium(){
const cat=document.getElementById('pr-cat').value;
const region=document.getElementById('pr-region').value;
const div=document.getElementById('pr-div').value;
const mode=tabState.premium;
let pts=PREMIUM_BASE[cat];
if(region!=='all'){
const allowed=REGION_DIVS[region]||[];
pts=pts.filter(function(p){return allowed.indexOf(p.d)>=0;});
}
if(div!=='all'){
pts=pts.filter(function(p){return p.d===div;});
}
document.getElementById('premium-plot').innerHTML=premiumPlot(pts,mode);
let scopeNote='';
if(region!=='all'){
const rName={northeast:'Northeast',midwest:'Midwest',south:'South',west:'West'}[region];
const dName=div==='all'?'':' / '+(DIVISIONS[region].find(function(d){return d.v===div;})||{}).n;
scopeNote=' <span style="color:#6b7280;">· filtered to '+rName+(dName||'')+'</span>';
}
// Defensive: don't throw if a category or mode is missing — surface a fallback instead
const noteText = (PREMIUM_NOTES[cat] && PREMIUM_NOTES[cat][mode]) || '<span class="scatter-note-em">Position read.</span> Each dot represents a census division. Above the 45° line = premium-skewed; below = value-skewed.';
document.getElementById('premium-note').innerHTML = noteText + scopeNote;
// Render the four new analytical blocks
renderTierLadder(cat);
renderDriverDecomp(cat);
renderChannelSplit(cat);
renderPremLeaderboard(cat);
renderPremInsights(cat, region);
}

document.getElementById('pr-cat').addEventListener('change',renderPremium);
document.getElementById('pr-div').addEventListener('change',renderPremium);
