function fmtMoney(v){
const a=Math.abs(v);
if(a>=100)return '$'+Math.round(v)+'M';
if(a>=10)return '$'+v.toFixed(1)+'M';
return '$'+v.toFixed(2)+'M';
}
function fmtContrib(v){
const sign=v>=0?'+':'−';
const a=Math.abs(v);
if(a>=100)return sign+'$'+Math.round(a)+'M';
if(a>=10)return sign+'$'+a.toFixed(1)+'M';
return sign+'$'+a.toFixed(2)+'M';
}

function renderWaterfall(){
const cat=document.getElementById('wf-cat').value;
const period=document.getElementById('wf-period').value;
const d=WATERFALL_DATA[period][cat];
const labels=PERIOD_LABELS[period];
const ending=d.prior+d.pod+d.velocity+d.priceMix;
const netChange=ending-d.prior;
const netPct=(netChange/d.prior)*100;

const bars=[
{label:'Starting position',sub:labels.prior,value:d.prior,baseline:0,type:'total',isContrib:false},
{label:'POD change',sub:'distribution',value:d.pod,baseline:d.prior,type:d.pod>=0?'pos':'neg',isContrib:true},
{label:'Velocity',sub:'per-POD rate of sale',value:d.velocity,baseline:d.prior+d.pod,type:d.velocity>=0?'pos':'neg',isContrib:true},
{label:'Price/Mix',sub:'price + premiumization',value:d.priceMix,baseline:d.prior+d.pod+d.velocity,type:d.priceMix>=0?'pos':'neg',isContrib:true},
{label:'Ending position',sub:labels.current,value:ending,baseline:0,type:'total',isContrib:false}
];

const W=860,H=440;
const padTop=70,padBottom=80,padLeft=80,padRight=40;
const chartW=W-padLeft-padRight;
const chartH=H-padTop-padBottom;
const maxVal=Math.max(d.prior,ending)*1.18;
const yPos=function(v){return padTop+chartH-(v/maxVal)*chartH;};

const barW=Math.min(110,chartW/bars.length*0.62);
const slotW=chartW/bars.length;

let s='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block;max-height:480px;background:#fafafa;">';

// Net change header
const netColor=netChange>=0?'#2e7d57':'#b8402b';
s+='<text x="'+padLeft+'" y="34" font-size="13" font-weight="500" fill="#5f6368">Net revenue change</text>';
s+='<text x="'+padLeft+'" y="56" font-size="22" font-weight="700" fill="'+netColor+'">'+fmtContrib(netChange)+'  <tspan font-size="15" font-weight="600" fill="#5f6368">('+(netChange>=0?'+':'')+netPct.toFixed(1)+'%)</tspan></text>';

// Gridlines + Y-axis labels
const gridSteps=5;
for(let i=0;i<=gridSteps;i++){
const v=(maxVal/gridSteps)*i;
const y=yPos(v);
s+='<line x1="'+padLeft+'" y1="'+y+'" x2="'+(W-padRight)+'" y2="'+y+'" stroke="#ebebed" stroke-width="1"/>';
s+='<text x="'+(padLeft-8)+'" y="'+(y+4)+'" text-anchor="end" font-size="11" fill="#6b7280">'+fmtMoney(v)+'</text>';
}

// Bars + connectors + labels
bars.forEach(function(bar,i){
const cx=padLeft+slotW*(i+0.5);
const x=cx-barW/2;
const valTop=bar.baseline+Math.max(0,bar.value);
const valBottom=bar.baseline+Math.min(0,bar.value);
const yTop=yPos(valTop);
const yBottom=yPos(valBottom);
const barH=Math.max(2,yBottom-yTop);

let color;
if(bar.type==='total')color='#4E79A7';
else if(bar.type==='pos')color='#4cb8a4';
else color='#e07b5f';

s+='<rect x="'+x+'" y="'+yTop+'" width="'+barW+'" height="'+barH+'" fill="'+color+'" rx="1"/>';

// Value label above (or below if negative)
const labelText=bar.isContrib?fmtContrib(bar.value):fmtMoney(bar.value);
const labelY=bar.value>=0?yTop-9:yBottom+18;
s+='<text x="'+cx+'" y="'+labelY+'" text-anchor="middle" font-size="13" font-weight="700" fill="#1f1f1f">'+labelText+'</text>';

// X-axis labels (two lines)
s+='<text x="'+cx+'" y="'+(H-padBottom+24)+'" text-anchor="middle" font-size="13" font-weight="600" fill="#3c3c3c">'+bar.label+'</text>';
s+='<text x="'+cx+'" y="'+(H-padBottom+42)+'" text-anchor="middle" font-size="11" fill="#6b7280">'+bar.sub+'</text>';

// Connector line to next bar
if(i<bars.length-1){
const endY=yPos(bar.baseline+bar.value);
const nextCx=padLeft+slotW*(i+1.5);
const nextX=nextCx-barW/2;
s+='<line x1="'+(x+barW)+'" y1="'+endY+'" x2="'+nextX+'" y2="'+endY+'" stroke="#6b7280" stroke-width="1" stroke-dasharray="4,3"/>';
}
});

s+='</svg>';
document.getElementById('wf-chart').innerHTML=s;

// Narrative under chart — pick by net direction
let narrativeKey;
if(Math.abs(netPct)<1.5)narrativeKey='flat';
else if(netChange>=0)narrativeKey='positive';
else narrativeKey='negative';
document.getElementById('wf-note').innerHTML=WATERFALL_NARRATIVES[cat][narrativeKey];
renderWaterfallTable();
}

document.getElementById('wf-cat').addEventListener('change',renderWaterfall);
document.getElementById('wf-period').addEventListener('change',renderWaterfall);

