// =====================================================================
// Trajectories analytical blocks
// =====================================================================
const TJ_CAT_COLOR = {whiskey:'#d97706', vodka:'#1a73e8', tequila:'#4cb8a4', rum:'#2a3654'};
const TJ_CAT_KEYS = DOMAIN.categories.map(function(c){return c.key;});
const TJ_CAT_LABEL = {whiskey:'Whiskey', vodka:'Vodka', tequila:'Tequila', rum:'Rum'};
const TJ_METRIC_LABEL = {velocity:'Velocity', activation:'Activation', premiumidx:'Premium index', pricemix:'Price/Mix', podeff:'POD efficiency'};
const TJ_METRIC_SHORT = {velocity:'Velocity', activation:'Activate', premiumidx:'Premium', pricemix:'Price/Mix', podeff:'POD eff'};
const TJ_METRIC_DESC = {velocity:'cs per buying account', activation:'% of base transacting', premiumidx:'revenue share \u00f7 9L share', pricemix:'revenue growth \u2212 9L growth', podeff:'9L share \u00f7 POD share'};
const TJ_METRICS = ['velocity','activation','premiumidx','pricemix','podeff'];

// Compute the 24-month slope (sign + magnitude) for each (metric, category)
function tjSlope(series){
const n = series.length;
const first = (series[0] + series[1] + series[2]) / 3;
const last  = (series[n-3] + series[n-2] + series[n-1]) / 3;
return last - first;
}

// Direction: -1 = down, 0 = flat, +1 = up. Threshold scales with metric magnitude.
function tjDirection(series, key){
const slope = tjSlope(series);
const avg = series.reduce(function(a,b){return a+b;},0) / series.length;
const relSlope = avg !== 0 ? slope / avg : slope;
// 5% relative change over 24 months counts as a direction
const thresh = 0.05;
if(relSlope > thresh) return 1;
if(relSlope < -thresh) return -1;
return 0;
}

// Format a metric value for display
function tjFormatVal(key, val){
const m = METRIC_DATA[key];
const numStr = val.toFixed(m.decimals);
return (m.signed && val >= 0 ? '+' : '') + numStr + (m.unit || '');
}

function renderTrajectoriesBlocks(){
// Block A: Metric leaderboard — per metric, who wins
let lbHtml = '';
TJ_METRICS.forEach(function(mkey){
const m = METRIC_DATA[mkey];
// For divergent metrics centered on 1.0, "winning" means highest absolute value above center
// For price/mix (centered on 0, signed), winning means highest value
// For simple metrics, winning means highest value
const ranked = m.values.map(function(v){
const catKey = v.cat.toLowerCase();
return { cat: v.cat, catKey: catKey, val: v.val, color: TJ_CAT_COLOR[catKey] };
}).sort(function(a, b){ return b.val - a.val; });
const winner = ranked[0];
const loser = ranked[ranked.length - 1];
const spreadNum = winner.val - loser.val;
lbHtml += '<div class="tj-lb-metric">' +
'<div class="tj-lb-metric-name">' + TJ_METRIC_LABEL[mkey] + '</div>' +
'<div class="tj-lb-metric-bar">' +
'<span class="tj-lb-winner"><span class="tj-lb-winner-swatch" style="background:' + winner.color + ';"></span>' + winner.cat + '</span>' +
'<span class="tj-lb-winner-val">' + tjFormatVal(mkey, winner.val) + '</span>' +
'<span class="tj-lb-spread">spread ' + spreadNum.toFixed(m.decimals) + (m.unit || '') + ' \u00b7 last: ' + loser.cat + ' (' + tjFormatVal(mkey, loser.val) + ')</span>' +
'</div>' +
'</div>';
});
document.getElementById('tj-leaderboard').innerHTML = lbHtml;
// Leaderboard takeaway
const winCount = {Whiskey:0, Vodka:0, Tequila:0, Rum:0};
TJ_METRICS.forEach(function(mkey){
const m = METRIC_DATA[mkey];
const ranked = m.values.slice().sort(function(a, b){ return b.val - a.val; });
winCount[ranked[0].cat]++;
});
const wcRanked = Object.keys(winCount).sort(function(a,b){return winCount[b] - winCount[a];});
const wcLeader = wcRanked[0];
const wcTakeaway = winCount[wcLeader] >= 3
? '<span class="em-pos"><strong>' + wcLeader + '</strong></span> wins on <strong>' + winCount[wcLeader] + ' of 5</strong> metrics \u2014 the structurally strongest category in the framework. The other categories should be measured against ' + wcLeader + '.'
: '<strong>No dominant winner</strong> across the 5 metrics \u2014 ' + wcRanked.slice(0,3).map(function(c){return '<strong>'+c+'</strong> leads ' + winCount[c];}).join(', ') + '. The categories have differentiated strengths, not a single ranking.';
document.getElementById('tj-leaderboard-takeaway').innerHTML = wcTakeaway;

// Block B: 24-month direction grid
let dirHtml = '<div class="tj-dir-head">' +
'<div></div>' +
TJ_METRICS.map(function(mkey){ return '<div class="tj-dir-head-cell">' + TJ_METRIC_SHORT[mkey] + '</div>'; }).join('') +
'</div>';
const dirMatrix = {};
TJ_CAT_KEYS.forEach(function(ckey){
dirMatrix[ckey] = {};
dirHtml += '<div class="tj-dir-row">' +
'<span class="tj-dir-cat"><span class="tj-dir-cat-swatch" style="background:' + TJ_CAT_COLOR[ckey] + ';"></span>' + TJ_CAT_LABEL[ckey] + '</span>';
TJ_METRICS.forEach(function(mkey){
const dir = tjDirection(METRIC_LINES[mkey][ckey], mkey);
dirMatrix[ckey][mkey] = dir;
const cls = dir > 0 ? 'up' : (dir < 0 ? 'down' : 'flat');
const arrow = dir > 0 ? '\u2191' : (dir < 0 ? '\u2193' : '\u2192');
dirHtml += '<div class="tj-dir-cell ' + cls + '">' + arrow + '</div>';
});
dirHtml += '</div>';
});
document.getElementById('tj-direction').innerHTML = dirHtml;
// Direction takeaway
let totalUp = 0, totalDown = 0;
const allDirsByCat = {};
TJ_CAT_KEYS.forEach(function(ckey){
let up = 0, down = 0;
TJ_METRICS.forEach(function(mkey){
const d = dirMatrix[ckey][mkey];
if(d > 0){ up++; totalUp++; }
else if(d < 0){ down++; totalDown++; }
});
allDirsByCat[ckey] = { up: up, down: down };
});
const mostUp = TJ_CAT_KEYS.slice().sort(function(a,b){ return allDirsByCat[b].up - allDirsByCat[a].up; })[0];
const mostDown = TJ_CAT_KEYS.slice().sort(function(a,b){ return allDirsByCat[b].down - allDirsByCat[a].down; })[0];
let dirTakeaway;
if(allDirsByCat[mostUp].up >= 4){
dirTakeaway = '<span class="em-pos"><strong>' + TJ_CAT_LABEL[mostUp] + '</strong></span> is rising on <strong>' + allDirsByCat[mostUp].up + ' of 5</strong> metrics over 24 months \u2014 broad-based strength, not a single-axis story.';
}else if(allDirsByCat[mostDown].down >= 4){
dirTakeaway = '<span class="em-neg"><strong>' + TJ_CAT_LABEL[mostDown] + '</strong></span> is falling on <strong>' + allDirsByCat[mostDown].down + ' of 5</strong> metrics over 24 months \u2014 structural deterioration, not a temporary blip.';
}else{
dirTakeaway = '<strong>' + TJ_CAT_LABEL[mostUp] + '</strong> rising on ' + allDirsByCat[mostUp].up + ' axes, <strong>' + TJ_CAT_LABEL[mostDown] + '</strong> falling on ' + allDirsByCat[mostDown].down + '. Mixed but directional \u2014 the long-term picture matches the snapshot.';
}
document.getElementById('tj-direction-takeaway').innerHTML = dirTakeaway;

// Block C: Profile signature — strongest and weakest metric per category
let profHtml = '';
TJ_CAT_KEYS.forEach(function(ckey){
// Compute relative strength per metric: each category's value vs the mean of all categories on that metric
const strengths = TJ_METRICS.map(function(mkey){
const m = METRIC_DATA[mkey];
const allVals = m.values.map(function(v){ return v.val; });
const mean = allVals.reduce(function(a,b){return a+b;},0) / allVals.length;
const catVal = m.values.find(function(v){ return v.cat.toLowerCase() === ckey; }).val;
const relStrength = mean !== 0 ? (catVal - mean) / Math.abs(mean) : 0;
return { metric: mkey, label: TJ_METRIC_LABEL[mkey], val: catVal, relStrength: relStrength };
});
strengths.sort(function(a, b){ return b.relStrength - a.relStrength; });
const top = strengths[0];
const bot = strengths[strengths.length - 1];
const topDir = dirMatrix[ckey][top.metric];
const botDir = dirMatrix[ckey][bot.metric];
const topDirText = topDir > 0 ? ' and rising' : (topDir < 0 ? ' but falling' : ' and stable');
const botDirText = botDir > 0 ? ' but rising' : (botDir < 0 ? ' and falling' : ' and stable');
profHtml += '<div class="tj-prof-row">' +
'<div class="tj-prof-head">' +
'<span class="tj-prof-name"><span class="tj-prof-name-swatch" style="background:' + TJ_CAT_COLOR[ckey] + ';"></span>' + TJ_CAT_LABEL[ckey] + '</span>' +
'</div>' +
'<div class="tj-prof-detail">Strongest on <span class="tj-prof-strength">' + top.label + '</span> (' + tjFormatVal(top.metric, top.val) + topDirText + '); weakest on <span class="tj-prof-weakness">' + bot.label + '</span> (' + tjFormatVal(bot.metric, bot.val) + botDirText + ').</div>' +
'</div>';
});
document.getElementById('tj-profile').innerHTML = profHtml;

// Block D: Volume-led vs value-led — direction comparison of velocity vs pricemix
let mixHtml = '';
TJ_CAT_KEYS.forEach(function(ckey){
const velDir = dirMatrix[ckey].velocity;
const pmDir = dirMatrix[ckey].pricemix;
let tag, tagText;
if(velDir > 0 && pmDir > 0){ tag = 'dual'; tagText = 'Dual-engine'; }
else if(velDir > 0 && pmDir <= 0){ tag = 'volume-led'; tagText = 'Volume-led'; }
else if(velDir <= 0 && pmDir > 0){ tag = 'value-led'; tagText = 'Value-led'; }
else if(velDir < 0 && pmDir < 0){ tag = 'decline'; tagText = 'Both declining'; }
else { tag = 'volume-led'; tagText = 'Stable'; }
const velVal = METRIC_DATA.velocity.values.find(function(v){ return v.cat.toLowerCase() === ckey; }).val;
const pmVal = METRIC_DATA.pricemix.values.find(function(v){ return v.cat.toLowerCase() === ckey; }).val;
const velCls = velDir > 0 ? 'pos' : (velDir < 0 ? 'neg' : 'flat');
const pmCls = pmDir > 0 ? 'pos' : (pmDir < 0 ? 'neg' : 'flat');
mixHtml += '<div class="tj-mix-row">' +
'<span class="tj-mix-cat"><span class="tj-mix-cat-swatch" style="background:' + TJ_CAT_COLOR[ckey] + ';"></span>' + TJ_CAT_LABEL[ckey] + '</span>' +
'<span class="tj-mix-val ' + velCls + '" title="Velocity 24-mo direction">' + (velDir > 0 ? '\u2191' : (velDir < 0 ? '\u2193' : '\u2192')) + ' ' + velVal.toFixed(1) + '</span>' +
'<span class="tj-mix-val ' + pmCls + '" title="Price/Mix 24-mo direction">' + (pmDir > 0 ? '\u2191' : (pmDir < 0 ? '\u2193' : '\u2192')) + ' ' + (pmVal >= 0 ? '+' : '') + pmVal.toFixed(1) + 'pt</span>' +
'<span class="tj-mix-tag ' + tag + '">' + tagText + '</span>' +
'</div>';
});
document.getElementById('tj-mix').innerHTML = mixHtml;
// Mix takeaway
const tagCounts = {dual:0, 'volume-led':0, 'value-led':0, decline:0};
TJ_CAT_KEYS.forEach(function(ckey){
const velDir = dirMatrix[ckey].velocity;
const pmDir = dirMatrix[ckey].pricemix;
if(velDir > 0 && pmDir > 0) tagCounts.dual++;
else if(velDir > 0 && pmDir <= 0) tagCounts['volume-led']++;
else if(velDir <= 0 && pmDir > 0) tagCounts['value-led']++;
else if(velDir < 0 && pmDir < 0) tagCounts.decline++;
});
let mixTakeaway;
if(tagCounts.dual >= 1){
mixTakeaway = '<strong>' + tagCounts.dual + '</strong> categor' + (tagCounts.dual > 1 ? 'ies are' : 'y is') + ' dual-engine (volume <em>and</em> value rising) \u2014 the cleanest growth story. <strong>' + tagCounts['volume-led'] + '</strong> volume-led, <strong>' + tagCounts['value-led'] + '</strong> value-led. Value-led growth is more margin-rich but harder to sustain; volume-led is more scalable but compresses margin.';
}else if(tagCounts['value-led'] >= 2){
mixTakeaway = '<strong>Mostly value-led growth</strong> (' + tagCounts['value-led'] + ' categories): margin expansion is the story, not unit growth. This is sustainable while the premiumization wave runs but eventually requires re-engaging the velocity engine.';
}else if(tagCounts['volume-led'] >= 2){
mixTakeaway = '<strong>Mostly volume-led growth</strong> (' + tagCounts['volume-led'] + ' categories): unit expansion without significant margin lift. Wide reach is being achieved; the next phase is extracting premium economics from it.';
}else{
mixTakeaway = 'Mixed signals across the portfolio. <span class="em-neg">' + tagCounts.decline + '</span> in decline mode, ' + tagCounts['volume-led'] + ' volume-led, ' + tagCounts['value-led'] + ' value-led. No single growth model dominates \u2014 strategy must be category-by-category.';
}
document.getElementById('tj-mix-takeaway').innerHTML = mixTakeaway;

// Insights box
renderTrajectoriesInsights(dirMatrix, winCount, allDirsByCat);
}

function renderTrajectoriesInsights(dirMatrix, winCount, allDirsByCat){
const el = document.getElementById('tj-insights');
if(!el) return;
// Identify the leader, the deteriorator, and the divergent
const wcRanked = Object.keys(winCount).sort(function(a,b){ return winCount[b] - winCount[a]; });
const metricLeader = wcRanked[0];
const dirLeader = TJ_CAT_KEYS.slice().sort(function(a,b){ return allDirsByCat[b].up - allDirsByCat[a].up; })[0];
const dirLagger = TJ_CAT_KEYS.slice().sort(function(a,b){ return allDirsByCat[b].down - allDirsByCat[a].down; })[0];
const items = [];
// Item 1: who's the structural leader
const dirLeaderUps = allDirsByCat[dirLeader].up;
if(metricLeader.toLowerCase() === dirLeader && winCount[metricLeader] >= 3 && dirLeaderUps >= 3){
items.push('<strong>' + metricLeader + ' is the structural leader</strong> across the 5-metric framework: wins on <strong>' + winCount[metricLeader] + ' of 5</strong> metrics in the snapshot and rising on <strong>' + dirLeaderUps + ' of 5</strong> over 24 months. <span class="lift">Action:</span> this is the safest portfolio bet \u2014 distribution expansion compounds, premium positioning is intact, and the trend hasn\'t inflected. Treat as the anchor of the next plan cycle.');
}else if(winCount[metricLeader] >= 3){
items.push('<strong>' + metricLeader + ' wins on level</strong> (' + winCount[metricLeader] + ' of 5 metrics) but the 24-month picture shows the slope is moderating. <span class="lift">Action:</span> protect the position rather than push for further gains; the easy expansion is behind us.');
}else{
items.push('<strong>No single leader</strong> across the 5 metrics \u2014 the strengths are distributed. <span class="lift">Action:</span> portfolio strategy can\'t default to a hero category. Allocate by sub-channel and tier where the wins are clearer (Premium tab).');
}
// Item 2: deteriorator
const dirLaggerDowns = allDirsByCat[dirLagger].down;
if(dirLaggerDowns >= 4){
items.push('<span class="em-neg"><strong>' + TJ_CAT_LABEL[dirLagger] + '</strong></span> is falling on <strong>' + dirLaggerDowns + ' of 5</strong> metrics over 24 months \u2014 broad-based deterioration, not noise. <span class="lift">Action:</span> harvest distribution at current rates; do not invest in new SKU launches or premium tier extensions; reallocate trade spend to the lean-in categories.');
}else if(dirLaggerDowns >= 3){
items.push('<strong>' + TJ_CAT_LABEL[dirLagger] + '</strong> shows 24-month decline on ' + dirLaggerDowns + ' metrics. <span class="lift">Action:</span> the position is at risk; identify which axes are still positive and double down on those rather than fighting the falling ones.');
}else{
items.push('<strong>No category in structural decline</strong> across the framework. Weakest is <strong>' + TJ_CAT_LABEL[dirLagger] + '</strong> at <strong>' + dirLaggerDowns + ' of 5</strong> falling. <span class="lift">Action:</span> portfolio is broadly healthy; no triage needed. Focus on lifting the strongest performer further out.');
}
// Item 3: value vs volume mix observation
const dualCount = TJ_CAT_KEYS.filter(function(ckey){ return dirMatrix[ckey].velocity > 0 && dirMatrix[ckey].pricemix > 0; }).length;
if(dualCount >= 2){
items.push('<strong>' + dualCount + ' of 4 categories</strong> are dual-engine (velocity <em>and</em> price/mix both rising). <span class="lift">Action:</span> this is rare \u2014 dual-engine usually compresses into volume-led or value-led within 4\u20136 quarters. Capture the margin while you can.');
}else if(dualCount === 1){
const dualCat = TJ_CAT_KEYS.find(function(ckey){ return dirMatrix[ckey].velocity > 0 && dirMatrix[ckey].pricemix > 0; });
items.push('<strong>' + TJ_CAT_LABEL[dualCat] + ' is the only dual-engine category</strong> \u2014 simultaneous velocity and price/mix expansion. <span class="lift">Action:</span> protect this with disciplined pricing; resist the temptation to use ' + TJ_CAT_LABEL[dualCat] + ' to lift weaker performers via shared promotions \u2014 it dilutes the dual engine.');
}else{
items.push('<strong>No dual-engine category</strong> \u2014 every category is either volume-led, value-led, or in decline. <span class="lift">Action:</span> the trade-off between price and volume is real in this portfolio. Be explicit about which lever each category is pulling and don\'t expect both at once.');
}
const html = '<div class="tj-insights-eyebrow">What this means \u00b7 actionable takeaways</div>' +
'<div class="tj-insights-head">Three lines that should make it into the next portfolio review</div>' +
'<div class="tj-insights-list">' + items.map(function(t){ return '<div class="tj-insights-item">' + t + '</div>'; }).join('') + '</div>';
el.innerHTML = html;
}


