function aiGrowthColor(g){
if(g>=10)return '#2e7d57';
if(g>=5)return '#5dcaa5';
if(g>=0)return '#9fe1cb';
if(g>=-5)return '#f5c4b3';
if(g>=-10)return '#d85a30';
return '#993c1d';
}

function renderAISubcat(){
const maxShare=Math.max.apply(null,AI_SUBCAT_DATA.map(function(d){return d.share;}));
let html='';
AI_SUBCAT_DATA.forEach(function(d){
const pct=d.share/maxShare*100;
const color=aiGrowthColor(d.growth);
const sign=d.growth>0?'+':'';
const valCls=d.growth>=0?'pos':'neg';
html+='<div class="ai-bar-row">';
html+='<span class="ai-bar-label">'+d.label+' <span style="color:#6b7280;font-weight:400;">'+d.share+'%</span></span>';
html+='<div class="ai-bar-track"><div class="ai-bar-fill" style="left:0;width:'+pct+'%;background:'+color+';"></div></div>';
html+='<span class="ai-bar-val '+valCls+'">'+sign+d.growth+'%</span>';
html+='</div>';
});
document.getElementById('ai-subcat-chart').innerHTML=html;
}

function renderAITier(){
const maxAbs=Math.max.apply(null,AI_TIER_DATA.map(function(d){return Math.abs(d.value);}));
let html='';
AI_TIER_DATA.forEach(function(d){
const pct=Math.abs(d.value)/maxAbs*50;
const sign=d.value>0?'+':'';
const valCls=d.value>=0?'pos':'neg';
const fillStyle=d.value>=0?'left:50%;background:#4cb8a4;':'right:50%;background:#e07b5f;';
html+='<div class="ai-bar-row">';
html+='<span class="ai-bar-label">'+d.label+'</span>';
html+='<div class="ai-bar-track"><div class="ai-bar-fill" style="'+fillStyle+'width:'+pct+'%;"></div><div class="ai-bar-zero"></div></div>';
html+='<span class="ai-bar-val '+valCls+'">'+sign+d.value+'%</span>';
html+='</div>';
});
document.getElementById('ai-tier-chart').innerHTML=html;
}

