// ---- Over/under-index vs industry: the "where do I beat the market" centerpiece ----
const DIST_BREAK_LABELS={subcat:'sub-category',tier:'price tier',channel:'on-prem sub-channel',region:'census division',cohort:'new-item cohort',class:'account class'};
function distIndexItems(breakKey){
switch(breakKey){
case 'subcat': return DIST_REPORTS[0].items.concat(DIST_REPORTS[1].items);
case 'tier': return DIST_REPORTS[2].items;
case 'channel': return DIST_REPORTS[3].items;
case 'region': return DIST_REPORTS[4].items;
case 'cohort': return DIST_REPORTS[5].items;
case 'class': return DIST_REPORTS[6].classData;
default: return DIST_REPORTS[0].items;
}
}
function renderDistIndex(){
const host=document.getElementById('dist-index'); if(!host) return;
const measureKey=document.getElementById('d-measure').value;
const breakSel=document.getElementById('d-breakby'); const breakKey=breakSel?breakSel.value:'subcat';
const m=DIST_MEASURES[measureKey];
const dimLabel=DIST_BREAK_LABELS[breakKey]||'segment';
const dimPlural = /y$/.test(dimLabel)?dimLabel.replace(/y$/,'ies'):(/s$/.test(dimLabel)?dimLabel+'es':dimLabel+'s');
const thr=distDeltaThreshold(measureKey);
const rows=distIndexItems(breakKey).map(function(it){ const c=distMeasureValues(it,measureKey); return {label:it.label, w:c.w, i:c.i, delta:c.w-c.i}; });
rows.sort(function(a,b){return b.delta-a.delta;});
const maxAbs=Math.max.apply(null, rows.map(function(r){return Math.abs(r.delta);}))||0.1;
let bars='';
rows.forEach(function(r){
const cls=r.delta>thr?'pos':(r.delta<-thr?'neg':'flat');
const pct=Math.min(50, Math.abs(r.delta)/maxAbs*50);
const bar = cls==='flat' ? '' : '<div class="dist-idx-bar '+cls+'" style="width:'+pct+'%;"></div>';
bars+='<div class="dist-idx-row"><span class="dist-idx-label" title="'+r.label+'">'+r.label+'</span>'+
'<div class="dist-idx-track">'+bar+'<div class="dist-idx-zero"></div></div>'+
'<span class="dist-idx-val '+cls+'">'+distFormatDelta(r.delta,measureKey)+'</span></div>';
});
const overs=rows.filter(function(r){return r.delta>thr;});
const unders=rows.filter(function(r){return r.delta<-thr;}).sort(function(a,b){return a.delta-b.delta;});
const coItem=function(r,sign){ return '<div class="dist-idx-co-item"><span class="dist-idx-co-label">'+r.label+'</span><span class="dist-idx-co-val '+(sign>0?'pos':'neg')+'">'+distFormatDelta(r.delta,measureKey)+'</span></div>'; };
const edgeHtml = overs.length? overs.slice(0,4).map(function(r){return coItem(r,1);}).join('') : '<div class="dist-idx-co-empty">No segment is ahead of the market on this measure.</div>';
const gapHtml = unders.length? unders.slice(0,4).map(function(r){return coItem(r,-1);}).join('') : '<div class="dist-idx-co-empty">No material gaps to market in this cut — a defensible position.</div>';
// adaptive analyst read
const nOver=overs.length, nUnder=unders.length, n=rows.length;
const hero=DIST_HERO_DATA; const volD=hero[0].whlsl-hero[0].industry, revD=hero[1].whlsl-hero[1].industry;
const bullets=[];
let archetype;
if(nOver>=n*0.66) archetype='You out-index the Hoodie composite across most of this book — a broadly market-beating position on '+m.label.toLowerCase()+'.';
else if(nUnder>=n*0.66) archetype='Your book trails the composite across most '+dimPlural+' on '+m.label.toLowerCase()+' — a concentrated catch-up opportunity.';
else archetype='A selective profile: ahead of the market in '+nOver+' of '+n+' '+dimPlural+', behind in '+nUnder+'. Strength is concentrated, not uniform.';
bullets.push(archetype);
if(overs.length) bullets.push('Strongest edge: <strong>'+overs[0].label+'</strong> at '+distFormatDelta(overs[0].delta,measureKey)+' vs the composite — defend and lean into the supplier story here.');
if(unders.length) bullets.push('Largest gap to market: <strong>'+unders[0].label+'</strong> at '+distFormatDelta(unders[0].delta,measureKey)+' — the clearest addressable opportunity in this cut, and the one to model headroom on next.');
if(revD-volD>0.6) bullets.push('Across the book, revenue is outpacing volume by '+(revD-volD).toFixed(1)+'pt more than the market — a price/mix advantage that compounds the volume lead.');
else if(volD>0.3) bullets.push('Your overall volume growth runs '+volD.toFixed(1)+'pt ahead of the composite, so these gains are real share, not just market lift.');
host.innerHTML='<div class="dist-idx-wrap">'+
'<div class="dist-idx-head"><div class="dist-idx-eyebrow">▮ Over / under-index vs industry</div>'+
'<div class="dist-idx-title">Where your book beats the market — and where the headroom is</div>'+
'<div class="dist-idx-sub"><strong>'+m.label+'</strong> · by '+dimLabel+' · bars show your wholesaler minus the Hoodie composite, ranked. Teal = ahead of market, coral = behind.</div></div>'+
'<div class="dist-idx-chart">'+bars+'</div>'+
'<div class="dist-idx-callouts"><div class="dist-idx-callout edge"><div class="dist-idx-callout-h">Your edge vs market</div>'+edgeHtml+'</div>'+
'<div class="dist-idx-callout gap"><div class="dist-idx-callout-h">Addressable vs market</div>'+gapHtml+'</div></div>'+
'<div class="dist-idx-insights"><div class="dist-idx-ins-h">Hoodie read</div><ul>'+bullets.map(function(b){return '<li>'+b+'</li>';}).join('')+'</ul></div>'+
'</div>';
}

let distMeasureListenerAttached=false;

function renderDist(){
renderDistHero();
renderDistIndex();
const measureKey=document.getElementById('d-measure').value;
const measureLabel=DIST_MEASURES[measureKey].label;
let html='<div style="font-size:12px;color:#5f6368;margin-bottom:14px;padding:8px 12px;background:#f5f5f7;border-radius:4px;">Full side-by-side detail below — showing <strong style="color:var(--dash-accent,#4E79A7);">'+measureLabel+'</strong> across every report. Hero scorecard shows R12 growth on the four base measures.</div>';
DIST_REPORTS.forEach(function(r){
html+='<div class="dist-pair-wrap"><div class="dist-pair-title">'+r.title+'</div>';
if(r.type==='bars')html+=distCompareTable(r,measureKey);
else if(r.type==='acctclass')html+=renderDistAcctClass(r,measureKey);
html+='</div>';
});
document.getElementById('dist-reports').innerHTML=html;
if(!distMeasureListenerAttached){
document.getElementById('d-measure').addEventListener('change',renderDist);
const bb=document.getElementById('d-breakby'); if(bb) bb.addEventListener('change',renderDistIndex);
distMeasureListenerAttached=true;
}
}

