// === "What's being poured / going home right now" — live current-period momentum board ===
// Anonymized to category x tier. No brands, no accounts, no raw case volumes — momentum is a
// 0-100 current-velocity index and the delta is the pt change vs the prior 4-week window.
const DNOW = {
onprem: { asof: 'latest 4 weeks · on-premise depletions', rows: [
{label:'Tequila', tier:'super-premium', mom:94, delta:6.2},
{label:'RTD / cocktails', tier:'craft serve', mom:89, delta:8.1},
{label:'Mezcal', tier:'all tiers', mom:83, delta:5.4},
{label:'American whiskey', tier:'single malt', mom:78, delta:3.7},
{label:'Agave', tier:'cristalino', mom:74, delta:4.9},
{label:'Irish whiskey', tier:'premium', mom:66, delta:1.2},
{label:'Vodka', tier:'premium', mom:52, delta:-2.1},
{label:'Cognac', tier:'VS / VSOP', mom:47, delta:-1.4},
{label:'Vodka', tier:'value', mom:38, delta:-4.6}
]},
offprem: { asof: 'latest 4 weeks · off-premise depletions', rows: [
{label:'RTD / cocktails', tier:'multi-serve pack', mom:92, delta:9.3},
{label:'Tequila', tier:'mid-premium', mom:86, delta:5.1},
{label:'Flavored whiskey', tier:'standard', mom:80, delta:4.2},
{label:'Canned cocktail', tier:'single-serve', mom:77, delta:6.8},
{label:'Tequila', tier:'super-premium', mom:71, delta:3.3},
{label:'American whiskey', tier:'standard', mom:63, delta:1.1},
{label:'Vodka', tier:'value', mom:55, delta:-1.8},
{label:'Cordials', tier:'value', mom:44, delta:-2.9},
{label:'Wine', tier:'value table', mom:36, delta:-3.7}
]}
};
function dnowDateLabel(){
const d = new Date(2026, 3, 30); // through end of latest comparable period (Apr '26, R12 trailing)
return d.toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'});
}
function renderDrinkingNow(channel){
const mount = document.getElementById(channel + '-dnow');
if(!mount) return;
const cfg = DNOW[channel]; if(!cfg) return;
const rows = cfg.rows.slice().sort(function(a,b){ return b.mom - a.mom; });
const heating = rows.filter(function(r){ return r.delta > 0; }).length;
const topMover = rows.slice().sort(function(a,b){ return b.delta - a.delta; })[0];
const title = channel === 'onprem' ? "What's being poured right now" : "What's going home right now";
const sub = channel === 'onprem'
? 'The most recent four weeks of on-premise depletions, ranked by current pour velocity. This is the leading edge of the channel — what bartenders are reaching for before it shows up in a quarterly read.'
: 'The off-premise comp: the same four weeks of take-home depletions, ranked by current sell-through. Read side-by-side with on-premise to see where the two baskets diverge.';
let html = '<div class="dnow-head">' +
'<div class="chart-card-title" style="margin-bottom:0;">' + title + '</div>' +
'<span class="dnow-live"><span class="dnow-live-dot"></span>Live momentum</span>' +
'<span class="dnow-asof">' + cfg.asof + ' · through ' + dnowDateLabel() + '</span>' +
'</div>' +
'<div class="dnow-sub">' + sub + '</div>' +
'<div class="dnow-list">';
rows.forEach(function(r, i){
const up = r.delta >= 0;
const fill = up ? (r.mom >= 75 ? '#2fb98a' : '#5cc3a3') : '#c98a72';
html += '<div class="dnow-row">' +
'<div class="dnow-rank">' + (i+1) + '</div>' +
'<div class="dnow-namewrap"><div class="dnow-name">' + r.label + '</div><div class="dnow-tier">' + r.tier + '</div></div>' +
'<div class="dnow-barwrap"><div class="dnow-bar"><div class="dnow-bar-fill" style="width:' + r.mom + '%;background:' + fill + ';"></div></div><span class="dnow-mom">' + r.mom + '</span></div>' +
'<div class="dnow-delta ' + (up ? 'up' : 'down') + '">' + (up ? '▲' : '▼') + ' ' + (up ? '+' : '') + r.delta.toFixed(1) + ' pt</div>' +
'</div>';
});
html += '</div>';
html += '<div class="dnow-foot">' +
'<div class="dnow-stat"><div class="dnow-stat-val">' + heating + ' of ' + rows.length + '</div><div class="dnow-stat-lbl">Segments accelerating vs prior 4 weeks</div></div>' +
'<div class="dnow-stat"><div class="dnow-stat-val">' + topMover.label + '</div><div class="dnow-stat-lbl">Fastest mover · ' + topMover.tier + ' (+' + topMover.delta.toFixed(1) + ' pt)</div></div>' +
'<div class="dnow-stat"><div class="dnow-stat-val">4-wk</div><div class="dnow-stat-lbl">Recency window · refreshes every period</div></div>' +
'</div>';
const proof = channel === 'onprem'
? '<strong>Why this matters:</strong> off-premise scanner data cannot see the bar. A four-week on-premise read at category × tier is the earliest honest signal of what is actually being consumed — the premium-tequila and craft-RTD surge shows up here weeks before it reaches a distributor\u2019s quarterly review.'
: '<strong>The two-basket story:</strong> the same consumer behaves differently by channel. On-premise leans premium and experiential (super-premium agave, craft cocktails); off-premise leans take-home value and format (multi-serve RTD, mid-tier tequila, flavored whiskey). Seeing both at the same granularity, in the same period, is the analytical edge.';
html += '<div class="onprem-callout" style="margin-top:14px;">' + proof + '</div>';
mount.innerHTML = html;
}

