// Cross-correlation peak lag (months). Positive = on-prem leads off-prem.
diffusion: { lag: 1, confidence: 'low', correlation: 0.21 },
// Margin pool: % of category dollar volume from on-premise, then vs 24 months ago
margin: { onPct: 31, onPctPrior: 38, direction: 'to-off' },
// Premium index per channel
asymmetry: { onPrem: 1.18, offPrem: 1.14 },
// 24-month rolling on-prem index (starts ~95, ends ~105). For the diffusion timing chart
