diffusion: { lag: -4, confidence: 'med', correlation: 0.58 },
margin: { onPct: 24, onPctPrior: 28, direction: 'to-off' },
asymmetry: { onPrem: 0.84, offPrem: 0.88 },
onCurve: [105, 104, 104, 103, 103, 102, 102, 101, 101, 100, 100, 99, 99, 98, 98, 97, 97, 96, 96, 95, 95, 94, 94, 93],
