// === Flip-table builders for on-prem and off-prem charts ===

function buildHeatmapFlipTable(elId,heatData,cats){
let html='<table><thead><tr><th>Sub-channel</th>';
cats.forEach(function(c){html+='<th class="num">'+c+'</th>';});
html+='</tr></thead><tbody>';
Object.keys(heatData).forEach(function(channel){
html+='<tr><td>'+channel+'</td>';
cats.forEach(function(c){
const v=heatData[channel][c];
const cls=v>=0?'pos':'neg';
const sign=v>=0?'+':'';
html+='<td class="num '+cls+'">'+sign+v+'%</td>';
});
html+='</tr>';
});
html+='</tbody></table>';
document.getElementById(elId).innerHTML=html;
}

function buildTrajectoryFlipTable(elId,trajData){
let html='<table><thead><tr><th>Sub-channel</th><th class="num">M-24</th><th class="num">M-12</th><th class="num">Current</th><th class="num">Peak</th><th class="num">Trough</th><th class="num">Net change</th></tr></thead><tbody>';
Object.keys(trajData).forEach(function(channel){
const series=trajData[channel];
const start=series[0];
const mid=series[12];
const current=series[series.length-1];
const peak=Math.max.apply(null,series);
const trough=Math.min.apply(null,series);
const net=current-start;
const netCls=net>=0?'pos':'neg';
const netSign=net>=0?'+':'';
html+='<tr><td>'+channel+'</td>';
html+='<td class="num">'+start+'</td>';
html+='<td class="num">'+mid+'</td>';
html+='<td class="num">'+current+'</td>';
html+='<td class="num">'+peak+'</td>';
html+='<td class="num">'+trough+'</td>';
html+='<td class="num '+netCls+'">'+netSign+net+'</td>';
html+='</tr>';
});
html+='</tbody></table>';
document.getElementById(elId).innerHTML=html;
}

function buildAcctClassFlipTable(elId,data){
let html='<table><thead><tr><th>Sub-channel</th><th class="num">A %</th><th class="num">B %</th><th class="num">C %</th><th class="num">D %</th><th class="num">A+B %</th></tr></thead><tbody>';
data.forEach(function(row){
const ab=row.a+row.b;
html+='<tr><td>'+row.channel+'</td>';
html+='<td class="num">'+row.a+'</td>';
html+='<td class="num">'+row.b+'</td>';
html+='<td class="num">'+row.c+'</td>';
html+='<td class="num">'+row.d+'</td>';
html+='<td class="num" style="font-weight:600;">'+ab+'</td>';
html+='</tr>';
});
html+='</tbody></table>';
document.getElementById(elId).innerHTML=html;
}

function buildNewitemFlipTable(elId,data){
let html='<table><thead><tr><th>Sub-channel</th><th class="num">Days to 100 accounts</th><th>Adoption speed</th></tr></thead><tbody>';
data.forEach(function(row){
const speedLabel=row.speed==='fast'?'Fast':(row.speed==='mid'?'Mid':'Slow');
const speedColor=row.speed==='fast'?'#2e7d57':(row.speed==='mid'?'#d97706':'#b8402b');
html+='<tr><td>'+row.channel+'</td>';
html+='<td class="num">'+row.days+'</td>';
html+='<td style="color:'+speedColor+';font-weight:500;">'+speedLabel+'</td>';
html+='</tr>';
});
html+='</tbody></table>';
document.getElementById(elId).innerHTML=html;
}

