function escapeHTML(s){ return (s||'').replace(/[&<>"]/g,function(c){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c];}); }
function highlightMatch(text, query){
if(!query) return escapeHTML(text);
const re = new RegExp('(' + query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ')','gi');
return escapeHTML(text).replace(re,'<mark>$1</mark>');
}

function runGlobalSearch(query){
const results = document.getElementById('global-search-results');
if(!results) return;
const q = (query||'').trim().toLowerCase();
if(q.length === 0){ results.style.display='none'; return; }
// Score each entry: title match (3x), desc match (2x), keywords match (1x)
const scored = SEARCH_INDEX.map(function(e){
const t = e.title.toLowerCase();
const d = e.desc.toLowerCase();
const k = e.keywords.toLowerCase();
let score = 0;
if(t.indexOf(q) >= 0) score += 30 + (t.indexOf(q) === 0 ? 10 : 0);
if(d.indexOf(q) >= 0) score += 12;
if(k.indexOf(q) >= 0) score += 6;
// Word match bonus
q.split(/\s+/).forEach(function(w){ if(w.length<2)return; if(t.indexOf(w)>=0)score+=4; if(k.indexOf(w)>=0)score+=2; });
return {entry:e, score:score};
}).filter(function(s){ return s.score > 0; }).sort(function(a,b){ return b.score - a.score; }).slice(0, 8);

if(scored.length === 0){
results.innerHTML = '<div class="gs-empty"><strong>No matches</strong>Try a category name, a sub-channel, or a methodology term.</div>';
results.style.display = 'block';
return;
}
// Group results by group
const grouped = {};
scored.forEach(function(s){
const g = s.entry.group || 'Views';
if(!grouped[g]) grouped[g] = [];
grouped[g].push(s.entry);
});
let html = '';
Object.keys(grouped).forEach(function(g){
html += '<div class="gs-result-group">'+escapeHTML(g)+'</div>';
grouped[g].forEach(function(e){
html += '<div class="gs-result" data-view="'+e.view+'">';
html += '<div class="gs-result-title">'+highlightMatch(e.title,q)+'</div>';
html += '<div class="gs-result-meta">'+highlightMatch(e.desc,q)+'</div>';
html += '</div>';
});
});
results.innerHTML = html;
results.style.display = 'block';
results.querySelectorAll('.gs-result').forEach(function(r){
r.addEventListener('click', function(){
const view = r.dataset.view;
const navLink = document.querySelector('.nav-subitem[data-view="'+view+'"]');
if(navLink) navLink.click();
results.style.display = 'none';
document.getElementById('global-search-input').value = '';
});
});
}

function setupGlobalSearch(){
const input = document.getElementById('global-search-input');
const wrap = document.getElementById('global-search-wrap');
const results = document.getElementById('global-search-results');
if(!input || !results) return;
input.addEventListener('input', function(){ runGlobalSearch(input.value); });
input.addEventListener('focus', function(){ if(input.value.trim()) runGlobalSearch(input.value); });
input.addEventListener('keydown', function(e){
if(e.key === 'Escape'){ results.style.display='none'; input.blur(); }
if(e.key === 'Enter'){
const first = results.querySelector('.gs-result');
if(first) first.click();
}
});
// Click outside to close
document.addEventListener('click', function(e){
if(!wrap.contains(e.target)) results.style.display = 'none';
});
}

// === Bookmarks · Share · Team activity ===
let BOOKMARKS = [];
try { BOOKMARKS = JSON.parse(localStorage.getItem('sipsourceBookmarks') || '[]'); } catch(e){ BOOKMARKS = []; }
function saveBookmarks(){ try { localStorage.setItem('sipsourceBookmarks', JSON.stringify(BOOKMARKS)); } catch(e){} }

function captureViewState(viewId){
const state = {view:viewId, ts:Date.now()};
if(viewId === 'headroom' && typeof HR_STATE !== 'undefined'){
state.filters = {cat:HR_STATE.cat, channel:HR_STATE.channel, subch:HR_STATE.subch, period:HR_STATE.period, scope:HR_STATE.scope};
state.label = (HEADROOM_CATEGORIES.find(function(c){return c.k===HR_STATE.cat;})||{}).n + ' · ' + (HR_STATE.channel==='both'?'Both channels':(HR_STATE.channel==='onprem'?'On-prem':'Off-prem')) + ' · ' + HR_STATE.subch + ' · ' + (HR_STATE.scope==='mybook'?'My book':(HR_STATE.scope==='overlay'?'Overlay':'Industry'));
}else if(viewId === 'builder'){
state.filters = {rows:RB_STATE.rows, columns:RB_STATE.columns, filters:RB_STATE.filters, measures:RB_STATE.measures};
state.label = 'Report: '+(RB_STATE.rows.length>0?'by '+RB_STATE.rows.join('+'):'no rows')+' · '+(RB_STATE.measures.length>0?RB_STATE.measures.length+' measure(s)':'no measures');
}else{
state.label = viewId;
}
return state;
}

function applyViewState(state){
if(!state || !state.view) return;
if(state.view === 'headroom' && state.filters && typeof HR_STATE !== 'undefined'){
HR_STATE.cat = state.filters.cat || HR_STATE.cat;
HR_STATE.channel = state.filters.channel || HR_STATE.channel;
HR_STATE.subch = state.filters.subch || HR_STATE.subch;
HR_STATE.period = state.filters.period || HR_STATE.period;
HR_STATE.scope = state.filters.scope || HR_STATE.scope;
}
if(state.view === 'builder' && state.filters && typeof RB_STATE !== 'undefined'){
RB_STATE.rows = state.filters.rows || [];
RB_STATE.columns = state.filters.columns || [];
RB_STATE.filters = state.filters.filters || [];
RB_STATE.measures = state.filters.measures || [];
}
const navLink = document.querySelector('.nav-subitem[data-view="'+state.view+'"]');
if(navLink) navLink.click();
// Re-render the specific view
setTimeout(function(){
if(state.view === 'headroom' && typeof renderHeadroom === 'function') renderHeadroom();
if(state.view === 'builder' && typeof rbRenderAll === 'function') rbRenderAll();
}, 100);
}

function addBookmark(viewId){
const state = captureViewState(viewId);
state.id = 'bk-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);
BOOKMARKS.unshift(state);
saveBookmarks();
showActionToast && showActionToast('Bookmark saved · '+BOOKMARKS.length+' total');
updateBookmarkButtons();
}
function removeBookmark(id){
BOOKMARKS = BOOKMARKS.filter(function(b){ return b.id !== id; });
saveBookmarks();
renderBookmarksModal();
updateBookmarkButtons();
}

function updateBookmarkButtons(){
document.querySelectorAll('.bookmark-btn[data-bookmark-view]').forEach(function(btn){
const v = btn.dataset.bookmarkView;
const matched = BOOKMARKS.some(function(b){ return b.view === v; });
if(matched){ btn.classList.add('saved'); btn.innerHTML = '<span class="bk-icon">★</span>Bookmarked'; }
else{ btn.classList.remove('saved'); btn.innerHTML = '<span class="bk-icon">★</span>Save bookmark'; }
});
}

function buildShareURL(viewId){
const state = captureViewState(viewId);
const params = new URLSearchParams();
params.set('view', viewId);
if(state.filters){
Object.keys(state.filters).forEach(function(k){
const v = state.filters[k];
if(typeof v === 'string') params.set(k, v);
else if(Array.isArray(v)) params.set(k, JSON.stringify(v));
});
}
return window.location.origin + window.location.pathname + '#' + params.toString();
}

function copyShareURL(viewId){
const url = buildShareURL(viewId);
if(navigator.clipboard && navigator.clipboard.writeText){
navigator.clipboard.writeText(url).then(function(){
showActionToast && showActionToast('Link copied · paste anywhere to share this exact view');
}).catch(function(){
prompt('Copy this link:', url);
});
}else{
prompt('Copy this link:', url);
}
}

function applyURLState(){
const hash = window.location.hash.slice(1);
if(!hash) return;
const params = new URLSearchParams(hash);
const view = params.get('view');
if(!view) return;
const filters = {};
params.forEach(function(v, k){ if(k!=='view') filters[k] = v; });
applyViewState({view:view, filters:filters});
}

