const RB_STATE = {
rows:['category'], columns:[], filters:[], measures:['uom:vol9l:growth','headroom_pt'], rowLevel:false, factEngine:true,
viz:'table', timeInterval:'single', periodWindow:'r12', periodGrain:'month', timePreset:'', calculated:[], groupings:[], annotations:[]
};
const RB_DEFAULT = JSON.parse(JSON.stringify(RB_STATE));

// =====================================================================
// Worksheet system — RB_STATE is the live state for the ACTIVE sheet.
// RB_SHEETS holds every sheet's state. Switching sheets saves the current
// RB_STATE into the active slot, then loads the target slot into RB_STATE.
// =====================================================================
const RB_SHEETS = { sheets: [], activeIdx: 0 };
const RB_SHEETS_KEY = 'sipsource_rb_sheets';

function rbCloneState(s){ return JSON.parse(JSON.stringify(s)); }
function rbSheetsLoad(){
try {
const raw = localStorage.getItem(RB_SHEETS_KEY);
if(raw){
const parsed = JSON.parse(raw);
if(parsed && parsed.sheets && parsed.sheets.length){
RB_SHEETS.sheets = parsed.sheets;
RB_SHEETS.activeIdx = Math.min(parsed.activeIdx || 0, parsed.sheets.length - 1);
return true;
}
}
// Migration path: if the old single-sheet key has data, fold it into a one-sheet workbook
const legacy = JSON.parse(localStorage.getItem('sipsourceRBState') || 'null');
if(legacy && legacy.rows){
RB_SHEETS.sheets = [{ id: 'sheet_' + Date.now(), name: 'Sheet 1', state: legacy }];
RB_SHEETS.activeIdx = 0;
return true;
}
} catch(_){}
// Brand-new user: seed with one default sheet
RB_SHEETS.sheets = [{ id: 'sheet_' + Date.now(), name: 'Sheet 1', state: rbCloneState(RB_DEFAULT) }];
RB_SHEETS.activeIdx = 0;
return false;
}
function rbSheetsSave(){
// Snapshot the live RB_STATE into the active sheet, then persist the whole workbook
const idx = RB_SHEETS.activeIdx;
if(RB_SHEETS.sheets[idx]) RB_SHEETS.sheets[idx].state = rbCloneState(RB_STATE);
try { localStorage.setItem(RB_SHEETS_KEY, JSON.stringify(RB_SHEETS)); } catch(_){}
}
function rbSheetsLoadActiveIntoState(){
const sheet = RB_SHEETS.sheets[RB_SHEETS.activeIdx];
if(!sheet) return;
const s = sheet.state || rbCloneState(RB_DEFAULT);
Object.keys(RB_STATE).forEach(function(k){ delete RB_STATE[k]; });
Object.assign(RB_STATE, rbCloneState(s));
// Ensure shape — older sheets may be missing newer fields
if(!RB_STATE.rows) RB_STATE.rows = [];
if(!RB_STATE.columns) RB_STATE.columns = [];
if(!RB_STATE.filters) RB_STATE.filters = [];
if(!RB_STATE.measures) RB_STATE.measures = [];
if(!RB_STATE.calculated) RB_STATE.calculated = [];
if(!RB_STATE.parameters) RB_STATE.parameters = [];
if(!RB_STATE.groupings) RB_STATE.groupings = [];
if(typeof rbSyncGroupedDims === 'function') rbSyncGroupedDims();
if(!RB_STATE.viz) RB_STATE.viz = 'table';
if(!RB_STATE.timeInterval) RB_STATE.timeInterval = 'single';
}
function rbSheetsSwitch(targetIdx){
if(targetIdx === RB_SHEETS.activeIdx) return;
if(targetIdx < 0 || targetIdx >= RB_SHEETS.sheets.length) return;
// Snapshot current state into the leaving sheet
const cur = RB_SHEETS.sheets[RB_SHEETS.activeIdx];
if(cur) cur.state = rbCloneState(RB_STATE);
RB_SHEETS.activeIdx = targetIdx;
rbSheetsLoadActiveIntoState();
rbSheetsSave();
// Reset undo/redo on sheet switch — undo within a sheet shouldn't cross sheet boundaries
if(typeof RB_UNDO_STACK !== 'undefined'){ RB_UNDO_STACK.length = 0; RB_REDO_STACK.length = 0; if(typeof rbUpdateUndoButtons === 'function') rbUpdateUndoButtons(); }
rbSheetsRenderTabs();
if(typeof rbRenderAll === 'function') rbRenderAll();
if(typeof rbCellsSyncPanel === 'function') rbCellsSyncPanel();
}
function rbSheetsAdd(){
// Save current state first
const cur = RB_SHEETS.sheets[RB_SHEETS.activeIdx];
if(cur) cur.state = rbCloneState(RB_STATE);
// Compute a non-colliding sheet name like "Sheet 2"
const existingNames = RB_SHEETS.sheets.map(function(s){ return s.name; });
let n = RB_SHEETS.sheets.length + 1;
while(existingNames.indexOf('Sheet ' + n) >= 0) n++;
var _blank = rbCloneState(RB_DEFAULT); _blank.rows=[]; _blank.columns=[]; _blank.measures=[]; _blank.viz='table'; _blank._titleOverride=''; 
const newSheet = { id: 'sheet_' + Date.now() + '_' + n, name: 'Sheet ' + n, state: _blank };
RB_SHEETS.sheets.push(newSheet);
RB_SHEETS.activeIdx = RB_SHEETS.sheets.length - 1;
rbSheetsLoadActiveIntoState();
rbSheetsSave();
if(typeof RB_UNDO_STACK !== 'undefined'){ RB_UNDO_STACK.length = 0; RB_REDO_STACK.length = 0; if(typeof rbUpdateUndoButtons === 'function') rbUpdateUndoButtons(); }
rbSheetsRenderTabs();
if(typeof rbRenderAll === 'function') rbRenderAll();
if(typeof rbCellsSyncPanel === 'function') rbCellsSyncPanel();
if(typeof showActionToast === 'function') showActionToast('New sheet \u2014 ' + newSheet.name);
}
function rbSheetsDuplicate(idx){
const src = RB_SHEETS.sheets[idx];
if(!src) return;
// If duplicating the active sheet, snapshot current live state first
if(idx === RB_SHEETS.activeIdx) src.state = rbCloneState(RB_STATE);
const copy = { id: 'sheet_' + Date.now() + '_copy', name: src.name + ' copy', state: rbCloneState(src.state) };
RB_SHEETS.sheets.splice(idx + 1, 0, copy);
RB_SHEETS.activeIdx = idx + 1;
rbSheetsLoadActiveIntoState();
rbSheetsSave();
rbSheetsRenderTabs();
if(typeof rbRenderAll === 'function') rbRenderAll();
if(typeof showActionToast === 'function') showActionToast('Duplicated \u2014 ' + copy.name);
}
function rbSheetsDelete(idx){
if(RB_SHEETS.sheets.length <= 1){ if(typeof showActionToast === 'function') showActionToast('Can\'t delete the last sheet'); return; }
const removing = RB_SHEETS.sheets[idx];
if(!removing) return;
const wasActive = idx === RB_SHEETS.activeIdx;
RB_SHEETS.sheets.splice(idx, 1);
if(RB_SHEETS.activeIdx >= RB_SHEETS.sheets.length) RB_SHEETS.activeIdx = RB_SHEETS.sheets.length - 1;
else if(idx < RB_SHEETS.activeIdx) RB_SHEETS.activeIdx--;
if(wasActive) rbSheetsLoadActiveIntoState();
rbSheetsSave();
rbSheetsRenderTabs();
if(wasActive && typeof rbRenderAll === 'function') rbRenderAll();
if(typeof showActionToast === 'function') showActionToast('Removed \u2014 ' + removing.name);
}
function rbSheetNameNeedsQuote(name){ return !/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(name)); }
function rbSheetRewriteSheetRefs(formula, oldName, newName){ if(typeof formula!=='string' || formula.charAt(0)!=='=') return formula; var oldLc=String(oldName).trim().toLowerCase(); var newRef=rbSheetNameNeedsQuote(newName)?("'"+String(newName).replace(/'/g,"''")+"'"):String(newName); var parts=formula.split('"'); for(var i=0;i<parts.length;i+=2){ parts[i]=parts[i].replace(/('(?:[^']|'')*'|[A-Za-z_][A-Za-z0-9_]*)\s*!/g, function(m, tok){ var nm=tok; if(nm.charAt(0)==="'") nm=nm.slice(1,-1).replace(/''/g,"'"); if(nm.trim().toLowerCase()===oldLc) return newRef+'!'; return m; }); } return parts.join('"'); }
function rbSheetRenameUpdateRefs(oldName, newName){ if(String(oldName)===String(newName)) return; try{ for(var i=0;i<RB_SHEETS.sheets.length;i++){ var sh=RB_SHEETS.sheets[i]; if(!sh||!sh.id) continue; var key=RB_CELLS_KEY+'_'+sh.id; var data; try{ data=JSON.parse(localStorage.getItem(key)||'null'); }catch(_){ data=null; } if(!data) continue; var changed=false; if(data.cells){ for(var addr in data.cells){ var raw=data.cells[addr]; if(typeof raw==='string' && raw.charAt(0)==='='){ var nw=rbSheetRewriteSheetRefs(raw, oldName, newName); if(nw!==raw){ data.cells[addr]=nw; changed=true; } } } } if(data.condFormats){ for(var ci=0;ci<data.condFormats.length;ci++){ var cf=data.condFormats[ci]; if(cf && cf.kind==='formula' && typeof cf.expr==='string'){ var ex=cf.expr.charAt(0)==='='?cf.expr:('='+cf.expr); var ne=rbSheetRewriteSheetRefs(ex, oldName, newName); if(ne!==ex){ cf.expr=(cf.expr.charAt(0)==='=')?ne:ne.slice(1); changed=true; } } } } if(changed) localStorage.setItem(key, JSON.stringify(data)); } }catch(_){} }
function rbSheetsRename(idx, newName){
const s = RB_SHEETS.sheets[idx];
if(!s) return;
const trimmed = (newName || '').trim();
if(!trimmed) return;
const oldName = s.name;
const finalName = trimmed.slice(0, 32); // cap length to keep tab bar tidy
if(oldName !== finalName){ rbSheetRenameUpdateRefs(oldName, finalName); }
s.name = finalName;
rbSheetsSave();
rbSheetsRenderTabs();
if(typeof rbRenderCells==='function') rbRenderCells();
}
function rbSheetsRenderTabs(){
const wsContainer = document.getElementById('rb-worksheets');
if(!wsContainer) return;
const addBtn = document.getElementById('rb-worksheet-add');
// Remove all existing tabs (preserve the add button)
Array.from(wsContainer.querySelectorAll('.rb-worksheet-tab')).forEach(function(t){ t.remove(); });
RB_SHEETS.sheets.forEach(function(sheet, i){
const tab = document.createElement('button');
tab.className = 'rb-worksheet-tab' + (i === RB_SHEETS.activeIdx ? ' active' : '');
tab.dataset.sheet = String(i);
tab.title = 'Click to open · double-click to rename';
// Tab content: label + close X (close only shown if >1 sheet)
const label = document.createElement('span');
label.className = 'rb-worksheet-tab-label';
label.textContent = sheet.name;
tab.appendChild(label);
if(RB_SHEETS.sheets.length > 1){
const closeBtn = document.createElement('span');
closeBtn.className = 'rb-worksheet-tab-close';
closeBtn.innerHTML = '\u00d7';
closeBtn.title = 'Remove sheet';
closeBtn.addEventListener('click', function(e){
e.stopPropagation();
hoodieConfirm({danger:true, title:'Remove \u201C' + sheet.name + '\u201D?', body:'This cannot be undone.', confirmLabel:'Remove', onConfirm:function(){ rbSheetsDelete(i); }});
});
tab.appendChild(closeBtn);
}
tab.addEventListener('click', function(){ rbSheetsSwitch(i); });
// Double-click to rename in place
tab.addEventListener('dblclick', function(e){
e.preventDefault();
const input = document.createElement('input');
input.type = 'text';
input.value = sheet.name;
input.className = 'rb-worksheet-tab-rename';
input.style.cssText = 'background:transparent;border:none;border-bottom:1px solid var(--dash-accent,#4E79A7);color:var(--dash-accent,#4E79A7);font-size:11px;font-weight:700;font-family:inherit;width:' + Math.max(50, sheet.name.length * 7) + 'px;outline:none;padding:0;';
label.replaceWith(input);
input.focus();
input.select();
const commit = function(){ rbSheetsRename(i, input.value); };
input.addEventListener('blur', commit);
input.addEventListener('keydown', function(ev){
if(ev.key === 'Enter'){ ev.preventDefault(); input.blur(); }
else if(ev.key === 'Escape'){ input.value = sheet.name; input.blur(); }
});
});
// Right-click context menu for duplicate/rename
tab.addEventListener('contextmenu', function(e){
e.preventDefault();
rbSheetsShowContextMenu(e.clientX, e.clientY, i);
});
wsContainer.insertBefore(tab, addBtn);
});
}
function rbSheetsShowContextMenu(x, y, sheetIdx){
// Remove any existing menu
const existing = document.querySelector('.rb-worksheet-ctx-menu');
if(existing) existing.remove();
const menu = document.createElement('div');
menu.className = 'rb-worksheet-ctx-menu';
menu.style.cssText = 'position:fixed;left:' + x + 'px;top:' + y + 'px;background:#fff;border:1px solid #d4d4d8;border-radius:5px;box-shadow:0 6px 22px rgba(0,0,0,0.18);padding:5px 0;z-index:9000;font-size:12px;min-width:160px;';
const items = [
{ label: 'Rename', action: function(){
const tab = document.querySelectorAll('#rb-worksheets .rb-worksheet-tab')[sheetIdx];
if(tab) tab.dispatchEvent(new MouseEvent('dblclick'));
}},
{ label: 'Duplicate', action: function(){ rbSheetsDuplicate(sheetIdx); }}
];
if(RB_SHEETS.sheets.length > 1){
items.push({ label: 'Remove', action: function(){
hoodieConfirm({danger:true, title:'Remove \u201C' + RB_SHEETS.sheets[sheetIdx].name + '\u201D?', body:'This cannot be undone.', confirmLabel:'Remove', onConfirm:function(){ rbSheetsDelete(sheetIdx); }});
}, danger: true });
}
items.forEach(function(item){
const opt = document.createElement('div');
opt.style.cssText = 'padding:7px 14px;cursor:pointer;color:' + (item.danger ? '#b8402b' : '#1a1a1a') + ';';
opt.textContent = item.label;
opt.addEventListener('mouseenter', function(){ opt.style.background = item.danger ? '#fef0ed' : '#f5f5f7'; });
opt.addEventListener('mouseleave', function(){ opt.style.background = 'transparent'; });
opt.addEventListener('click', function(){ menu.remove(); item.action(); });
menu.appendChild(opt);
});
document.body.appendChild(menu);
const dismiss = function(ev){ if(!menu.contains(ev.target)){ menu.remove(); document.removeEventListener('click', dismiss); } };
setTimeout(function(){ document.addEventListener('click', dismiss); }, 0);
}

// Initialize the workbook on script load
rbSheetsLoad();
rbSheetsLoadActiveIntoState();

function rbSaveState(){
// Persist BOTH the legacy single-state key (for any old code still reading it) AND the workbook
try { localStorage.setItem('sipsourceRBState', JSON.stringify(RB_STATE)); } catch(e){}
rbSheetsSave();
}

// === Undo/Redo for Report Builder =========================================
const RB_UNDO_STACK = [];
const RB_REDO_STACK = [];
const RB_UNDO_LIMIT = 50;
let _rbHistoryMuted = false; // true while we're applying undo/redo (so the apply doesn't push to stack)
function rbStateSnapshot(){ return JSON.parse(JSON.stringify(RB_STATE)); }
function rbPushHistory(){
if(_rbHistoryMuted) return;
const snap = rbStateSnapshot();
const last = RB_UNDO_STACK[RB_UNDO_STACK.length - 1];
// Skip duplicate consecutive snapshots
if(last && JSON.stringify(last) === JSON.stringify(snap)) return;
RB_UNDO_STACK.push(snap);
if(RB_UNDO_STACK.length > RB_UNDO_LIMIT) RB_UNDO_STACK.shift();
// Any new change clears the redo stack
RB_REDO_STACK.length = 0;
rbUpdateUndoButtons();
}
function rbUndo(){
if(RB_UNDO_STACK.length < 2) return; // need at least one prior + current
const current = RB_UNDO_STACK.pop();
RB_REDO_STACK.push(current);
const target = RB_UNDO_STACK[RB_UNDO_STACK.length - 1];
_rbHistoryMuted = true;
Object.keys(RB_STATE).forEach(function(k){ delete RB_STATE[k]; });
Object.assign(RB_STATE, JSON.parse(JSON.stringify(target)));
rbRenderAll();
_rbHistoryMuted = false;
rbUpdateUndoButtons();
if(typeof showActionToast === 'function') showActionToast('Undo');
}
function rbRedo(){
if(RB_REDO_STACK.length === 0) return;
const target = RB_REDO_STACK.pop();
RB_UNDO_STACK.push(JSON.parse(JSON.stringify(target)));
_rbHistoryMuted = true;
Object.keys(RB_STATE).forEach(function(k){ delete RB_STATE[k]; });
Object.assign(RB_STATE, JSON.parse(JSON.stringify(target)));
rbRenderAll();
_rbHistoryMuted = false;
rbUpdateUndoButtons();
if(typeof showActionToast === 'function') showActionToast('Redo');
}
function rbUpdateUndoButtons(){
const u = document.getElementById('rb-undo-btn');
const r = document.getElementById('rb-redo-btn');
if(u) u.disabled = RB_UNDO_STACK.length < 2;
if(r) r.disabled = RB_REDO_STACK.length === 0;
}
// Initial push so the first user action has a baseline to revert to
function rbInitHistory(){ if(RB_UNDO_STACK.length === 0) RB_UNDO_STACK.push(rbStateSnapshot()); rbUpdateUndoButtons(); }

