RB_STATE.groupings = RB_STATE.groupings || [];
const id = 'grp_' + Math.random().toString(36).slice(2,8);
RB_STATE.groupings.push({id: id, key: id, label: (_rbGroupDraft.label || 'Group').trim(), base: _rbGroupDraft.base, groups: _rbGroupDraft.groups, includeOthers: _rbGroupDraft.includeOthers});
