// ===== Index toggle: % measures rebased to 100 = column average =====
var RB_INDEX_REF = {};
function rbBuildIndexRefs(model){
  RB_INDEX_REF = {};
  if(!RB_STATE.indexMode || !model || !model.rowCombos || !model.measureDefs) return;
  model.measureDefs.forEach(function(m){
    if(m.type !== 'percent') return;
    var sum=0, cnt=0;
    model.rowCombos.forEach(function(rc){
      try{
        var dims=rbDimsFor(rc, null, model);
        var raw=rbComputeWithMod(m.key, dims, m.mod, m.window, m.scope);
        var n=parseFloat(String(raw).replace(/[+%pt,$]/g,''));
        if(!isNaN(n)){ sum+=n; cnt++; }
      }catch(e){}
    });
    if(cnt>0){ var mean=sum/cnt; RB_INDEX_REF[m.key]=(Math.abs(mean)>=1)?mean:null; }
  });
}
function rbToggleIndex(){
  RB_STATE.indexMode = !RB_STATE.indexMode;
  try{ localStorage.setItem('rb_index_mode', RB_STATE.indexMode?'1':'0'); }catch(_){}
  var b=document.getElementById('rb-index-btn'); if(b) b.classList.toggle('active', !!RB_STATE.indexMode);
  if(typeof rbRenderAll==='function') rbRenderAll();
}

function hoodieGenShare(age){
  age = age || 39;
  var d = (age - 39) / 12;
  var genz = Math.max(0.04, 0.16 - d*0.07);
  var mill = Math.max(0.08, 0.30 - d*0.06);
  var genx = Math.max(0.08, 0.27 + d*0.02);
  var boom = Math.max(0.08, 0.27 + d*0.11);
  var sum = genz+mill+genx+boom;
  return { genz:genz/sum, millennial:mill/sum, genx:genx/sum, boomer:boom/sum };
}
