const rowDim = RB_STATE.rows.filter(function(k){return k!=='period';})[0] || null;
let rowVals;
if(rowDim){ const def = RB_FIELDS.dimensions.find(function(d){return d.key===rowDim;}); rowVals = ((def&&def.values)||[]).filter(function(v){return v.v!=='__all__'&&v.v!=='all';}); }
