  var DIV2REGION={new_england:'northeast',mid_atlantic:'northeast',e_n_central:'midwest',w_n_central:'midwest',south_atlantic:'south',e_s_central:'south',w_s_central:'south',mountain:'west',pacific:'west'};
  var DIV_STATES={new_england:['CT','ME','MA','NH','RI','VT'],mid_atlantic:['NJ','NY','PA'],e_n_central:['IL','IN','MI','OH','WI'],w_n_central:['IA','KS','MN','MO','NE','ND','SD'],south_atlantic:['DE','FL','GA','MD','NC','SC','VA','WV','DC'],e_s_central:['AL','KY','MS','TN'],w_s_central:['AR','LA','OK','TX'],mountain:['AZ','CO','ID','MT','NV','NM','UT','WY'],pacific:['AK','CA','HI','OR','WA']};
