// === Modifier display label & unit override ===
const RB_MOD_LABELS = {abs:'Abs', growth:'Growth', share:'Share', yoy:'YoY'};
function rbModLabel(mod){ mod=String(mod||''); if(mod.indexOf('cmp_target:')===0){ var t=mod.slice(11); return 'vs Target'+(t!==''?(' '+t):''); } return RB_MOD_LABELS[mod]||'Abs'; }
