// ===== Tableau-style PARAMETERS =====
function rbParamUid(){ return 'prm_' + Math.random().toString(36).slice(2,8); }
function rbParamValue(p){ if(!p) return NaN; if(p.type==='string'||p.type==='date') return String(p.current==null?'':p.current); if(p.type==='bool') return (p.current===true||p.current==='true'||p.current===1||p.current==='1')?1:0; var n=parseFloat(p.current); if(isNaN(n)) n=0; if(p.type==='int') n=Math.round(n); return n; }
