const isDashed = hasDualAxis && s.axis === 'right';
let path = 'M';
s.points.forEach(function(p, i){ path += (i === 0 ? '' : 'L') + xPos(i) + ',' + yPos(p.y) + ' '; });
svg += '<path d="' + path + '" fill="none" stroke="' + color + '" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"' + (isDashed ? ' stroke-dasharray="6,3"' : '') + '/>';
