const dims = rbDimsFor(rc, cc, model);
const v = parseFloat(String(rbComputeWithMod(m.key, dims, m.mod, m.window, m.scope)).replace(/[+%pt,]/g, ''));
values.push(isNaN(v) ? 0 : v);
