  var curLow=String(current||'').toLowerCase();
  var STD=['#b8402b','#e74c3c','#e67e22','#f1c40f','#2ecc71','#1abc9c','#3498db','#2c3e50','#8e44ad','#7f8c8d','#000000','#ffffff'];
