    var eyeBtn = window.EyeDropper ? '<button class="rb-cp-eyedrop" id="rb-cp-eye" title="Pick from screen"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#46586a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m2 22 1-1h3l9-9"></path><path d="M3 21v-3l9-9"></path><path d="m15 6 3.4-3.4a2.1 2.1 0 1 1 3 3L18 9l.4.4a2.1 2.1 0 1 1-3 3l-3.8-3.8a2.1 2.1 0 1 1 3-3l.4.4Z"></path></svg></button>' : '';
