// Convert hex grid coords to SVG x/y. Uses pointy-top hex orientation with offset rows.
function rbHexXY(row, col, size){
const w = size * Math.sqrt(3); // hex width (pointy-top)
const h = size * 2;
const xOffset = (row % 2) * (w / 2);
return { cx: col * w + xOffset + size, cy: row * h * 0.75 + size };
}

// SVG path for a pointy-top hexagon centered at (cx, cy)
function rbHexPath(cx, cy, size){
const points = [];
for(let i = 0; i < 6; i++){
const angle = Math.PI / 6 + i * Math.PI / 3; // pointy-top
points.push((cx + size * Math.cos(angle)).toFixed(1) + ',' + (cy + size * Math.sin(angle)).toFixed(1));
}
return points.join(' ');
}

