// ===== Inline editing (Excel/Tableau-style) — field aliases, member aliases, cell overrides, editable title/subtitle =====
function rbUnesc(s){ return String(s == null ? '' : s).replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&'); }
