input.type = 'text'; input.className = 'rb-inline-edit-input'; input.value = cur;
input.style.textAlign = (type === 'cell') ? 'right' : 'left';
el.setAttribute('data-prev-html', el.innerHTML);
el.innerHTML = ''; el.appendChild(input);
input.focus(); input.select();
