/* ===== Refactor Phase 1 — unified state scaffold (additive; nothing depends on it yet) =====
   This establishes the single-source-of-truth seam from the production blueprint without
   touching the working RB_STATE / QBR_STATE / QR_STATE wiring. Phase 2 replaces the legacy
   stores with this one and makes siCompute() the single pure calc path. */
var SI_STORE = (function(){
var state=null, version=0, subs=[];
function snapshot(){
return {
version: version,
filterContext: (typeof QR_STATE!=='undefined' && QR_STATE.filters) ? QR_STATE.filters.slice() : [],
worksheet: (typeof RB_STATE!=='undefined') ? {rows:RB_STATE.rows.slice(), columns:RB_STATE.columns.slice(), measures:RB_STATE.measures.slice(), viz:RB_STATE.viz, filters:(RB_STATE.filters||[]).slice()} : null,
deck: (QBR_STATE && QBR_STATE.slides) ? {slides:QBR_STATE.slides.length, loopDim:QBR_STATE.loopDim} : null,
period: (typeof RB_STATE!=='undefined') ? {window:RB_STATE.periodWindow, grain:RB_STATE.periodGrain} : null
};
}
return {
getState:function(){ if(!state) state=snapshot(); return state; },
refresh:function(){ state=snapshot(); version++; subs.forEach(function(f){ try{ f(state); }catch(_){ } }); return state; },
dispatch:function(){ return this.refresh(); },
subscribe:function(f){ subs.push(f); return function(){ var i=subs.indexOf(f); if(i>=0) subs.splice(i,1); }; },
compute:function(spec){ return (typeof siCompute==='function') ? siCompute(spec || (this.getState().worksheet)) : null; }
};
})();
// Phase 1 seam (live). Phase 2: inline the engine + memoize by hash(filterContext + spec).
function siCompute(spec){
// Phase-1 compute seam: produce the canonical model for a declarative spec by routing through
// the existing engine (rbBuildDataModel), so the result is identical BY CONSTRUCTION to what the
// Report Builder renders today. Phase 2 inlines the engine here and points every projection at it.
if(typeof rbBuildDataModel!=='function' || typeof RB_STATE==='undefined') return null;
spec=spec||{};
var temp={};
if(spec.rows) temp.rows=spec.rows.slice();
if(spec.columns) temp.columns=spec.columns.slice();
if(spec.measures) temp.measures=spec.measures.slice();
if(spec.filters) temp.filters=spec.filters.slice();
if(spec.viz) temp.viz=spec.viz;
if(spec.period){ if(spec.period.window) temp.periodWindow=spec.period.window; if(spec.period.grain) temp.periodGrain=spec.period.grain; }
// Delegate to the shared state-swap primitive the slide charts and maps already use, so there is
// exactly one compute path. Parity is guaranteed because this is the same engine they trust.
if(typeof qbrWithState==='function') return qbrWithState(temp, function(){ return rbBuildDataModel(); });
var keys=['rows','columns','measures','filters','viz','periodWindow','periodGrain'];
var saved={}; keys.forEach(function(k){ saved[k]=RB_STATE[k]; });
try{ Object.keys(temp).forEach(function(k){ RB_STATE[k]=temp[k]; }); return rbBuildDataModel(); }
finally{ keys.forEach(function(k){ RB_STATE[k]=saved[k]; }); }
}
// Parity check — run siComputeSelfTest() in the console. PASS proves the seam returns the same
// shape as the live builder for the current state (it must, since it calls the same engine).
function siComputeSelfTest(){
try{
var direct=rbBuildDataModel();
var seam=siCompute({rows:RB_STATE.rows, columns:RB_STATE.columns, measures:RB_STATE.measures, filters:RB_STATE.filters});
var ok=!!direct && !!seam && direct.rowCombos.length===seam.rowCombos.length && direct.colCombos.length===seam.colCombos.length && direct.measureDefs.length===seam.measureDefs.length;
if(typeof console!=='undefined') console.log('[siCompute parity] '+(ok?'PASS':'FAIL'), {rowCombos:direct.rowCombos.length, colCombos:direct.colCombos.length, measures:direct.measureDefs.length});
return ok;
}catch(e){ if(typeof console!=='undefined') console.warn('[siCompute parity] error', e); return false; }
}
/* ===== Backwards-compatibility: schema version + migration registry =====
   Phase 2 reshapes persisted state (saved reports, sheets, deck specs, share links) toward the
   unified model. So a report a distributor bookmarked months ago keeps opening cleanly, every
   schema change registers an ordered migration here; siRunMigrations() applies any the user is
   behind on, once, at load. Today CURRENT=1 with no migrations — this is the seam, not a no-op
   forever. */
var SI_SCHEMA_VERSION = 1;
var SI_VERSION_KEY = 'siSchemaVersion';
var SI_MIGRATIONS = {
// 2: function(){ /* e.g. rename a persisted RB_STATE field across all saved payloads */ }
};
// Per-payload upgrade for in-memory objects decoded from a share link or saved report.
// No-op at v1; Phase 2 adds version-keyed transforms so an older payload upgrades on read.
function siMigratePayload(obj){
if(!obj || typeof obj!=='object') return obj;
var v = (typeof obj.__v==='number') ? obj.__v : 0;
for(var i=v+1; i<=SI_SCHEMA_VERSION; i++){ if(typeof SI_MIGRATIONS[i]==='function'){ try{ obj = SI_MIGRATIONS[i](obj) || obj; }catch(_){ } } }
obj.__v = SI_SCHEMA_VERSION;
return obj;
}
// One-time localStorage migration sweep on load. Reads the stored schema version, applies any
// pending migrations in order, then stamps the current version.
function siRunMigrations(){
try{
var from = 0;
try{ from = parseInt(localStorage.getItem(SI_VERSION_KEY) || '0', 10) || 0; }catch(_){ from = 0; }
if(from >= SI_SCHEMA_VERSION) return;
for(var v = from + 1; v <= SI_SCHEMA_VERSION; v++){ if(typeof SI_MIGRATIONS[v] === 'function'){ try{ SI_MIGRATIONS[v](); }catch(_){ } } }
try{ localStorage.setItem(SI_VERSION_KEY, String(SI_SCHEMA_VERSION)); }catch(_){ }
}catch(_){ }
}
if(document.readyState !== 'loading') setTimeout(siRunMigrations, 0); else document.addEventListener('DOMContentLoaded', siRunMigrations);

