const breadcrumbEl = document.getElementById('rb-viz-breadcrumb');
const badgeEl = document.getElementById('rb-viz-type-badge');
if(!out) return;
var _rl=document.getElementById('rb-rowlevel-toggle');
if(_rl){ if(!_rl.dataset.wired){ _rl.dataset.wired='1'; _rl.addEventListener('click', function(){ RB_STATE.rowLevel=!RB_STATE.rowLevel; rbRenderAll(); }); } _rl.classList.toggle('active', !!RB_STATE.rowLevel); }
