const paras=_pptxPara([{t:card.label||'',sz:1100,color:muted,b:1,font:bodyFont}])+_pptxPara([{t:card.value||'',sz:3200,b:1,color:accent,font:headFont}])+(card.delta?_pptxPara([{t:card.delta,sz:1200,color:dColor,font:bodyFont}]):'');
