    if(ch==='"'){ var j=i+1, str=''; while(j<n && src[j]!=='"'){ if(src[j]==='\\'&&j+1<n){ str+=src[j+1]; j+=2; } else { str+=src[j]; j++; } } i=j+1; toks.push({t:'STR',v:str}); continue; }
    if(ch==="'"){ var sj=i+1, snm=''; while(sj<n && src[sj]!=="'"){ snm+=src[sj]; sj++; } sj++; if(src[sj]==='!'){ var si=sj+1; var sw=si; while(sw<n && /[A-Za-z0-9_$]/.test(src[sw])) sw++; var sr1=src.slice(si,sw); if(src[sw]===':'){ var sw2=sw+1; while(sw2<n && /[A-Za-z0-9_$]/.test(src[sw2])) sw2++; var sr2=src.slice(sw+1,sw2); var sa=rbSheetParseRef(sr1), sb=rbSheetParseRef(sr2); if(sa&&sb){ i=sw2; toks.push({t:'RANGE',a:sa,b:sb,sheet:snm}); continue; } } var sref=rbSheetParseRef(sr1); if(sref){ i=sw; toks.push({t:'REF',c:sref.c,r:sref.r,sheet:snm}); continue; } } return null; }
