  function next(){ return toks[pos++]; }
  function num(v){ if(rbSheetIsErr(v)) throw v; if(rbSheetIsRange(v)){ var f=v.flat[0]; return typeof f==='number'?f:(parseFloat(f)||0); } if(typeof v==='number') return v; if(typeof v==='string'){ var p=parseFloat(v.replace(/[,$%]/g,'')); return isNaN(p)?0:p; } return v?1:0; }
