  function pdate(v){ if(rbSheetIsRange(v)) v=v.flat[0]; if(v instanceof Date) return v; if(typeof v==='number'){ var ep=new Date(1899,11,30); ep.setDate(ep.getDate()+Math.trunc(v)); return ep; } var s=String(v).trim(); var m=/^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s); if(m) return new Date(+m[1], +m[2]-1, +m[3]); var d=new Date(s); return isNaN(d.getTime())?null:d; }
