  function concat(){ var l=sum(); while(peek()&&peek().t==='&'){ next(); var r=sum(); var ls=rbSheetIsRange(l)?l.flat[0]:l, rs=rbSheetIsRange(r)?r.flat[0]:r; l=String(ls==null?'':ls)+String(rs==null?'':rs); } return l; }
