    if(tk.t==='STR'){ next(); return tk.v; }
    if(tk.t==='REF'){ next(); return tk.sheet?(ctx.getX?ctx.getX(tk.sheet,tk.c,tk.r):rbSheetErr('#REF!')):ctx.get(tk.c,tk.r); }
    if(tk.t==='RANGE'){ next(); var rows=[],flatv=[]; var _rg=tk.sheet?function(cc,rr){ return ctx.getX?ctx.getX(tk.sheet,cc,rr):rbSheetErr('#REF!'); }:ctx.get; for(var rr=Math.min(tk.a.r,tk.b.r);rr<=Math.max(tk.a.r,tk.b.r);rr++){ var row=[]; for(var cc=Math.min(tk.a.c,tk.b.c);cc<=Math.max(tk.a.c,tk.b.c);cc++){ var cv=_rg(cc,rr); if(rbSheetIsErr(cv)) throw cv; row.push(cv); flatv.push(cv); } rows.push(row); } return {__rng:true,rows:rows,flat:flatv}; }
    if(tk.t==='ID'){ next(); if(peek()&&peek().t==='('){ return call(tk.v.toUpperCase()); } return rbSheetErr('#NAME?'); }
