  function critTest(v, crit){ crit=rbSheetIsRange(crit)?crit.flat[0]:crit; if(typeof crit==='string'){ var m=/^(<=|>=|<>|<|>|=)?(.*)$/.exec(crit.trim()); var op=m[1]||'=', rhs=m[2]; var rn=parseFloat(rhs); var vn=(typeof v==='number')?v:parseFloat(v); var numeric=!isNaN(rn)&&!isNaN(vn); switch(op){ case '=': return numeric?vn===rn:String(v)===rhs; case '<>': return numeric?vn!==rn:String(v)!==rhs; case '<': return numeric&&vn<rn; case '<=': return numeric&&vn<=rn; case '>': return numeric&&vn>rn; case '>=': return numeric&&vn>=rn; } return false; } return (typeof v==='number')?v===crit:String(v)===String(crit); }
