// Mock for prototype — engineering should replace with SSO/auth user + real org chart.
const TEAM_MEMBERS = [
{id:'u_chris', name:'Chris Lawson', initials:'CL', role:'VP Commercial Operations', managerId:'u_kevin', color:'#4E79A7'},
{id:'u_kevin', name:'Kevin Lawson', initials:'KL', role:'EVP, Strategy', managerId:'u_ceo', color:'#5b3d8a'},
{id:'u_sara',  name:'Sara Martinez', initials:'SM', role:'Director, Chain Accounts', managerId:'u_chris', color:'#2e7d57'},
{id:'u_mike',  name:'Mike Chen', initials:'MC', role:'Director, Field Sales', managerId:'u_chris', color:'#d97706'},
{id:'u_ana',   name:'Ana Patel', initials:'AP', role:'Trade Marketing Lead', managerId:'u_kevin', color:'#b8402b'},
{id:'u_jordan',name:'Jordan Reyes', initials:'JR', role:'Senior Analyst, BI', managerId:'u_sara', color:'#0891b2'}
];
const CURRENT_USER_ID = 'u_chris'; // demo user — change to inhabit a different role
function currentUser(){ return TEAM_MEMBERS.find(function(u){return u.id === CURRENT_USER_ID;}); }
function userById(id){ return TEAM_MEMBERS.find(function(u){return u.id === id;}); }
// Sharing scopes
const SHARE_PRIVATE = 'private', SHARE_TEAM = 'team', SHARE_ORG = 'org';
// Hierarchy helper — true if A is in B's reporting chain or vice versa, within 1 level for direct manager up
function isInHierarchy(ownerId, viewerId){
if(ownerId === viewerId) return true;
const owner = userById(ownerId), viewer = userById(viewerId);
if(!owner || !viewer) return false;
// Viewer's manager owns it → visible (share up one level)
if(viewer.managerId === ownerId) return true;
// Walk up owner's chain looking for viewer (share down to all reports)
let cursor = owner;
while(cursor){
if(cursor.managerId === viewerId) return true;
cursor = userById(cursor.managerId);
}
return false;
}
function canSeeItem(item, viewerId){
if(!item.owner) return true; // legacy items with no owner are visible
if(item.owner === viewerId) return true;
const scope = item.sharing || SHARE_PRIVATE;
if(scope === SHARE_ORG) return true;
if(scope === SHARE_TEAM) return isInHierarchy(item.owner, viewerId);
return false;
}
function shareScopeLabel(scope){
return {private:'Private', team:'Team', org:'Org'}[scope] || 'Private';
}
function shareScopeIcon(scope){
return {private:'\ud83d\udd12', team:'\ud83d\udc65', org:'\ud83c\udf10'}[scope] || '\ud83d\udd12';
}

