// === Save report modal ====================================================
let _rbSaveModalMode = 'report'; // 'report' or 'pin'
function rbOpenSaveModal(mode){
_rbSaveModalMode = mode;
const modal = document.getElementById('rb-save-modal');
const title = document.getElementById('rb-save-modal-title');
const sub = document.getElementById('rb-save-modal-sub');
const input = document.getElementById('rb-save-modal-input');
if(!modal || !input) return;
const autoTitle = rbGenerateVizTitle().title;
input.value = autoTitle === 'Empty workbench' ? '' : autoTitle;
if(mode === 'dashboard'){
title.textContent = 'Save dashboard';
sub.textContent = 'Saves the whole layout to Saved reports so you (and your team, if shared) can reopen it';
var _dnm = (typeof dashActiveId==='function' && dashActiveId()!=='mydash') ? mydashDashName(dashActiveId()) : ('Dashboard \u2014 ' + new Date().toLocaleDateString('en-US', {month:'short', day:'numeric'}));
input.value = _dnm;
}else if(mode === 'pin'){
title.textContent = 'Pin to dashboard';
sub.textContent = 'This card will appear on My dashboard and flips to reveal the data table';
}else{
title.textContent = 'Save report';
sub.textContent = 'Saved configurations appear in Saved reports — click any to reopen in the builder';
}
modal.classList.add('open');
setTimeout(function(){ input.focus(); input.select(); }, 50);
}
function rbCloseSaveModal(){
const modal = document.getElementById('rb-save-modal');
if(modal) modal.classList.remove('open');
}
function rbConfirmSave(){
const input = document.getElementById('rb-save-modal-input');
const name = (input ? input.value : '').trim();
if(!name){ if(input) input.focus(); return; }
if(_rbSaveModalMode === 'dashboard'){
const meD = currentUser();
const tiles = mydashLoad().filter(function(it){return !it.owner || it.owner === meD.id;});
let snapTiles; try { snapTiles = JSON.parse(JSON.stringify(tiles)); } catch(_){ snapTiles = tiles; }
const dashItem = {id: rbGenId(), name: name, type: 'dashboard', tiles: snapTiles, layoutMode: mydashSettings().mode, theme: mydashSettings().theme, createdAt: Date.now(), owner: meD.id, sharing: SHARE_PRIVATE};
const sr = savedReportsLoad(); sr.unshift(dashItem); savedReportsWrite(sr);
if(typeof showActionToast === 'function') showActionToast('Saved dashboard "' + name + '" to Saved reports');
rbCloseSaveModal();
return;
}
const snap = rbStateSnapshot();
const item = {id: rbGenId(), name: name, state: snap, vizType: snap.viz, createdAt: Date.now()};
if(_rbSaveModalMode === 'pin'){
const items = mydashLoad();
items.unshift(item);
mydashWrite(items);
if(typeof showActionToast === 'function') showActionToast('Pinned "' + name + '" to My dashboard');
}else{
const items = savedReportsLoad();
items.unshift(item);
savedReportsWrite(items);
if(typeof showActionToast === 'function') showActionToast('Saved report "' + name + '"');
}
rbCloseSaveModal();
}

// Schedule from the builder: autosave the current build into Saved reports, then open the
// schedule modal pre-tied to it. Reuses this session's autosave slot (if it's still the most
// recent saved report) so repeated clicks refine one entry instead of piling up duplicates.
let _rbBuilderAutosaveId = null;
function rbScheduleFromBuilder(){
if(RB_STATE.rows.length === 0 && RB_STATE.measures.length === 0){
if(typeof showActionToast === 'function') showActionToast('Build a report before scheduling');
return;
}
if(RB_STATE.measures.length === 0){
if(typeof showActionToast === 'function') showActionToast('Add at least one measure before scheduling');
return;
}
const titleObj = rbGenerateVizTitle();
const name = (RB_STATE._titleOverride && RB_STATE._titleOverride.trim()) ? RB_STATE._titleOverride.trim() : (titleObj.title === 'Empty workbench' ? 'Untitled report' : titleObj.title);
const snap = rbStateSnapshot();
const items = savedReportsLoad();
let target = (_rbBuilderAutosaveId && items.length && items[0].id === _rbBuilderAutosaveId) ? items[0] : null;
if(target){
target.name = name; target.state = snap; target.vizType = snap.viz; target.updatedAt = Date.now();
savedReportsWrite(items);
if(typeof showActionToast === 'function') showActionToast('Updated "' + name + '" in Saved reports');
}else{
target = {id: rbGenId(), name: name, state: snap, vizType: snap.viz, createdAt: Date.now()};
items.unshift(target);
savedReportsWrite(items);
_rbBuilderAutosaveId = target.id;
if(typeof showActionToast === 'function') showActionToast('Autosaved "' + name + '" to Saved reports');
}
if(typeof openScheduleModal === 'function') openScheduleModal({reportId: target.id, reportName: name});
}

// === My dashboard render ===================================================
function renderMyDashboard(){
DASH_READ_REG = new Map();
const grid = document.getElementById('mydashboard-grid');
const empty = document.getElementById('mydashboard-empty');
const toolbar = document.getElementById('mydashboard-toolbar');
if(!grid) return;
if(dashActiveId()!=='mydash' && !dashRegistry().some(function(d){return d.id===dashActiveId();})) dashSetActive('mydash');
mydashApplyTheme(grid);
const me = currentUser();
const allItems = mydashLoad();
// My dashboard: items I own
const items = allItems.filter(function(it){return !it.owner || it.owner === me.id;});
if(toolbar){
toolbar.innerHTML = items.length === 0 ? '<div class="mydash-toolbar-left"><span class="mydash-count">Start a dashboard \u2014 drop in a tile</span></div><div class="mydash-toolbar-actions"><span class="mydash-add-wrap"><button class="rb-action-btn rb-action-primary" id="mydash-add-menu-btn">+ Add \u25be</button></span><button class="rb-action-btn" id="mydash-reseed">Restore demo data</button></div>' :
'<div class="mydash-toolbar-left"><span class="mydash-count"><strong>' + items.length + '</strong> ' + (items.length === 1 ? 'card' : 'cards') + ' pinned</span><span class="mydash-user-chip"><span class="mydash-user-avatar" style="background:' + me.color + ';">' + me.initials + '</span><span class="mydash-user-name">' + me.name + '</span></span></div>' +
'<div class="mydash-toolbar-actions"><span class="mydash-tb-sep"></span><span class="mydash-more-wrap"><button class="rb-action-btn" id="mydash-more-btn" title="More actions">\u22ef</button></span></div>';
toolbar.insertAdjacentHTML('afterbegin', mydashSwitcherHtml());
var _swb=document.getElementById('mydash-switcher-btn');
if(_swb) _swb.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenSwitcher(_swb); });
mydashSyncXfChip();
const moreBtn = document.getElementById('mydash-more-btn');
if(moreBtn) moreBtn.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenMoreMenu(moreBtn); });
const reseedBtn = document.getElementById('mydash-reseed');
if(reseedBtn) reseedBtn.addEventListener('click', function(){ mydashReseedData(); });
if(items.length === 0){
const amb0=document.getElementById('mydash-add-menu-btn'); if(amb0) amb0.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenAddMenu(amb0); });
}
}
// Layout-mode controls (Edit layout / Done / Auto grid)
if(toolbar && items.length){
const actions = toolbar.querySelector('.mydash-toolbar-actions');
if(actions){
const mode = mydashSettings().mode;
let lay = '';
if(mode === 'canvas'){
lay += '<button class="rb-action-btn' + (_mydashEditing ? ' rb-action-primary' : '') + '" id="mydash-editlayout">\u25a6 ' + (_mydashEditing ? 'Done' : 'Edit layout') + '</button>';
if(_mydashEditing){
lay += '<span class="mydash-add-wrap"><button class="rb-action-btn" id="mydash-add-menu-btn">+ Add \u25be</button></span>';
lay += '<button class="rb-action-btn" id="mydash-tidy" title="Pack tiles into a clean non-overlapping grid">\u2637 Tidy</button>';
}
lay += '<button class="rb-action-btn" id="mydash-gridmode" title="Switch back to the automatic responsive grid">Auto grid</button>';
} else {
lay += '<button class="rb-action-btn" id="mydash-editlayout" title="Arrange cards freely on a canvas">\u25a6 Edit layout</button>';
}
actions.insertAdjacentHTML('afterbegin', lay);
const sdb0 = document.getElementById('mydash-save-dash');
if(!sdb0){ actions.insertAdjacentHTML('afterbegin', '<button class="rb-action-btn" id="mydash-save-dash" title="Save this dashboard layout to Saved reports">\u25b3 Save dashboard</button>'); }
const sdb = document.getElementById('mydash-save-dash');
if(sdb) sdb.addEventListener('click', function(){ rbOpenSaveModal('dashboard'); });
const tmb0 = document.getElementById('mydash-theme-btn');
if(!tmb0){ actions.insertAdjacentHTML('afterbegin', '<button class="rb-action-btn" id="mydash-theme-btn" title="Theme this dashboard \u2014 page background &amp; accent color">\ud83c\udfa8 Theme</button>'); }
const tmb = document.getElementById('mydash-theme-btn');
if(tmb) tmb.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenThemePicker(tmb); });
if(!document.querySelector('.mydash-export-wrap')){ actions.insertAdjacentHTML('afterbegin', '<span class="mydash-export-wrap"><button class="rb-action-btn" id="mydash-export-btn" title="Export this dashboard as a PNG image or PDF">\u2B07 Export</button></span>'); }
const exb = document.getElementById('mydash-export-btn');
if(exb) exb.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenExportMenu(exb); });
const elb = document.getElementById('mydash-editlayout');
if(elb) elb.addEventListener('click', function(){
const s = mydashSettings();
if(s.mode !== 'canvas'){
const all = mydashLoad();
const mine = all.filter(function(it){return !it.owner || it.owner === me.id;});
mydashEnsureLayout(mine); mydashWrite(all); mydashSetMode('canvas'); _mydashEditing = true;
} else { _mydashEditing = !_mydashEditing; }
renderMyDashboard();
});
const gmb = document.getElementById('mydash-gridmode');
if(gmb) gmb.addEventListener('click', function(){ mydashSetMode('grid'); _mydashEditing = false; renderMyDashboard(); });
const amb=document.getElementById('mydash-add-menu-btn');
if(amb) amb.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenAddMenu(amb); });
const tdb = document.getElementById('mydash-tidy');
if(tdb) tdb.addEventListener('click', function(){ mydashTidyLayout(); });
}
}
if(items.length === 0){
grid.innerHTML = '';
if(empty) empty.style.display = 'block';
return;
}
if(empty) empty.style.display = 'none';
let html = '';
items.forEach(function(item){
html += renderDashCard(item);
});
grid.innerHTML = html;
grid.querySelectorAll('.mydash-ai').forEach(function(card){
const id = card.dataset.cardId;
const inp = card.querySelector('.mydash-ai-input');
const ask = card.querySelector('.mydash-ai-ask');
const run = function(){ if(inp) mydashAiGenerate(id, inp.value); };
if(inp){ inp.addEventListener('pointerdown', function(e){ e.stopPropagation(); }); inp.addEventListener('keydown', function(e){ if(e.key === 'Enter'){ e.preventDefault(); run(); } }); }
if(ask){ ask.addEventListener('pointerdown', function(e){ e.stopPropagation(); }); ask.addEventListener('click', function(e){ e.stopPropagation(); run(); }); }
card.querySelectorAll('[data-ai-ex]').forEach(function(b){ b.addEventListener('pointerdown', function(e){ e.stopPropagation(); }); b.addEventListener('click', function(e){ e.stopPropagation(); mydashAiGenerate(id, b.dataset.aiEx); }); });
});
const _mode = mydashSettings().mode;
if(_mode === 'canvas'){
grid.classList.add('mydash-canvas');
grid.classList.toggle('mydash-canvas-editing', _mydashEditing);
if(mydashEnsureLayout(items)) mydashWrite(allItems);
mydashPositionCards(grid, items);
if(_mydashEditing){
grid.querySelectorAll('.mydash-card').forEach(function(card){
if(!card.querySelector('.mydash-canvas-resize')){ const h = document.createElement('div'); h.className = 'mydash-canvas-resize'; h.title = 'Drag to resize'; card.appendChild(h); }
});
wireDashCanvasEdit(grid, items, allItems);
}else{
wireCardInteractions(grid, function(){ renderMyDashboard(); });
}
if(!grid._canvasResizeWired){ grid._canvasResizeWired = true; window.addEventListener('resize', function(){ if(grid.classList.contains('mydash-canvas')) mydashPositionCards(grid, mydashLoad().filter(function(it){return !it.owner || it.owner === currentUser().id;})); }); }
return;
}
grid.classList.remove('mydash-canvas', 'mydash-canvas-editing');
grid.style.minHeight = '';
wireCardInteractions(grid, function(){ renderMyDashboard(); });
wireCardDragReorder(grid, function(dragId, targetId, after){
const all = mydashLoad();
const fromIdx = all.findIndex(function(it){return it.id === dragId;});
if(fromIdx < 0) return;
const moved = all.splice(fromIdx, 1)[0];
let toIdx = all.findIndex(function(it){return it.id === targetId;});
if(toIdx < 0) toIdx = all.length;
if(after) toIdx += 1;
all.splice(toIdx, 0, moved);
mydashWrite(all);
renderMyDashboard();
});
}

