function connectorsLoadState(){
try { return JSON.parse(localStorage.getItem(CONNECTORS_KEY) || '{}'); } catch(_){ return {}; }
}
function connectorsSaveState(state){
try { localStorage.setItem(CONNECTORS_KEY, JSON.stringify(state)); } catch(_){}
}
function connectorStatus(id){
const baseline = (CONNECTORS.find(function(c){return c.id === id;}) || {}).status || 'available';
const overrides = connectorsLoadState();
return overrides[id] || baseline;
}

function renderConnectorCard(c){
const status = connectorStatus(c.id);
const statusLabel = status === 'connected' ? 'Connected' : (status === 'preview' ? 'Preview' : 'Available');
const btnLabel = status === 'connected' ? '\u2713 Connected' : (status === 'preview' ? 'Request access' : 'Connect');
const btnClass = status === 'connected' ? 'connected' : (status === 'preview' ? 'secondary' : '');
const catLabel = {crm:'CRM & sales', warehouse:'Data warehouse', communication:'Communication', bi:'BI & reporting', industry:'Industry-specific', files:'Files'}[c.cat] || c.cat;
return '<div class="connector-card" data-connector-id="' + c.id + '" data-cat="' + c.cat + '">' +
'<div class="connector-card-head">' +
'<div class="connector-card-icon" style="background:' + c.color + ';">' + c.initial + '</div>' +
'<div class="connector-card-meta">' +
'<div class="connector-card-name">' + c.name + '</div>' +
'<div class="connector-card-cat">' + catLabel + '</div>' +
'</div>' +
'</div>' +
'<div class="connector-card-desc">' + c.desc + '</div>' +
'<div class="connector-card-foot">' +
'<span class="connector-card-status ' + status + '">' + statusLabel + '</span>' +
'<button class="connector-card-btn ' + btnClass + '" data-connector-action="' + c.id + '">' + btnLabel + '</button>' +
'</div>' +
'</div>';
}

let _connectorsFilter = 'all';
let _connectorsSearch = '';

function renderConnectors(){
const grid = document.getElementById('connectors-grid');
if(!grid) return;
const _statEl=document.getElementById('connectors-stat');
if(_statEl){ const _conn=CONNECTORS.filter(function(c){return connectorStatus(c.id)==='connected';}).length; _statEl.innerHTML='<b>'+_conn+'</b>&nbsp;connected · '+CONNECTORS.length+' available'; }
const q = (_connectorsSearch || '').toLowerCase().trim();
const filtered = CONNECTORS.filter(function(c){
if(_connectorsFilter !== 'all' && c.cat !== _connectorsFilter) return false;
if(q && c.name.toLowerCase().indexOf(q) < 0 && c.desc.toLowerCase().indexOf(q) < 0) return false;
return true;
});
// Sort: connected first, then available, then preview. Within each group, alphabetical.
const rank = {connected: 0, available: 1, preview: 2};
filtered.sort(function(a, b){
const ra = rank[connectorStatus(a.id)] - rank[connectorStatus(b.id)];
if(ra !== 0) return ra;
return a.name.localeCompare(b.name);
});
if(filtered.length === 0){
grid.innerHTML = '<div class="connectors-empty">No connectors match your search. Try a different category or use the "Request a connector" button below.</div>';
return;
}
grid.innerHTML = filtered.map(renderConnectorCard).join('');
// Wire connect buttons
grid.querySelectorAll('[data-connector-action]').forEach(function(btn){
btn.addEventListener('click', function(e){
e.stopPropagation();
const id = btn.dataset.connectorAction;
const c = CONNECTORS.find(function(x){return x.id === id;});
if(!c) return;
openConnectModal(c);
});
});
}

function openConnectModal(c){
const existing = document.querySelector('.connect-modal');
if(existing) existing.remove();
const status = connectorStatus(c.id);
const catLabel = {crm:'CRM & sales', warehouse:'Data warehouse', communication:'Communication', bi:'BI & reporting', industry:'Industry-specific', files:'Files'}[c.cat] || c.cat;
const overlay = document.createElement('div');
overlay.className = 'connect-modal';
let bodyHtml = '<div class="connect-modal-body">';
if(status === 'connected'){
bodyHtml += '<p>' + c.name + ' is connected and feeding data into your Hoodie workspace. Data flows in at <strong>' + c.frequency.toLowerCase() + '</strong> cadence using <strong>' + c.auth + '</strong>.</p>' +
'<div class="connect-modal-step"><strong>Status \u00b7</strong> Healthy. Last successful sync just now.</div>' +
'<div class="connect-modal-step"><strong>Data flowing \u00b7</strong> Aligned to the same anonymized cell structure (N\u226510) as the syndicated baseline. Your row-level data never leaves your tenant.</div>';
}else if(status === 'preview'){
bodyHtml += '<p>' + c.name + ' is in private preview. Joining the preview cohort means working with our integration team to validate the schema mapping and confirm the data-fiduciary review.</p>' +
'<div class="connect-modal-step"><strong>1 \u00b7</strong> Submit a request and we\'ll reach out within 2 business days to schedule a scoping call.</div>' +
'<div class="connect-modal-step"><strong>2 \u00b7</strong> Schema mapping + sample-data review. We confirm anonymization rules apply correctly to your data shape.</div>' +
'<div class="connect-modal-step"><strong>3 \u00b7</strong> Sandbox connection \u2014 you validate the data lineage before any production cells get computed.</div>';
}else{
bodyHtml += '<p>Connect ' + c.name + ' to bring its data into the same dimensional model as your Hoodie depletions. The connector handles authentication and schema mapping; you control what flows in.</p>' +
'<div class="connect-modal-step"><strong>1 \u00b7</strong> Authenticate via <strong>' + c.auth + '</strong> \u2014 you stay in the source\'s security model, no credentials stored.</div>' +
'<div class="connect-modal-step"><strong>2 \u00b7</strong> Pick the entities to map. Hoodie suggests the right dimensional alignment based on your schema.</div>' +
'<div class="connect-modal-step"><strong>3 \u00b7</strong> First sync runs. Frequency: <strong>' + c.frequency.toLowerCase() + '</strong>. You can pause, audit, or revoke at any time.</div>';
}
bodyHtml += '<div class="connect-modal-fiduciary"><strong>Data fiduciary commitment \u00b7</strong> Anything that flows through this connector is subject to the same anonymization rules as the syndicated data. Single-tenant cells under N=10 are suppressed. Source-of-record permissions are preserved end-to-end.</div>';
bodyHtml += '</div>';
const btnLabel = status === 'connected' ? 'Disconnect' : (status === 'preview' ? 'Request preview access' : 'Connect ' + c.name);
const btnClass = status === 'connected' ? '' : 'primary';
overlay.innerHTML = '<div class="connect-modal-panel">' +
'<div class="connect-modal-head">' +
'<div class="connect-modal-icon" style="background:' + c.color + ';">' + c.initial + '</div>' +
'<div><div class="connect-modal-title">' + c.name + '</div><div class="connect-modal-sub">' + catLabel + ' \u00b7 ' + (status === 'connected' ? 'Connected' : (status === 'preview' ? 'Preview' : 'Available')) + '</div></div>' +
'</div>' +
bodyHtml +
'<div class="connect-modal-foot">' +
'<button class="connect-modal-btn" data-modal-action="cancel">Cancel</button>' +
'<button class="connect-modal-btn ' + btnClass + '" data-modal-action="confirm">' + btnLabel + '</button>' +
'</div>' +
'</div>';
document.body.appendChild(overlay);
overlay.addEventListener('click', function(e){ if(e.target === overlay) overlay.remove(); });
overlay.querySelector('[data-modal-action="cancel"]').addEventListener('click', function(){ overlay.remove(); });
overlay.querySelector('[data-modal-action="confirm"]').addEventListener('click', function(){
const overrides = connectorsLoadState();
if(status === 'connected'){
overrides[c.id] = 'available';
if(typeof showActionToast === 'function') showActionToast('Disconnected \u2014 ' + c.name);
}else if(status === 'preview'){
if(typeof showActionToast === 'function') showActionToast('Preview access requested \u2014 we\'ll be in touch within 2 business days');
}else{
overrides[c.id] = 'connected';
if(typeof showActionToast === 'function') showActionToast('Connected \u2014 ' + c.name);
}
connectorsSaveState(overrides);
overlay.remove();
renderConnectors();
});
}

function wireConnectorsView(){
const search = document.getElementById('connectors-search');
if(search){
search.addEventListener('input', function(){
_connectorsSearch = search.value;
renderConnectors();
});
}
const filterRow = document.getElementById('connectors-filter-row');
if(filterRow){
filterRow.querySelectorAll('.connectors-filter-btn').forEach(function(btn){
btn.addEventListener('click', function(){
_connectorsFilter = btn.dataset.cat;
filterRow.querySelectorAll('.connectors-filter-btn').forEach(function(b){ b.classList.remove('active'); });
btn.classList.add('active');
renderConnectors();
});
});
}
const reqBtn = document.getElementById('connectors-request');
if(reqBtn){
reqBtn.addEventListener('click', function(){
if(typeof showActionToast === 'function') showActionToast('Connector request form opens here \u2014 wired to the JV product roadmap intake');
});
}
renderConnectors();
}

// Team dashboard sort/filter state (sort persists across sessions)
const TEAM_SORT_KEY = 'sipsource_team_sort';
const TEAM_ORDER_KEY = 'sipsource_team_order';
let _teamOwnerFilter = '';
let _teamSort = (function(){ try { return localStorage.getItem(TEAM_SORT_KEY) || 'owner_asc'; } catch(_){ return 'owner_asc'; } })();
function teamOrderLoad(){ try { return JSON.parse(localStorage.getItem(TEAM_ORDER_KEY) || '[]'); } catch(_){ return []; } }
function teamOrderSave(ids){ try { localStorage.setItem(TEAM_ORDER_KEY, JSON.stringify(ids)); } catch(_){} }
const TEAM_SORT_OPTIONS = [
{key:'owner_asc',  label:'Teammate (A\u2013Z)'},
{key:'owner_desc', label:'Teammate (Z\u2013A)'},
{key:'name_asc',   label:'Report name (A\u2013Z)'},
{key:'recent',     label:'Recently shared'},
{key:'custom',     label:'Custom order (drag)'}
];
function teamSortLabel(){ const o = TEAM_SORT_OPTIONS.find(function(x){return x.key===_teamSort;}); return o ? o.label : 'Teammate (A\u2013Z)'; }
function teamSortItems(items){
const ownerName = function(it){ const u = userById(it.owner); return (u ? u.name : it.owner || '').toLowerCase(); };
const arr = items.slice();
if(_teamSort === 'owner_asc') arr.sort(function(a,b){ return ownerName(a).localeCompare(ownerName(b)) || (a.name||'').localeCompare(b.name||''); });
else if(_teamSort === 'owner_desc') arr.sort(function(a,b){ return ownerName(b).localeCompare(ownerName(a)) || (a.name||'').localeCompare(b.name||''); });
else if(_teamSort === 'name_asc') arr.sort(function(a,b){ return (a.name||'').localeCompare(b.name||''); });
else if(_teamSort === 'recent') arr.sort(function(a,b){ return (b.createdAt||0) - (a.createdAt||0); });
else if(_teamSort === 'custom'){
const order = teamOrderLoad();
const rank = function(it){ const i = order.indexOf(it.id); return i < 0 ? 1e9 : i; };
arr.sort(function(a,b){ const d = rank(a) - rank(b); if(d !== 0) return d; return ownerName(a).localeCompare(ownerName(b)); });
}
return arr;
}
function showTeamSortMenu(x, y){
const existing = document.querySelector('.dash-ctx-menu');
if(existing) existing.remove();
const menu = document.createElement('div');
menu.className = 'dash-ctx-menu';
let html = '<div class="dash-ctx-menu-head">Sort by</div>';
TEAM_SORT_OPTIONS.forEach(function(o){
html += '<div class="dash-ctx-menu-item' + (o.key === _teamSort ? ' active' : '') + '" data-sort="' + o.key + '"><span>' + o.label + '</span><span class="dash-ctx-menu-check">\u2713</span></div>';
});
menu.innerHTML = html;
// Keep the menu on-screen
menu.style.left = Math.min(x, window.innerWidth - 230) + 'px';
menu.style.top = Math.min(y, window.innerHeight - 190) + 'px';
document.body.appendChild(menu);
menu.querySelectorAll('[data-sort]').forEach(function(opt){
opt.addEventListener('click', function(){
_teamSort = opt.dataset.sort;
try { localStorage.setItem(TEAM_SORT_KEY, _teamSort); } catch(_){}
menu.remove();
renderTeamDashboard();
});
});
const dismiss = function(ev){ if(!menu.contains(ev.target)){ menu.remove(); document.removeEventListener('click', dismiss); document.removeEventListener('keydown', onEsc); } };
const onEsc = function(ev){ if(ev.key === 'Escape'){ menu.remove(); document.removeEventListener('click', dismiss); document.removeEventListener('keydown', onEsc); } };
setTimeout(function(){ document.addEventListener('click', dismiss); document.addEventListener('keydown', onEsc); }, 0);
}

function renderTeamDashboard(){
DASH_READ_REG = new Map();
const grid = document.getElementById('teamdashboard-grid');
const empty = document.getElementById('teamdashboard-empty');
const toolbar = document.getElementById('teamdashboard-toolbar');
if(!grid) return;
const me = currentUser();
const allItems = mydashLoadRaw();
// Team dashboard: items NOT owned by me but visible per sharing rules
const items = allItems.filter(function(it){return it.owner && it.owner !== me.id && canSeeItem(it, me.id);});
// Distinct owners (for the filter dropdown)
const ownerIds = [];
items.forEach(function(it){ if(ownerIds.indexOf(it.owner) < 0) ownerIds.push(it.owner); });
ownerIds.sort(function(a,b){ var ua=userById(a), ub=userById(b); return ((ua?ua.name:a)||'').localeCompare((ub?ub.name:b)||''); });
// Reset stale filter
if(_teamOwnerFilter && ownerIds.indexOf(_teamOwnerFilter) < 0) _teamOwnerFilter = '';

if(items.length === 0){
grid.innerHTML = '';
if(toolbar) toolbar.innerHTML = '';
if(empty) empty.style.display = 'block';
return;
}
if(empty) empty.style.display = 'none';

const filtered = _teamOwnerFilter ? items.filter(function(it){return it.owner === _teamOwnerFilter;}) : items;
const sorted = teamSortItems(filtered);

if(toolbar){
toolbar.innerHTML =
'<div class="mydash-toolbar-left">' +
'<span class="mydash-count"><strong>' + items.length + '</strong> ' + (items.length === 1 ? 'card' : 'cards') + ' shared with your team \u00b7 from <strong>' + ownerIds.length + '</strong> ' + (ownerIds.length === 1 ? 'colleague' : 'colleagues') + '</span>' +
'<button class="team-sort-control" id="team-sort-btn" title="Sort the board (or right-click anywhere on the grid)"><span class="team-sort-control-label">Sort:</span><span class="team-sort-control-val">' + teamSortLabel() + '</span><span class="team-sort-control-caret">\u25be</span></button>' +
'<span class="team-sort-hint">right-click the grid to sort</span>' +
'</div>' +
'<div class="mydash-toolbar-actions"><span class="mydash-filter-label">Teammate:</span><select class="mydash-filter-select" id="team-owner-filter"><option value="">All teammates</option>' + ownerIds.map(function(uid){var u = userById(uid); return '<option value="' + uid + '"' + (uid === _teamOwnerFilter ? ' selected' : '') + '>' + (u ? u.name : uid) + '</option>';}).join('') + '</select></div>';
const sortBtn = document.getElementById('team-sort-btn');
if(sortBtn) sortBtn.addEventListener('click', function(e){ e.stopPropagation(); const r = sortBtn.getBoundingClientRect(); showTeamSortMenu(r.left, r.bottom + 4); });
const filterSel = document.getElementById('team-owner-filter');
if(filterSel) filterSel.addEventListener('change', function(){ _teamOwnerFilter = filterSel.value; renderTeamDashboard(); });
var teamActions = toolbar.querySelector('.mydash-toolbar-actions');
if(teamActions && !document.getElementById('team-export-btn')){
teamActions.insertAdjacentHTML('afterbegin', '<span class="mydash-export-wrap"><button class="rb-action-btn" id="team-export-btn" title="Export this board as a PNG image or PDF">\u2B07 Export</button></span><span class="mydash-tb-sep"></span>');
var teamExp = document.getElementById('team-export-btn');
if(teamExp) teamExp.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenExportMenu(teamExp, 'teamdashboard-grid'); });
}
}

// Flat grid — every report tagged with its owner, no per-user bucketing
grid.innerHTML = sorted.map(function(item){ return renderDashCard(item); }).join('');
wireCardInteractions(grid, function(){ renderTeamDashboard(); });
// Drag-and-drop reorder → saves a custom view order and switches the sort to Custom
wireCardDragReorder(grid, function(dragId, targetId, after){
const visible = Array.prototype.map.call(grid.querySelectorAll('.mydash-card'), function(c){ return c.dataset.cardId; });
const fromIdx = visible.indexOf(dragId);
if(fromIdx < 0) return;
visible.splice(fromIdx, 1);
let toIdx = visible.indexOf(targetId);
if(toIdx < 0) toIdx = visible.length;
if(after) toIdx += 1;
visible.splice(toIdx, 0, dragId);
// Preserve any team cards currently filtered out, appended in their prior order
const teamIds = mydashLoadRaw().filter(function(it){return it.owner && it.owner !== me.id && canSeeItem(it, me.id);}).map(function(it){return it.id;});
const prior = teamOrderLoad();
const tail = teamIds.filter(function(idv){return visible.indexOf(idv) < 0;}).sort(function(a,b){ return (prior.indexOf(a) - prior.indexOf(b)); });
teamOrderSave(visible.concat(tail));
_teamSort = 'custom';
try { localStorage.setItem(TEAM_SORT_KEY, 'custom'); } catch(_){}
renderTeamDashboard();
});
// Right-click anywhere on the grid → sort menu
grid.oncontextmenu = function(e){ e.preventDefault(); showTeamSortMenu(e.clientX, e.clientY); };
}

// Shared card interaction wiring (flip / open / change-share-scope)
function wireCardInteractions(rootEl, refreshFn){
rootEl.querySelectorAll('.mydash-card').forEach(function(card){
const id = card.dataset.cardId;
card.querySelectorAll('.mydash-card-btn-flip').forEach(function(btn){
btn.addEventListener('click', function(e){ e.stopPropagation(); card.classList.toggle('flipped'); });
});
card.querySelectorAll('.mydash-card-btn-layout').forEach(function(btn){
btn.addEventListener('pointerdown', function(e){ e.stopPropagation(); });
btn.addEventListener('click', function(e){ e.stopPropagation(); mydashOpenVariantPicker(id, btn); });
});
const removeBtn = card.querySelector('.mydash-card-btn-remove');
if(removeBtn) removeBtn.addEventListener('click', function(e){
e.stopPropagation();
const items = mydashLoad().filter(function(it){return it.id !== id;});
mydashWrite(items);
refreshFn();
});
const openBtn = card.querySelector('.mydash-card-btn-open');
if(openBtn) openBtn.addEventListener('click', function(e){
e.stopPropagation();
openDashCardInBuilder(id);
});
card.querySelectorAll('.mydash-card-btn-expand').forEach(function(btn){
btn.addEventListener('click', function(e){
e.stopPropagation();
openDashCardFullscreen(id, card.classList.contains('flipped'));
});
});
// Sharing scope cycle on owned cards: private → team → org → private
const shareBtn = card.querySelector('.mydash-card-share-btn');
if(shareBtn) shareBtn.addEventListener('click', function(e){
e.stopPropagation();
const items = mydashLoad();
const target = items.find(function(it){return it.id === id;});
if(!target) return;
const cur = target.sharing || SHARE_PRIVATE;
target.sharing = cur === SHARE_PRIVATE ? SHARE_TEAM : (cur === SHARE_TEAM ? SHARE_ORG : SHARE_PRIVATE);
mydashWrite(items);
if(typeof showActionToast === 'function') showActionToast('Sharing: ' + shareScopeLabel(target.sharing));
refreshFn();
});
card.querySelectorAll('.mydash-card-body').forEach(function(b){
b.addEventListener('click', function(e){
if(e.target.closest('button, a, input, select, th.sortable, [data-page-action], [data-page-num]')) return;
if(card.classList.contains('mydash-card-combo')) return;
card.classList.toggle('flipped');
});
});
});
}

// Shared viz dispatcher — one place renderDashCard + full-screen both use.
function rbRenderVizByKey(viz, model){
switch(viz){
case 'bar': return rbRenderBar(model, false);
case 'hbar': return rbRenderBar(model, true);
case 'stacked_bar': return rbRenderStackedBar(model);
case 'grouped_bar': return rbRenderGroupedBar(model);
case 'line': return rbRenderLine(model);
case 'area': return rbRenderArea(model);
case 'combo': return rbRenderCombo(model);
case 'heatmap': return rbRenderHeatmap(model);
case 'treemap': return rbRenderTreemap(model);
case 'pie': return rbRenderPie(model, false);
case 'donut': return rbRenderPie(model, true);
case 'bubble': return rbRenderBubble(model);
case 'scatter': return rbRenderScatter(model);
case 'boxplot': return rbRenderBoxplot(model);
case 'bullet': return rbRenderBullet(model);
case 'funnel': return rbRenderFunnel(model);
case 'histogram': return rbRenderHistogram(model);
case 'sunburst': return rbRenderSunburst(model);
case 'map': return rbRenderMap(model, false);
case 'hexmap': return rbRenderHexMap(model);
case 'mapdiv': return rbRenderMap(model, true);
case 'kpi': return rbRenderKPI(model);
case 'crosstab':
case 'table':
default: return rbRenderTable(model);
}
}

// Condense a model for the dashboard TILE so it reads as a quick summary rather
// than the full report crammed into 340px. Charts compress their axes fine, so we
// only cap series/rows; tabular vizes (table/crosstab/heatmap) also cap columns.
// "Wrong but readable" by design — the full, exact report lives in the expand.
function rbCondenseModel(model, viz){
const m = Object.assign({}, model);
const tabular = ['table','crosstab','heatmap'].indexOf(viz) >= 0;
const isTimeSeries = ['line','area','combo'].indexOf(viz) >= 0;
let rowCap;
if(isTimeSeries) rowCap = 4;                                              // # of series lines
else if(['bar','hbar','stacked_bar','grouped_bar'].indexOf(viz)>=0) rowCap = 7;
else if(viz === 'funnel') rowCap = 6;
else if(['pie','donut','treemap'].indexOf(viz)>=0){ rowCap = 99999; m._topN = 5; }
else rowCap = 6;                                                          // table / crosstab / heatmap
if(m.rowCombos && m.rowCombos.length > rowCap){
m.rowCombos = m.rowCombos.slice(0, rowCap);
m._moreRows = model.rowCombos.length - rowCap;
}
if(tabular && m.colCombos && m.colCombos.length > 6){
if(m.timeAxis && m.timeAxis.length > 6){
// keep the most-recent 6 periods so the summary shows current state
m.colCombos = model.colCombos.slice(model.colCombos.length - 6);
m.timeAxis = model.timeAxis.slice(model.timeAxis.length - 6);
} else {
m.colCombos = model.colCombos.slice(0, 6);
}
m._moreCols = model.colCombos.length - 6;
}
return m;
}

function renderDashAiTile(item){
const handle = '<span class="mydash-card-handle" title="Drag to move">\u22ee\u22ee</span>';
const remove = '<button class="mydash-card-btn mydash-card-btn-remove" title="Remove">\u00d7</button>';
const promptVal = String(item.aiPrompt || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
let body, expandBtn = '';
if(item.state){
let vizHtml = '<div class="rb-output-empty">No answer yet</div>';
let insight = '';
try {
const prev = rbStateSnapshot(); rbStateRestore(item.state);
const fullModel = rbBuildDataModel();
const av = rbVizAvailability(item.state.viz);
if(av.ok && RB_STATE.measures.length > 0){ const tm = rbCondenseModel(fullModel, item.state.viz); vizHtml = rbRenderVizByKey(item.state.viz, tm).html.replace(/<div class="rb-output-toolbar">[\s\S]*?<\/div>/, '').replace(/<div class="rb-pagination">[\s\S]*?<\/div>/, ''); try{ insight = dashCardAIContext(fullModel) || ''; }catch(_){ insight = ''; } }
rbStateRestore(prev);
} catch(_){ vizHtml = '<div class="rb-output-empty">Could not build that answer \u2014 try rephrasing.</div>'; }
const summary = insight ? '<div class="mydash-ai-summary"><span class="mydash-ai-summary-spark">\u2728</span><span class="mydash-ai-summary-txt">' + insight + '</span></div>' : '';
body = summary + '<div class="mydash-ai-answer">' + vizHtml + '</div>';
expandBtn = '<button class="mydash-card-btn mydash-card-btn-expand" title="Expand to full screen">\u26f6</button>';
} else {
const ex = ['Volume growth by category','Headroom by sub-channel','Tequila trend over time','Top declining channels'];
body = '<div class="mydash-ai-empty"><div class="mydash-ai-empty-ico">\u2728</div><div class="mydash-ai-empty-txt">Ask a question about the book \u2014 I\u2019ll pick the right chart and fit it to this tile.</div><div class="mydash-ai-examples">' + ex.map(function(e){ return '<button class="mydash-ai-ex" data-ai-ex="' + e.replace(/"/g,'&quot;') + '">' + e + '</button>'; }).join('') + '</div></div>';
}
return '<div class="mydash-card mydash-obj mydash-ai" data-card-id="' + item.id + '" draggable="false">' +
'<div class="mydash-obj-inner">' + handle + remove + expandBtn +
'<div class="mydash-ai-promptbar"><span class="mydash-ai-spark">\u2728</span><input class="mydash-ai-input" data-ai-id="' + item.id + '" placeholder="Ask a question\u2026" value="' + promptVal + '" autocomplete="off"/><button class="mydash-ai-ask" data-ai-ask="' + item.id + '" title="Ask">\u2192</button></div>' +
body +
'</div></div>';
}
function mydashAiGenerate(itemId, prompt){
const all = mydashLoad(); const it = all.find(function(x){return x.id === itemId;}); if(!it) return;
prompt = String(prompt || '').trim();
it.aiPrompt = prompt;
if(prompt) it.name = prompt;
if(prompt && typeof rbAIBuild === 'function'){
const fullPrev = JSON.parse(JSON.stringify(RB_STATE));
try { rbAIBuild(prompt); it.state = rbStateSnapshot(); it.state.periodWindow = RB_STATE.periodWindow; it.state.periodGrain = RB_STATE.periodGrain; }
catch(_){ it.state = null; }
['rows','columns','filters','measures','timeInterval','periodWindow','periodGrain','viz','calculated','groupings','annotations'].forEach(function(k){ try{ RB_STATE[k] = JSON.parse(JSON.stringify(fullPrev[k])); }catch(_){ RB_STATE[k] = fullPrev[k]; } });
}
mydashWrite(all);
renderMyDashboard();
}
function renderDashObjectTile(item){
const handle = '<span class="mydash-card-handle" title="Drag to move">\u22ee\u22ee</span>';
const remove = '<button class="mydash-card-btn mydash-card-btn-remove" title="Remove">\u00d7</button>';
if(item.type === 'spacer'){
return '<div class="mydash-card mydash-obj mydash-obj-spacer" data-card-id="' + item.id + '" draggable="false">' +
'<div class="mydash-obj-inner">' + handle + remove +
'<div class="mydash-obj-spacer-label">Spacer</div></div></div>';
}
const safe = String(item.text || '').replace(/</g, '&lt;');
const size = item.size || 'title';
const align = item.align || 'left';
const inner = safe ? safe.replace(/\n/g, '<br/>') : '<span class="mydash-obj-placeholder">Add text\u2026</span>';
return '<div class="mydash-card mydash-obj mydash-obj-text" data-card-id="' + item.id + '" draggable="false">' +
'<div class="mydash-obj-inner">' + handle + remove +
'<div class="mydash-obj-text-body mydash-obj-text-' + size + ' mydash-obj-align-' + align + '" data-text-id="' + item.id + '">' + inner + '</div>' +
'</div></div>';
}
function rbSheetColgroup(cols, colW){ var h='<colgroup><col class="mydash-sheet-col-rowh"/>'; for(var c=0;c<cols;c++){ var w=(colW&&colW[c])?colW[c]:72; h+='<col data-colidx="'+c+'" style="width:'+w+'px"/>'; } return h+'</colgroup>'; }
function renderDashSheetTile(item){
const handle = '<span class="mydash-card-handle" title="Drag to move">\u22ee\u22ee</span>';
const remove = '<button class="mydash-card-btn mydash-card-btn-remove" title="Remove">\u00d7</button>';
const rows = item.rows || 8, cols = item.cols || 6;
const cells = item.cells || {};
const res = rbSheetRecalc(cells, rows, cols);
let h = '<table class="mydash-sheet-table">' + rbSheetColgroup(cols, item.colW) + '<thead><tr><th class="mydash-sheet-corner"></th>';
for(let c=0;c<cols;c++) h += '<th class="mydash-sheet-colh" data-col="' + c + '">' + rbSheetIdxToCol(c) + '</th>';
h += '</tr></thead><tbody>';
for(let r=0;r<rows;r++){
h += '<tr><th class="mydash-sheet-rowh" data-row="' + r + '">' + (r+1) + '</th>';
for(let c=0;c<cols;c++){
const addr = rbSheetAddr(c,r);
const raw = cells[addr] || '';
const dv = res.display[addr];
const isErr = dv != null && String(dv).charAt(0) === '#';
const disp = (dv == null) ? '' : rbSheetFmt(dv);
h += '<td class="mydash-sheet-td"><input class="mydash-sheet-cell' + (isErr?' mydash-sheet-err':'') + (raw.charAt(0)==='='?' mydash-sheet-formula':'') + '" data-addr="' + addr + '" data-raw="' + _dashEsc(raw) + '" value="' + _dashEsc(disp) + '" spellcheck="false"/></td>';
}
h += '</tr>';
}
h += '</tbody></table>';
return '<div class="mydash-card mydash-obj mydash-obj-sheet" data-card-id="' + item.id + '" draggable="false">' +
'<div class="mydash-obj-inner">' + handle + remove +
'<div class="mydash-sheet-bar"><span class="mydash-sheet-namebox">A1</span><span class="mydash-sheet-fx">\u0192x</span><span class="mydash-sheet-formula-line"></span></div>' +
'<div class="mydash-sheet-wrap">' + h + '</div>' +
'</div></div>';
}
function mydashSheetCommit(id, addr, val){
const all = mydashLoad(); const it = all.find(function(x){return x.id===id;}); if(!it) return null;
it.cells = it.cells || {};
if(val==null || val==='') delete it.cells[addr]; else it.cells[addr] = val;
mydashWrite(all); return it;
}
function mydashSheetRefresh(card, it){
const rows = it.rows || 8, cols = it.cols || 6;
const res = rbSheetRecalc(it.cells || {}, rows, cols);
card.querySelectorAll('.mydash-sheet-cell').forEach(function(inp){
const addr = inp.dataset.addr; const raw = (it.cells && it.cells[addr]) || '';
inp.dataset.raw = raw;
inp.classList.toggle('mydash-sheet-formula', raw.charAt(0)==='=');
if(document.activeElement !== inp){
const dv = res.display[addr];
inp.value = (dv==null) ? '' : rbSheetFmt(dv);
inp.classList.toggle('mydash-sheet-err', dv!=null && String(dv).charAt(0)==='#');
}
});
}
function mydashSheetBar(inp){
const card = inp.closest('.mydash-card, .rb-ws-host'); if(!card) return;
const fl = card.querySelector('.mydash-sheet-formula-line');
if(fl) fl.textContent = inp.dataset.raw || '';
}
function mydashSheetMove(inp, dc, dr){
const card = inp.closest('.mydash-card, .rb-ws-host'); if(!card) return false;
const ref = rbSheetParseRef(inp.dataset.addr); if(!ref) return false;
const tc = ref.c + dc, tr = ref.r + dr; if(tc < 0 || tr < 0) return false;
const t = card.querySelector('.mydash-sheet-cell[data-addr="' + rbSheetAddr(tc,tr) + '"]');
if(t){ t.focus(); return true; } return false;
}
// ---- Shared spreadsheet selection model: host._sel = {a:anchor, f:edge} ----
function rbSheetGridDims(host){ return {cols: host.querySelectorAll('.mydash-sheet-colh').length, rows: host.querySelectorAll('.mydash-sheet-rowh').length}; }
function rbSheetCell(host, c, r){ return host.querySelector('.mydash-sheet-cell[data-addr="'+rbSheetAddr(c,r)+'"]'); }
function rbSheetSelBounds(host){ var s=host._sel; if(!s) return null; return {c0:Math.min(s.a.c,s.f.c), r0:Math.min(s.a.r,s.f.r), c1:Math.max(s.a.c,s.f.c), r1:Math.max(s.a.r,s.f.r)}; }
function rbSheetPaintSel(host){
if(host._addPaint){ host._addPaint=false; } else { host._selRanges=null; }
host.querySelectorAll('.mydash-sheet-sel').forEach(function(x){ x.classList.remove('mydash-sheet-sel'); });
host.querySelectorAll('.mydash-sheet-hl').forEach(function(x){ x.classList.remove('mydash-sheet-hl'); });
var _xr=host._selRanges||[]; for(var _i=0;_i<_xr.length;_i++){ var _er=_xr[_i]; for(var _r=_er.r0;_r<=_er.r1;_r++){ for(var _c=_er.c0;_c<=_er.c1;_c++){ var _cl=rbSheetCell(host,_c,_r); if(_cl) _cl.classList.add('mydash-sheet-sel'); } } for(var _ec=_er.c0;_ec<=_er.c1;_ec++){ var _ech=host.querySelector('.mydash-sheet-colh[data-col="'+_ec+'"]'); if(_ech) _ech.classList.add('mydash-sheet-hl'); } for(var _err=_er.r0;_err<=_er.r1;_err++){ var _erh=host.querySelector('.mydash-sheet-rowh[data-row="'+_err+'"]'); if(_erh) _erh.classList.add('mydash-sheet-hl'); } }
var b=rbSheetSelBounds(host); if(!b) return;
for(var r=b.r0;r<=b.r1;r++){ for(var c=b.c0;c<=b.c1;c++){ var cell=rbSheetCell(host,c,r); if(cell) cell.classList.add('mydash-sheet-sel'); } }
for(var c2=b.c0;c2<=b.c1;c2++){ var ch=host.querySelector('.mydash-sheet-colh[data-col="'+c2+'"]'); if(ch) ch.classList.add('mydash-sheet-hl'); }
for(var r2=b.r0;r2<=b.r1;r2++){ var rh=host.querySelector('.mydash-sheet-rowh[data-row="'+r2+'"]'); if(rh) rh.classList.add('mydash-sheet-hl'); }
var nb=host.querySelector('.mydash-sheet-namebox'); if(nb) nb.textContent = (b.c0===b.c1&&b.r0===b.r1) ? rbSheetAddr(b.c0,b.r0) : (rbSheetAddr(b.c0,b.r0)+':'+rbSheetAddr(b.c1,b.r1));
host.querySelectorAll('.mydash-sheet-fill-handle').forEach(function(x){ x.remove(); });
var brCell=rbSheetCell(host, b.c1, b.r1); if(brCell){ var brTd=brCell.closest('.mydash-sheet-td'); if(brTd){ var fh=document.createElement('span'); fh.className='mydash-sheet-fill-handle'; fh.title='Fill down to end of data'; brTd.appendChild(fh); } }
if(host.classList.contains('rb-ws-host') && typeof rbCellsUpdateStats==='function') rbCellsUpdateStats();
}
function rbSheetSetAnchor(host, c, r){ host._sel={a:{c:c,r:r}, f:{c:c,r:r}}; rbSheetPaintSel(host); }
function rbSheetExtend(host, c, r){ if(!host._sel) return; var d=rbSheetGridDims(host); c=Math.max(0,Math.min(c,d.cols-1)); r=Math.max(0,Math.min(r,d.rows-1)); host._sel.f={c:c,r:r}; rbSheetPaintSel(host); }
function rbSheetHasData(host, c, r){ var cell=rbSheetCell(host,c,r); return !!(cell && (cell.dataset.raw||'')!==''); }
function rbSheetJump(host, c, r, key){ var d=rbSheetGridDims(host); var dc=key==='ArrowLeft'?-1:key==='ArrowRight'?1:0, dr=key==='ArrowUp'?-1:key==='ArrowDown'?1:0; var cc=c, rr=r; var inb=function(x,y){ return x>=0&&y>=0&&x<d.cols&&y<d.rows; }; if(!inb(cc+dc, rr+dr)) return {c:cc,r:rr}; if(rbSheetHasData(host,cc,rr) && rbSheetHasData(host,cc+dc,rr+dr)){ while(inb(cc+dc,rr+dr) && rbSheetHasData(host,cc+dc,rr+dr)){ cc+=dc; rr+=dr; } } else { do { cc+=dc; rr+=dr; } while(inb(cc+dc,rr+dr) && !rbSheetHasData(host,cc,rr)); cc=Math.max(0,Math.min(cc,d.cols-1)); rr=Math.max(0,Math.min(rr,d.rows-1)); } return {c:cc,r:rr}; }
function rbSheetLastData(host){ var d=rbSheetGridDims(host); var mc=0, mr=0; for(var r=0;r<d.rows;r++){ for(var c=0;c<d.cols;c++){ if(rbSheetHasData(host,c,r)){ if(c>mc) mc=c; if(r>mr) mr=r; } } } return {c:mc, r:mr}; }
function rbSheetHostCommit(host, addr, val){ if(host.classList.contains('rb-ws-host')){ rbCellsCommit(addr, val); } else { var id=host.getAttribute('data-card-id'); if(id) mydashSheetCommit(id, addr, val); } }
function rbSheetHostRefresh(host){ if(host.classList.contains('rb-ws-host')){ rbCellsRefresh(host); } else { var id=host.getAttribute('data-card-id'); var it=mydashLoad().find(function(x){return x.id===id;}); if(it) mydashSheetRefresh(host, it); } }
function rbSheetHostRaw(host, addr){ if(host.classList.contains('rb-ws-host')){ var s=rbCellsLoad(); return (s.cells&&s.cells[addr])||''; } var id=host.getAttribute('data-card-id'); var it=mydashLoad().find(function(x){return x.id===id;})||{}; return (it.cells&&it.cells[addr])||''; }
function rbSheetSetColW(host, c, w){ if(host.classList.contains('rb-ws-host')){ var s=rbCellsLoad(); s.colW=s.colW||{}; s.colW[c]=w; rbCellsWrite(s); } else { var id=host.getAttribute('data-card-id'); var arr=mydashLoad(); var it=arr.find(function(x){return x.id===id;}); if(it){ it.colW=it.colW||{}; it.colW[c]=w; mydashWrite(arr); } } }
function rbSheetDisplayMap(host){ if(host.classList.contains('rb-ws-host')){ var s=rbCellsLoad(); return rbSheetRecalc(s.cells||{}, s.rows||12, s.cols||8).display; } var id=host.getAttribute('data-card-id'); var it=mydashLoad().find(function(x){return x.id===id;})||{}; return rbSheetRecalc(it.cells||{}, it.rows||8, it.cols||6).display; }
function rbSheetSyncActive(host){ var ae=document.activeElement; if(!ae||!ae.classList||!ae.classList.contains('mydash-sheet-cell')||!host.contains(ae)) return; var raw=rbSheetHostRaw(host, ae.dataset.addr); ae.dataset.raw=raw; ae.value=raw; ae._dirty=false; if(ae.select) ae.select(); }
function rbSheetAllSelRects(host){ var rects=(host._selRanges||[]).slice(); var b=rbSheetSelBounds(host); if(b) rects.push(b); return rects; }
function rbSheetClearSel(host){ var rects=rbSheetAllSelRects(host); if(!rects.length) return; rects.forEach(function(b){ for(var r=b.r0;r<=b.r1;r++){ for(var c=b.c0;c<=b.c1;c++){ rbSheetHostCommit(host, rbSheetAddr(c,r), ''); } } }); rbSheetHostRefresh(host); rbSheetSyncActive(host); rbSheetPaintSel(host); }
// ===== Cells undo/redo (a synchronous bulk op coalesces into one step via the armed flag) =====
var _rbCellsUndo=[], _rbCellsRedo=[], _rbCellsUndoArmed=true;
function rbCellsSnap(){ try{ return localStorage.getItem(rbCellsKey()); }catch(_){ return null; } }
function rbCellsPushUndo(){ if(!_rbCellsUndoArmed) return; _rbCellsUndo.push(rbCellsSnap()); if(_rbCellsUndo.length>80) _rbCellsUndo.shift(); _rbCellsRedo.length=0; _rbCellsUndoArmed=false; setTimeout(function(){ _rbCellsUndoArmed=true; }, 0); }
function rbCellsApplySnap(snap){ try{ if(snap==null) localStorage.removeItem(rbCellsKey()); else localStorage.setItem(rbCellsKey(), snap); }catch(_){} try{ rbRenderCells(); }catch(_){} }
function rbCellsUndo(){ if(!_rbCellsUndo.length){ if(typeof showActionToast==='function') showActionToast('Nothing to undo'); return; } _rbCellsRedo.push(rbCellsSnap()); rbCellsApplySnap(_rbCellsUndo.pop()); }
function rbCellsRedo(){ if(!_rbCellsRedo.length){ if(typeof showActionToast==='function') showActionToast('Nothing to redo'); return; } _rbCellsUndo.push(rbCellsSnap()); rbCellsApplySnap(_rbCellsRedo.pop()); }
// ===== Structural reference adjuster (absolute $refs still move on insert/delete, matching Excel) =====
function rbSheetReindex(f, axis, at, delta){ if(typeof f!=='string' || f.charAt(0)!=='=') return f; var parts=f.split('"'); for(var i=0;i<parts.length;i+=2){ parts[i]=parts[i].replace(/(\$?)([A-Za-z]{1,3})(\$?)(\d{1,7})(?!\s*\()/g, function(m,ad,col,ar,row){ var ci=rbSheetColToIdx(col.toUpperCase()); var ri=parseInt(row,10)-1; if(axis==='col'){ if(delta<0){ if(ci===at) return '#REF!'; if(ci>at) ci+=delta; } else { if(ci>=at) ci+=delta; } } else { if(delta<0){ if(ri===at) return '#REF!'; if(ri>at) ri+=delta; } else { if(ri>=at) ri+=delta; } } if(ci<0||ri<0) return '#REF!'; return ad+rbSheetIdxToCol(ci)+ar+(ri+1); }); } return parts.join('"'); }
// ===== Insert / delete rows & columns (builder Cells) =====
function rbCellsStructEdit(axis, at, delta){ var host=document.getElementById('rb-ws-host'); if(!host) return; rbCellsPushUndo(); var s=rbCellsLoad(); var cells=s.cells||{}; var nc={}; Object.keys(cells).forEach(function(addr){ var ref=rbSheetParseRef(addr); if(!ref){ nc[addr]=cells[addr]; return; } var c=ref.c, r=ref.r; if(axis==='col'){ if(delta<0){ if(c===at) return; if(c>at) c+=delta; } else { if(c>=at) c+=delta; } } else { if(delta<0){ if(r===at) return; if(r>at) r+=delta; } else { if(r>=at) r+=delta; } } nc[rbSheetAddr(c,r)]=rbSheetReindex(cells[addr], axis, at, delta); }); s.cells=nc; if(axis==='col') s.cols=Math.max(1,(s.cols||8)+delta); else s.rows=Math.max(1,(s.rows||12)+delta); rbCellsWrite(s); rbRenderCells(); }
function rbCellsInsertRow(at){ rbCellsStructEdit('row', at, 1); }
function rbCellsDeleteRow(at){ rbCellsStructEdit('row', at, -1); }
function rbCellsInsertCol(at){ rbCellsStructEdit('col', at, 1); }
function rbCellsDeleteCol(at){ rbCellsStructEdit('col', at, -1); }
// ===== Clear a Cells column whose header matches a removed report field =====
function rbCellsClearFieldColumn(label){ if(!label) return false; var s=rbCellsLoad(); if(!s.cells) return false; var cols=s.cols||8, rows=s.rows||12, target=-1; for(var c=0;c<cols;c++){ var h=s.cells[rbSheetAddr(c,0)]; if(typeof h==='string' && h.trim()===String(label).trim()){ target=c; break; } } if(target<0) return false; rbCellsPushUndo(); for(var r=0;r<rows;r++){ delete s.cells[rbSheetAddr(target,r)]; } rbCellsWrite(s); if(document.getElementById('rb-ws-host')){ try{ rbRenderCells(); }catch(_){} } return true; }
// ===== Right-click context menu =====
function rbCellFmt(dv, code){ if(dv==null||dv==='') return ''; var s=String(dv); if(s.charAt(0)==='#') return s; var n=(typeof dv==='number')?dv:parseFloat(s.replace(/[,$%]/g,'')); if(isNaN(n)) return rbSheetFmt(dv); switch(code){ case 'number': return n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); case 'comma': return n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); case 'comma0': return n.toLocaleString(undefined,{maximumFractionDigits:0}); case 'currency': return (n<0?'-$':'$')+Math.abs(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); case 'currency0': return (n<0?'-$':'$')+Math.abs(n).toLocaleString(undefined,{maximumFractionDigits:0}); case 'pct1': return n.toLocaleString(undefined,{minimumFractionDigits:1,maximumFractionDigits:1})+'%'; case 'percent': return (n*100).toLocaleString(undefined,{maximumFractionDigits:0})+'%'; case 'percent2': return (n*100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+'%'; default: return rbSheetFmt(dv); } }
function rbCellsSetFormat(code){ var host=document.getElementById('rb-ws-host'); if(!host) return; var rects=rbSheetAllSelRects(host); if(!rects.length) return; rbCellsPushUndo(); var s=rbCellsLoad(); s.formats=s.formats||{}; rects.forEach(function(b){ for(var r=b.r0;r<=b.r1;r++){ for(var c=b.c0;c<=b.c1;c++){ var addr=rbSheetAddr(c,r); if(!code||code==='general') delete s.formats[addr]; else s.formats[addr]=code; } } }); rbCellsWrite(s); rbRenderCells(); }
// Fill the selection's top row down / left column right (Excel Ctrl+D / Ctrl+R), with reference shifting
function rbSheetFillDownSel(host){ var b=rbSheetSelBounds(host); if(!b||b.r1<=b.r0) return; for(var c=b.c0;c<=b.c1;c++){ var src=rbSheetHostRaw(host, rbSheetAddr(c,b.r0)); for(var r=b.r0+1;r<=b.r1;r++){ var out=(typeof src==='string'&&src.charAt(0)==='=')?rbSheetShiftFormula(src, r-b.r0, 0):src; rbSheetHostCommit(host, rbSheetAddr(c,r), out); } } rbSheetHostRefresh(host); rbSheetSyncActive(host); rbSheetPaintSel(host); }
function rbSheetFillRightSel(host){ var b=rbSheetSelBounds(host); if(!b||b.c1<=b.c0) return; for(var r=b.r0;r<=b.r1;r++){ var src=rbSheetHostRaw(host, rbSheetAddr(b.c0,r)); for(var c=b.c0+1;c<=b.c1;c++){ var out=(typeof src==='string'&&src.charAt(0)==='=')?rbSheetShiftFormula(src, 0, c-b.c0):src; rbSheetHostCommit(host, rbSheetAddr(c,r), out); } } rbSheetHostRefresh(host); rbSheetSyncActive(host); rbSheetPaintSel(host); }
// ===== Find & Replace =====
var _rbFind=null;
function rbFindReplaceInStr(str, find, rep, mc){ if(!find) return str; if(mc) return str.split(find).join(rep); var out='', i=0, fl=find.length, low=str.toLowerCase(), fLow=find.toLowerCase(), idx; while((idx=low.indexOf(fLow,i))>=0){ out+=str.slice(i,idx)+rep; i=idx+fl; } out+=str.slice(i); return out; }
function rbCellsFindStat(msg){ var st=document.getElementById('rb-find-stat'); if(!st) return; if(msg!=null){ st.textContent=msg; return; } if(!_rbFind||!_rbFind.matches.length){ st.textContent=(_rbFind&&_rbFind.q)?'No matches':''; } else { st.textContent=(_rbFind.idx+1)+' / '+_rbFind.matches.length; } }
function rbCellsFindPaint(){ var host=document.getElementById('rb-ws-host'); if(!host) return; host.querySelectorAll('.mydash-sheet-find-hit,.mydash-sheet-find-cur').forEach(function(x){ x.classList.remove('mydash-sheet-find-hit'); x.classList.remove('mydash-sheet-find-cur'); }); if(!_rbFind) return; _rbFind.matches.forEach(function(m,i){ var cell=rbSheetCell(host,m.c,m.r); if(cell) cell.classList.add(i===_rbFind.idx?'mydash-sheet-find-cur':'mydash-sheet-find-hit'); }); }
function rbCellsFindRun(){ if(!_rbFind) return; var qEl=document.getElementById('rb-find-q'); _rbFind.q=qEl?qEl.value:''; var cEl=document.getElementById('rb-find-case'); _rbFind.matchCase=cEl?cEl.checked:false; var s=rbCellsLoad(); var cells=s.cells||{}, rows=s.rows||12, cols=s.cols||8; var matches=[]; if(_rbFind.q!==''){ var needle=_rbFind.matchCase?_rbFind.q:_rbFind.q.toLowerCase(); for(var r=0;r<rows;r++){ for(var c=0;c<cols;c++){ var addr=rbSheetAddr(c,r); var raw=cells[addr]; if(raw==null) continue; var hay=_rbFind.matchCase?String(raw):String(raw).toLowerCase(); if(hay.indexOf(needle)>=0) matches.push({addr:addr,c:c,r:r}); } } } _rbFind.matches=matches; _rbFind.idx=matches.length?0:-1; rbCellsFindPaint(); rbCellsFindStat(); if(matches.length) rbCellsFindGo(0,true); }
function rbCellsFindGo(i, noFocus){ if(!_rbFind||!_rbFind.matches.length) return; var n=_rbFind.matches.length; i=((i%n)+n)%n; _rbFind.idx=i; var m=_rbFind.matches[i]; var host=document.getElementById('rb-ws-host'); if(host){ rbSheetSetAnchor(host,m.c,m.r); var cell=rbSheetCell(host,m.c,m.r); if(cell && cell.scrollIntoView){ try{ cell.scrollIntoView({block:'nearest',inline:'nearest'}); }catch(_){} } } rbCellsFindPaint(); rbCellsFindStat(); }
function rbCellsFindNext(dir){ if(!_rbFind||!_rbFind.matches.length){ rbCellsFindRun(); return; } rbCellsFindGo(_rbFind.idx+(dir||1)); }
function rbCellsReplaceOne(){ if(!_rbFind||!_rbFind.matches.length||_rbFind.idx<0) return; var rEl=document.getElementById('rb-find-r'); var rep=rEl?rEl.value:''; var m=_rbFind.matches[_rbFind.idx]; var prev=_rbFind.idx; var raw=String((rbCellsLoad().cells||{})[m.addr]||''); rbCellsCommit(m.addr, rbFindReplaceInStr(raw,_rbFind.q,rep,_rbFind.matchCase)); var ws=document.getElementById('rb-ws-host'); if(ws) rbCellsRefresh(ws); rbCellsFindRun(); if(_rbFind.matches.length) rbCellsFindGo(Math.min(prev,_rbFind.matches.length-1)); }
function rbCellsReplaceAll(){ if(!_rbFind) return; rbCellsFindRun(); var ms=_rbFind.matches.slice(); if(!ms.length){ rbCellsFindStat('No matches'); return; } var rEl=document.getElementById('rb-find-r'); var rep=rEl?rEl.value:''; rbCellsPushUndo(); var s=rbCellsLoad(); var cells=s.cells||{}, n=0; ms.forEach(function(m){ var raw=String(cells[m.addr]||''); var out=rbFindReplaceInStr(raw,_rbFind.q,rep,_rbFind.matchCase); if(out!==raw){ if(out==='') delete cells[m.addr]; else cells[m.addr]=out; n++; } }); s.cells=cells; rbCellsWrite(s); rbRenderCells(); rbCellsFindRun(); rbCellsFindStat('Replaced '+n); }
function rbCellsFindClose(){ var p=document.getElementById('rb-cells-find'); if(p) p.remove(); _rbFind=null; var host=document.getElementById('rb-ws-host'); if(host) host.querySelectorAll('.mydash-sheet-find-hit,.mydash-sheet-find-cur').forEach(function(x){ x.classList.remove('mydash-sheet-find-hit'); x.classList.remove('mydash-sheet-find-cur'); }); }
function rbCellsFindOpen(showReplace){ var panel=document.getElementById('rb-cells-panel'); if(!panel) return; var existing=document.getElementById('rb-cells-find'); if(existing){ if(showReplace){ var rr=document.getElementById('rb-find-replace-row'); if(rr) rr.style.display='flex'; var rb1=document.getElementById('rb-find-rep'), rb2=document.getElementById('rb-find-repall'); if(rb1)rb1.style.display=''; if(rb2)rb2.style.display=''; } var qf=document.getElementById('rb-find-q'); if(qf){ qf.focus(); qf.select(); } return; } _rbFind={q:'',matchCase:false,matches:[],idx:-1}; if(getComputedStyle(panel).position==='static') panel.style.position='relative'; var p=document.createElement('div'); p.id='rb-cells-find'; p.style.cssText='position:absolute;top:6px;right:10px;z-index:60;background:#fff;border:1px solid #cfd6dd;border-radius:8px;box-shadow:0 6px 22px rgba(0,0,0,.16);padding:8px;font:12px -apple-system,Segoe UI,Roboto,sans-serif;display:flex;flex-direction:column;gap:6px;width:296px;'; var btn='padding:4px 9px;border:1px solid #d4d4d8;background:#f7f8fa;border-radius:5px;cursor:pointer;font:inherit;'; var inp='flex:1;padding:5px 8px;border:1px solid #d4d4d8;border-radius:5px;font:inherit;min-width:0;'; p.innerHTML='<div style="display:flex;gap:6px;align-items:center;"><input id="rb-find-q" placeholder="Find" style="'+inp+'"/><span id="rb-find-stat" style="font-size:11px;color:#5f6368;min-width:46px;text-align:right;"></span><button id="rb-find-x" title="Close" style="'+btn+'border:none;background:none;font-size:15px;padding:0 4px;">\u00d7</button></div><div id="rb-find-replace-row" style="display:'+(showReplace?'flex':'none')+';gap:6px;"><input id="rb-find-r" placeholder="Replace with" style="'+inp+'"/></div><div style="display:flex;gap:6px;align-items:center;"><label style="font-size:11px;display:flex;gap:4px;align-items:center;cursor:pointer;"><input type="checkbox" id="rb-find-case"/>Match case</label><span style="flex:1;"></span><button id="rb-find-prev" style="'+btn+'">Prev</button><button id="rb-find-next" style="'+btn+'">Next</button><button id="rb-find-rep" style="'+btn+'display:'+(showReplace?'':'none')+';">Replace</button><button id="rb-find-repall" style="'+btn+'display:'+(showReplace?'':'none')+';">All</button></div>'; panel.appendChild(p); var q=document.getElementById('rb-find-q'); q.addEventListener('input', rbCellsFindRun); q.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); rbCellsFindNext(e.shiftKey?-1:1); } else if(e.key==='Escape'){ e.preventDefault(); rbCellsFindClose(); } }); document.getElementById('rb-find-case').addEventListener('change', rbCellsFindRun); document.getElementById('rb-find-x').addEventListener('click', rbCellsFindClose); document.getElementById('rb-find-prev').addEventListener('click', function(){ rbCellsFindNext(-1); }); document.getElementById('rb-find-next').addEventListener('click', function(){ rbCellsFindNext(1); }); document.getElementById('rb-find-rep').addEventListener('click', rbCellsReplaceOne); document.getElementById('rb-find-repall').addEventListener('click', rbCellsReplaceAll); var rEl=document.getElementById('rb-find-r'); if(rEl) rEl.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); rbCellsReplaceOne(); } else if(e.key==='Escape'){ e.preventDefault(); rbCellsFindClose(); } }); q.focus(); }
// ===== Column sort (sorts the selected rows by the anchor column; blanks last; carries formats) =====
function rbCellsDataRegion(host, c, r){ var d=rbSheetGridDims(host); if(!rbSheetHasData(host,c,r)) return {c0:c,c1:c,r0:r,r1:r}; var c0=c,c1=c,r0=r,r1=r,changed=true; function colData(col,a,b){ for(var rr=a;rr<=b;rr++) if(rbSheetHasData(host,col,rr)) return true; return false; } function rowData(row,a,b){ for(var cc=a;cc<=b;cc++) if(rbSheetHasData(host,cc,row)) return true; return false; } while(changed){ changed=false; if(c0>0 && colData(c0-1,r0,r1)){ c0--; changed=true; } if(c1<d.cols-1 && colData(c1+1,r0,r1)){ c1++; changed=true; } if(r0>0 && rowData(r0-1,c0,c1)){ r0--; changed=true; } if(r1<d.rows-1 && rowData(r1+1,c0,c1)){ r1++; changed=true; } } return {c0:c0,c1:c1,r0:r0,r1:r1}; }
function rbCellsHasHeader(host, reg){ if(reg.r1<=reg.r0) return false; var topText=0, topNum=0, belowNum=0; for(var c=reg.c0;c<=reg.c1;c++){ var t=rbSheetHostRaw(host, rbSheetAddr(c,reg.r0)); if(t!=null&&t!==''){ var tn=parseFloat(String(t).replace(/[,$%]/g,'')); if(!isNaN(tn)&&isFinite(tn)&&/^[-+]?[\d,.$%\s]+$/.test(String(t))) topNum++; else topText++; } var b=rbSheetHostRaw(host, rbSheetAddr(c,reg.r0+1)); if(b!=null&&b!==''){ var bn=parseFloat(String(b).replace(/[,$%]/g,'')); if(!isNaN(bn)) belowNum++; } } return topText>0 && topNum===0 && belowNum>0; }
function rbCellsSortSelection(dir){ var host=document.getElementById('rb-ws-host'); if(!host) return; var b=rbSheetSelBounds(host); var reg, keyC; var singleColOrCell = !b || (b.c0===b.c1); if(singleColOrCell){ var ac=(host._sel&&host._sel.a)?host._sel.a.c:(b?b.c0:0); var ar=(host._sel&&host._sel.a)?host._sel.a.r:(b?b.r0:0); reg=rbCellsDataRegion(host, ac, ar); keyC=ac; } else { reg={c0:b.c0,c1:b.c1,r0:b.r0,r1:b.r1}; keyC=(host._sel&&host._sel.a)?Math.min(Math.max(host._sel.a.c,b.c0),b.c1):b.c0; } var startR = rbCellsHasHeader(host, reg) ? reg.r0+1 : reg.r0; if(reg.r1<=startR) return; rbCellsPushUndo(); var s=rbCellsLoad(); var cells=s.cells||{}; var fmts=s.formats||{}; var rows=[]; for(var r=startR;r<=reg.r1;r++){ var vals={}, fm={}; for(var c=reg.c0;c<=reg.c1;c++){ var addr=rbSheetAddr(c,r); vals[c]=cells[addr]; fm[c]=fmts[addr]; } rows.push({key:cells[rbSheetAddr(keyC,r)], vals:vals, fm:fm}); } var sgn=(dir==='desc')?-1:1; rows.sort(function(x,y){ var a=x.key, bb=y.key; var ae=(a==null||a===''), be=(bb==null||bb===''); if(ae&&be) return 0; if(ae) return 1; if(be) return -1; var an=parseFloat(String(a).replace(/[,$%]/g,'')), bn=parseFloat(String(bb).replace(/[,$%]/g,'')); var bothNum=!isNaN(an)&&!isNaN(bn); var cmp; if(bothNum) cmp=an-bn; else { var as=String(a).toLowerCase(), bs=String(bb).toLowerCase(); cmp=as<bs?-1:as>bs?1:0; } return sgn*cmp; }); for(var i=0;i<rows.length;i++){ var rr=startR+i; for(var c2=reg.c0;c2<=reg.c1;c2++){ var ad=rbSheetAddr(c2,rr); var v=rows[i].vals[c2]; if(v==null||v==='') delete cells[ad]; else cells[ad]=v; var f=rows[i].fm[c2]; if(f) fmts[ad]=f; else delete fmts[ad]; } } s.cells=cells; s.formats=fmts; rbCellsWrite(s); rbRenderCells(); host._sel={a:{c:reg.c0,r:startR}, f:{c:reg.c1,r:reg.r1}}; rbSheetPaintSel(host); }
// ===== Excel reflex helpers: F4 absolute-ref toggle, AutoSum, Ctrl+Enter fill =====
function rbSheetF4Toggle(inp){ var v=inp.value||''; var pos=(inp.selectionStart!=null)?inp.selectionStart:v.length; var re=/(\$?)([A-Za-z]{1,3})(\$?)(\d+)/g; var m, hit=null, prev=null; while((m=re.exec(v))){ var s=m.index, en=s+m[0].length; var t={s:s,e:en,c$:m[1]==='$',col:m[2],r$:m[3]==='$',row:m[4]}; if(pos>=s && pos<=en){ hit=t; break; } if(en<=pos){ prev=t; } else { if(!prev) prev=t; break; } } var f=hit||prev; if(!f) return; var nc, nr; if(!f.c$ && !f.r$){ nc=true; nr=true; } else if(f.c$ && f.r$){ nc=false; nr=true; } else if(!f.c$ && f.r$){ nc=true; nr=false; } else { nc=false; nr=false; } var tok=(nc?'$':'')+f.col+(nr?'$':'')+f.row; inp.value=v.slice(0,f.s)+tok+v.slice(f.e); inp._dirty=true; var np=f.s+tok.length; if(inp.setSelectionRange){ try{ inp.setSelectionRange(np,np); }catch(_){} } var host=inp.closest('.mydash-card, .rb-ws-host'); var fl=host&&host.querySelector('.mydash-sheet-formula-line'); if(fl) fl.textContent=inp.value; }
function rbSheetAutoSum(host, ref){ var c=ref.c, r=ref.r; function isNum(cc,rr){ var raw=rbSheetHostRaw(host, rbSheetAddr(cc,rr)); if(raw==null||raw==='') return false; if(typeof raw==='string'&&raw.charAt(0)==='=') return true; return !isNaN(parseFloat(String(raw).replace(/[,$%]/g,''))); } var rng=null; if(r>0 && isNum(c,r-1)){ var top=r-1; while(top-1>=0 && isNum(c,top-1)) top--; rng=rbSheetAddr(c,top)+':'+rbSheetAddr(c,r-1); } else if(c>0 && isNum(c-1,r)){ var left=c-1; while(left-1>=0 && isNum(left-1,r)) left--; rng=rbSheetAddr(left,r)+':'+rbSheetAddr(c-1,r); } var cell=rbSheetCell(host,c,r); if(!cell) return; var formula='=SUM('+(rng||'')+')'; cell.focus(); cell.value=formula; cell._dirty=true; var cp=formula.length-1; if(cell.setSelectionRange){ try{ cell.setSelectionRange(cp,cp); }catch(_){} } var fl=host.querySelector('.mydash-sheet-formula-line'); if(fl) fl.textContent=formula; }
function rbSheetCtrlEnter(host, inp, ref){ var val=inp.value; var b=rbSheetSelBounds(host); var anchor=(host._sel&&host._sel.a)?host._sel.a:ref; inp._dirty=false; if(b && !(b.c0===b.c1 && b.r0===b.r1)){ for(var rr=b.r0; rr<=b.r1; rr++){ for(var cc=b.c0; cc<=b.c1; cc++){ var dRow=rr-anchor.r, dCol=cc-anchor.c; var out=(typeof val==='string'&&val.charAt(0)==='=')?rbSheetShiftFormula(val,dRow,dCol):val; rbSheetHostCommit(host, rbSheetAddr(cc,rr), out); } } rbSheetHostRefresh(host); rbSheetSyncActive(host); rbSheetPaintSel(host); } else { rbSheetHostCommit(host, rbSheetAddr(ref.c,ref.r), val); rbSheetHostRefresh(host); } var ac=rbSheetCell(host, ref.c, ref.r); if(ac){ ac.focus(); ac.value=ac.dataset.raw||''; } }
