function rbFbShow(el){ if(!el||!el.classList||!el.classList.contains('mydash-sheet-cell')){ rbFbClose(); return; } var a=rbFbAnalyze(el); if(!a){ rbFbClose(); return; } if(a.nameTok && a.nameTok.length>=1){ var names=rbFbMatch(a.nameTok); if(names.length && !(names.length===1 && names[0]===a.nameTok.toUpperCase())){ rbFbShowList(el, a, names); return; } } if(a.fnName && RB_FN_CATALOG[a.fnName]!=null){ rbFbShowHint(el, a.fnName, RB_FN_CATALOG[a.fnName], a.argIndex); return; } rbFbClose(); }
