function rbCellNum(dv){ if(dv==null||dv==='') return null; if(typeof dv==='number') return isFinite(dv)?dv:null; var s=String(dv); if(s.charAt(0)==='#') return null; var p=parseFloat(s.replace(/[,$%\s]/g,'')); return isNaN(p)?null:p; }
