function rbCFRectsIntersect(a,b){ return !(a.c1<b.c0||a.c0>b.c1||a.r1<b.r0||a.r0>b.r1); }
function rbCFParseRanges(str){ var out=[]; String(str||'').split(',').forEach(function(part){ part=part.trim(); if(!part) return; var seg=part.split(':'); var a=rbSheetParseRef(seg[0].trim()); if(!a) return; var b2=(seg[1]&&rbSheetParseRef(seg[1].trim()))||a; out.push({c0:Math.min(a.c,b2.c), c1:Math.max(a.c,b2.c), r0:Math.min(a.r,b2.r), r1:Math.max(a.r,b2.r)}); }); return out; }
function rbCFKindLabel(cf){ var L={gt:'Greater than',lt:'Less than',gte:'\u2265',lte:'\u2264',eq:'Equal to',ne:'Not equal',between:'Between',nbetween:'Not between',contains:'Text contains',ncontains:'Not contains',begins:'Begins with',ends:'Ends with',dup:'Duplicate values',unique:'Unique values',topN:'Top N',topPct:'Top %',botN:'Bottom N',botPct:'Bottom %',aboveAvg:'Above average',belowAvg:'Below average'}; if(cf.kind==='scale2') return '2-color scale'; if(cf.kind==='scale3') return '3-color scale'; if(cf.kind==='databar') return 'Data bar'; if(cf.kind==='iconset') return 'Icon set ('+(cf.iconStyle||'3arrows')+')'; if(cf.kind==='crosscol') return 'When col '+rbSheetIdxToCol(cf.refCol)+' '+(cf.op||'eq')+' '+(cf.v1raw||''); if(cf.kind==='formula') return 'Formula: '+(cf.expr||''); var base=L[cf.op]||cf.op; var v=(cf.v1raw!=null&&cf.v1raw!=='')?(' '+cf.v1raw):''; var v2=(cf.op==='between'||cf.op==='nbetween')&&cf.v2raw!=null?(' & '+cf.v2raw):''; return base+v+v2; }
