function rbCFgv(id){ var e=document.getElementById(id); return e?e.value:''; }
function rbCFchk(id){ var e=document.getElementById(id); return e?!!e.checked:false; }
function rbCFBasisOf(pfx){ return {type:rbCFgv(pfx+'-b')||'min', val:rbCFgv(pfx+'-v')}; }
