  if(mode==='transpose'){ for(i=0;i<ch;i++){ for(j=0;j<cw;j++){ tr=tR0+j; tc=tC0+i; if(tr>=dims.rows||tc>=dims.cols) continue; var raw=clip.raws[i][j]; var out=(typeof raw==='string'&&raw.charAt(0)==='=')?String(clip.vals[i][j]):raw; rbSheetHostCommit(host, rbSheetAddr(tc,tr), out); if(tr>lastR)lastR=tr; if(tc>lastC)lastC=tc; } } if(isWS){ var st=rbCellsLoad(); st.formats=st.formats||{}; for(i=0;i<ch;i++){ for(j=0;j<cw;j++){ tr=tR0+j; tc=tC0+i; if(tr>=dims.rows||tc>=dims.cols) continue; f=clip.fmts[i][j]; ad=rbSheetAddr(tc,tr); if(f) st.formats[ad]=f; else delete st.formats[ad]; } } rbCellsWrite(st); } }
  else if(mode==='values'){ for(i=0;i<ch;i++){ for(j=0;j<cw;j++){ tr=tR0+i; tc=tC0+j; if(tr>=dims.rows||tc>=dims.cols) continue; var v=clip.vals[i][j]; rbSheetHostCommit(host, rbSheetAddr(tc,tr), (v==null?'':String(v))); if(tr>lastR)lastR=tr; if(tc>lastC)lastC=tc; } } }
  else if(mode==='formats'){ if(!isWS) return false; var sf=rbCellsLoad(); sf.formats=sf.formats||{}; for(i=0;i<ch;i++){ for(j=0;j<cw;j++){ tr=tR0+i; tc=tC0+j; if(tr>=dims.rows||tc>=dims.cols) continue; f=clip.fmts[i][j]; ad=rbSheetAddr(tc,tr); if(f) sf.formats[ad]=f; else delete sf.formats[ad]; if(tr>lastR)lastR=tr; if(tc>lastC)lastC=tc; } } rbCellsWrite(sf); }
