function rbSheetFillDown(host){ var b=rbSheetSelBounds(host); if(!b) return; var d=rbSheetGridDims(host); var probeCol=(b.c0>0)?b.c0-1:((b.c1+1<=d.cols-1)?b.c1+1:-1); var endR; if(probeCol>=0){ endR=b.r1; for(var r=b.r1+1;r<d.rows;r++){ if(rbSheetHasData(host,probeCol,r)) endR=r; else break; } } else { endR=d.rows-1; } if(endR<=b.r1) return; if(host.classList.contains('rb-ws-host') && typeof rbCellsPushUndo==='function') rbCellsPushUndo(); var srcH=b.r1-b.r0+1; var count=endR-b.r1; for(var cc=b.c0; cc<=b.c1; cc++){ var srcRaws=[]; for(var rs=b.r0; rs<=b.r1; rs++) srcRaws.push(rbSheetHostRaw(host, rbSheetAddr(cc,rs))); var series=rbFillSeriesGen(srcRaws, count); for(var k=0;k<count;k++){ var rr=b.r1+1+k; var out; if(series){ out=series[k]; } else { var srcR=b.r0+((rr-b.r0)%srcH); var srcRaw=rbSheetHostRaw(host, rbSheetAddr(cc,srcR)); out=(typeof srcRaw==='string'&&srcRaw.charAt(0)==='=')?rbSheetShiftFormula(srcRaw, rr-srcR, 0):srcRaw; } rbSheetHostCommit(host, rbSheetAddr(cc,rr), out); } } rbSheetHostRefresh(host); rbSheetSyncActive(host); host._sel={a:{c:b.c0,r:b.r0}, f:{c:b.c1,r:endR}}; rbSheetPaintSel(host); }
function rbSheetCanPoint(inp){ if(!inp._dirty) return false; var v=inp.value||''; if(v.charAt(0)!=='=') return false; if(inp._point) return true; var pos=(inp.selectionStart!=null)?inp.selectionStart:v.length; var before=v.slice(0,pos).replace(/\s+$/,''); if(before==='=') return true; var last=before.charAt(before.length-1); return '=+-*/^&(,<>'.indexOf(last)>=0; }
function rbSheetPaintPoint(host, p){ host.querySelectorAll('.mydash-sheet-point').forEach(function(x){ x.classList.remove('mydash-sheet-point'); }); if(!p) return; var c0=Math.min(p.c0,p.c), c1=Math.max(p.c0,p.c), r0=Math.min(p.r0,p.r), r1=Math.max(p.r0,p.r); for(var r=r0;r<=r1;r++){ for(var c=c0;c<=c1;c++){ var cell=rbSheetCell(host,c,r); if(cell) cell.classList.add('mydash-sheet-point'); } } }
