// Pack any items lacking a {x,y,w,h} layout 2-up below whatever is already placed.
function mydashEnsureLayout(items){
let changed = false, nextRow = 0, placed = 0;
items.forEach(function(it){ if(it.layout && typeof it.layout.x === 'number') nextRow = Math.max(nextRow, it.layout.y + it.layout.h); });
items.forEach(function(it){
if(it.layout && typeof it.layout.x === 'number') return;
it.layout = {x: (placed % 2) ? 6 : 0, y: nextRow + Math.floor(placed/2)*10, w: 6, h: 10};
placed++; changed = true;
});
return changed;
}
// Floating layer order: bring-to-front / send-to-back via context menu.
function mydashSetLayer(id, where){
const all = mydashLoad();
const me = currentUser();
const mine = all.filter(function(it){return !it.owner || it.owner === me.id;});
const zs = mine.map(function(it){ return (it.layout && it.layout.z) || 1; });
const maxZ = zs.length ? Math.max.apply(null, zs) : 1;
const minZ = zs.length ? Math.min.apply(null, zs) : 1;
const t = all.find(function(x){return x.id === id;});
if(!t || !t.layout) return;
t.layout.z = (where === 'front') ? maxZ + 1 : minZ - 1;
mydashWrite(all); renderMyDashboard();
}
function mydashShowTileMenu(x, y, id){
document.querySelectorAll('.mydash-tile-menu').forEach(function(m){ m.remove(); });
const menu = document.createElement('div');
menu.className = 'mydash-tile-menu';
menu.innerHTML =
'<button class="mydash-tile-menu-item" data-act="front">\u2912 Bring to front</button>' +
'<button class="mydash-tile-menu-item" data-act="back">\u2913 Send to back</button>' +
'<div class="mydash-tile-menu-sep"></div>' +
'<button class="mydash-tile-menu-item mydash-tile-menu-danger" data-act="remove">\u00d7 Remove</button>';
document.body.appendChild(menu);
menu.style.position = 'fixed';
menu.style.left = Math.min(x, window.innerWidth - menu.offsetWidth - 8) + 'px';
menu.style.top = Math.min(y, window.innerHeight - menu.offsetHeight - 8) + 'px';
menu.style.zIndex = '6000';
menu.querySelectorAll('[data-act]').forEach(function(b){
b.addEventListener('click', function(){
const act = b.dataset.act;
if(act === 'front') mydashSetLayer(id, 'front');
else if(act === 'back') mydashSetLayer(id, 'back');
else if(act === 'remove'){ const remaining = mydashLoad().filter(function(x){return x.id !== id;}); mydashWrite(remaining); renderMyDashboard(); }
menu.remove();
});
});
setTimeout(function(){ document.addEventListener('mousedown', function h(ev){ if(!menu.contains(ev.target)){ menu.remove(); document.removeEventListener('mousedown', h, true); } }, true); }, 0);
}
// Tiled pack: flow all tiles left-to-right into non-overlapping rows on the 12-col grid.
function mydashTidyLayout(){
const all = mydashLoad();
const me = currentUser();
const mine = all.filter(function(it){return !it.owner || it.owner === me.id;});
mydashEnsureLayout(mine);
const ordered = mine.slice().sort(function(a, b){
const la = a.layout, lb = b.layout;
return (la.y - lb.y) || (la.x - lb.x);
});
let cx = 0, rowY = 0, rowH = 0;
ordered.forEach(function(it){
const w = Math.max(1, Math.min(MYDASH_COLS, it.layout.w));
const h = Math.max(2, it.layout.h);
if(cx + w > MYDASH_COLS){ rowY += rowH; cx = 0; rowH = 0; }
it.layout.x = cx; it.layout.y = rowY; it.layout.w = w;
cx += w; rowH = Math.max(rowH, h);
});
mydashWrite(all); renderMyDashboard();
if(typeof showActionToast === 'function') showActionToast('Tiles tidied into a packed grid');
}
// Apply each card's grid-unit layout as absolute px against the live container width.
function mydashPositionCards(grid, items){
const colW = (grid.clientWidth - (MYDASH_COLS-1)*MYDASH_GAP) / MYDASH_COLS;
let maxBottom = 0;
grid.querySelectorAll('.mydash-card').forEach(function(card){
const it = items.find(function(x){return x.id === card.dataset.cardId;});
if(!it || !it.layout) return;
const L = it.layout;
const left = L.x * (colW + MYDASH_GAP);
const top = L.y * (MYDASH_ROWH + MYDASH_GAP);
const width = L.w * colW + (L.w - 1) * MYDASH_GAP;
const height = L.h * MYDASH_ROWH + (L.h - 1) * MYDASH_GAP;
card.style.position = 'absolute';
card.style.left = left + 'px'; card.style.top = top + 'px';
card.style.width = width + 'px'; card.style.height = height + 'px';
card.style.zIndex = String((L.z || 1));
card.setAttribute('draggable', 'false');
maxBottom = Math.max(maxBottom, top + height);
});
grid.style.minHeight = (maxBottom + 16) + 'px';
}
// Pointer-driven move (header handle) + resize (SE handle); snaps to grid units on release.
function wireDashCanvasEdit(grid, items, allItems){
const cellW = function(){ return (grid.clientWidth - (MYDASH_COLS-1)*MYDASH_GAP)/MYDASH_COLS + MYDASH_GAP; };
const rowU = MYDASH_ROWH + MYDASH_GAP;
grid.querySelectorAll('.mydash-card').forEach(function(card){
const it = items.find(function(x){return x.id === card.dataset.cardId;});
if(!it || !it.layout) return;
const handle = card.querySelector('.mydash-card-handle');
if(handle) handle.addEventListener('pointerdown', function(e){ beginMove(e, card, it); });
const rh = card.querySelector('.mydash-canvas-resize');
if(rh) rh.addEventListener('pointerdown', function(e){ beginResize(e, card, it); });
const rm = card.querySelector('.mydash-card-btn-remove');
if(rm) rm.addEventListener('click', function(e){ e.stopPropagation(); e.preventDefault(); const remaining = mydashLoad().filter(function(x){return x.id !== card.dataset.cardId;}); mydashWrite(remaining); renderMyDashboard(); });
const ex = card.querySelector('.mydash-card-btn-expand');
if(ex){ ex.addEventListener('pointerdown', function(e){ e.stopPropagation(); }); ex.addEventListener('click', function(e){ e.stopPropagation(); e.preventDefault(); openDashCardFullscreen(card.dataset.cardId, false); }); }
if(it.type === 'text'){
const tb = card.querySelector('.mydash-obj-text-body');
if(tb){
tb.setAttribute('contenteditable', 'true');
tb.classList.add('mydash-obj-editing');
tb.addEventListener('pointerdown', function(ev){ ev.stopPropagation(); });
tb.addEventListener('focus', function(){ if(tb.querySelector('.mydash-obj-placeholder')) tb.innerHTML = ''; });
tb.addEventListener('blur', function(){
const txt = tb.innerText.replace(/\u00a0/g, ' ').trim();
const all = mydashLoad(); const t = all.find(function(x){return x.id === it.id;});
if(t){ t.text = txt; mydashWrite(all); }
if(!txt) tb.innerHTML = '<span class="mydash-obj-placeholder">Add text\u2026</span>';
});
}
}
});
function beginMove(e, card, it){
e.preventDefault(); e.stopPropagation();
const cw = cellW(); const sx = e.clientX, sy = e.clientY; const ox = it.layout.x, oy = it.layout.y;
const baseL = ox * cw, baseT = oy * rowU;
card.classList.add('mydash-card-dragging');
function mv(ev){ card.style.left = Math.max(0, baseL + (ev.clientX - sx)) + 'px'; card.style.top = Math.max(0, baseT + (ev.clientY - sy)) + 'px'; }
function up(ev){
document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up);
let nx = Math.round((baseL + (ev.clientX - sx)) / cw);
let ny = Math.round((baseT + (ev.clientY - sy)) / rowU);
it.layout.x = Math.max(0, Math.min(MYDASH_COLS - it.layout.w, nx));
it.layout.y = Math.max(0, ny);
card.classList.remove('mydash-card-dragging');
mydashWrite(allItems); renderMyDashboard();
}
document.addEventListener('pointermove', mv); document.addEventListener('pointerup', up);
}
function beginResize(e, card, it){
e.preventDefault(); e.stopPropagation();
const cw = cellW(); const colWonly = cw - MYDASH_GAP;
const sx = e.clientX, sy = e.clientY; const ow = it.layout.w, oh = it.layout.h;
const startW = ow * colWonly + (ow-1) * MYDASH_GAP, startH = oh * MYDASH_ROWH + (oh-1) * MYDASH_GAP;
card.classList.add('mydash-card-resizing');
function mv(ev){ card.style.width = Math.max(colWonly, startW + (ev.clientX - sx)) + 'px'; card.style.height = Math.max(MYDASH_ROWH*3, startH + (ev.clientY - sy)) + 'px'; }
function up(ev){
document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up);
let nw = Math.round((startW + (ev.clientX - sx) + MYDASH_GAP) / cw);
let nh = Math.round((startH + (ev.clientY - sy) + MYDASH_GAP) / rowU);
it.layout.w = Math.max(2, Math.min(MYDASH_COLS - it.layout.x, nw));
it.layout.h = Math.max(3, nh);
card.classList.remove('mydash-card-resizing');
mydashWrite(allItems); renderMyDashboard();
}
document.addEventListener('pointermove', mv); document.addEventListener('pointerup', up);
}
}

// === Saved reports render ==================================================
// Restore a saved dashboard into My dashboard (replaces the viewer's own tiles; keeps team tiles).
function mydashRestoreDashboard(item){
if(!item || !item.tiles) return;
const me = currentUser();
// Open as its OWN dashboard (never overwrite My dashboard). If we've already opened this
// saved snapshot before, switch to that working copy instead of piling up duplicates.
var reg = dashRegistry();
var existing = reg.find(function(d){ return d.srcId && d.srcId === item.id; });
if(existing){
dashSetActive(existing.id); _mydashEditing = false;
var nav0 = document.querySelector('.nav-subitem[data-view="mydashboard"]'); if(nav0) nav0.click(); else if(typeof showView==='function') showView('mydashboard');
renderMyDashboard();
if(typeof showActionToast === 'function') showActionToast('Switched to "' + existing.name + '"');
return;
}
let tiles; try { tiles = JSON.parse(JSON.stringify(item.tiles)); } catch(_){ tiles = item.tiles.slice(); }
tiles.forEach(function(t){ t.id = rbGenId(); t.owner = me.id; });
var base = item.name || 'Dashboard'; var name = base; var k = 2; var names = reg.map(function(d){return d.name;});
while(names.indexOf(name) >= 0){ name = base + ' (' + k + ')'; k++; }
var id = 'dash_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
reg.push({id:id, name:name, srcId:item.id, createdAt:Date.now()}); dashRegistryWrite(reg);
try { localStorage.setItem(dashCustomKey(id), JSON.stringify(tiles)); } catch(_){}
try { localStorage.setItem(dashSettingsKey(id), JSON.stringify({mode: item.layoutMode || 'canvas', theme: item.theme})); } catch(_){}
dashSetActive(id); _mydashEditing = false;
const nav = document.querySelector('.nav-subitem[data-view="mydashboard"]');
if(nav) nav.click(); else if(typeof showView==='function') showView('mydashboard');
renderMyDashboard();
if(typeof showActionToast === 'function') showActionToast('Opened "' + name + '" as its own dashboard');
}
// Saved-reports row markup for a dashboard-type item.
function savedDashboardRowHtml(item, me){
const tiles = item.tiles || [];
const reportN = tiles.filter(function(t){ return t.type !== 'text' && t.type !== 'spacer'; }).length;
const textN = tiles.filter(function(t){ return t.type === 'text'; }).length;
const safeName = String(item.name).replace(/</g,'&lt;');
const ownerId = item.owner || me.id;
const ownerObj = userById(ownerId) || me;
const isMine = ownerId === me.id;
const scope = item.sharing || SHARE_PRIVATE;
const ownerBadge = isMine ?
'<span class="saved-row-share scope-' + scope + '" data-saved-action="cycle-share" title="Sharing: ' + shareScopeLabel(scope) + ' \u00b7 click to cycle">' + shareScopeIcon(scope) + ' ' + shareScopeLabel(scope) + '</span>' :
'<span class="saved-row-owner" title="Shared by ' + ownerObj.name + ' \u00b7 ' + ownerObj.role + '"><span class="saved-row-owner-avatar" style="background:' + ownerObj.color + ';">' + ownerObj.initials + '</span><span class="saved-row-owner-name">' + ownerObj.name + '</span></span>';
const meta = reportN + ' chart' + (reportN===1?'':'s') + (textN ? ' \u00b7 ' + textN + ' text' : '');
return '<div class="saved-row saved-row-dashboard" data-saved-id="' + item.id + '">' +
'<div class="saved-row-icon saved-row-icon-dash" title="Dashboard">\u25a6</div>' +
'<div class="saved-row-main">' +
'<div class="saved-row-name">' + safeName + '</div>' +
'<div class="saved-row-meta">' +
'<span class="saved-row-meta-chip saved-row-chip-dash">Dashboard</span>' +
'<span>' + meta + '</span>' +
ownerBadge +
'</div></div>' +
'<div class="saved-row-date" title="' + new Date(item.createdAt).toLocaleString() + '">' + rbFormatDate(item.createdAt) + '</div>' +
'<div class="saved-row-actions">' +
'<button class="saved-row-btn saved-row-btn-open" data-saved-action="open-dash" title="Open this dashboard">\u2197 Open</button>' +
(isMine ? '<button class="saved-row-btn saved-row-btn-remove" data-saved-action="remove" title="Delete this saved dashboard">Delete</button>' : '') +
'</div></div>';
}
function renderSavedReports(){
const list = document.getElementById('savedreports-list');
const empty = document.getElementById('savedreports-empty');
const toolbar = document.getElementById('savedreports-toolbar');
if(!list) return;
const me = currentUser();
const allItems = savedReportsLoad();
// Filter to items I own + items shared with me through hierarchy
const visibleItems = allItems.filter(function(it){return canSeeItem(it, me.id);});
const searchTerm = ((toolbar && toolbar._search) || '').toLowerCase();
const ownerFilter = (toolbar && toolbar._ownerFilter) || 'all'; // 'all' | 'mine' | 'shared'
let scopedItems = visibleItems;
if(ownerFilter === 'mine') scopedItems = visibleItems.filter(function(it){return !it.owner || it.owner === me.id;});
else if(ownerFilter === 'shared') scopedItems = visibleItems.filter(function(it){return it.owner && it.owner !== me.id;});
const items = searchTerm ? scopedItems.filter(function(it){return it.name.toLowerCase().indexOf(searchTerm) >= 0;}) : scopedItems;
const mineCount = visibleItems.filter(function(it){return !it.owner || it.owner === me.id;}).length;
const sharedCount = visibleItems.filter(function(it){return it.owner && it.owner !== me.id;}).length;
if(toolbar){
toolbar.innerHTML = visibleItems.length === 0 ? '' :
'<input type="text" class="saved-search" id="saved-search-input" placeholder="Search saved reports..." value="' + searchTerm.replace(/"/g,'&quot;') + '"/>' +
'<div class="saved-tab-group">' +
'<button class="saved-tab' + (ownerFilter==='all'?' active':'') + '" data-saved-filter="all">All <span class="saved-tab-count">' + visibleItems.length + '</span></button>' +
'<button class="saved-tab' + (ownerFilter==='mine'?' active':'') + '" data-saved-filter="mine">Mine <span class="saved-tab-count">' + mineCount + '</span></button>' +
'<button class="saved-tab' + (ownerFilter==='shared'?' active':'') + '" data-saved-filter="shared">Shared with me <span class="saved-tab-count">' + sharedCount + '</span></button>' +
'</div>' +
'<div class="mydash-toolbar-actions"><span class="mydash-count"><strong>' + items.length + '</strong> shown</span></div>';
const searchInput = document.getElementById('saved-search-input');
if(searchInput){
searchInput.addEventListener('input', function(){
toolbar._search = searchInput.value;
renderSavedReports();
setTimeout(function(){ const e = document.getElementById('saved-search-input'); if(e){ e.focus(); e.setSelectionRange(e.value.length, e.value.length); } }, 0);
});
}
toolbar.querySelectorAll('[data-saved-filter]').forEach(function(b){
b.addEventListener('click', function(){ toolbar._ownerFilter = b.dataset.savedFilter; renderSavedReports(); });
});
}
if(visibleItems.length === 0){
list.innerHTML = '';
if(empty) empty.style.display = 'block';
return;
}
if(empty) empty.style.display = 'none';
let html = '';
const _sectioned = (ownerFilter === 'all' && !searchTerm);
let _orderedItems = items;
if(_sectioned){
const mineI = items.filter(function(it){return !it.owner || it.owner === me.id;});
const teamI = items.filter(function(it){return it.owner && it.owner !== me.id;});
_orderedItems = mineI.concat(teamI);
}
let _shownMine = false, _shownTeam = false;
const _mineShown = _orderedItems.filter(function(it){return !it.owner || it.owner === me.id;}).length;
const _teamShown = _orderedItems.filter(function(it){return it.owner && it.owner !== me.id;}).length;
_orderedItems.forEach(function(item){
if(_sectioned){
const isMineItem = !item.owner || item.owner === me.id;
if(isMineItem && !_shownMine){ html += '<div class="saved-section-hdr">My reports &amp; dashboards <span class="saved-section-count">' + _mineShown + '</span></div>'; _shownMine = true; }
if(!isMineItem && !_shownTeam){ html += '<div class="saved-section-hdr">Shared by your team <span class="saved-section-count">' + _teamShown + '</span></div>'; _shownTeam = true; }
}
if(item.type === 'dashboard'){ html += savedDashboardRowHtml(item, me); return; }
const vizDef = VIZ_TYPES.find(function(v){return v.key === item.state.viz;}) || {label:'Table', svg:''};
const tiLabel = {single:'R12', cytd:'CYTD', r3:'R3', cm:'CM', mom:'MoM', qoq:'QoQ', yoy:'YoY', rolling12:'R12 trend'}[item.state.timeInterval] || item.state.timeInterval;
const dimCount = (item.state.rows || []).length + (item.state.columns || []).length;
const measCount = (item.state.measures || []).length;
const filterCount = (item.state.filters || []).length;
const safeName = String(item.name).replace(/</g,'&lt;');
const ownerId = item.owner || me.id;
const ownerObj = userById(ownerId) || me;
const isMine = ownerId === me.id;
const scope = item.sharing || SHARE_PRIVATE;
const ownerBadge = isMine ?
'<span class="saved-row-share scope-' + scope + '" data-saved-action="cycle-share" title="Sharing: ' + shareScopeLabel(scope) + ' \u00b7 click to cycle">' + shareScopeIcon(scope) + ' ' + shareScopeLabel(scope) + '</span>' :
'<span class="saved-row-owner" title="Shared by ' + ownerObj.name + ' \u00b7 ' + ownerObj.role + '"><span class="saved-row-owner-avatar" style="background:' + ownerObj.color + ';">' + ownerObj.initials + '</span><span class="saved-row-owner-name">' + ownerObj.name + '</span></span>';
const schedCount = (typeof schedulesForReport === 'function') ? schedulesForReport(item.id).length : 0;
const schedChip = schedCount > 0 ? '<span class="saved-row-schedule-chip" title="' + schedCount + ' active schedule' + (schedCount===1?'':'s') + '"><span class="saved-row-schedule-chip-icon">\u23F0</span>' + schedCount + ' scheduled</span>' : '';
html += '<div class="saved-row" data-saved-id="' + item.id + '">' +
'<div class="saved-row-icon">' + vizDef.svg + '</div>' +
'<div class="saved-row-main">' +
'<div class="saved-row-name">' + safeName + schedChip + '</div>' +
'<div class="saved-row-meta">' +
'<span class="saved-row-meta-chip">' + vizDef.label + '</span>' +
'<span class="saved-row-meta-chip">' + tiLabel + '</span>' +
'<span>' + dimCount + ' dim' + (dimCount===1?'':'s') + ' \u00b7 ' + measCount + ' measure' + (measCount===1?'':'s') + (filterCount > 0 ? ' \u00b7 ' + filterCount + ' filter' + (filterCount===1?'':'s') : '') + '</span>' +
ownerBadge +
'</div></div>' +
'<div class="saved-row-date" title="' + new Date(item.createdAt).toLocaleString() + '">' + rbFormatDate(item.createdAt) + '</div>' +
'<div class="saved-row-actions">' +
(isMine ? '<button class="saved-row-btn" data-saved-action="schedule" title="Schedule recurring email">\u23F0 Schedule</button>' : '') +
'<button class="saved-row-btn saved-row-btn-pin" data-saved-action="pin" title="Pin to dashboard">📌 Pin</button>' +
(isMine ? '<button class="saved-row-btn saved-row-btn-remove" data-saved-action="remove" title="Delete this saved report">Delete</button>' : '') +
'</div></div>';
});
list.innerHTML = html;
list.querySelectorAll('.saved-row').forEach(function(row){
const id = row.dataset.savedId;
row.addEventListener('click', function(){
const item = savedReportsLoad().find(function(it){return it.id === id;});
if(!item) return;
if(item.kind === 'qa'){ if(typeof openQA==='function'){ openQA(); } else { var _nv=document.querySelector('.nav-subitem[data-view="qa"]'); if(_nv) _nv.click(); } if(typeof qaAsk==='function') qaAsk(item.query); return; }
if(item.type === 'dashboard'){ mydashRestoreDashboard(item); return; }
// Navigate to builder first so the sheet tab bar is in the DOM
const navItem = document.querySelector('.nav-subitem[data-view="builder"]');
if(navItem) navItem.click();
// Open as a new sheet — preserves the user's current work on whatever sheet they had open
rbOpenAsSheet(item);
});
row.querySelectorAll('[data-saved-action]').forEach(function(btn){
btn.addEventListener('click', function(e){
e.stopPropagation();
const act = btn.dataset.savedAction;
const items2 = savedReportsLoad();
const item = items2.find(function(it){return it.id === id;});
if(!item) return;
if(act === 'remove'){
hoodieConfirm({danger:true, title:'Delete saved ' + (item.type === 'dashboard' ? 'dashboard' : 'report') + ' \u201C' + item.name + '\u201D?', onConfirm:function(){
const remaining = items2.filter(function(it){return it.id !== id;});
savedReportsWrite(remaining);
renderSavedReports();
}});
}else if(act === 'open-dash'){
mydashRestoreDashboard(item);
}else if(act === 'pin'){
const me = currentUser();
const pinItem = {id: rbGenId(), name: item.name, state: item.state, vizType: item.vizType, createdAt: Date.now(), owner: me.id, sharing: SHARE_PRIVATE};
const dash = mydashLoad();
dash.unshift(pinItem);
mydashWrite(dash);
if(typeof showActionToast === 'function') showActionToast('Pinned "' + item.name + '" to My dashboard');
}else if(act === 'schedule'){
openScheduleModal({reportId: item.id, reportName: item.name});
}else if(act === 'cycle-share'){
const cur = item.sharing || SHARE_PRIVATE;
item.sharing = cur === SHARE_PRIVATE ? SHARE_TEAM : (cur === SHARE_TEAM ? SHARE_ORG : SHARE_PRIVATE);
savedReportsWrite(items2);
if(typeof showActionToast === 'function') showActionToast('Sharing: ' + shareScopeLabel(item.sharing));
renderSavedReports();
}
});
});
});
}

// Wire save/pin buttons + modal — called from setupReportBuilder
function setupSaveActions(){
const pinBtn = document.getElementById('rb-pin-dashboard');
const deckBtn = document.getElementById('rb-add-to-deck');
if(deckBtn) deckBtn.addEventListener('click', function(){ appReportToDeck(appBuilderEntry()); });
const atlasBtn = document.getElementById('rb-add-to-atlas');
if(atlasBtn) atlasBtn.addEventListener('click', function(){ appBuilderToAtlas(); });
const saveBtn = document.getElementById('rb-save-report');
const schedFromBuilderBtn = document.getElementById('rb-schedule-report-btn');
const modalCancel = document.getElementById('rb-save-modal-cancel');
const modalConfirm = document.getElementById('rb-save-modal-confirm');
const modalBg = document.getElementById('rb-save-modal');
const modalInput = document.getElementById('rb-save-modal-input');
if(pinBtn) pinBtn.addEventListener('click', function(){ rbOpenSaveModal('pin'); });
if(saveBtn) saveBtn.addEventListener('click', function(){ rbOpenSaveModal('report'); });
if(schedFromBuilderBtn) schedFromBuilderBtn.addEventListener('click', rbScheduleFromBuilder);
if(modalCancel) modalCancel.addEventListener('click', rbCloseSaveModal);
if(modalConfirm) modalConfirm.addEventListener('click', rbConfirmSave);
if(modalBg) modalBg.addEventListener('click', function(e){ if(e.target === modalBg) rbCloseSaveModal(); });
if(modalInput) modalInput.addEventListener('keydown', function(e){
if(e.key === 'Enter') rbConfirmSave();
else if(e.key === 'Escape') rbCloseSaveModal();
});
}

function setupReportBuilder(){
try{ if(typeof rbGetVizFormat==='function'){ rbGetVizFormat().dataTable=false; } else if(RB_STATE._vizFormat){ RB_STATE._vizFormat.dataTable=false; } }catch(_){}
rbRenderFieldsPane();
rbSetupAI();
rbSetupShelfDropTargets();
setupSaveActions();
rbInitHistory();
// Undo / Redo buttons
const undoBtn = document.getElementById('rb-undo-btn');
const redoBtn = document.getElementById('rb-redo-btn');
if(undoBtn) undoBtn.addEventListener('click', function(){ rbUndo(); });
if(redoBtn) redoBtn.addEventListener('click', function(){ rbRedo(); });
// Share button → open share modal
const shareBtn = document.getElementById('rb-share-btn');
if(shareBtn) shareBtn.addEventListener('click', function(){ openShareModal({source:'builder', name: rbGenerateVizTitle().title, state: rbStateSnapshot()}); });
// Keyboard shortcuts — only when builder view is active
document.addEventListener('keydown', function(e){
const builderActive = document.getElementById('view-builder') && document.getElementById('view-builder').classList.contains('active');
if(!builderActive) return;
const tag = (e.target && e.target.tagName || '').toLowerCase();
if(tag === 'input' || tag === 'textarea' || tag === 'select') return;
const isMod = e.metaKey || e.ctrlKey;
if(isMod && !e.shiftKey && e.key.toLowerCase() === 'z'){ e.preventDefault(); rbUndo(); }
else if(isMod && (e.shiftKey && e.key.toLowerCase() === 'z' || e.key.toLowerCase() === 'y')){ e.preventDefault(); rbRedo(); }
else if(e.key === 'Escape'){
// Close any open builder popovers/menus
['rb-method-popover','rb-export-menu','rb-share-modal','rb-save-modal','rb-calc-modal'].forEach(function(id){
const el = document.getElementById(id);
if(el && el.style.display !== 'none') el.style.display = 'none';
});
}
});
// Methodology popover
const methodBtn = document.getElementById('rb-method-info');
const methodPop = document.getElementById('rb-method-popover');
const methodClose = document.getElementById('rb-method-popover-close');
if(methodBtn) methodBtn.addEventListener('click', function(e){
e.stopPropagation();
if(methodPop) methodPop.style.display = methodPop.style.display === 'none' ? 'block' : 'none';
});
if(methodClose) methodClose.addEventListener('click', function(){ if(methodPop) methodPop.style.display = 'none'; });
document.addEventListener('click', function(e){
if(methodPop && methodPop.style.display !== 'none' && !methodPop.contains(e.target) && e.target !== methodBtn) methodPop.style.display = 'none';
});
// Export dropdown menu
const expBtn = document.getElementById('rb-export-menu-btn');
const expMenu = document.getElementById('rb-export-menu');
if(expBtn) expBtn.addEventListener('click', function(e){
e.stopPropagation();
if(expMenu) expMenu.style.display = expMenu.style.display === 'none' ? 'flex' : 'none';
});
if(expMenu) expMenu.querySelectorAll('[data-export]').forEach(function(item){
item.addEventListener('click', function(e){
e.stopPropagation();
expMenu.style.display = 'none';
rbExportTable(item.dataset.export);
});
});
document.addEventListener('click', function(e){
if(expMenu && expMenu.style.display !== 'none' && !expMenu.contains(e.target) && e.target !== expBtn) expMenu.style.display = 'none';
});
const clearBtn = document.getElementById('rb-clear');
if(clearBtn){
clearBtn.addEventListener('click', function(){
RB_STATE.rows = []; RB_STATE.columns = []; RB_STATE.filters = []; RB_STATE.measures = [];
RB_STATE.viz = 'table'; RB_STATE.timeInterval = 'single';
RB_STATE.periodWindow = 'r12'; RB_STATE.periodGrain = 'month';
const pw = document.getElementById('rb-period-window'); if(pw) pw.value = 'r12';
const pg = document.getElementById('rb-period-grain'); if(pg) pg.value = 'month';
if(typeof rbCellsClearForSheet === 'function') rbCellsClearForSheet();
rbRenderAll();
});
}
const resetBtn = document.getElementById('rb-reset');
if(resetBtn){
resetBtn.addEventListener('click', function(){
Object.assign(RB_STATE, JSON.parse(JSON.stringify(RB_DEFAULT)));
const pw = document.getElementById('rb-period-window'); if(pw) pw.value = RB_STATE.periodWindow || 'r12';
const pg = document.getElementById('rb-period-grain'); if(pg) pg.value = RB_STATE.periodGrain || 'month';
rbRenderAll();
});
}
const periodWinSel = document.getElementById('rb-period-window');
function rbEnsurePeriodForTrend(){
// Trend vizes need Period on a shelf; if it isn't there, drop it on columns.
if(['line','area','combo'].indexOf(RB_STATE.viz) >= 0 && !rbPeriodOnShelf()){
RB_STATE.columns = (RB_STATE.columns || []).slice();
if(RB_STATE.columns.indexOf('period') < 0) RB_STATE.columns.push('period');
RB_STATE.timeInterval = 'single';
}
}
if(periodWinSel){
periodWinSel.value = RB_STATE.periodWindow || 'r12';
periodWinSel.addEventListener('change', function(){
RB_STATE.periodWindow = periodWinSel.value;
RB_STATE.timeInterval = 'single'; // window now owns point-in-time scope
rbEnsurePeriodForTrend();
const av = rbVizAvailability(RB_STATE.viz);
if(!av.ok) RB_STATE.viz = 'table';
rbRenderAll();
});
}
const periodGrainSel = document.getElementById('rb-period-grain');
if(periodGrainSel){
periodGrainSel.value = RB_STATE.periodGrain || 'month';
periodGrainSel.addEventListener('change', function(){
RB_STATE.periodGrain = periodGrainSel.value;

rbEnsurePeriodForTrend();
rbRenderAll();
});
}
const timePresetSel = document.getElementById('rb-time-preset');
if(timePresetSel){
timePresetSel.value = RB_STATE.timePreset || '';
timePresetSel.addEventListener('change', function(){
RB_STATE.timePreset = timePresetSel.value;
if(RB_STATE.timePreset && RB_STATE.measures.length === 0){ RB_STATE.measures = [RB_STATE.timePreset === 'summary' ? 'account_count' : 'volume_growth']; }
rbRenderAll();
});
}
const calcBtn = document.getElementById('rb-calc-field');
if(calcBtn) calcBtn.addEventListener('click', rbOpenCalcModal);
const calcCloseBtn = document.getElementById('rb-calc-close');
const calcCancelBtn = document.getElementById('rb-calc-cancel');
const calcSaveBtn = document.getElementById('rb-calc-save');
if(calcCloseBtn) calcCloseBtn.addEventListener('click', rbCloseCalcModal);
if(calcCancelBtn) calcCancelBtn.addEventListener('click', rbCloseCalcModal);
if(calcSaveBtn) calcSaveBtn.addEventListener('click', rbSaveCalcField);
// Wire preset buttons
document.querySelectorAll('.rb-calc-preset').forEach(function(btn){
btn.addEventListener('click', function(){
const preset = btn.dataset.preset;
const presets = {
'headroom_pod': {name:'Headroom per POD', a:'headroom_pt', op:'div', b:'pod_growth', unit:'pt/%'},
'rev_vol_gap': {name:'Mix uplift', a:'revenue_growth', op:'sub', b:'volume_growth', unit:'pt'},
'vel_premium': {name:'Velocity × Premium', a:'velocity_idx', op:'mul', b:'premium_idx', unit:'idx²'},
'real_gap': {name:'Realization gap', a:'realized_pct', op:'sub', b:'realized_pct', unit:'%'}
};
const p = presets[preset];
if(!p) return;
document.getElementById('rb-calc-name').value = p.name;
document.getElementById('rb-calc-a').value = p.a;
document.getElementById('rb-calc-op').value = p.op;
document.getElementById('rb-calc-b').value = p.b;
(function(u,v){ if(!u) return; if(u.tagName==='SELECT' && !Array.prototype.some.call(u.options,function(o){return o.value===v;})){ var o=document.createElement('option'); o.value=v; o.textContent=v; u.appendChild(o); } u.value=v; })(document.getElementById('rb-calc-unit'), p.unit);
rbUpdateCalcPreview();
});
});
// Live preview when any input changes
['rb-calc-a','rb-calc-b','rb-calc-op','rb-calc-unit'].forEach(function(id){
const el = document.getElementById(id);
if(el) el.addEventListener('change', rbUpdateCalcPreview);
if(el) el.addEventListener('input', rbUpdateCalcPreview);
});
const calcModal = document.getElementById('rb-calc-modal');
if(calcModal) calcModal.addEventListener('click', function(e){ if(e.target === calcModal) rbCloseCalcModal(); });
// Worksheet tab system — each sheet has its own independent RB_STATE
const wsAdd = document.getElementById('rb-worksheet-add');
if(wsAdd){
wsAdd.addEventListener('click', function(){ rbSheetsAdd(); });
}
// Render the tab bar from the workbook (replaces the static "Sheet 1" placeholder
// and wires every tab to the real switcher)
rbSheetsRenderTabs();
rbRenderAll();
}

