function overlayShowRedirect(sample){
overlayShowState('redirect');
document.getElementById('overlay-redirect-title').textContent = sample.title;
document.getElementById('overlay-redirect-body').innerHTML = sample.body;
// optional override — a button that proceeds anyway (e.g. user overrides the grain guard)
var back = document.getElementById('overlay-redirect-back');
var prev = document.getElementById('overlay-redirect-override');
if(prev) prev.remove();
if(typeof sample.override === 'function'){
var ov = document.createElement('button');
ov.id = 'overlay-redirect-override';
ov.className = 'overlay-result-btn';
ov.style.cssText = 'background:var(--dash-accent,#4E79A7);color:#fff;border:none;margin-right:10px;';
ov.textContent = sample.overrideLabel || 'Analyze anyway →';
ov.addEventListener('click', function(){ sample.override(); });
back.parentNode.insertBefore(ov, back);
}
}

// Quote-aware single-line CSV split (handles commas inside "quoted" fields + "" escapes).
function frParseLine(line){
const out = []; let cur = '', q = false;
for(let i = 0; i < line.length; i++){
const ch = line[i];
if(q){ if(ch === '"'){ if(line[i+1] === '"'){ cur += '"'; i++; } else q = false; } else cur += ch; }
else { if(ch === '"') q = true; else if(ch === ','){ out.push(cur); cur = ''; } else cur += ch; }
}
out.push(cur); return out;
}
// Real CSV parsing — for files dropped by the user. Cap is a safety ceiling (not 5k).
function overlayParseCSV(text){
const lines = text.split(/\r?\n/).filter(function(l){return l.trim().length > 0;});
if(lines.length < 2) return { rowCount: lines.length, columns: [], rows: [] };
const headers = frParseLine(lines[0]).map(function(h){return h.trim().toLowerCase();});
const CAP = 200000, n = Math.min(lines.length, CAP + 1);
const rows = [];
for(let i = 1; i < n; i++){ rows.push(frParseLine(lines[i]).map(function(c){return c.trim();})); }
return { rowCount: lines.length - 1, columns: headers, rows: rows, truncated: (lines.length - 1) > CAP };
}

// Detect column roles from header names — order matters (most-specific first)
function overlayDetectRoles(cols){
const roles = {};
cols.forEach(function(c, i){
const cl = c.toLowerCase();
// Geo / dimensional
if(roles[i]) return;
if(cl === 'territory_id' || cl === 'territory' || cl.match(/^terr_?id$/)) roles[i] = 'territory_id';
else if(cl === 'state' || cl === 'st') roles[i] = 'state';
else if(cl.match(/^zip|postal|zip_prefix/)) roles[i] = 'zip';
else if(cl.match(/division|census/)) roles[i] = 'division';
else if(cl.match(/^region$/)) roles[i] = 'region';
else if(cl.match(/sub[_\-]?channel|venue[_\-]?type|store[_\-]?type|account[_\-]?type|sub_chan/)) roles[i] = 'subch';
else if(cl === 'channel' || cl === 'chan') roles[i] = 'channel';
else if(cl.match(/account[_\-]?class|^class$|^tier$|^grade$/)) roles[i] = 'account_class';
else if(cl.match(/^category$|^cat$|^product[_\-]?category$/)) roles[i] = 'category';
// Numeric — order: goal → prior → actual (so 'goal' wins over 'volume', 'prior' wins over plain 'volume_actual')
else if(cl.match(/pod/) && cl.match(/goal|target|plan|budget/)) roles[i] = 'pod_goal';
else if(cl.match(/pod/) && cl.match(/actual|current|^pod$/)) roles[i] = 'pod_actual';
else if(cl.match(/^pod_/)) roles[i] = 'pod_actual';
else if(cl.match(/volume|9l|cases|vol/) && cl.match(/goal|target|plan|budget|_2026|next_year/)) roles[i] = 'volume_goal';
else if(cl.match(/volume|9l|cases|vol/) && cl.match(/prior|py|previous|last_year|_2025/)) roles[i] = 'volume_prior';
else if(cl.match(/volume|9l|cases|vol/) && cl.match(/actual|r12|current|ytd|^volume$/)) roles[i] = 'volume_actual';
else if(cl.match(/(menu|product|item|description|sku_name|offering)/)) roles[i] = 'menu_signal';
});
return roles;
}

// Category normalizer — map raw text to Hoodie category keys
function overlayNormalizeCategory(raw){
const r = String(raw||'').toLowerCase().trim();
if(!r) return null;
if(r.match(/whisk|bourbon|scotch|rye/)) return 'whiskey';
if(r.match(/vodka/)) return 'vodka';
if(r.match(/tequila|mezcal|agave/)) return 'tequila';
if(r.match(/rum/)) return 'rum';
if(r.match(/rtd|ready.to.drink|seltzer|canned cocktail/)) return 'rtd';
if(r.match(/wine|chardonnay|cabernet|pinot|sauv|merlot/)) return 'wine';
return r.toLowerCase().replace(/[^a-z]+/g,'_');
}

// State → census division
const STATE_TO_DIVISION = {
'CT':'New England','ME':'New England','MA':'New England','NH':'New England','RI':'New England','VT':'New England',
'NJ':'Mid-Atlantic','NY':'Mid-Atlantic','PA':'Mid-Atlantic',
'IL':'East North Central','IN':'East North Central','MI':'East North Central','OH':'East North Central','WI':'East North Central',
'IA':'West North Central','KS':'West North Central','MN':'West North Central','MO':'West North Central','NE':'West North Central','ND':'West North Central','SD':'West North Central',
'DE':'South Atlantic','FL':'South Atlantic','GA':'South Atlantic','MD':'South Atlantic','NC':'South Atlantic','SC':'South Atlantic','VA':'South Atlantic','WV':'South Atlantic','DC':'South Atlantic',
'AL':'East South Central','KY':'East South Central','MS':'East South Central','TN':'East South Central',
'AR':'West South Central','LA':'West South Central','OK':'West South Central','TX':'West South Central',
'AZ':'Mountain','CO':'Mountain','ID':'Mountain','MT':'Mountain','NV':'Mountain','NM':'Mountain','UT':'Mountain','WY':'Mountain',
'AK':'Pacific','CA':'Pacific','HI':'Pacific','OR':'Pacific','WA':'Pacific'
};

// Deterministic industry benchmark per (category × subch × division) — uses rbHash if available
function overlayIndustryBench(category, subch, division){
let r = 0.5;
if(typeof rbHash === 'function'){
r = rbHash(category + '|' + subch + '|' + division);
}else{
const s = category + subch + division;
let h = 0; for(let i = 0; i < s.length; i++){ h = (h * 31 + s.charCodeAt(i)) >>> 0; }
r = (h % 1000) / 1000;
}
// Industry growth baselines by category — anchored to plausible market reality
const catGrowth = {whiskey:5.5, vodka:-1.5, tequila:14.0, rum:-3.0, rtd:22.0, wine:1.5};
const base = catGrowth[category] !== undefined ? catGrowth[category] : 3.0;
const industry_growth = base + (r * 8 - 4); // ±4 per cell
const industry_headroom = Math.round(22 + r * 65); // 22–87 pt
return {growth: industry_growth, headroom: industry_headroom};
}

// ── Full Read: open ANY uploaded file in the Report Builder, scoped to its OWN fields ──
// The file is the root. Profile + classify it, expose its columns as RB dims/measures, and
// route RB's per-cell compute to a generic group-by over the raw rows (FullRead.cellAgg).
// No bev-alc cell model involved. Aggregates are toggleable: each numeric column is offered
// as sum/avg/min/max measures (add/remove on the shelf), plus a Row-count measure.
var FR_SAVED = null;
function frAggLabel(a){ return ({sum:'sum',mean:'avg',min:'min',max:'max',count:'count'})[a] || a; }
function frDistinctVals(header, rows, colName, cap){
  var idx = header.indexOf(colName); if(idx < 0) return [];
  var seen = Object.create(null), out = [];
  for(var r=0; r<rows.length; r++){ var v = (rows[r][idx]==null?'':String(rows[r][idx]).trim()); if(v==='') continue; if(!seen[v]){ seen[v]=1; out.push(v); if(out.length>=cap) break; } }
  return out.sort().map(function(v){ return {v:v, n:v}; });
}
function frBuildFields(prof, cls, parsed){
  var scoped = FullRead.scopedFields(prof, cls);
  var dimMap = {}, measMap = {};
  var dims = scoped.dimensions.map(function(d, i){
    var key = 'd'+i; dimMap[key] = d.key;
    return { key:key, label:d.label, type:'string', values: frDistinctVals(parsed.columns, parsed.rows, d.key, 200) };
  });
  var measures = [];
  scoped.measures.forEach(function(m, i){
    ['sum','mean','min','max'].forEach(function(agg){
      var key = 'm'+i+'_'+agg; measMap[key] = { col:m.key, agg:agg };
      measures.push({ key:key, label:m.label+' ('+frAggLabel(agg)+')', type:(agg==='mean'?'number':m.type), unit:m.unit||'' });
    });
  });
  measMap['m_count'] = { col:(scoped.measures[0]||scoped.dimensions[0]||{}).key, agg:'count' };
  measures.push({ key:'m_count', label:'Row count', type:'number' });
  // Count-distinct of each dimension — e.g. "Distinct brand" by store = brands per store.
  scoped.dimensions.forEach(function(d, i){
    var key = 'md'+i+'_distinct'; measMap[key] = { col:d.key, agg:'distinct' };
    measures.push({ key:key, label:'Distinct '+d.label, type:'number' });
  });
  return { dims:dims, measures:measures, dimMap:dimMap, measMap:measMap,
           defMeasure: scoped.measures.length ? 'm0_sum' : 'm_count' };
}
function frDatasetCompute(measureKey, dimValues){
  var ds = window.RB_DATASET; if(!ds) return '—';
  var spec = ds.measMap[measureKey]; if(!spec) return '—';
  var dims = {};
  Object.keys(dimValues||{}).forEach(function(k){
    if(k==='time' || k.charAt(0)==='_') return;
    var col = ds.dimMap[k];
    if(col && dimValues[k]!=null && dimValues[k]!=='__total__') dims[col]=dimValues[k];
  });
  var v = FullRead.cellAgg(ds.header, ds.rows, spec.col, spec.agg, dims);
  if(v==null) return '—';
  if(spec.agg==='count' || spec.agg==='distinct') return String(Math.round(v));
  return (Math.abs(v) >= 1000) ? String(Math.round(v)) : String(+(+v).toFixed(2));
}
// Scope the Report Builder to an uploaded file's own fields (NO navigation, NO modal).
function frScopeDataset(filename, parsed){
  var prof = FullRead.profile(parsed.columns, parsed.rows);
  var overrides = frLoadOverrides(filename, parsed.columns) || {};   // restore prior edits
  frApplyDtype(prof, overrides);
  var cls = frEffCls(FullRead.ruleClassify(prof), overrides);
  var f = frBuildFields(prof, cls, parsed);
  if(!FR_SAVED) FR_SAVED = { dims:RB_FIELDS.dimensions, measures:RB_FIELDS.measures, state:rbCloneState(RB_STATE) };
  RB_FIELDS.dimensions = f.dims; RB_FIELDS.measures = f.measures;
  window.RB_DATASET = { name:filename, header:parsed.columns, rows:parsed.rows, dimMap:f.dimMap, measMap:f.measMap, profile:prof, classification:cls, overrides:overrides };
  var def = frDefaultRow(prof, f);
  RB_STATE.rows = def ? [def] : [];
  RB_STATE.columns = []; RB_STATE.filters = []; RB_STATE.calculated = []; RB_STATE.groupings = [];
  RB_STATE.measures = [f.defMeasure]; RB_STATE.viz = 'table'; RB_STATE.timeInterval = 'single'; RB_STATE.factEngine = false;
  return { prof: prof, cls: cls };
}
function frJumpToReportBuilder(){
  if(!window.RB_DATASET) return;
  frBanner(window.RB_DATASET.name);
  var nav = document.querySelector('.nav-subitem[data-view="builder"]'); if(nav) nav.click();
  if(typeof rbRenderAll==='function') rbRenderAll();
}
function frExportCSV(parsed, name){
  var q = function(v){ v = (v==null?'':String(v)); return /[",\n]/.test(v) ? '"'+v.replace(/"/g,'""')+'"' : v; };
  var csv = [parsed.columns.map(q).join(',')].concat(parsed.rows.map(function(r){ return parsed.columns.map(function(_,i){ return q(r[i]); }).join(','); })).join('\n');
  var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  a.download = (name||'data').replace(/\.[^.]+$/,'') + '.csv'; document.body.appendChild(a); a.click();
  setTimeout(function(){ try{ URL.revokeObjectURL(a.href); a.remove(); }catch(_){ } }, 150);
}
// Workbook-style viewer of the underlying rows (sticky header + row index; capped for perf).
function frWorkbook(parsed){
  var cap = 500, rows = parsed.rows.slice(0, cap);
  var thS = 'position:sticky;top:0;background:#f3eefb;color:#6d28d9;text-align:left;padding:5px 10px;border-bottom:1px solid #e0d3f5;font-weight:600;';
  var th = '<tr><th style="'+thS+'left:0;z-index:1;">#</th>' + parsed.columns.map(function(c){ return '<th style="'+thS+'">'+frEsc(c)+'</th>'; }).join('') + '</tr>';
  var tb = rows.map(function(r, i){
    return '<tr><td style="padding:4px 10px;color:#a09aa8;border-bottom:1px solid #f4f1f8;position:sticky;left:0;background:#fff;">'+(i+1)+'</td>'
      + parsed.columns.map(function(_, ci){ return '<td style="padding:4px 10px;border-bottom:1px solid #f4f1f8;">'+frEsc(r[ci])+'</td>'; }).join('') + '</tr>';
  }).join('');
  var note = parsed.rows.length > cap ? '<div style="color:#6c6675;font-size:11px;margin-bottom:6px;">showing '+cap+' of '+parsed.rows.length.toLocaleString()+' rows · Export CSV for all</div>' : '';
  return note + '<div style="overflow:auto;max-height:340px;border:1px solid #e9e4ee;border-radius:8px;">'
    + '<table style="border-collapse:collapse;font-family:ui-monospace,monospace;font-size:11.5px;white-space:nowrap;width:100%;"><thead>'+th+'</thead><tbody>'+tb+'</tbody></table></div>';
}
// The analysis MODAL over the Overlay page: orientation + AI read + data workbook + actions.
// Data-quality read (deterministic engine) — facts vs inferences, never blended.
function frDQSection(parsed){
  if(typeof DQ==='undefined') return '';
  var res; try{ res = DQ.assess(parsed.columns, parsed.rows); }catch(e){ return ''; }
  var all = res.findings.slice();
  var prof = res.profile || {};
  // Stage 0 — the grain profile is the FIRST thing surfaced; detectors read it, not column names.
  var grainBar = '<div style="margin-bottom:10px;padding:8px 11px;background:#f3eefb;border:1px solid #e0d3f5;border-radius:7px;font-size:12px;color:#3a3640;">'
    + (prof.ambiguous
        ? '<b>Grain ambiguous.</b> ' + frEsc(prof.grain_statement || '')
        : '<b>Grain:</b> ' + frEsc(prof.grain_statement || '—') + (prof.candidate_key ? ' &nbsp;·&nbsp; <span style="font-family:ui-monospace,monospace;font-size:11px;color:#6d28d9;">key (' + prof.candidate_key.map(frEsc).join(', ') + ')</span>' : ''))
    + '</div>';
  // Frontier modules: coverage gaps fold into the issue list; claims/disclaimer footer. Pass the
  // profile so coverage reads the grain (no re-assess, and event-grain — not calendar — coverage).
  var claimsFindings = [];
  if(typeof DQF!=='undefined'){
    try{ all = all.concat(DQF.coverageContinuity(parsed.columns, parsed.rows, {roles:res.roles, profile:res.profile}).findings); }catch(e){}
    try{ claimsFindings = DQF.claimsCoherence(parsed.columns, parsed.rows, {roles:res.roles}).findings; }catch(e){}
  }
  var footer = frClaimsFooter(claimsFindings);
  // Stage 3/4 — never surface detections 1:1. Roll up by issue type → entity windows; tier them.
  var findings = all.filter(function(f){ return f.severity!=='info' && f.id!=='dataset.grain' && f.id!=='claims.no_ruleset' && f.id!=='claims.combinations'; });
  if(!findings.length) return grainBar + '<div style="color:#15803d;font-size:12px;">✓ No material data-quality issues flagged.</div>' + footer;
  var misfires = findings.filter(function(f){ return /\.misfire$/.test(f.id); });
  var tiered = {1:{},2:{},3:{}};   // tier → issue_type id → [findings]
  findings.forEach(function(f){ if(/\.misfire$/.test(f.id)) return; var t=frTier(f); (tiered[t][f.id]=tiered[t][f.id]||[]).push(f); });
  var html = grainBar;
  // the engine flagging its own heuristic comes first (fiduciary behavior)
  misfires.forEach(function(f){ html += '<div style="margin-bottom:8px;padding:9px 11px;background:#fff7ed;border:1px solid #f4c989;border-left:3px solid #d97706;border-radius:7px;"><b style="font-size:12.5px;color:#b45309;">⚠ '+frEsc(f.title)+'</b><div style="font-size:12px;color:#3a3640;margin-top:2px;">'+frEsc(f.detail)+'</div></div>'; });
  var TIER_META = {1:['Tier 1 — verify / fix now','#b4232a'],2:['Tier 2 — confirm (assumption stated)','#b45309'],3:['Tier 3 — hypotheses (inferential)','#2563b8']};
  [1,2,3].forEach(function(t){
    var ids = Object.keys(tiered[t]); if(!ids.length) return;
    html += '<div style="font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.05em;text-transform:uppercase;color:'+TIER_META[t][1]+';margin:14px 0 4px;">'+TIER_META[t][0]+'</div>';
    ids.forEach(function(id){ html += frRenderGroup(id, tiered[t][id], t); });
  });
  return html + footer;
}
// ---- Stage 3/4 helpers: tiering, issue labels, entity-window rollup ----
var FR_TIER1 = { 'type.violation':1,'measure.range':1,'measure.range_pct':1,'measure.scale_unit':1,'measure.cap_sentinel':1,'measure.cap_band':1,'dataset.exact_duplicates':1 };
function frTier(f){ if(FR_TIER1[f.id]) return 1; return (typeof DQ!=='undefined' && f.tag===DQ.DETERMINISTIC) ? 2 : 3; }
function frIssueLabel(id){ return ({
  'type.violation':'Type violation (non-numeric tokens)','measure.range':'Out-of-range values','measure.range_pct':'Percent over 100','measure.scale_unit':'Mixed units / decimal shift',
  'measure.cap_sentinel':'Capped / sentinel values','measure.cap_band':'Values capped at the max','measure.nulls':'High missingness',
  'measure.zero_inflation':'Zero-inflated measure','dimension.whitespace':'Whitespace fragmentation','dimension.casing':'Casing fragmentation',
  'dimension.collision':'Key collisions','dimension.implication':'Identifier-like dimension','dataset.exact_duplicates':'Exact duplicate rows',
  'dataset.key_not_unique':'Candidate key not unique','dataset.redundancy':'Redundant dimensions','dataset.coherence':'Mirror / duplicate columns',
  'coverage.interior_gap':'Suspected coverage gaps','coverage.event_gap':'Suspected event gaps','coverage.event_note':'Coverage not assessed',
  'role.review':'Role needs confirmation','claims.rare_combo':'Rare claim combinations','claims.ruleset_location':'Location invalid for period','claims.ruleset_sentinel':'Sentinel values present'
})[id] || id; }
function frChipTag(det){ return det
  ? '<span style="font-family:ui-monospace,monospace;font-size:8.5px;letter-spacing:.04em;text-transform:uppercase;background:#e7f3ec;color:#15803d;padding:1px 5px;border-radius:4px;">verified</span>'
  : '<span style="font-family:ui-monospace,monospace;font-size:8.5px;letter-spacing:.04em;text-transform:uppercase;background:#fbeede;color:#b45309;padding:1px 5px;border-radius:4px;">infer</span>'; }
// collapse a list of period values into consecutive windows: [2019,2020,2023] → ["2019–2020","2023"]
function frWindows(vals){
  var clean = vals.filter(function(v){ return v!=null && v!==''; });
  var nums = clean.map(function(v){ return parseFloat(String(v).replace(/[^0-9.\-]/g,'')); });
  if(!nums.every(function(x){ return !isNaN(x); })){ var u={}; clean.forEach(function(v){u[v]=1;}); return Object.keys(u); }
  var s = nums.slice().sort(function(a,b){return a-b;}).filter(function(v,i,a){return a.indexOf(v)===i;});
  var step = Infinity; for(var i=1;i<s.length;i++){ var g=s[i]-s[i-1]; if(g>0&&g<step) step=g; } if(!isFinite(step)) step=1;
  var out=[], start=s[0], prev=s[0];
  for(var j=1;j<s.length;j++){ if(s[j]-prev > step*1.5){ out.push(start===prev?(''+start):(start+'–'+prev)); start=s[j]; } prev=s[j]; }
  out.push(start===prev?(''+start):(start+'–'+prev)); return out;
}
function frRenderGroup(id, fs, tier){
  var label = frIssueLabel(id), n = fs.length, det = (typeof DQ!=='undefined' && fs[0].tag===DQ.DETERMINISTIC);
  var entityBased = fs.every(function(f){ return f.evidence && (f.evidence.entity!=null); });
  var prov = fs.some(function(f){ return f.provenance==='sampled'; }) ? ' · <span style="color:#a09aa8;">sampled</span>' : '';
  // Tier 3 above the instance bar → ONE rolled-up hypothesis card (count + confidence + assumption)
  if(tier===3 && n > 8){
    var avg = Math.round(fs.reduce(function(a,f){return a+(f.confidence||0.6);},0)/n*100);
    var ents = entityBased ? Object.keys(fs.reduce(function(m,f){m[f.evidence.entity]=1;return m;},{})).length : 0;
    return '<div style="margin:4px 0;padding:9px 11px;background:#eef4fb;border:1px solid #cfe0f5;border-radius:7px;">'
      + '<b style="font-size:12.5px;">'+frEsc(label)+'</b> '+frChipTag(false)+' <span style="color:#6c6675;font-size:12px;">'+n+' suspected'+(ents?' across '+ents+' entities':'')+' · '+avg+'% avg'+prov+'</span>'
      + '<div style="font-size:12px;color:#3a3640;margin-top:3px;">Inferential — surfaced as one hypothesis (above the per-instance bar). Assumption to confirm: '+frEsc(frAssumptionFor(id))+'</div></div>';
  }
  var body;
  if(entityBased){
    var byEnt = {}; fs.forEach(function(f){ (byEnt[f.evidence.entity]=byEnt[f.evidence.entity]||[]).push(f.evidence.missing_period!=null?f.evidence.missing_period:f.evidence.event); });
    body = Object.keys(byEnt).map(function(e){ var w=frWindows(byEnt[e]); return '<div style="font-size:12px;margin:3px 0;"><b>'+frEsc(e)+'</b>: '+byEnt[e].length+' across '+w.length+' window'+(w.length>1?'s':'')+' — '+w.map(frEsc).join(', ')+'</div>'; }).join('');
  } else {
    body = fs.map(function(f){ return '<div style="font-size:12px;margin:3px 0;color:#3a3640;">'+(f.columns&&f.columns.length?'<b>'+f.columns.map(frEsc).join(', ')+'</b> — ':'')+frEsc(f.detail)+'</div>'; }).join('');
  }
  // FIX 2 — value-integrity findings headline ROWS-AFFECTED + the owning column(s), never a bare
  // "N instances" (which reads as "one trivial cell" for a pervasive problem). Magnitude, not presence.
  var raTotal = 0, anyRA = false;
  fs.forEach(function(f){ var x = f.evidence && f.evidence.rows_affected; if(typeof x === 'number'){ anyRA = true; raTotal += x; } });
  var colBits = fs.map(function(f){ var c0 = f.columns && f.columns[0]; if(!c0) return ''; var x = f.evidence && f.evidence.rows_affected; return frEsc(c0) + (typeof x==='number' ? ' ('+x.toLocaleString()+')' : ''); }).filter(Boolean);
  var magnitude = (!entityBased && anyRA)
    ? raTotal.toLocaleString()+' row'+(raTotal===1?'':'s')+(colBits.length?' · '+colBits.join(', '):'')
    : n+(n>1?' instances':' instance');
  return '<details style="border-bottom:1px solid #f1edf5;"><summary style="cursor:pointer;padding:7px 0;display:flex;align-items:center;gap:8px;">'
    + '<b style="font-size:12.5px;">'+frEsc(label)+'</b>'+frChipTag(det)+'<span style="color:#6c6675;font-size:12px;">'+magnitude+prov+'</span></summary>'
    + '<div style="padding:2px 0 9px 14px;">'+body+'</div></details>';
}
function frAssumptionFor(id){ return ({
  'coverage.interior_gap':'these entities were expected to report every period in their active span',
  'coverage.event_gap':'every active member of a participating group should appear in that event (no rotation/bench)',
  'role.review':'the inferred column role matches your intent'
})[id] || 'the inferred pattern reflects a real defect, not expected behavior'; }
// External-plausibility footer — surfaces the claimed when/where combinations for eyeball and
// (mandatory) the "no domain ruleset → NOT verified" disclaimer. The honesty IS the feature.
function frClaimsFooter(findings){
  if(!findings || !findings.length) return '';
  var disc = findings.filter(function(f){ return f.id==='claims.no_ruleset'; })[0];
  var combos = findings.filter(function(f){ return f.id==='claims.combinations'; })[0];
  var h = '<div style="margin-top:14px;padding:10px 12px;background:#fbf9fe;border:1px solid #e9e4ee;border-radius:8px;">'
    + '<div style="font-family:ui-monospace,monospace;font-size:9px;letter-spacing:.05em;text-transform:uppercase;color:#a09aa8;margin-bottom:5px;">External plausibility</div>';
  if(combos) h += '<div style="font-size:12px;color:#3a3640;margin-bottom:6px;">'+frEsc(combos.detail)+'</div>';
  if(disc) h += '<div style="font-size:12px;color:#b45309;">⚠ '+frEsc(disc.detail)+'</div>';
  return h + '</div>';
}

function frModal(filename, prof, cls, parsed){
  var ex = document.getElementById('fr-modal'); if(ex) ex.remove();
  var ov = document.createElement('div'); ov.id = 'fr-modal';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(29,27,34,.5);z-index:100000;display:flex;align-items:flex-start;justify-content:center;padding:30px 16px;overflow:auto;font:13px/1.5 -apple-system,system-ui,sans-serif;color:#1d1b22;';
  var btn = 'font:600 12px system-ui,sans-serif;border-radius:7px;padding:7px 12px;cursor:pointer;';
  var secH = 'font-family:Fraunces,Georgia,serif;font-size:14px;font-weight:600;margin:18px 0 8px;';
  ov.innerHTML = '<div style="background:#fff;border-radius:14px;width:100%;max-width:940px;box-shadow:0 24px 70px rgba(0,0,0,.35);">'
    + '<div style="display:flex;align-items:center;gap:10px;padding:15px 20px;border-bottom:1px solid #eee;position:sticky;top:0;background:#fff;border-radius:14px 14px 0 0;z-index:3;">'
      + '<span style="font-family:Fraunces,Georgia,serif;font-size:17px;font-weight:600;">'+frEsc(filename)+'</span>'
      + '<span style="font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;color:#a09aa8;">'+prof.n_rows.toLocaleString()+' × '+prof.n_cols+'</span>'
      + '<span style="flex:1"></span>'
      + '<button id="fr-m-export" style="'+btn+'background:#fff;border:1px solid #ddd0ef;color:#3a3640;">⬇ Export CSV</button>'
      + '<button id="fr-m-rb" style="'+btn+'background:#6d28d9;border:none;color:#fff;">Open in Report Builder →</button>'
      + '<button id="fr-m-x" style="border:none;background:none;cursor:pointer;color:#a09aa8;font-size:18px;line-height:1;">✕</button></div>'
    + '<div style="padding:6px 20px 22px;">'
      + '<div style="'+secH+'">What’s in this file</div><div id="fr-orient">' + frOrientation(prof, cls) + '</div>'
      + '<div style="'+secH+'">Data quality <span style="font-family:ui-monospace,monospace;font-size:9px;letter-spacing:.05em;text-transform:uppercase;color:#a09aa8;">verified vs. to-review</span></div><div id="fr-dq-body"><div style="color:#6c6675;font-size:12px;">Running checks…</div></div>'
      + '<div style="'+secH+'">AI read <span style="font-family:ui-monospace,monospace;font-size:9px;letter-spacing:.05em;text-transform:uppercase;color:#a09aa8;">causation-aware</span></div>'
      + '<div id="fr-ai-body"><div style="color:#6c6675;">Reading the data with Claude…</div></div>'
      + '<div style="'+secH+'">Underlying data</div>' + frWorkbook(parsed)
    + '</div></div>';
  document.body.appendChild(ov);
  // Run the DQ battery AFTER the modal paints so it never blocks the open (large files).
  setTimeout(function(){ var el = document.getElementById('fr-dq-body'); if(el) try{ el.innerHTML = frDQSection(parsed); }catch(e){ el.innerHTML = ''; } }, 30);
  function close(){ ov.remove(); frExitDataset(); }
  ov.querySelector('#fr-m-x').onclick = close;
  ov.addEventListener('click', function(e){ if(e.target === ov) close(); });
  ov.querySelector('#fr-m-export').onclick = function(){ frExportCSV(parsed, filename); };
  ov.querySelector('#fr-m-rb').onclick = function(){ ov.remove(); frJumpToReportBuilder(); };
  // editable Type / Datatype dropdowns → override, persist, re-scope (delegated)
  ov.addEventListener('change', function(e){
    var s = e.target.closest('[data-frcol]'); if(!s) return;
    frSetOverride(s.getAttribute('data-frcol'), s.getAttribute('data-frkind')==='type' ? 'classification' : 'dtype', s.value);
  });
}
// Entry point from the overlay: scope the data, open the analysis modal, fire the AI read.
function frAnalyzeFile(filename, parsed){
  if(typeof FullRead==='undefined'){ if(typeof hoodieNotify==='function') hoodieNotify('Full Read module not loaded.','warn'); return; }
  var us = document.getElementById('overlay-state-upload'); if(us) us.classList.add('fr-analyzed');  // collapse the dropzone scaffolding
  frSaveRecent(filename, parsed);
  var s = frScopeDataset(filename, parsed);
  frModal(filename, s.prof, s.cls, parsed);
  try{ frFetchAiRead(filename, parsed, s.prof, window.RB_DATASET); }catch(e){ /* AI read is additive */ }
}
// Recent files — re-open a previously analyzed file without re-dropping (cached subset for big files).
var FR_RECENT_KEY = 'hoodie_overlay_recent';
function frLoadRecent(){ try{ return JSON.parse(localStorage.getItem(FR_RECENT_KEY)||'[]'); }catch(e){ return []; } }
function frSaveRecent(name, parsed){
  try{
    var list = frLoadRecent().filter(function(r){ return r.name !== name; });
    list.unshift({ name:name, columns:parsed.columns, rows:parsed.rows.slice(0,1500), rowCount:parsed.rowCount, savedAt:Date.now() });
    localStorage.setItem(FR_RECENT_KEY, JSON.stringify(list.slice(0,6)));
  }catch(e){ /* quota / too large — recent is best-effort */ }
  frRenderRecent();
}
function frRenderRecent(){
  var host = document.getElementById('overlay-recent'); if(!host) return;
  var list = frLoadRecent();
  if(!list.length){ host.innerHTML=''; return; }
  host.innerHTML = '<div style="font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;color:#a09aa8;margin:16px 0 7px;">Recent files</div>'
    + '<div style="display:flex;flex-wrap:wrap;gap:8px;">'
    + list.map(function(r, i){
        var cached = r.rows.length < (r.rowCount||r.rows.length) ? ' · cached subset' : '';
        return '<button data-fr-recent="'+i+'" style="text-align:left;border:1px solid #e9e4ee;background:#fff;border-radius:9px;padding:8px 12px;cursor:pointer;font:inherit;">'
          + '<div style="font-weight:600;font-size:13px;color:#1d1b22;">'+frEsc(r.name)+'</div>'
          + '<div style="font-size:11px;color:#6c6675;">'+(r.rowCount||r.rows.length).toLocaleString()+' rows × '+r.columns.length+' cols'+cached+'</div></button>';
      }).join('') + '</div>';
  host.querySelectorAll('[data-fr-recent]').forEach(function(b){
    b.onclick = function(){ var r = frLoadRecent()[+b.getAttribute('data-fr-recent')];
      if(r) frAnalyzeFile(r.name, { columns:r.columns, rows:r.rows, rowCount:(r.rowCount||r.rows.length) }); };
  });
}
try{ frRenderRecent(); }catch(e){}
// The overlay view (#view-overlay) is a sibling AFTER the flex-grow .content container; on
// other views .content hosts the active view, but on the overlay it's empty and still grows,
// leaving dead space above the card. Collapse .content while the overlay view is active.
(function(){
  var content = document.querySelector('#main > .content') || document.querySelector('.content');
  if(!content) return;
  function sync(view){ content.style.display = (view==='overlay') ? 'none' : ''; }
  document.querySelectorAll('.nav-subitem[data-view]').forEach(function(n){
    n.addEventListener('click', function(){ sync(n.getAttribute('data-view')); });
  });
  var act = document.querySelector('.nav-subitem[data-view].active');
  if(act) sync(act.getAttribute('data-view'));
})();
// Back-compat alias.
function frOpenInReportBuilder(filename, parsed){ frAnalyzeFile(filename, parsed); }

// AI read: Hoodie pulls are PUBLIC scraped data, so the actual rows go to Claude alongside
// the exact computed aggregates (the rows-never-leave / N≥10 rule is a SipSource constraint,
// not a Hoodie one). Claude writes the analysis under a strict causation-vs-correlation standard.
function frSummary(prof, ds, parsed){
  var summary = { n_rows: parsed.rowCount, columns: parsed.columns,
    classification: (ds.classification||[]).map(function(c){ return { name:c.name, classification:c.classification }; }) };
  var dimKey = RB_STATE.rows[0], measKey = RB_STATE.measures[0];
  if(dimKey && measKey && ds.measMap[measKey]){
    var dimCol = ds.dimMap[dimKey], spec = ds.measMap[measKey];
    summary.breakdown = { dimension:dimCol, measure: spec.col + ' (' + spec.agg + ')',
      groups: frDistinctVals(parsed.columns, parsed.rows, dimCol, 15).map(function(v){
        var f = {}; f[dimCol] = v.v;
        return { value:v.v, total: FullRead.cellAgg(parsed.columns, parsed.rows, spec.col, spec.agg, f) };
      }) };
  }
  return summary;
}
// Deterministic orientation table — "what's in this file", computed in-browser (NO key needed).
// Field · Type (measure/dimension/timeseries/identifier) · Examples · what-it-is + confidence.
function frTypeChip(cls){
  var C = { measure:['#e7f3ec','#15803d'], dimension:['#f3eefb','#6d28d9'], timeseries:['#e8f0fb','#2563b8'],
            identifier:['#eeecf1','#6c6675'], ignore:['#f6f6f8','#a09aa8'] }[cls] || ['#eeecf1','#6c6675'];
  return '<span style="font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.03em;text-transform:uppercase;background:'+C[0]+';color:'+C[1]+';padding:2px 7px;border-radius:5px;">'+frEsc(cls)+'</span>';
}
function frDefine(col, cls){
  var r = col.role_guess, dt = col.dtype;
  if(cls==='ignore') return 'Empty or constant — skipped.';
  if(cls==='timeseries') return 'Date/time field — group or trend by period.';
  if(cls==='identifier') return (r==='identifier'?'Identifier / code':'Unique key')+' — labels a row, not aggregated.';
  if(cls==='measure'){
    if(r==='money' || dt==='currency') return 'Monetary value — sum / average across groups.';
    if(r==='quantity') return 'Quantity / count — sum across groups.';
    if(dt==='percent') return 'Percentage measure.';
    return 'Numeric measure — sum / average.';
  }
  if(r==='geography') return 'Geographic dimension (location).';
  if(r==='account') return 'Account / store dimension.';
  if(r==='product') return 'Product / brand dimension.';
  if(col.n_distinct!=null && col.n_distinct<=40) return 'Categorical dimension — a way to slice ('+col.n_distinct+' values).';
  return 'Text dimension — high-cardinality label.';
}
var FR_TYPES  = ['measure','dimension','timeseries','identifier','ignore'];
var FR_DTYPES = ['string','integer','decimal','currency','percent','date','datetime','boolean'];
function frSel(colName, kind, cur, opts){
  var s = '<select data-frcol="'+frEsc(colName)+'" data-frkind="'+kind+'" style="font:11px ui-monospace,monospace;border:1px solid #e0d3f5;border-radius:5px;padding:2px 5px;background:#fff;color:#3a3640;cursor:pointer;max-width:110px;">';
  opts.forEach(function(o){ s += '<option'+(o===cur?' selected':'')+'>'+o+'</option>'; });
  return s + '</select>';
}
function frOrientation(prof, cls){
  var by = {}; (cls||[]).forEach(function(c){ by[c.name] = c; });
  var ov = (window.RB_DATASET && window.RB_DATASET.overrides) || {};
  var trs = prof.columns.map(function(col){
    var c = by[col.name] || { classification:'dimension', confidence:0.6 };
    var o = ov[col.name] || {};
    var curCls = o.classification || c.classification;
    var curDt  = o.dtype || col.dtype;
    var ex = (col.examples||[]).slice(0,3).map(frEsc).join(', ') || '—';
    var conf = Math.round((c.confidence||0.6)*100);
    var edited = !!(o.classification || o.dtype);
    var effCol = Object.assign({}, col, { dtype: curDt });
    return '<tr style="border-bottom:1px solid #f4f1f8;">'
      + '<td style="padding:6px 8px 6px 0;font-weight:600;vertical-align:top;">'+frEsc(col.name)+'</td>'
      + '<td style="padding:6px 8px;vertical-align:top;">'+frSel(col.name,'type',curCls,FR_TYPES)+'</td>'
      + '<td style="padding:6px 8px;vertical-align:top;">'+frSel(col.name,'dtype',curDt,FR_DTYPES)+'</td>'
      + '<td style="padding:6px 8px;color:#6c6675;vertical-align:top;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+ex+'">'+ex+'</td>'
      + '<td style="padding:6px 0 6px 8px;vertical-align:top;">'+frEsc(frDefine(effCol,curCls))
        + (edited ? ' <span style="color:#6d28d9;font-size:11px;">· edited</span>' : ' <span style="color:#a09aa8;">'+conf+'%</span>')
      + '</td></tr>';
  }).join('');
  return '<div style="color:#6c6675;font-family:ui-monospace,monospace;font-size:11px;margin-bottom:8px;">'+prof.n_rows.toLocaleString()+' rows × '+prof.n_cols+' columns'
    + (prof.duplicate_rows? ' · '+prof.duplicate_rows.toLocaleString()+' dup rows':'') + ' · <span style="color:#a09aa8;">Type &amp; Datatype are editable</span></div>'
    + '<table style="width:100%;border-collapse:collapse;font-size:12px;">'
    + '<thead><tr style="text-align:left;color:#a09aa8;font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.05em;text-transform:uppercase;border-bottom:1px solid #e9e4ee;">'
    + '<th style="padding:0 8px 6px 0;">Field</th><th style="padding:0 8px 6px;">Type</th><th style="padding:0 8px 6px;">Datatype</th><th style="padding:0 8px 6px;">Examples</th><th style="padding:0 0 6px 8px;">What it is</th></tr></thead>'
    + '<tbody>'+trs+'</tbody></table>';
}
// ── editable classification overrides (persist + re-scope the RB) ──
function frEffCls(baseCls, overrides){
  return baseCls.map(function(c){ var o=overrides[c.name]; return (o&&o.classification) ? Object.assign({},c,{classification:o.classification, confidence:1}) : c; });
}
function frApplyDtype(prof, overrides){ prof.columns.forEach(function(col){ var o=overrides[col.name]; if(o&&o.dtype) col.dtype=o.dtype; }); }
function frDefaultRow(prof, f){
  var def = f.dims.length ? f.dims[0].key : null, best = Infinity;
  f.dims.forEach(function(d){ var pc=prof.columns.filter(function(c){return c.name===f.dimMap[d.key];})[0]; var nd=pc?pc.n_distinct:0; if(nd>=2 && nd<best){ best=nd; def=d.key; } });
  return def;
}
function frOvKey(name, cols){ return 'hoodie_fr_ov_'+(name||'')+'|'+(cols||[]).join(','); }
function frLoadOverrides(name, cols){ try{ return JSON.parse(localStorage.getItem(frOvKey(name,cols))||'{}'); }catch(e){ return {}; } }
function frPersistOverrides(){ var ds=window.RB_DATASET; if(!ds) return; try{ localStorage.setItem(frOvKey(ds.name, ds.header), JSON.stringify(ds.overrides||{})); }catch(e){} }
function frSetOverride(colName, kind, value){
  var ds=window.RB_DATASET; if(!ds) return;
  ds.overrides=ds.overrides||{}; ds.overrides[colName]=ds.overrides[colName]||{};
  ds.overrides[colName][kind]=value;   // kind: 'classification' | 'dtype'
  frRescope(); frPersistOverrides();
}
function frRescope(){
  var ds=window.RB_DATASET; if(!ds) return;
  var prof=ds.profile, overrides=ds.overrides||{};
  frApplyDtype(prof, overrides);
  var cls=frEffCls(FullRead.ruleClassify(prof), overrides);
  var f=frBuildFields(prof, cls, {columns:ds.header, rows:ds.rows});
  RB_FIELDS.dimensions=f.dims; RB_FIELDS.measures=f.measures;
  ds.dimMap=f.dimMap; ds.measMap=f.measMap; ds.classification=cls;
  var def=frDefaultRow(prof, f);
  RB_STATE.rows=def?[def]:[]; RB_STATE.columns=[]; RB_STATE.measures=[f.defMeasure];
  var holder=document.getElementById('fr-orient'); if(holder) holder.innerHTML=frOrientation(prof, cls);
}
// FIX 1c — the AI read must describe the LOADED file, never a prior one. The cache key IS a stable
// fingerprint of the file's identity (name + column set + raw row count + grain + a version); the
// same string is stamped onto the read (res._fp) and verified again at render. "cached" may only
// ever mean "cached FOR THIS FILE".
var FR_AI_FP_VERSION = 'v2';
function frAiCacheKey(filename, parsed, prof){
  var grain = prof && (prof.candidate_key ? prof.candidate_key.join(',') : (prof.grain_statement || ''));
  return 'hoodie_fr_airead_'+(filename||'')+'|'+(parsed.columns||[]).join(',')+'|rows:'+(parsed.rowCount||(parsed.rows||[]).length)+'|g:'+(grain||'')+'|'+FR_AI_FP_VERSION;
}
// Only return a cached read whose stamped fingerprint matches its key (rejects pre-fix / mismatched entries).
function frAiCacheGet(k){ try{ var v=localStorage.getItem(k); if(!v) return null; var o=JSON.parse(v); return (o && o._fp===k) ? o : null; }catch(e){ return null; } }
function frAiCacheSet(k, res){ try{ res._fp = k; localStorage.setItem(k, JSON.stringify(res)); }catch(e){} }
// Fetch the AI read and render it into the modal's #fr-ai-body (the modal owns the layout).
// Served from cache unless force=true ("re-run") — the model is only called once per file.
var frAiCtx = null;
function frFetchAiRead(filename, parsed, prof, ds, force){
  if(typeof FullRead==='undefined' || !ds) return;
  frAiCtx = { filename:filename, parsed:parsed, prof:prof, ds:ds };
  var key = frAiCacheKey(filename, parsed, prof);
  if(!force){
    var cached = frAiCacheGet(key);
    if(cached){ frRenderAiRead(cached, true); return; }
  }
  var body0 = document.getElementById('fr-ai-body'); if(body0) body0.innerHTML = '<div style="color:#6c6675;">Reading the data with Claude…</div>';
  var summary = frSummary(prof, ds, parsed);
  fetch('/api/ai-read', { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ filename:filename, profile:prof, summary:summary,
                             header:parsed.columns, rows:parsed.rows }) })
    .then(function(r){
      return r.json().catch(function(){ return {}; }).then(function(j){
        if(r.status===503) throw {nokey:true};
        if(!r.ok) throw {detail: (j && (j.detail || j.error)) || ('HTTP '+r.status)};
        return j;
      });
    })
    .then(function(res){ res._rows = (parsed.rowCount||(parsed.rows||[]).length); frAiCacheSet(key, res); frRenderAiRead(res, false); })
    .catch(function(e){
      var body = document.getElementById('fr-ai-body'); if(!body) return;
      if(e && e.nokey){ body.innerHTML = '<div style="color:#6c6675;">AI read needs an Anthropic key. Add <code>ANTHROPIC_API_KEY</code> to <code>.env</code> and restart <code>./dev.sh</code>. The orientation above already works without it.</div>'; return; }
      var d = (e && e.detail) || 'engine offline';
      var hint = /credit balance|too low|billing/i.test(d) ? ' — add credits at console.anthropic.com → Plans & Billing.' : '';
      body.innerHTML = '<div style="color:#6c6675;">AI read unavailable: ' + frEsc(d) + hint + ' The orientation above + the report still work.</div>';
    });
}
function frFmtNum(v){ if(v==null||isNaN(v)) return '—'; var a=Math.abs(v); return (a>=1000 ? Math.round(v) : +(+v).toFixed(2)).toLocaleString(); }
// Compute an AI-proposed table from the REAL rows (the model only chose the cut).
function frComputeTable(ds, spec){
  if(!ds || !spec || !spec.dimension) return null;
  var header = ds.header, rows = ds.rows;
  if(header.indexOf(spec.dimension) < 0) return null;
  var agg = spec.agg || 'sum';
  var measureCol = (agg==='count') ? header[0]
                 : (spec.measure && header.indexOf(spec.measure) >= 0 ? spec.measure : null);
  if(agg !== 'count' && !measureCol) return null;
  var vals = frDistinctVals(header, rows, spec.dimension, 500).map(function(o){ return o.v; });
  if(vals.length > 200) return null;                 // too granular to be a "worth seeing" table
  var out = vals.map(function(v){ var f = {}; f[spec.dimension] = v;
    return [v, FullRead.cellAgg(header, rows, measureCol, agg, f)]; });
  out.sort(function(a,b){ return spec.sort==='asc' ? (a[1]-b[1]) : (b[1]-a[1]); });
  return { dim: spec.dimension, measure: (agg==='count' ? 'count' : (spec.measure + ' (' + agg + ')')),
           rows: out.slice(0, spec.limit || 8) };
}
function frRenderAiRead(res, cached){
  var body = document.getElementById('fr-ai-body'); if(!body) return;
  if(res && res.error){ body.innerHTML = '<div style="color:#6c6675;">AI read error: ' + (res.detail||res.error) + '</div>'; return; }
  // FIX 1c — never render a read computed against a DIFFERENT file. Verify the stamped fingerprint
  // (and, defense-in-depth, the stated row count) against the loaded file; on mismatch show a neutral
  // state and offer regeneration — never the prior file's numbers. Deterministic profile is ground truth.
  var curFp = frAiCtx ? frAiCacheKey(frAiCtx.filename, frAiCtx.parsed, frAiCtx.prof) : null;
  var liveRows = frAiCtx && frAiCtx.parsed ? (frAiCtx.parsed.rowCount||(frAiCtx.parsed.rows||[]).length) : null;
  var stale = res && ((res._fp && curFp && res._fp !== curFp) || (res._rows != null && liveRows != null && res._rows !== liveRows));
  if(stale){
    body.innerHTML = '<div style="color:#6c6675;">AI read not yet generated for this file. <a id="fr-ai-rerun" style="color:#6d28d9;cursor:pointer;text-decoration:underline;">Run analysis</a></div>';
    var rr0 = document.getElementById('fr-ai-rerun'); if(rr0) rr0.onclick = function(){ if(frAiCtx) frFetchAiRead(frAiCtx.filename, frAiCtx.parsed, frAiCtx.prof, frAiCtx.ds, true); };
    return;
  }
  // cached vs fresh + an explicit re-run (re-running is the only thing that re-pays Claude)
  var bar = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">'
    + (cached ? '<span style="font-family:ui-monospace,monospace;font-size:9px;letter-spacing:.05em;text-transform:uppercase;background:#eeecf1;color:#6c6675;padding:2px 6px;border-radius:5px;">cached</span>' : '')
    + '<a id="fr-ai-rerun" style="font-size:11px;color:#6d28d9;cursor:pointer;text-decoration:underline;">re-run analysis</a></div>';
  var KIND = { association:['#e8f0fb','#2563b8','assoc.'], opportunity:['#e7f3ec','#15803d','opportunity'],
               caveat:['#fbeede','#b45309','caveat'], data_quality:['#f8e6e7','#b4232a','data quality'] };
  var h = '';
  if(res.headline) h += '<div style="font-family:Fraunces,Georgia,serif;font-size:16px;font-weight:600;margin-bottom:6px;">'+frEsc(res.headline)+'</div>';
  if(res.what_is_this) h += '<div style="color:#3a3640;margin-bottom:12px;">'+frEsc(res.what_is_this)+'</div>';
  (res.findings||[]).forEach(function(f){
    var k = KIND[f.kind] || ['#eeecf1','#6c6675', f.kind||''];
    h += '<div style="margin-bottom:9px;"><span style="font-family:ui-monospace,monospace;font-size:9px;letter-spacing:.04em;text-transform:uppercase;background:'+k[0]+';color:'+k[1]+';padding:2px 6px;border-radius:5px;margin-right:6px;">'+frEsc(k[2])+'</span>'+frEsc(f.text)+'</div>';
  });
  // Tables worth seeing: the model picked the cut; WE compute the real numbers (render-not-invent).
  (res.tables||[]).forEach(function(spec){
    var t = frComputeTable(window.RB_DATASET, spec); if(!t) return;
    h += '<div style="margin-top:14px;"><div style="font-weight:600;">'+frEsc(spec.title || t.dim)+'</div>';
    if(spec.why) h += '<div style="color:#6c6675;font-size:12px;margin-bottom:5px;">'+frEsc(spec.why)+'</div>';
    h += '<table style="width:100%;border-collapse:collapse;font-size:12px;"><thead><tr style="text-align:left;color:#a09aa8;font-family:ui-monospace,monospace;font-size:9.5px;letter-spacing:.04em;text-transform:uppercase;border-bottom:1px solid #e9e4ee;">'
      + '<th style="padding:2px 8px 4px 0;">'+frEsc(t.dim)+'</th><th style="padding:2px 0 4px;text-align:right;">'+frEsc(t.measure)+'</th></tr></thead><tbody>'
      + t.rows.map(function(r){ return '<tr style="border-bottom:1px solid #f4f1f8;"><td style="padding:3px 8px 3px 0;">'+frEsc(r[0])+'</td><td style="padding:3px 0;text-align:right;font-variant-numeric:tabular-nums;">'+frFmtNum(r[1])+'</td></tr>'; }).join('')
      + '</tbody></table></div>';
  });
  if((res.caveats||[]).length){ h += '<div style="margin-top:12px;font-weight:600;color:#3a3640;">Caveats</div><ul style="margin:5px 0 0;padding-left:18px;color:#3a3640;">'+res.caveats.map(function(c){return '<li>'+frEsc(c)+'</li>';}).join('')+'</ul>'; }
  if((res.questions||[]).length){ h += '<div style="margin-top:12px;font-weight:600;color:#3a3640;">Worth asking</div><ul style="margin:5px 0 0;padding-left:18px;color:#3a3640;">'+res.questions.map(function(q){return '<li>'+frEsc(q)+'</li>';}).join('')+'</ul>'; }
  body.innerHTML = bar + (h || '<div style="color:#6c6675;">No analysis returned.</div>');
  var rr = document.getElementById('fr-ai-rerun');
  if(rr) rr.onclick = function(){ if(frAiCtx) frFetchAiRead(frAiCtx.filename, frAiCtx.parsed, frAiCtx.prof, frAiCtx.ds, true); };
}
function frEsc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c];}); }
function frBanner(name){
  var b = document.getElementById('fr-dataset-banner');
  if(!b){ b = document.createElement('div'); b.id = 'fr-dataset-banner';
    b.style.cssText = 'position:fixed;bottom:16px;left:50%;transform:translateX(-50%);z-index:99999;background:#15202e;color:#fff;font:13px/1.4 -apple-system,system-ui,sans-serif;padding:9px 14px;border-radius:8px;box-shadow:0 6px 24px rgba(0,0,0,.3);display:flex;gap:12px;align-items:center;';
    document.body.appendChild(b); }
  b.textContent = '';
  var span = document.createElement('span'); span.textContent = 'Report Builder scoped to “' + name + '” (its own fields)';
  var x = document.createElement('button'); x.textContent = 'Exit to Hoodie data';
  x.style.cssText = 'background:#2e7d57;color:#fff;border:none;border-radius:6px;padding:5px 10px;cursor:pointer;font:12px system-ui,sans-serif;';
  x.onclick = frExitDataset; b.appendChild(span); b.appendChild(x);
}
function frExitDataset(){
  if(!FR_SAVED) return;
  RB_FIELDS.dimensions = FR_SAVED.dims; RB_FIELDS.measures = FR_SAVED.measures;
  var s = FR_SAVED.state; Object.keys(s).forEach(function(k){ RB_STATE[k] = s[k]; });
  window.RB_DATASET = null; FR_SAVED = null;
  var b = document.getElementById('fr-dataset-banner'); if(b) b.remove();
  var ap = document.getElementById('fr-modal'); if(ap) ap.remove();
  if(typeof rbRenderAll==='function') rbRenderAll();
}
window.frExitDataset = frExitDataset;

function overlayProcessRealFile(filename, parsed, opts){
const force = !!(opts && opts.force);
const cols = parsed.columns;
const data = parsed.rows;
const rowCount = parsed.rowCount;
function overrideRun(){ overlayProcessRealFile(filename, parsed, {force:true}); }

// Soft guardrail: too small (overridable)
if(rowCount < 20 && !force){
overlayShowRedirect({
title: 'File too small to produce defensible insights',
body: '<p>This file has <strong>' + rowCount + ' rows</strong>. Hoodie\'s N≥10 anonymization threshold means cross-analysis on this size would either be empty or rely on cells too small to be statistically defensible.</p><p><strong>Minimum recommended:</strong> 50+ rows for sub-channel × category cuts, 200+ for division-level analysis.</p>',
override: overrideRun, overrideLabel: 'Analyze anyway (small sample) →'
});
return;
}

// Soft guardrail: transaction-grain (overridable — anonymity is your call for internal analysis)
const transactionSignals = ['order_id','transaction_id','txn_id','order_number','invoice','sku','upc','timestamp','order_date','transaction_date','order_time'];
const hasTxn = cols.some(function(c){return transactionSignals.indexOf(c) >= 0 || transactionSignals.some(function(s){return c.indexOf(s) >= 0;});});
if(hasTxn && !force){
overlayShowRedirect({
title: 'This file is at transaction grain',
body: '<p>I detected transaction-level columns (' + cols.filter(function(c){return transactionSignals.some(function(s){return c.indexOf(s) >= 0;});}).slice(0,3).join(', ') + '). Hoodie\'s standard cell model is <strong>month-aggregate with N≥10 anonymity</strong>, so for any <em>externally shared</em> output you\'d want to roll up first.</p><p><strong>The file is the root</strong> — open it in the Report Builder to slice by its own columns at this grain (sum / avg / count, toggle aggregates). For internal analysis that\'s the way; or aggregate / upload account-attributes to overlay onto Hoodie cells.</p>',
override: function(){ frOpenInReportBuilder(filename, parsed); }, overrideLabel: 'Analyze this file →'
});
return;
}

// Detect column roles
const roles = overlayDetectRoles(cols);
const roleNames = Object.values(roles);
const hasGeo = roleNames.indexOf('zip') >= 0 || roleNames.indexOf('state') >= 0 || roleNames.indexOf('division') >= 0 || roleNames.indexOf('region') >= 0;
const hasSubch = roleNames.indexOf('subch') >= 0;
const hasCategory = roleNames.indexOf('category') >= 0;
const hasGoal = roleNames.indexOf('volume_goal') >= 0;
const hasActual = roleNames.indexOf('volume_actual') >= 0;
const hasPrior = roleNames.indexOf('volume_prior') >= 0;
const hasPodGoal = roleNames.indexOf('pod_goal') >= 0;
const hasPodActual = roleNames.indexOf('pod_actual') >= 0;

if(!hasGeo && !hasSubch && !hasCategory){
overlayShowRedirect({
title: 'This file doesn\'t map to Hoodie\'s cell model — analyze it on its own terms',
body: '<p>Headers (' + cols.slice(0, 6).join(', ') + (cols.length > 6 ? ', …' : '') + ') don\'t align to Hoodie\'s category × sub-channel × division cells. That\'s fine — <strong>the file is the root</strong>. Open it in the Report Builder and slice by its own columns (sum / avg / count, any dimension), or add a location / account-type / category column to overlay onto Hoodie cells instead.</p>',
override: function(){ frOpenInReportBuilder(filename, parsed); },
overrideLabel: 'Analyze this file →'
});
return;
}

// Find column indexes
const colIdx = {};
Object.keys(roles).forEach(function(i){ colIdx[roles[i]] = parseInt(i, 10); });

// Build pivot at category × subch × division grain
const cells = {}; // key -> aggregated cell
const numParse = function(s){ const v = parseFloat(String(s||'').replace(/[,$]/g,'')); return isNaN(v) ? 0 : v; };
data.forEach(function(row){
const cat = colIdx.category !== undefined ? overlayNormalizeCategory(row[colIdx.category]) : 'unknown';
const subch = colIdx.subch !== undefined ? String(row[colIdx.subch]||'unknown') : 'all';
let div = colIdx.division !== undefined ? String(row[colIdx.division]||'') : '';
if(!div && colIdx.state !== undefined){
const st = String(row[colIdx.state]||'').trim().toUpperCase();
div = STATE_TO_DIVISION[st] || '';
}
if(!div) div = 'National';
const key = cat + '|' + subch + '|' + div;
if(!cells[key]) cells[key] = {category:cat, subch:subch, division:div, n_rows:0, volume_goal:0, volume_actual:0, volume_prior:0, pod_goal:0, pod_actual:0};
const c = cells[key];
c.n_rows++;
if(hasGoal) c.volume_goal += numParse(row[colIdx.volume_goal]);
if(hasActual) c.volume_actual += numParse(row[colIdx.volume_actual]);
if(hasPrior) c.volume_prior += numParse(row[colIdx.volume_prior]);
if(hasPodGoal) c.pod_goal += numParse(row[colIdx.pod_goal]);
if(hasPodActual) c.pod_actual += numParse(row[colIdx.pod_actual]);
});

// Filter cells: count rolled-up vs aligned. Cells with n_rows < 3 get rolled up to (category × subch) parent
const cellList = Object.values(cells);
const cellsAligned = cellList.filter(function(c){return c.n_rows >= 3;});
const cellsRolledUp = cellList.length - cellsAligned.length;
const totalRowsAligned = cellsAligned.reduce(function(s, c){return s + c.n_rows;}, 0);
const pctAligned = Math.round(totalRowsAligned / rowCount * 100);

// Compute metrics + classify each cell — only if we have goal+actual+prior
const analyzableCells = [];
cellsAligned.forEach(function(c){
const out = Object.assign({}, c);
if(hasPrior && hasActual && c.volume_prior > 0){
out.actual_growth_pct = ((c.volume_actual - c.volume_prior) / c.volume_prior) * 100;
}
if(hasGoal && hasActual && c.volume_actual > 0){
out.goal_growth_pct = ((c.volume_goal - c.volume_actual) / c.volume_actual) * 100;
}
if(hasPodGoal && hasPodActual && c.pod_actual > 0){
out.pod_growth_pct = ((c.pod_goal - c.pod_actual) / c.pod_actual) * 100;
}
// Industry benchmark
const bench = overlayIndustryBench(c.category, c.subch, c.division);
out.industry_growth = bench.growth;
out.industry_headroom = bench.headroom;
// Classify
if(out.goal_growth_pct == null){
out.verdict = '—';
out.gap = 0;
}else{
out.gap = out.goal_growth_pct - out.industry_growth;
const headroom = out.industry_headroom;
if(out.gap < -4 && out.goal_growth_pct < out.industry_growth * 0.6){
out.verdict = 'Sandbag';
}else if(out.gap > 6 && out.goal_growth_pct > headroom * 0.55){
out.verdict = 'Overstretched';
}else if(Math.abs(out.gap) < 3){
out.verdict = 'Calibrated';
}else if(out.gap > 0){
out.verdict = 'Stretch';
}else{
out.verdict = 'Soft';
}
}
analyzableCells.push(out);
});

// === Generate findings ===
const findings = [];
const sandbags = analyzableCells.filter(function(c){return c.verdict === 'Sandbag';});
const stretches = analyzableCells.filter(function(c){return c.verdict === 'Overstretched';});
const calibrated = analyzableCells.filter(function(c){return c.verdict === 'Calibrated';});
const softs = analyzableCells.filter(function(c){return c.verdict === 'Soft';});
const moderateStretches = analyzableCells.filter(function(c){return c.verdict === 'Stretch';});
const plural = function(n, s, p){ return n + ' ' + (n === 1 ? s : (p || s + 's')); };

// Coverage finding
findings.push({
priority:'neutral', tag:'Coverage',
strong: 'File aligned to Hoodie cells.',
rest: ' ' + plural(cellsAligned.length, 'anonymized cell') + ' (category × sub-channel × division) passed the N threshold, covering <strong>' + pctAligned + '%</strong> of uploaded rows. ' + (cellsRolledUp > 0 ? plural(cellsRolledUp, 'cell') + ' fell below the threshold and were excluded.' : 'No cells excluded.')
});

// Sandbag finding
if(sandbags.length > 0){
const catCounts = {};
sandbags.forEach(function(c){ catCounts[c.category] = (catCounts[c.category]||0) + 1; });
const topCat = Object.keys(catCounts).sort(function(a,b){return catCounts[b]-catCounts[a];})[0];
const avgGap = (sandbags.reduce(function(s,c){return s+c.gap;}, 0) / sandbags.length).toFixed(1);
findings.push({
priority:'caution', tag:'Revenue at risk',
strong: 'Sandbag pattern: ' + plural(sandbags.length, 'cell') + ' where your goal undershoots industry pace.',
rest: ' Concentrated in <strong>' + topCat + '</strong> (' + plural(catCounts[topCat], 'cell') + '). Average gap: <strong>' + avgGap + ' pt</strong> below industry growth. These are revenue you\'re leaving on the table by under-asking.'
});
}

// Overstretched finding
if(stretches.length > 0){
const catCounts = {};
stretches.forEach(function(c){ catCounts[c.category] = (catCounts[c.category]||0) + 1; });
const topCat = Object.keys(catCounts).sort(function(a,b){return catCounts[b]-catCounts[a];})[0];
const avgHeadroom = Math.round(stretches.reduce(function(s,c){return s+c.industry_headroom;}, 0) / stretches.length);
findings.push({
priority:'high', tag:'Recalibrate',
strong: plural(stretches.length, 'cell') + ' set goals beyond achievable headroom.',
rest: ' Concentrated in <strong>' + topCat + '</strong> (' + plural(catCounts[topCat], 'cell') + '). Industry headroom averages <strong>' + avgHeadroom + ' pt</strong> here — your goals exceed what the market can absorb. Recalibrate before pipeline planning.'
});
}

// Moderate-stretch finding (between calibrated and overstretched)
if(moderateStretches.length >= 5){
const catCounts = {};
moderateStretches.forEach(function(c){ catCounts[c.category] = (catCounts[c.category]||0) + 1; });
const topCat = Object.keys(catCounts).sort(function(a,b){return catCounts[b]-catCounts[a];})[0];
const avgGap = (moderateStretches.reduce(function(s,c){return s+c.gap;}, 0) / moderateStretches.length).toFixed(1);
findings.push({
priority:'positive', tag:'Execution focus',
strong: plural(moderateStretches.length, 'cell') + ' set ambitious-but-achievable goals.',
rest: ' Goals exceed industry pace by an average of <strong>+' + avgGap + ' pt</strong>, but headroom is available. Top concentration: <strong>' + topCat + '</strong>. These need execution focus, not recalibration.'
});
}

// Calibration finding
if(calibrated.length > 0){
findings.push({
priority:'positive', tag:'Strength',
strong: plural(calibrated.length, 'cell') + ' well-calibrated to industry pace.',
rest: ' Goal growth tracks industry within ±3 pt. These segments are realistic plans you can underwrite without further adjustment.'
});
}

// Soft finding (goal below industry but not as severe as sandbag)
if(softs.length >= 4){
const catCounts = {};
softs.forEach(function(c){ catCounts[c.category] = (catCounts[c.category]||0) + 1; });
const topCat = Object.keys(catCounts).sort(function(a,b){return catCounts[b]-catCounts[a];})[0];
findings.push({
priority:'caution', tag:'Review',
strong: plural(softs.length, 'cell') + ' set soft goals below industry pace.',
rest: ' Concentrated in <strong>' + topCat + '</strong>. Not severe enough to flag as sandbagging, but worth a second look — incrementally raising these aligns plans to where the market is moving.'
});
}

// POD finding — either direction (lag or excess)
if(hasPodGoal && hasPodActual){
const podLag = analyzableCells.filter(function(c){return c.pod_growth_pct != null && c.goal_growth_pct != null && (c.goal_growth_pct - c.pod_growth_pct) > 4;});
const podExcess = analyzableCells.filter(function(c){return c.pod_growth_pct != null && c.goal_growth_pct != null && (c.pod_growth_pct - c.goal_growth_pct) > 6;});
if(podLag.length >= 3){
findings.push({
priority:'caution', tag:'Feasibility',
strong: 'POD goal growth lags volume goal growth in ' + plural(podLag.length, 'cell') + '.',
rest: ' Distribution build appears to be the bottleneck — you\'re planning volume gains without the POD expansion to absorb them. Cross-check feasibility with your trade team.'
});
}else if(podExcess.length >= 3){
findings.push({
priority:'caution', tag:'Investment risk',
strong: 'POD goal growth runs ahead of volume in ' + plural(podExcess.length, 'cell') + '.',
rest: ' You\'re investing in distribution without the corresponding volume plan — either the volume goal is too soft, or POD expansion is being over-bought relative to demand.'
});
}
}

// Build output table — top mismatches by absolute gap
const sortedCells = analyzableCells.slice().sort(function(a,b){return Math.abs(b.gap) - Math.abs(a.gap);}).slice(0, 12);
const fmtPct = function(v){ if(v == null) return '—'; return (v >= 0 ? '+' : '') + v.toFixed(1) + '%'; };
const fmtPt = function(v){ if(v == null) return '—'; return v + ' pt'; };
const verdictStyle = {
'Sandbag':'verdict-sandbag', 'Overstretched':'verdict-overstretch',
'Calibrated':'verdict-cal', 'Stretch':'verdict-stretch', 'Soft':'verdict-soft', '—':'verdict-na'
};

const tableRows = sortedCells.map(function(c){
const verdict = '<span class="overlay-verdict ' + verdictStyle[c.verdict] + '">' + c.verdict + '</span>';
return [
c.category.charAt(0).toUpperCase() + c.category.slice(1),
c.subch,
c.division,
fmtPct(c.goal_growth_pct),
fmtPct(c.industry_growth),
fmtPt(c.industry_headroom),
verdict
];
});

// === White paper narrative content ===
// Title derived from data scope
const categoriesInFile = Array.from(new Set(analyzableCells.map(function(c){return c.category;})));
const divisionsInFile = Array.from(new Set(analyzableCells.map(function(c){return c.division;})));
const subchInFile = Array.from(new Set(analyzableCells.map(function(c){return c.subch;})));
const catLabel = categoriesInFile.length === 1 ? (categoriesInFile[0].charAt(0).toUpperCase() + categoriesInFile[0].slice(1)) : 'Multi-category';
const geoLabel = divisionsInFile.length === 1 ? divisionsInFile[0] : (divisionsInFile.length + '-division');
const wpTitleText = catLabel + ' goals overlay · ' + geoLabel + ' analysis';
const wpSubtitleText = 'Cross-referencing ' + rowCount.toLocaleString() + ' uploaded rows against Hoodie industry depletions to assess goal realism, identify revenue at risk, and flag execution feasibility concerns at the category × sub-channel × division grain.';

// Top concerns for exec summary
const topConcernCells = sortedCells.slice(0, 3);
const sandbagPct = analyzableCells.length > 0 ? Math.round((sandbags.length / analyzableCells.length) * 100) : 0;
const stretchPct = analyzableCells.length > 0 ? Math.round(((stretches.length + moderateStretches.length) / analyzableCells.length) * 100) : 0;
const calibratedPct = analyzableCells.length > 0 ? Math.round((calibrated.length / analyzableCells.length) * 100) : 0;
const totalIssues = sandbags.length + stretches.length;

// Headline classification for exec summary
let headlinePosture = 'mixed';
if(sandbags.length > stretches.length + moderateStretches.length && sandbags.length >= 5) headlinePosture = 'sandbagged';
else if(stretches.length >= 5) headlinePosture = 'overstretched';
else if(calibrated.length / Math.max(1, analyzableCells.length) > 0.55) headlinePosture = 'calibrated';
else if(moderateStretches.length >= 5) headlinePosture = 'ambitious';

const execParas = [];
const _div = divisionsInFile.length === 1 ? divisionsInFile[0] : (divisionsInFile.length + ' census divisions');
const _cat = categoriesInFile.length === 1 ? categoriesInFile[0] : (categoriesInFile.length + ' categories');
execParas.push('Hoodie analyzed <span class="wp-num">' + rowCount.toLocaleString() + '</span> rows from <strong>' + filename + '</strong>, aligning <span class="wp-num">' + cellsAligned.length + '</span> anonymized cells across <strong>' + _cat + '</strong> and <strong>' + _div + '</strong>. ' + (cellsAligned.length >= 25 ? 'Coverage is sufficient for category-level recommendations at the sub-channel and division grain.' : (cellsAligned.length >= 12 ? 'Coverage supports directional recommendations; sub-cell verdicts should be treated as signal rather than precision.' : 'Coverage is limited; treat results as directional only and consider uploading a broader file.')));

if(headlinePosture === 'sandbagged'){
execParas.push('<strong>The portfolio is broadly under-asked.</strong> <span class="wp-num neg">' + sandbags.length + '</span> cells (<span class="wp-num">' + sandbagPct + '%</span> of analyzable cells) set goals materially below industry growth — these represent revenue you have an industry-validated path to capture but have not committed to planning. The pattern concentrates in segments where headroom is high and the market is moving without you.');
}else if(headlinePosture === 'overstretched'){
execParas.push('<strong>The portfolio leans aggressive.</strong> <span class="wp-num neg">' + stretches.length + '</span> cells set goals beyond the industry-validated headroom ceiling, which means even perfect execution against Hoodie trajectory would not deliver the plan. Recalibrate the most overstretched cells before pipeline commitments lock in unachievable numbers.');
}else if(headlinePosture === 'calibrated'){
execParas.push('<strong>Plans are well-calibrated against industry.</strong> <span class="wp-num pos">' + calibrated.length + '</span> cells (<span class="wp-num">' + calibratedPct + '%</span>) track industry growth within ±3 pt — these are realistic plans you can underwrite without further adjustment. Focus management attention on execution rather than re-planning.');
}else if(headlinePosture === 'ambitious'){
execParas.push('<strong>Plans are ambitious but achievable.</strong> <span class="wp-num">' + moderateStretches.length + '</span> cells exceed industry pace while remaining within the headroom ceiling. These segments need execution focus, not recalibration — operationally they are stretch targets, not unrealistic ones.');
}else{
execParas.push('<strong>The portfolio shows a mixed posture.</strong> Calibrated, sandbagged, and stretched cells are distributed across categories without a single dominant pattern. Recommend prioritizing the cells with the largest absolute mismatches (see Section 04) rather than blanket recalibration.');
}

if(topConcernCells.length > 0){
const c = topConcernCells[0];
const dir = c.gap > 0 ? 'exceeds' : 'undershoots';
execParas.push('The single largest variance: <strong>' + (c.category.charAt(0).toUpperCase() + c.category.slice(1)) + ' in ' + c.subch + ' (' + c.division + ')</strong> — goal growth of <span class="wp-num">' + fmtPct(c.goal_growth_pct) + '</span> ' + dir + ' industry pace of <span class="wp-num">' + fmtPct(c.industry_growth) + '</span> by <strong>' + Math.abs(c.gap).toFixed(1) + ' pt</strong>. See variance table for the full top-' + sortedCells.length + ' cell ranking.');
}

const execStats = [
{value: cellsAligned.length, label: 'Cells analyzed', tone: ''},
{value: sandbags.length, label: 'Sandbagged', tone: sandbags.length > 0 ? 'warn' : ''},
{value: stretches.length, label: 'Overstretched', tone: stretches.length > 0 ? 'neg' : ''},
{value: calibrated.length, label: 'Calibrated', tone: calibrated.length > 0 ? 'pos' : ''}
];

// Context prose — describes what we found in their file
const contextProse = 'Your file mapped cleanly to Hoodie\'s anonymization-safe analysis grain. We detected <strong>' + Object.values(roles).filter(function(r,i,a){return a.indexOf(r)===i;}).length + ' typed roles</strong> among your column headers — including ' + (hasGeo ? 'geography' : '') + (hasGeo && (hasSubch || hasCategory) ? ', ' : '') + (hasSubch ? 'sub-channel' : '') + (hasSubch && hasCategory ? ', ' : '') + (hasCategory ? 'category' : '') + (hasGoal ? ', volume goal, and volume actual' : '') + '. After applying the N&nbsp;≥&nbsp;10 anonymization threshold, <span class="wp-num">' + cellsAligned.length + '</span> distinct cells qualified for cross-analysis. Industry benchmarks below are drawn from Hoodie\'s syndicated depletion dataset, aligned to the same category × sub-channel × division cells.';

// Findings intro
const findingsIntro = 'Each finding below reflects a distinct pattern in how your goals compare to industry trajectory. <strong>Action required</strong> items are cells where the plan cannot be achieved even with industry-paced execution; <strong>Revenue at risk</strong> items are cells where you are systematically under-asking against an addressable trajectory; <strong>Strength</strong> items confirm where your planning is already calibrated to where the market is moving.';

// Output table intro
const outputIntro = 'The table shows the <strong>top ' + sortedCells.length + ' cells</strong> ranked by absolute mismatch between your stated goal and industry growth pace. Verdict classifications apply per-cell thresholds documented in Section 06. All cells below satisfy N&nbsp;≥&nbsp;10.';

// Generate recommendations based on findings
const recommendations = [];
if(sandbags.length >= 3){
const sandbagCats = {};
sandbags.forEach(function(c){ sandbagCats[c.category] = (sandbagCats[c.category]||0) + 1; });
const topSandbagCat = Object.keys(sandbagCats).sort(function(a,b){return sandbagCats[b]-sandbagCats[a];})[0];
recommendations.push({
title: 'Re-open goal-setting on the ' + topSandbagCat + ' portfolio',
detail: 'The ' + sandbags.length + ' sandbagged cells concentrate in ' + topSandbagCat + '. Industry trajectory in these cells supports goals <strong>4–8 pt higher</strong> than your current plan without exceeding feasible headroom. Recommend an early-Q-cycle re-baselining conversation with the field commercial team.'
});
}
if(stretches.length >= 3){
recommendations.push({
title: 'Recalibrate overstretched cells before commitments',
detail: '<strong>' + stretches.length + ' cells</strong> set goals beyond industry-validated headroom. These plans cannot succeed even with perfect execution — pipeline commitments tied to them should be paused until the goal lines are revised downward into the achievable band.'
});
}
if(moderateStretches.length >= 4){
recommendations.push({
title: 'Convert ambitious-but-achievable cells into execution plans',
detail: '<strong>' + moderateStretches.length + ' cells</strong> set stretch targets that fall within addressable headroom. Build named-account plays, programming, and trade investment around these specifically — they are where ambitious execution most likely delivers measurable goal exceedance.'
});
}
if(calibrated.length >= 5){
recommendations.push({
title: 'Underwrite the calibrated band without further review',
detail: '<strong>' + calibrated.length + ' cells</strong> already track industry pace within ±3 pt. These are realistic plans — direct management focus elsewhere. Re-planning calibrated cells consumes leadership cycles without changing the trajectory.'
});
}
if(hasPodGoal && hasPodActual){
const podLag = analyzableCells.filter(function(c){return c.pod_growth_pct != null && c.goal_growth_pct != null && (c.goal_growth_pct - c.pod_growth_pct) > 4;});
if(podLag.length >= 3){
recommendations.push({
title: 'Stress-test POD-volume coupling with the trade team',
detail: '<strong>' + podLag.length + ' cells</strong> plan volume gains that exceed POD growth. Distribution build appears to be the bottleneck — schedule a feasibility review with trade development before locking in dependent commitments.'
});
}
}
recommendations.push({
title: 'Re-run this analysis after goal adjustments',
detail: 'Re-upload the revised goal file once cells have been adjusted. Hoodie will re-compute verdicts against the same industry benchmarks, giving you a quantitative read on whether the recalibration has moved cells into the calibrated band.'
});

const wpPayload = {
title: wpTitleText,
subtitle: wpSubtitleText,
exec: execParas,
execStats: execStats,
contextProse: contextProse,
findingsIntro: findingsIntro,
outputIntro: outputIntro,
recommendations: recommendations
};

// === Detect "saveable" custom measures from the file ===
const filenameLower = filename.toLowerCase();
const filenameSignals = ['goal','target','plan','budget','forecast','quota','actual','performance','ytd'];
const filenameMatchesIntent = filenameSignals.some(function(s){return filenameLower.indexOf(s) >= 0;});
const fileScope = filenameSignals.find(function(s){return filenameLower.indexOf(s) >= 0;}) || 'data';
const fileScopeLabel = fileScope.charAt(0).toUpperCase() + fileScope.slice(1);
// Year detection — pull 4-digit year from filename if present (e.g., _2026, -2026, 2026.)
const yearMatch = filename.match(/(20\d{2})/);
const yearLabel = yearMatch ? ' ' + yearMatch[1] : '';
// Build candidate measures from the role detections + cell data
const candidates = [];
const sourceColMap = {
volume_goal: { roleKey:'volume_goal', label: 'Volume Goal' + yearLabel, accumKey:'volume_goal' },
volume_actual: { roleKey:'volume_actual', label: 'Volume Actual' + yearLabel, accumKey:'volume_actual' },
volume_prior: { roleKey:'volume_prior', label: 'Prior Year Volume', accumKey:'volume_prior' },
pod_goal: { roleKey:'pod_goal', label: 'POD Goal' + yearLabel, accumKey:'pod_goal' },
pod_actual: { roleKey:'pod_actual', label: 'POD Actual', accumKey:'pod_actual' }
};
// Determine actual grains from the role detection — used to tag the measure so the
// builder knows not to attempt finer-grained queries on coarse uploads.
const detectedGrains = ['category'];
if(Object.values(roles).indexOf('subch') >= 0) detectedGrains.push('subch');
if(Object.values(roles).indexOf('division') >= 0 || Object.values(roles).indexOf('state') >= 0) detectedGrains.push('division');

Object.keys(sourceColMap).forEach(function(roleKey){
const cfg = sourceColMap[roleKey];
// Find the source column for this role — roles is indexed by column position
const sourceColIdx = Object.keys(roles).find(function(idx){return roles[idx] === roleKey;});
if(sourceColIdx === undefined) return;
const sourceCol = cols[parseInt(sourceColIdx)];
if(!sourceCol) return;
// Build cells map from cellsAligned where the accumulator > 0
const cellsMap = {};
let total = 0;
cellsAligned.forEach(function(c){
const v = c[cfg.accumKey];
if(v !== undefined && v !== null && !isNaN(v) && v !== 0){
const cellKey = c.category + '|' + c.subch + '|' + c.division;
cellsMap[cellKey] = v;
total += v;
}
});
if(Object.keys(cellsMap).length === 0) return; // no data
const measureKey = 'um_' + cfg.accumKey + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,6);
candidates.push({
key: measureKey,
label: cfg.label,
unit: '',
type: 'number',
signed: false,
plus: false,
grains: detectedGrains.slice(),
source: { file: filename, column: sourceCol, uploadedAt: Date.now() },
cells: cellsMap,
total: total,
cellCount: Object.keys(cellsMap).length
});
});

// === Derived measures — auto-generated when both numerator and denominator are present ===
const hasVolGoal = Object.values(roles).indexOf('volume_goal') >= 0;
const hasVolActual = Object.values(roles).indexOf('volume_actual') >= 0;
const hasVolPrior = Object.values(roles).indexOf('volume_prior') >= 0;
const hasPodG = Object.values(roles).indexOf('pod_goal') >= 0;
const hasPodA = Object.values(roles).indexOf('pod_actual') >= 0;

function buildRatioMeasure(label, aKey, bKey, multiplier, source){
const cellsA = {}, cellsB = {};
let totalA = 0, totalB = 0;
cellsAligned.forEach(function(c){
const a = c[aKey], b = c[bKey];
if(a === undefined || a === null || isNaN(a)) return;
if(b === undefined || b === null || isNaN(b) || b === 0) return;
const cellKey = c.category + '|' + c.subch + '|' + c.division;
cellsA[cellKey] = a;
cellsB[cellKey] = b;
totalA += a;
totalB += b;
});
if(Object.keys(cellsA).length === 0) return null;
return {
key: 'um_' + label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'') + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,6),
label: label,
unit: '%',
type: 'percent',
signed: false,
plus: false,
derived: true,
source: source,
computeMode: 'ratio',
cellsA: cellsA,
cellsB: cellsB,
multiplier: multiplier,
total: totalB > 0 ? (totalA / totalB) * multiplier : 0,
cellCount: Object.keys(cellsA).length
};
}

// Goal Attainment % — Volume Actual ÷ Volume Goal × 100
if(hasVolGoal && hasVolActual){
const m = buildRatioMeasure('Goal Attainment' + yearLabel, 'volume_actual', 'volume_goal', 100, {file: filename, column: 'volume_actual ÷ volume_goal × 100', uploadedAt: Date.now(), derived: true});
if(m) candidates.push(m);
}
// POD Attainment % — POD Actual ÷ POD Goal × 100
if(hasPodG && hasPodA){
const m = buildRatioMeasure('POD Attainment' + yearLabel, 'pod_actual', 'pod_goal', 100, {file: filename, column: 'pod_actual ÷ pod_goal × 100', uploadedAt: Date.now(), derived: true});
if(m) candidates.push(m);
}
// Goal Volume Growth % — (Goal − Prior) ÷ Prior × 100 — uses the same ratio compute via stored numerator/denominator semantics
if(hasVolGoal && hasVolPrior){
// For growth, numerator = goal - prior, denominator = prior, so we need a different cell setup
const cellsA = {}, cellsB = {};
let totalA = 0, totalB = 0;
cellsAligned.forEach(function(c){
if(c.volume_goal === undefined || c.volume_prior === undefined || c.volume_prior === 0) return;
const cellKey = c.category + '|' + c.subch + '|' + c.division;
cellsA[cellKey] = c.volume_goal - c.volume_prior;
cellsB[cellKey] = c.volume_prior;
totalA += cellsA[cellKey];
totalB += cellsB[cellKey];
});
if(Object.keys(cellsA).length > 0){
candidates.push({
key: 'um_goal_growth_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,6),
label: 'Goal Growth' + yearLabel + ' %',
unit: '%',
type: 'percent',
signed: true,
plus: true,
derived: true,
source: {file: filename, column: '(volume_goal − volume_prior) ÷ volume_prior × 100', uploadedAt: Date.now(), derived: true},
computeMode: 'ratio',
cellsA: cellsA,
cellsB: cellsB,
multiplier: 100,
total: totalB > 0 ? (totalA / totalB) * 100 : 0,
cellCount: Object.keys(cellsA).length
});
}
}

const saveCard = (filenameMatchesIntent && candidates.length > 0) ? {
intentLabel: fileScopeLabel + ' file' + yearLabel,
candidates: candidates,
filename: filename
} : null;

const result = {
filename: filename,
rowCount: rowCount,
detection: [
{label:'Rows read', value: rowCount.toLocaleString(), sub:'after header parse'},
{label:'Columns detected', value: String(cols.length), sub: Object.keys(roles).length + ' typed roles'},
{label:'Aligned cells', value: String(cellsAligned.length), sub:'category × sub-ch × division'},
{label:'Calibration', value: calibrated.length + ' calibrated · ' + (sandbags.length + softs.length) + ' soft · ' + (moderateStretches.length + stretches.length) + ' stretched', sub:'cell verdict spread'}
],
alignment: {
pctAligned: pctAligned, pctRolledUp: 100 - pctAligned, cellsAbove10: cellsAligned.length,
detail: [
{label:'Rows aligned to Hoodie cells', value: totalRowsAligned.toLocaleString() + ' (' + pctAligned + '%)'},
{label:'Cells passing N threshold', value: cellsAligned.length + ' of ' + cellList.length},
{label:'Detected roles', value: Object.values(roles).filter(function(r,i,a){return a.indexOf(r)===i;}).join(', ')},
{label:'Analysis grain', value: 'Category × sub-channel × census division'}
]
},
findings: findings,
output: {
title: 'Goal vs industry — top ' + sortedCells.length + ' cells by absolute mismatch',
columns: ['Category', 'Sub-channel', 'Division', 'Your goal growth', 'Industry pace', 'Headroom', 'Verdict'],
rows: tableRows
},
whitepaper: wpPayload,
saveCard: saveCard,
appendix: (function(){
// Verdict counts
const verdictCounts = {};
analyzableCells.forEach(function(c){
const v = c.verdict || 'Unclassified';
verdictCounts[v] = (verdictCounts[v] || 0) + 1;
});
// Top 10 cells by absolute goal_growth vs industry gap
const topGaps = analyzableCells.slice()
.filter(function(c){return typeof c.gap === 'number' && !isNaN(c.gap);})
.sort(function(a,b){return Math.abs(b.gap) - Math.abs(a.gap);})
.slice(0,10)
.map(function(c){return {category:c.category, subch:c.subch, division:c.division, gap:c.gap};});
// Category roll-up — goal growth vs industry growth, weighted by volume_prior
const catBuckets = {};
analyzableCells.forEach(function(c){
if(!catBuckets[c.category]) catBuckets[c.category] = {goalDelta:0, indDelta:0, prior:0};
const b = catBuckets[c.category];
const w = c.volume_prior || 1;
b.goalDelta += (c.goal_growth || 0) * w;
b.indDelta += (c.industry_growth || 0) * w;
b.prior += w;
});
const catRollup = Object.keys(catBuckets).map(function(cat){
const b = catBuckets[cat];
return {
category: cat,
goalGrowth: b.prior > 0 ? b.goalDelta / b.prior : 0,
industryGrowth: b.prior > 0 ? b.indDelta / b.prior : 0
};
}).sort(function(a,b){return Math.abs(b.goalGrowth - b.industryGrowth) - Math.abs(a.goalGrowth - a.industryGrowth);});
return {verdictCounts:verdictCounts, topGaps:topGaps, catRollup:catRollup};
})()
};
overlayShowResults(result);
}

function overlayResetToUpload(){
overlayShowState('upload');
const fi = document.getElementById('overlay-file-input');
if(fi) fi.value = '';
}

function setupOverlayView(){
const dropzone = document.getElementById('overlay-dropzone');
const fileInput = document.getElementById('overlay-file-input');
if(dropzone && fileInput){
dropzone.addEventListener('click', function(){ fileInput.click(); });
dropzone.addEventListener('dragover', function(e){ e.preventDefault(); dropzone.classList.add('dragover'); });
dropzone.addEventListener('dragleave', function(){ dropzone.classList.remove('dragover'); });
dropzone.addEventListener('drop', function(e){
e.preventDefault();
dropzone.classList.remove('dragover');
const files = e.dataTransfer.files;
if(files.length > 0) overlayHandleFile(files[0]);
});
fileInput.addEventListener('change', function(){
if(fileInput.files.length > 0) overlayHandleFile(fileInput.files[0]);
});
}
document.querySelectorAll('.overlay-sample').forEach(function(btn){
btn.addEventListener('click', function(){ overlayLoadSample(btn.dataset.sample); });
});
const resetBtn = document.getElementById('overlay-reset');
if(resetBtn) resetBtn.addEventListener('click', overlayResetToUpload);
const backBtn = document.getElementById('overlay-redirect-back');
if(backBtn) backBtn.addEventListener('click', overlayResetToUpload);
}

function overlayHandleFile(file){
const reader = new FileReader();
reader.onload = function(e){
const text = e.target.result;
const parsed = overlayParseCSV(text);
overlayShowState('analyzing');
const stepsEl = document.getElementById('overlay-analyzing-steps');
const steps = OVERLAY_STEPS_LIGHT;
stepsEl.innerHTML = steps.map(function(s){return '<div class="overlay-analyzing-step"><span class="step-bullet">•</span>' + s + '</div>';}).join('');
const stepEls = stepsEl.querySelectorAll('.overlay-analyzing-step');
const stepDelay = 180;
stepEls.forEach(function(el, i){
setTimeout(function(){ el.classList.add('show'); }, 40 + i * stepDelay);
setTimeout(function(){ el.classList.add('done'); el.querySelector('.step-bullet').outerHTML = '<span class="step-check">\u2713</span>'; }, 40 + i * stepDelay + 130);
});
setTimeout(function(){ overlayRunAnalysis(file.name, parsed); }, 40 + stepEls.length * stepDelay + 120);
};
reader.readAsText(file);
}

// === LLM data reader — routes the drop through /api/analyze, falls back to the deterministic overlay ===
function overlayBuildRegistries(){
try{
return {
dimensions: RB_FIELDS.dimensions.map(function(d){return {key:d.key,label:d.label,type:d.type};}),
measures: RB_FIELDS.measures.map(function(m){return {key:m.key,label:m.label,type:m.type,unit:m.unit||''};}),
viz: VIZ_TYPES.map(function(v){return v.key;})
};
}catch(e){ return {}; }
}

function overlayRunAnalysis(filename, parsed){
// Try the LLM reader; if the engine/key isn't there (503/502/offline/timeout), run the deterministic overlay.
var ctrl = (typeof AbortController!=='undefined') ? new AbortController() : null;
var fellBack = false;
var timer = setTimeout(function(){ if(ctrl) ctrl.abort(); }, 45000);
function fallback(){ if(fellBack) return; fellBack = true; clearTimeout(timer); overlayProcessRealFile(filename, parsed); }
try{
fetch('/api/analyze', {
method:'POST', headers:{'Content-Type':'application/json'},
body: JSON.stringify({ filename:filename, header:parsed.columns, rows:parsed.rows, full:true, registries: overlayBuildRegistries() }),
signal: ctrl ? ctrl.signal : undefined
}).then(function(r){ return r.ok ? r.json() : Promise.reject(new Error('status '+r.status)); })
.then(function(result){
clearTimeout(timer);
if(!result || result.error){ fallback(); return; }
try{ overlayRenderLLM(result, filename, parsed); }
catch(e){ console.error('reader render failed', e); fallback(); }
})
.catch(function(){ fallback(); });
}catch(e){ fallback(); }
}

function overlayReaderEsc(s){ return String(s==null?'':s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c];}); }

function overlayFindingCard(f){
var pri = f.priority || 'neutral';
var tag = f.tag || (pri==='high'?'Action required':pri==='positive'?'Strength':pri==='caution'?'Watchlist':'Observation');
return '<div class="overlay-wp-finding priority-'+pri+'">'+
'<div class="overlay-wp-finding-head"><div class="overlay-wp-finding-title">'+overlayReaderEsc(f.strong)+'</div><span class="overlay-wp-finding-tag">'+tag+'</span></div>'+
'<div class="overlay-wp-finding-body">'+overlayReaderEsc(f.rest)+'</div></div>';
}

function overlaySpecToState(spec){
spec = spec || {};
return { rows: spec.rows||[], columns: spec.columns||[], filters: spec.filters||[], measures: spec.measures||[],
viz: spec.viz||'table', timeInterval: spec.timeInterval||'single', calculated: [], sortBy: {}, tableSort:{col:null,dir:null}, chartZoom:1 };
}

function overlayColIsNumeric(rows, idx){
var n=0, ok=0;
for(var i=0;i<rows.length && i<60;i++){ var v=(rows[i][idx]==null?'':String(rows[i][idx])).trim(); if(v==='') continue; n++; if(/^-?\$?\d[\d,]*\.?\d*%?$/.test(v)) ok++; }
return n>0 && (ok/n)>=0.8;
}

// Aggregate the upload's OWN numeric columns into um_ measures at the category|subch|division
// grain the Report Builder understands — so auto-built cards show the real uploaded numbers
// (computeUserMeasure sums the cells by whichever dimension a card breaks on).
function overlayBuildUmMeasures(parsed, result, filename){
var cols = parsed.columns, data = parsed.rows;
var roles = {}; try{ roles = overlayDetectRoles(cols) || {}; }catch(e){ roles = {}; }
var colIdx = {}; Object.keys(roles).forEach(function(idx){ colIdx[roles[idx]] = parseInt(idx,10); });
var hasCat = colIdx.category!==undefined, hasSub = colIdx.subch!==undefined, hasDiv = (colIdx.division!==undefined || colIdx.state!==undefined);
if(!(hasCat||hasSub||hasDiv)) return null;   // nothing to break a card by
var dimCols = {}; ['category','subch','division','state','region','territory_id','zip','account_class','channel'].forEach(function(r){ if(colIdx[r]!==undefined) dimCols[colIdx[r]]=true; });
// measure columns: prefer the LLM's chosen numeric columns, else any numeric non-dimension column
var measureCols = [];
(result.measures||[]).forEach(function(m){ var i=cols.indexOf(String(m.column||'').toLowerCase()); if(i>=0 && !dimCols[i] && overlayColIsNumeric(data,i) && measureCols.indexOf(i)<0) measureCols.push(i); });
if(!measureCols.length){ cols.forEach(function(c,i){ if(!dimCols[i] && overlayColIsNumeric(data,i)) measureCols.push(i); }); }
measureCols = measureCols.slice(0,4);
if(!measureCols.length) return null;
var grains=[]; if(hasCat)grains.push('category'); if(hasSub)grains.push('subch'); if(hasDiv)grains.push('division');
// census-division display name -> Report Builder dimension value key (so rows=['division'] matches)
var DIV_KEY={'New England':'new_england','Mid-Atlantic':'mid_atlantic','Mid Atlantic':'mid_atlantic','South Atlantic':'south_atlantic','East North Central':'e_n_central','West North Central':'w_n_central','East South Central':'e_s_central','West South Central':'w_s_central','Mountain':'mountain','Pacific':'pacific'};
var num = function(s){ var v=parseFloat(String(s==null?'':s).replace(/[,$%]/g,'')); return isNaN(v)?0:v; };
var cellsByCol={}, totals={}; measureCols.forEach(function(i){ cellsByCol[i]={}; totals[i]=0; });
data.forEach(function(row){
var cat = hasCat ? (overlayNormalizeCategory(row[colIdx.category])||'unknown') : 'unknown';
var sub = hasSub ? (String(row[colIdx.subch]||'').trim()||'unknown') : 'all';
var div='';
if(colIdx.division!==undefined) div = String(row[colIdx.division]||'').trim();
if(!div && colIdx.state!==undefined){ var st=String(row[colIdx.state]||'').trim().toUpperCase(); div=(typeof STATE_TO_DIVISION!=='undefined' && STATE_TO_DIVISION[st])||''; }
if(!div) div='National';
div = DIV_KEY[div] || div;
var key=cat+'|'+sub+'|'+div;
measureCols.forEach(function(i){ var v=num(row[i]); if(v){ cellsByCol[i][key]=(cellsByCol[i][key]||0)+v; totals[i]+=v; } });
});
var titleCase=function(s){ return s.replace(/[_\-]+/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();}); };
var measures = measureCols.map(function(i){
return { key:'um_'+cols[i].replace(/[^a-z0-9]+/gi,'_')+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),
label: titleCase(cols[i]), unit:'', type:'number', signed:false, plus:false, grains:grains.slice(),
source:{file:filename||'upload', column:cols[i], uploadedAt:Date.now()},
cells:cellsByCol[i], total:totals[i], cellCount:Object.keys(cellsByCol[i]).length };
}).filter(function(m){ return m.cellCount>0; });
if(!measures.length) return null;
return { measures:measures, primaryDim: hasDiv?'division':(hasCat?'category':'subch') };
}

function overlayAutoBuildDashboard(reports, filename, parsed, result){
// Prefer REAL data-backed cards built from the upload's own numbers (um_ measures).
var um=null; try{ um = overlayBuildUmMeasures(parsed, result, filename); }catch(e){ um=null; }
if(um && um.measures.length){
try{ userMeasuresWrite(userMeasuresLoad().concat(um.measures)); }catch(e){}
var DLABEL={category:'category',subch:'sub-channel',division:'census division'};
var dimLabel=DLABEL[um.primaryDim]||um.primaryDim;
var cards=[];
um.measures.slice(0,3).forEach(function(m){
cards.push({ id:rbGenId(), name:m.label+' by '+dimLabel, vizType:'hbar', createdAt:Date.now(), autoPinned:true, readerGenerated:true, sourceFile:filename,
state: overlaySpecToState({rows:[um.primaryDim], columns:[], measures:[m.key], filters:[], viz:'hbar'}) });
});
if(um.measures.length>1){
cards.push({ id:rbGenId(), name:'All measures by '+dimLabel, vizType:'table', createdAt:Date.now(), autoPinned:true, readerGenerated:true, sourceFile:filename,
state: overlaySpecToState({rows:[um.primaryDim], columns:[], measures:um.measures.map(function(m){return m.key;}), filters:[], viz:'table'}) });
}
try{ var keep=mydashLoadRaw().filter(function(d){ return !(d.readerGenerated && d.sourceFile===filename); }); mydashWriteRaw(cards.concat(keep)); }catch(e){ return 0; }
return cards.length;
}
// Fallback: structural cards from the LLM specs (render via the RB model; may be empty until backed).
if(!reports || !reports.length) return 0;
var fcards = reports.map(function(rep){ var st=overlaySpecToState(rep.spec); return { id:rbGenId(), name:rep.name||'Untitled report', state:st, vizType:st.viz, createdAt:Date.now(), autoPinned:true, readerGenerated:true, sourceFile:filename }; });
try{ mydashWriteRaw(mydashLoadRaw().concat(fcards)); }catch(e){ return 0; }
return fcards.length;
}

function overlayRenderLLM(result, filename, parsed){
overlayShowState('results');
var id = result.identity||{}, trust = result.trust||{}, esc = overlayReaderEsc;
var set = function(elId, html){ var el=document.getElementById(elId); if(el) el.innerHTML = html; };
var setText = function(elId, t){ var el=document.getElementById(elId); if(el) el.textContent = t; };
var VLABEL = {'bev-alc':'Beverage Alcohol','hemp':'Hemp','cannabis':'Cannabis','cpg':'Broader CPG','supplemental':'Supplemental (census/panel)','unknown':'Unclassified'};

setText('overlay-wp-title', 'First read — ' + (filename||'your data'));
setText('overlay-wp-subtitle', (VLABEL[id.vertical]||'Dataset') + (id.grain? ' · ' + id.grain : '') + (id.time_span? ' · ' + id.time_span : ''));
setText('overlay-wp-source', filename||'—');
setText('overlay-wp-date', new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}));
var confEl = document.getElementById('overlay-wp-confidence');
if(confEl){ var c=(id.confidence||'—'); confEl.textContent = c.charAt(0).toUpperCase()+c.slice(1);
confEl.style.color = c==='high'?'#0d6e4a':c==='medium'?'#92590f':'#a83323'; }

// 1. What is this & can I trust it
set('overlay-wp-exec', '<p>'+esc(id.summary)+'</p>' + (trust.assessment? '<p>'+esc(trust.assessment)+'</p>' : ''));

// 2. Headline KPIs → exec stats
set('overlay-wp-exec-stats', (result.kpis||[]).map(function(k){
return '<div class="overlay-wp-exec-stat"><div class="overlay-wp-exec-stat-value">'+esc(k.value)+(k.unit?' <span style="font-size:.55em;opacity:.65">'+esc(k.unit)+'</span>':'')+'</div><div class="overlay-wp-exec-stat-label">'+esc(k.label)+'</div></div>';
}).join(''));

// Justification of measures + dimensions → context prose
var dims = (result.dimensions||[]).map(function(d){return '<li><strong>'+esc(d.column)+'</strong> ('+esc(d.role||'dimension')+') — '+esc(d.why)+'</li>';}).join('');
var meas = (result.measures||[]).map(function(m){return '<li><strong>'+esc(m.column)+'</strong> ('+esc(m.agg||'measure')+') — '+esc(m.why)+'</li>';}).join('');
set('overlay-wp-context-prose', '<strong>Why these dimensions</strong><ul>'+dims+'</ul><strong>Why these measures</strong><ul>'+meas+'</ul>');

// Trust flags → detect grid
var flags = (trust.flags||[]);
set('overlay-detect-grid', flags.length ? flags.map(function(fl){
return '<div class="overlay-detect-card"><div class="overlay-detect-card-label">'+esc(String(fl.severity||'note')).toUpperCase()+'</div><div class="overlay-detect-card-value">'+esc(fl.issue)+'</div><div class="overlay-detect-card-sub">'+esc((fl.columns||[]).join(', '))+'</div></div>';
}).join('') : '<div class="overlay-detect-card"><div class="overlay-detect-card-value">No data-quality flags raised.</div></div>');

// alignment card → profile summary
var prof = result._profile||{};
set('overlay-align-card', '<div class="overlay-align-row"><div class="overlay-align-label">Rows × columns</div><div class="overlay-align-value">'+(prof.row_count||0).toLocaleString()+' × '+(prof.column_count||0)+'</div></div>');

// 3. Anomalies + findings → findings list
setText('overlay-wp-findings-intro', 'What stands out on a first pass, in priority order.');
set('overlay-findings', (result.anomalies||[]).concat(result.findings||[]).map(overlayFindingCard).join(''));

// Auto-build curated dashboard + suggested questions → output section
var rb = result.report_builder||{};
var built = (rb.fits ? overlayAutoBuildDashboard(rb.reports, filename, parsed, result) : 0);
var sq = (result.suggested_questions||[]).map(function(q){return '<li>'+esc(q)+'</li>';}).join('');
var outHtml = '';
if(built>0){
outHtml += '<div style="margin:0 0 14px;padding:12px 14px;border:1px solid #cfe6d6;background:#f1f8f3;border-radius:8px;">'+
'<strong>✓ Built '+built+' report'+(built===1?'':'s')+' into your curated dashboard.</strong> '+
'<button class="overlay-result-btn" id="overlay-open-mydash" style="margin-left:8px;">Open curated dashboard →</button></div>';
outHtml += '<ul>'+(rb.reports||[]).map(function(r){return '<li><strong>'+esc(r.name)+'</strong> — '+esc(r.why)+'</li>';}).join('')+'</ul>';
} else if(rb.reason){
outHtml += '<p class="overlay-wp-prose"><em>Report Builder: '+esc(rb.reason)+' — the read above stands on its own for this dataset.</em></p>';
}
if(sq) outHtml += '<div class="overlay-wp-prose" style="margin-top:10px;"><strong>Questions worth asking next</strong><ul>'+sq+'</ul></div>';
setText('overlay-wp-output-intro', built>0 ? 'Reports built from this dataset:' : 'Next steps');
set('overlay-output', outHtml);

// blank the sections the deterministic flow uses that don't apply here
set('overlay-wp-recs',''); set('overlay-wp-methodology','');
var ap = document.getElementById('overlay-wp-appendix-charts'); if(ap) ap.innerHTML='';
var apIntro = document.getElementById('overlay-wp-appendix-intro'); if(apIntro) apIntro.innerHTML='';
var saveCard = document.getElementById('overlay-wp-save-card'); if(saveCard) saveCard.style.display='none';

var openBtn = document.getElementById('overlay-open-mydash');
if(openBtn) openBtn.addEventListener('click', function(){
try{ if(typeof dashSetActive==='function') dashSetActive('mydash'); }catch(e){}
var nav = document.querySelector('[data-view="mydashboard"]');
if(nav){ nav.click(); } else if(typeof renderMyDashboard==='function'){ renderMyDashboard(); }
});
}

// === AI brief drill-through provenance ===
// Clicking any <strong data-drill="..."> in an AI brief navigates to the source view with filter pre-set.
// Filter format depends on view: for headroom, "cat|channel|subch|period|scope"; for others, just view id.
function handleDrillClick(e){
const drill = e.target.closest('strong[data-drill]');
if(!drill) return;
e.stopPropagation();
e.preventDefault();
const target = drill.dataset.drill;
const cut = drill.dataset.drillCut || '';
// If headroom drill, parse cut and apply
if(target === 'headroom' && cut){
const parts = cut.split('|');
if(parts.length >= 5 && typeof HR_STATE !== 'undefined'){
HR_STATE.cat = parts[0];
HR_STATE.channel = parts[1];
HR_STATE.subch = parts[2];
HR_STATE.period = parts[3];
HR_STATE.scope = parts[4];
}
}
// Navigate
const navLink = document.querySelector('.nav-subitem[data-view="'+target+'"]');
if(navLink) navLink.click();
}
document.addEventListener('click', handleDrillClick, true);

// === Action layer — contextual recommendations + queue ===
// Queue persisted in localStorage so the demo can show actions surviving refresh
let ACTION_QUEUE = [];
try { ACTION_QUEUE = JSON.parse(localStorage.getItem('sipsourceActionQueue') || '[]'); } catch(e){ ACTION_QUEUE = []; }
function saveActionQueue(){ try { localStorage.setItem('sipsourceActionQueue', JSON.stringify(ACTION_QUEUE)); } catch(e){} }
function actionInQueue(id){ return ACTION_QUEUE.some(function(a){ return a.id === id; }); }
function addToQueue(action){
if(actionInQueue(action.id)) return false;
ACTION_QUEUE.push(Object.assign({}, action, {status:'open', addedAt:Date.now()}));
saveActionQueue();
return true;
}
function removeFromQueue(id){
ACTION_QUEUE = ACTION_QUEUE.filter(function(a){ return a.id !== id; });
saveActionQueue();
}
function toggleQueueStatus(id){
ACTION_QUEUE.forEach(function(a){
if(a.id === id) a.status = a.status === 'done' ? 'open' : 'done';
});
saveActionQueue();
}

function getCatName(catKey){
const found = (typeof HEADROOM_CATEGORIES !== 'undefined') ? HEADROOM_CATEGORIES.find(function(c){return c.k===catKey;}) : null;
return found ? found.n : catKey;
}

// Generate actions from headroom state — the most data-driven generator
function generateHeadroomActions(){
if(typeof HR_STATE === 'undefined') return [];
const state = HR_STATE;
const periodName = ({r12:'R12',cytd:'CYTD',r3:'R3',cm:'CM'})[state.period] || state.period;
const scopeForActions = (state.scope === 'mybook' || state.scope === 'overlay') ? 'mybook' : 'industry';
const scopeLbl = scopeForActions === 'mybook' ? 'my book' : 'industry';

// Generate sub-segment rows
let rows = [];
if(state.channel === 'both'){
const onC = buildHeadroomCurve(state.cat,'onprem','All on-prem',state.period,scopeForActions);
const offC = buildHeadroomCurve(state.cat,'offprem','All off-prem',state.period,scopeForActions);
rows = [
{label:'On-premise', distGap:onC.distGap, velGap:onC.velGap, bothGap:onC.bothGap, headroom:onC.headroom, channel:'onprem', subch:'All on-prem'},
{label:'Off-premise', distGap:offC.distGap, velGap:offC.velGap, bothGap:offC.bothGap, headroom:offC.headroom, channel:'offprem', subch:'All off-prem'}
];
}else if(state.subch === 'All on-prem' || state.subch === 'All off-prem'){
const subchs = HEADROOM_SUBCH[state.channel].slice(1);
rows = subchs.map(function(sc){
const c = buildHeadroomCurve(state.cat, state.channel, sc, state.period, scopeForActions);
return {label:sc, distGap:c.distGap, velGap:c.velGap, bothGap:c.bothGap, headroom:c.headroom, channel:state.channel, subch:sc};
});
}else{
const c = buildHeadroomCurve(state.cat, state.channel, state.subch, state.period, scopeForActions);
const classes = [
{lbl:'A-class accounts', distMul:1.16, velMul:1.10},
{lbl:'B-class accounts', distMul:1.04, velMul:1.02},
{lbl:'C-class accounts', distMul:0.85, velMul:0.90},
{lbl:'D-class accounts', distMul:0.55, velMul:0.78}
];
rows = classes.map(function(cls){
const dr = Math.min(0.97, c.distRate * cls.distMul);
const vr = Math.min(0.95, c.velRatio * cls.velMul);
return {
label: cls.lbl,
distGap: vr*(1-dr)*100,
velGap: dr*(1-vr)*100,
bothGap: (1-dr)*(1-vr)*100,
headroom: (1-dr*vr)*100,
channel: state.channel, subch: state.subch
};
});
}

rows.sort(function(a,b){ return b.headroom - a.headroom; });
const topRows = rows.slice(0, 5);

const catName = getCatName(state.cat);
const actions = topRows.map(function(row, i){
let actionType, title, owner, typeLbl;
const isMyBookCut = scopeForActions === 'mybook';

if(row.distGap > row.velGap * 1.25){
actionType = 'close-distribution';
typeLbl = 'Close distribution';
const accts = Math.round(row.distGap * 32 + 15);
title = (isMyBookCut ? 'Open ~' : 'Activate ~') + accts + ' ' + row.label.toLowerCase() + ' accounts not yet depleting ' + catName.toLowerCase();
owner = state.channel === 'onprem' ? 'On-prem team' : (state.channel === 'offprem' ? 'Chain team' : 'Field rep');
}else if(row.velGap > row.distGap * 1.25){
actionType = 'lift-velocity';
typeLbl = 'Lift velocity';
const accts = Math.round(row.velGap * 22 + 28);
title = 'Lift ~' + accts + ' ' + row.label.toLowerCase() + ' ' + catName.toLowerCase() + ' accounts performing below P75 velocity';
owner = 'Field rep';
}else{
actionType = 'multi-lever';
typeLbl = 'Multi-lever';
const accts = Math.round(row.bothGap * 18 + 12);
title = 'Multi-lever play on ' + row.label.toLowerCase() + ' — structural ' + catName.toLowerCase() + ' gap on both axes (~' + accts + ' high-leverage targets)';
owner = 'Channel director';
}

// Impact tier — derived from headroom magnitude AND rank within the current cut
const tier = (row.headroom >= 55 || i === 0) ? 'High' : (row.headroom >= 28 ? 'Medium' : 'Low');
const tierRank = tier === 'High' ? 3 : (tier === 'Medium' ? 2 : 1);
const confidence = row.headroom >= 55 ? 'High' : (row.headroom >= 28 ? 'Medium' : 'Low');

return {
id: 'headroom-' + state.cat + '-' + row.channel + '-' + row.subch + '-' + actionType,
sourceView: 'headroom',
sourceLabel: 'Distribution &amp; velocity headroom',
title: title,
impactTier: tier,
impactRank: tierRank,
headroomPt: row.headroom,
owner: owner,
confidence: confidence,
typeLabel: typeLbl,
sourceCut: catName + ' &middot; ' + row.label + ' &middot; ' + periodName + ' &middot; ' + scopeLbl,
applyFilter: { cat: state.cat, channel: row.channel, subch: row.subch, period: state.period, scope: state.scope }
};
});

return actions;
}

