// Decorate static actions with sourceView and confidence labels
Object.keys(STATIC_VIEW_ACTIONS).forEach(function(view){
const viewLabels = {onprem:'On-premise', offprem:'Off-premise', chains:'Chain accounts', anchor:'Anchor SKU dependency', demographics:'Demographics', leadlag:'Geographic lead-lag'};
STATIC_VIEW_ACTIONS[view].forEach(function(a){
a.sourceView = view;
a.sourceLabel = viewLabels[view] || view;
});
});

function getActionsForView(viewId){
if(viewId === 'headroom') return generateHeadroomActions();
return STATIC_VIEW_ACTIONS[viewId] || [];
}

function renderActionSurface(containerEl, viewId){
const actions = getActionsForView(viewId);
if(!actions || actions.length === 0){
containerEl.innerHTML = '';
return;
}
const highCount = actions.filter(function(a){ return a.impactTier === 'High'; }).length;
const top = actions[0];
const rest = actions.slice(1);

function renderItem(a, isTop){
const queued = actionInQueue(a.id);
const tierLbl = (a.impactTier || 'Medium');
const headroomBadge = a.headroomPt ? '<span class="action-pill action-pill-headroom">+'+Math.round(a.headroomPt)+'pt headroom</span>' : '';
return '<div class="action-item'+(isTop?' action-item-top':'')+'">'+
'<div class="action-item-pills">'+
'<span class="action-pill action-pill-impact action-pill-tier-'+tierLbl.toLowerCase()+'">'+tierLbl+' impact</span>'+
'<span class="action-pill action-pill-confidence '+a.confidence.toLowerCase()+'">'+a.confidence+' confidence</span>'+
'<span class="action-pill action-pill-type">'+a.typeLabel+'</span>'+
headroomBadge+
'</div>'+
'<div class="action-item-title">'+a.title+'</div>'+
'<div class="action-item-meta"><strong>Owner:</strong> '+a.owner+' &middot; <strong>Source:</strong> '+a.sourceCut+'</div>'+
'<div class="action-item-buttons">'+
'<button class="action-btn action-btn-add'+(queued?' added':'')+'" data-action-id="'+a.id+'">'+(queued?'✓ In queue':'+ Add to queue')+'</button>'+
(a.applyFilter?'<button class="action-btn action-btn-open" data-action-apply="'+a.id+'">Open this cut →</button>':'')+
'</div>'+
'</div>';
}

let html = '<div class="action-card">'+
'<div class="action-card-head">'+
'<span class="action-card-title"><span class="action-card-title-icon">▸</span>Recommended actions for this cut</span>'+
'<span class="action-card-count">'+actions.length+' actions · '+highCount+' high-impact</span>'+
'</div>'+
'<div class="action-card-sub">Ranked by impact tier and underlying headroom magnitude. Recommendations are generated from the data in this view — sub-segments with the biggest headroom drive the top of the list.</div>'+
'<div class="action-list">'+
renderItem(top, true);

if(rest.length > 0){
html += '<button class="action-expand-btn" data-action-expand>▼ Show '+rest.length+' more actions</button>'+
'<div class="action-list-rest" style="display:none;">'+
rest.map(function(a){return renderItem(a, false);}).join('')+
'</div>';
}
html += '</div></div>';

containerEl.innerHTML = html;
wireActionSurface(containerEl);
}

function wireActionSurface(containerEl){
containerEl.querySelectorAll('.action-btn-add').forEach(function(btn){
btn.addEventListener('click', function(){
const id = btn.dataset.actionId;
const allActions = Object.keys(STATIC_VIEW_ACTIONS).reduce(function(arr,k){ return arr.concat(STATIC_VIEW_ACTIONS[k]); }, generateHeadroomActions());
const action = allActions.find(function(a){ return a.id === id; });
if(action && addToQueue(action)){
btn.textContent = '✓ In queue';
btn.classList.add('added');
showActionToast('Added to your queue · '+ACTION_QUEUE.length+' action'+(ACTION_QUEUE.length===1?'':'s')+' total');
}
});
});
containerEl.querySelectorAll('[data-action-apply]').forEach(function(btn){
btn.addEventListener('click', function(){
const id = btn.dataset.actionApply;
const actions = generateHeadroomActions();
const action = actions.find(function(a){ return a.id === id; });
if(action && action.applyFilter){
const f = action.applyFilter;
HR_STATE.cat = f.cat; HR_STATE.channel = f.channel; HR_STATE.subch = f.subch;
HR_STATE.period = f.period; HR_STATE.scope = f.scope;
renderHeadroom();
}
});
});
const expandBtn = containerEl.querySelector('[data-action-expand]');
if(expandBtn){
expandBtn.addEventListener('click', function(){
const rest = containerEl.querySelector('.action-list-rest');
const isHidden = rest.style.display === 'none';
rest.style.display = isHidden ? 'flex' : 'none';
expandBtn.textContent = isHidden ? '▲ Collapse' : ('▼ Show '+rest.children.length+' more actions');
});
}
}

// ===== uiBtn: the one global way to emit a button. Keeps every surface consistent. =====
// opts: {label, icon, intent:'ghost'|'primary'|'subtle'|'icon'|'toggle', size:'sm', block, on, disabled, id, title, data:{k:v}, className, attrs}
function uiBtn(o){ o=o||{};
const cls=['ui-btn']; const it=o.intent||'ghost'; if(it&&it!=='base') cls.push('ui-btn--'+it); if(o.size) cls.push('ui-btn--'+o.size); if(o.block) cls.push('ui-btn--block'); if(o.on) cls.push('on'); if(o.className) cls.push(o.className);
let attrs=''; if(o.id) attrs+=' id="'+o.id+'"'; if(o.title) attrs+=' title="'+o.title+'"'; if(o.disabled) attrs+=' disabled';
if(o.data){ for(const k in o.data){ if(Object.prototype.hasOwnProperty.call(o.data,k)) attrs+=' data-'+k+'="'+o.data[k]+'"'; } }
if(o.attrs) attrs+=' '+o.attrs;
const ic=o.icon?('<span class="ui-btn-ic">'+o.icon+'</span>'):'';
return '<button class="'+cls.join(' ')+'"'+attrs+'>'+ic+(o.label!=null?o.label:'')+'</button>';
}
// ===== Bidirectional flow: send a report cut into a PPTX Studio deck as a slide =====
function appAtlasFiltersToBuilder(list){ const byDim={}; (list||[]).forEach(function(f){ (byDim[f.dim]=byDim[f.dim]||[]).push(f.val); }); return Object.keys(byDim).map(function(d){ return {field:d, op:'in', values:byDim[d]}; }); }
function appAtlasCardEntry(rep){
const measMap={vol_growth:'volume_growth',rev_growth:'revenue_growth',pod_growth:'pod_growth',velocity:'velocity',premium:'premium_idx',activation:'activation',pod_eff:'pod_efficiency',share:'share_pct'};
const meas=measMap[QR_STATE.measure]||'volume_growth';
const all=(QR_STATE.filters||[]).concat(rep.filters||[]);
const dimLabel=(qrDimDef(rep.dim)||{}).label||rep.dim; const measLabel=(QR_MEASURES[QR_STATE.measure]||{}).label||'Measure';
return { name: measLabel+' by '+dimLabel, state:{ rows:[rep.dim], columns:[], measures:[meas], filters:appAtlasFiltersToBuilder(all), viz:'bar', periodWindow:'r12', periodGrain:'month', refLines:[] } };
}
function appBuilderEntry(){
const rows=(RB_STATE.rows||[]).slice(), cols=(RB_STATE.columns||[]).slice(), meas=(RB_STATE.measures||[]).slice();
if(!rows.length && !meas.length) return null;
let nm=(RB_STATE.name&&String(RB_STATE.name).trim())||'';
if(!nm){ const mk=meas.length?(typeof meas[0]==='string'?meas[0]:meas[0].key):null; const mL=mk&&typeof qbrMeasureLabel==='function'?qbrMeasureLabel(mk):''; const dL=rows.length&&typeof qbrDimDef==='function'?((qbrDimDef(rows[0])||{}).label||''):''; const cL=cols.length&&typeof qbrDimDef==='function'?((qbrDimDef(cols[0])||{}).label||''):''; const byL=cL?(dL?(dL+' and '+cL):cL):dL; nm=(mL&&byL)?(mL+' by '+byL):(mL||byL||'Report'); }
return { name:nm, state:{ rows:rows, columns:cols, measures:meas, filters:(RB_STATE.filters||[]).slice(), viz:RB_STATE.viz, periodWindow:RB_STATE.periodWindow, periodGrain:RB_STATE.periodGrain, refLines:(typeof rbExportRefLines==='function'?rbExportRefLines():[]), vizFormat:_qbrVfSnapshot(), state:_qbrCaptureBuilderState() } };
}
function appReportToDeck(entry){ if(!entry){ if(typeof showActionToast==='function') showActionToast('Build a report first'); return; }
if(typeof qbrInit==='function') qbrInit();
if(typeof qbrDecksInit==='function') qbrDecksInit();
if(typeof qbrSyncActiveDeck==='function') qbrSyncActiveDeck();
var _nDecks=(QBR_DECKS&&QBR_DECKS.length)||0;
if(_nDecks<=1){ appInsertIntoDeck(entry, _nDecks===0?'new':'first'); return; } // one-click into the only/active deck
appOpenDeckPicker(entry); }
function appInsertIntoDeck(entry, mode, index){
if(typeof qbrInit==='function') qbrInit();
if(typeof qbrDecksInit==='function') qbrDecksInit();
if(typeof qbrSyncActiveDeck==='function') qbrSyncActiveDeck();
if(mode==='new'){ qbrAddDeck(); } else if(mode==='existing'){ qbrSwitchDeck(index); }
const deckName=(QBR_STATE&&QBR_STATE.name)||'deck';
qbrInsertSelectedReports([entry], true);
if(typeof qbrSyncActiveDeck==='function') qbrSyncActiveDeck();
if(typeof showActionToast==='function') showActionToast('Added \u201c'+(entry.name||'report')+'\u201d to '+deckName+' \u2014 open PPTX Studio to view');
}
function appOpenDeckPicker(entry){
let ov=document.getElementById('app-deckpick-overlay'); if(ov) ov.remove();
ov=document.createElement('div'); ov.id='app-deckpick-overlay'; ov.className='app-deckpick-overlay';
const esc=(typeof _qbrEsc==='function')?_qbrEsc:function(s){return s;};
const list=QBR_DECKS.map(function(d,i){ const n=(d.slides||[]).length; return '<button class="app-deckpick-item" data-deckidx="'+i+'"><span class="app-deckpick-name">'+esc(d.name||('Deck '+(i+1)))+'</span><span class="app-deckpick-meta">'+n+' slide'+(n===1?'':'s')+'</span></button>'; }).join('');
ov.innerHTML='<div class="app-deckpick-card"><div class="app-deckpick-head"><span>Add \u201c'+esc(entry.name||'report')+'\u201d to a deck</span><button class="qbr-rp-x" id="app-deckpick-x">\u00d7</button></div><div class="app-deckpick-list">'+list+'</div>'+uiBtn({label:'\uff0b Create new deck',intent:'primary',block:true,id:'app-deckpick-new'})+'</div>';
document.body.appendChild(ov);
ov.querySelectorAll('[data-deckidx]').forEach(function(b){ b.addEventListener('click',function(){ const i=parseInt(b.dataset.deckidx,10); ov.remove(); appInsertIntoDeck(entry,'existing',i); }); });
document.getElementById('app-deckpick-new').addEventListener('click',function(){ ov.remove(); appInsertIntoDeck(entry,'new'); });
document.getElementById('app-deckpick-x').addEventListener('click',function(){ ov.remove(); });
ov.addEventListener('mousedown',function(e){ if(e.target===ov) ov.remove(); });
}
function appSyncTopbarHeight(){ try{ const tb=document.querySelector('.top-bar'); if(tb){ const h=tb.offsetHeight; if(h>0) document.documentElement.style.setProperty('--app-topbar-h', h+'px'); } }catch(_){ } }
function appUpdateToolSwitch(id){ const sw=document.getElementById('app-toolswitch'); if(!sw) return; sw.querySelectorAll('[data-toolview]').forEach(function(b){ b.classList.toggle('on', b.dataset.toolview===id); }); }
if(typeof window!=='undefined'){ window.addEventListener('resize', appSyncTopbarHeight); }
function appBuilderToAtlas(){
const rows=(RB_STATE.rows||[]).slice(), cols=(RB_STATE.columns||[]).slice();
const dim=rows[0]||cols[0]||null; const dd=dim?qrDimDef(dim):null;
if(!dd || dd.type==='time'){ if(typeof showActionToast==='function') showActionToast('Add a dimension to Rows to send to Prism'); return; }
const filters=[];
(RB_STATE.filters||[]).forEach(function(f){ const fd=qrDimDef(f.field); if(!fd||fd.type==='time') return; (f.values||[]).forEach(function(v){ const vv=(fd.values||[]).find(function(x){return x.v===v;}); filters.push({dim:f.field, val:v, label:vv?vv.n:v, dimLabel:fd.label}); }); });
const rbMeas=(RB_STATE.measures||[])[0]; const rbMeasKey=rbMeas?(typeof rbMeas==='string'?rbMeas:rbMeas.key):null;
const rev={volume_growth:'vol_growth',revenue_growth:'rev_growth',pod_growth:'pod_growth',velocity:'velocity',premium_idx:'premium',activation:'activation',pod_efficiency:'pod_eff',share_pct:'share'};
if(rbMeasKey && rev[rbMeasKey]) QR_STATE.measure=rev[rbMeasKey];
QR_STATE.reports.push({dim:dim, filters:filters});
if(typeof qrRenderMeasureSeg==='function') qrRenderMeasureSeg();
if(typeof qrRenderCards==='function') qrRenderCards();
if(typeof showActionToast==='function') showActionToast('Added \u201c'+(dd.label||dim)+'\u201d to Prism \u2014 open Prism to view');
}
function showActionToast(msg){
let toast = document.getElementById('action-toast');
if(!toast){
toast = document.createElement('div');
toast.id = 'action-toast';
toast.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--dash-accent,#4E79A7);color:#fff;padding:10px 18px;border-radius:6px;font-size:12.5px;font-weight:500;z-index:1500;box-shadow:0 4px 16px rgba(0,0,0,0.18);opacity:0;transition:opacity 0.2s;';
document.body.appendChild(toast);
}
toast.textContent = msg;
toast.style.opacity = '1';
clearTimeout(toast.hideTimer);
toast.hideTimer = setTimeout(function(){ toast.style.opacity = '0'; }, 2200);
}

