'.hoodie-dlg-btn-cancel{background:#fff;border-color:var(--ui-ghost-bd,#d4d4d8);color:var(--ui-ghost-ink,#3c4043);}',
'.hoodie-dlg-btn-cancel:hover{border-color:var(--ui-ghost-bd-h,#6b7280);background:var(--ui-soft,#f1f2f5);}',
