const distLbl=mine?'MY DISTRIBUTION GAP':'DISTRIBUTION GAP';
const velLbl=mine?'MY VELOCITY GAP':'VELOCITY GAP';
const bothLbl=mine?'MY COMBINED GAP':'COMBINED GAP';
const distSub=mine?'accounts in universe my book does not yet supply':'accounts in universe not depleting';
const velSub=mine?'my depleting accounts below top-quartile velocity':'depleting accounts below top-quartile velocity';
const bothSub=mine?'high-velocity segment cells not yet on my book':'missing distribution × high-achievable cells';
let html='';
html+='<div class="score-card onprem-hero-card">';
html+='<div class="onprem-hero-label">'+distLbl+'</div>';
html+='<div class="onprem-hero-period">'+distSub+'</div>';
html+='<div class="onprem-hero-value">+'+curve.distGap.toFixed(1)+'pt</div>';
html+='<div class="onprem-hero-desc">closing distribution alone unlocks '+curve.distGap.toFixed(1)+' points of headroom — the "add accounts" lever</div>';
html+='</div>';
html+='<div class="score-card onprem-hero-card">';
html+='<div class="onprem-hero-label">'+velLbl+'</div>';
html+='<div class="onprem-hero-period">'+velSub+'</div>';
html+='<div class="onprem-hero-value">+'+curve.velGap.toFixed(1)+'pt</div>';
html+='<div class="onprem-hero-desc">activating existing accounts unlocks '+curve.velGap.toFixed(1)+' points — the "lift what you have" lever</div>';
html+='</div>';
html+='<div class="score-card onprem-hero-card">';
html+='<div class="onprem-hero-label">'+bothLbl+'</div>';
html+='<div class="onprem-hero-period">'+bothSub+'</div>';
html+='<div class="onprem-hero-value">+'+curve.bothGap.toFixed(1)+'pt</div>';
