'Regional Grocery':  {Whiskey:5,  Vodka:-4, Tequila:14, Wine:7,  RTD:8},
'Liquor — Large':    {Whiskey:6,  Vodka:-3, Tequila:18, Wine:2,  RTD:5},
'Liquor — Mid':      {Whiskey:3,  Vodka:-6, Tequila:13, Wine:0,  RTD:4},
