// === Pareto concentration curve ===
function renderChainsPareto(){
const w=360,h=220,padL=42,padR=12,padT=14,padB=34;
function mx(r){return padL+(r-1)/149*(w-padL-padR);}
function my(s){return padT+(100-s)/100*(h-padT-padB);}
let s='<svg viewBox="0 0 '+w+' '+h+'" class="scatter-svg" style="max-width:480px;">';
// Grid
[0,25,50,75,100].forEach(function(g){
s+='<line class="grid-line" x1="'+padL+'" y1="'+my(g)+'" x2="'+(w-padR)+'" y2="'+my(g)+'"/>';
s+='<text class="axis-label" x="'+(padL-6)+'" y="'+(my(g)+3)+'" text-anchor="end">'+g+'%</text>';
});
// X grid + labels
[1,25,50,100,150].forEach(function(r){
s+='<line class="grid-line" x1="'+mx(r)+'" y1="'+padT+'" x2="'+mx(r)+'" y2="'+(h-padB)+'" stroke-opacity="0.4"/>';
s+='<text class="axis-label" x="'+mx(r)+'" y="'+(h-padB+14)+'" text-anchor="middle">'+r+'</text>';
});
// Axes
s+='<line class="axis-line" x1="'+padL+'" y1="'+(h-padB)+'" x2="'+(w-padR)+'" y2="'+(h-padB)+'"/>';
s+='<line class="axis-line" x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(h-padB)+'"/>';
// Axis titles
s+='<text class="axis-label" x="'+(padL+(w-padL-padR)/2)+'" y="'+(h-2)+'" text-anchor="middle" font-weight="500">chain rank (1 = largest)</text>';
s+='<text class="axis-label" x="'+(padL+6)+'" y="'+(padT+10)+'" font-weight="500">cumulative % of chain volume</text>';
// Pareto curve as path
let pathD='M';
CHAIN_PARETO_POINTS.forEach(function(p,i){
pathD+=(i===0?'':'L')+mx(p[0])+','+my(p[1])+' ';
});
s+='<path d="'+pathD+'" fill="none" style="stroke:var(--dash-accent,#4E79A7)" stroke-width="2.5"/>';
// Fill under curve
let fillD=pathD+'L'+mx(150)+','+my(0)+'L'+mx(1)+','+my(0)+'Z';
s+='<path d="'+fillD+'" style="fill:var(--dash-accent,#4E79A7)" fill-opacity="0.08"/>';
// Annotation markers
const milestones=[{r:10,label:'Top 10 → '+Math.round(CHAIN_PARETO_POINTS[9][1])+'%'},
{r:50,label:'Top 50 → '+Math.round(CHAIN_PARETO_POINTS[49][1])+'%'}];
milestones.forEach(function(m){
const px=mx(m.r),py=my(CHAIN_PARETO_POINTS[m.r-1][1]);
s+='<circle cx="'+px+'" cy="'+py+'" r="3.5" style="fill:var(--dash-accent,#4E79A7)"/>';
s+='<text class="axis-label" x="'+(px+6)+'" y="'+(py-4)+'" font-weight="600" style="fill:var(--dash-accent,#4E79A7)">'+m.label+'</text>';
});
s+='</svg>';
document.getElementById('chain-pareto').innerHTML=s;
}

// === Format-level new-item rollout velocity ===
function renderChainsRollout(){
const maxDays=160;
const sorted=CHAIN_FORMATS.slice().sort(function(a,b){return a.rollout-b.rollout;});
let html='';
sorted.forEach(function(f){
const pct=Math.min(100,(f.rollout/maxDays)*100);
const speed=f.rollout<=30?'fast':f.rollout<=70?'mid':'slow';
html+='<div class="newitem-row">';
html+='<div class="newitem-label">'+f.format+'</div>';
html+='<div class="newitem-bar-wrap"><div class="newitem-bar '+speed+'" style="width:'+pct+'%"></div></div>';
html+='<div class="newitem-value">'+f.rollout+'<span class="newitem-suffix"> days</span></div>';
html+='</div>';
});
document.getElementById('chain-rollout').innerHTML=html;
}

