function renderCatman(){
const catSel = document.getElementById('ch-cat');
const cat = catSel ? catSel.value : 'all_spirits';
renderCatmanQuadrant();
renderCatmanAssortment();
renderCatmanDecomp();
renderCatmanIncrementality(cat);
renderCatmanInsights(cat);
}

function renderCatmanQuadrant(){
const el = document.getElementById('catman-quadrant');
if(!el) return;
const W = 760, H = 420, padL = 56, padR = 24, padT = 30, padB = 48;
const innerW = W - padL - padR, innerH = H - padT - padB;
// x = distribution breadth (0-100), y = velocity index (40-180)
const xMin = 30, xMax = 100, yMin = 50, yMax = 180;
const xThresh = 70, yThresh = 110; // quadrant dividers
function xPos(v){ return padL + (v - xMin) / (xMax - xMin) * innerW; }
function yPos(v){ return padT + (1 - (v - yMin) / (yMax - yMin)) * innerH; }
const xDiv = xPos(xThresh), yDiv = yPos(yThresh);
let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" class="catman-quad-svg">';
// Quadrant fills
svg += '<rect x="' + xDiv + '" y="' + padT + '" width="' + (W - padR - xDiv) + '" height="' + (yDiv - padT) + '" fill="#f0f7f3" opacity="0.6"/>';      // high/high — protect
svg += '<rect x="' + padL + '" y="' + padT + '" width="' + (xDiv - padL) + '" height="' + (yDiv - padT) + '" fill="#fdf3e0" opacity="0.6"/>';          // low dist/high vel — expand
svg += '<rect x="' + xDiv + '" y="' + yDiv + '" width="' + (W - padR - xDiv) + '" height="' + (H - padB - yDiv) + '" fill="#fcefe7" opacity="0.55"/>';  // high dist/low vel — rationalize
svg += '<rect x="' + padL + '" y="' + yDiv + '" width="' + (xDiv - padL) + '" height="' + (H - padB - yDiv) + '" fill="#f5f5f7" opacity="0.6"/>';      // low/low — deprioritize
// Quadrant labels
svg += '<text x="' + (W - padR - 8) + '" y="' + (padT + 15) + '" text-anchor="end" font-size="10" font-weight="700" fill="#245d45" letter-spacing="0.04em">PROTECT \u00b7 strong everywhere</text>';
svg += '<text x="' + (padL + 8) + '" y="' + (padT + 15) + '" font-size="10" font-weight="700" fill="#92590f" letter-spacing="0.04em">EXPAND DISTRIBUTION \u00b7 under-placed</text>';
svg += '<text x="' + (W - padR - 8) + '" y="' + (H - padB - 8) + '" text-anchor="end" font-size="10" font-weight="700" fill="#b8402b" letter-spacing="0.04em">RATIONALIZE \u00b7 broad but slow</text>';
svg += '<text x="' + (padL + 8) + '" y="' + (H - padB - 8) + '" font-size="10" font-weight="700" fill="#6b7280" letter-spacing="0.04em">DEPRIORITIZE \u00b7 low/low</text>';
// Divider lines
svg += '<line x1="' + xDiv + '" y1="' + padT + '" x2="' + xDiv + '" y2="' + (H - padB) + '" stroke="#c4c4c8" stroke-width="1" stroke-dasharray="4 3"/>';
svg += '<line x1="' + padL + '" y1="' + yDiv + '" x2="' + (W - padR) + '" y2="' + yDiv + '" stroke="#c4c4c8" stroke-width="1" stroke-dasharray="4 3"/>';
// Axes
svg += '<line x1="' + padL + '" y1="' + (H - padB) + '" x2="' + (W - padR) + '" y2="' + (H - padB) + '" stroke="#3c4043" stroke-width="1"/>';
svg += '<line x1="' + padL + '" y1="' + padT + '" x2="' + padL + '" y2="' + (H - padB) + '" stroke="#3c4043" stroke-width="1"/>';
// Axis labels
svg += '<text x="' + (padL + innerW / 2) + '" y="' + (H - 10) + '" text-anchor="middle" font-size="11" font-weight="600" fill="#3c4043">Distribution breadth (% of format doors carrying the category)</text>';
svg += '<text x="16" y="' + (padT + innerH / 2) + '" text-anchor="middle" font-size="11" font-weight="600" fill="#3c4043" transform="rotate(-90 16,' + (padT + innerH / 2) + ')">Velocity index (100 = all-format avg)</text>';
// X ticks
[30,50,70,90,100].forEach(function(v){ svg += '<text x="' + xPos(v) + '" y="' + (H - padB + 15) + '" text-anchor="middle" font-size="9.5" fill="#6b7280" font-variant-numeric="tabular-nums">' + v + '%</text>'; });
// Y ticks
[60,100,140,180].forEach(function(v){ svg += '<text x="' + (padL - 8) + '" y="' + (yPos(v) + 3) + '" text-anchor="end" font-size="9.5" fill="#6b7280" font-variant-numeric="tabular-nums">' + v + '</text>'; });
// Dots — sized by growth magnitude
CATMAN_FORMATS.forEach(function(f){
const r = 10 + Math.min(8, Math.abs(f.growth) * 0.4);
const x = xPos(f.dist), y = yPos(Math.max(yMin, Math.min(yMax, f.velIdx)));
svg += '<circle cx="' + x + '" cy="' + y + '" r="' + r + '" fill="' + f.color + '" fill-opacity="0.72" stroke="' + f.color + '" stroke-width="2"/>';
svg += '<text x="' + x + '" y="' + (y + 3.5) + '" text-anchor="middle" font-size="9.5" font-weight="700" fill="#fff" style="pointer-events:none;">' + f.abbr + '</text>';
});
svg += '</svg>';
el.innerHTML = svg;
// Quadrant callout — identify the standout opportunity (high velocity, under-distributed)
const expandQuadrant = CATMAN_FORMATS.filter(function(f){ return f.dist < 70 && f.velIdx >= 110; }).sort(function(a,b){ return b.velIdx - a.velIdx; });
const rationalize = CATMAN_FORMATS.filter(function(f){ return f.dist >= 70 && f.velIdx < 110; });
let callout = '<strong>How a category manager reads this:</strong> ';
if(expandQuadrant.length > 0){
const opp = expandQuadrant[0];
callout += '<strong>' + opp.name + '</strong> sits in the expand-distribution quadrant \u2014 velocity index ' + opp.velIdx + ' (well above average) on only ' + opp.dist + '% distribution. The category is pulling hard wherever it\'s placed but isn\'t placed widely enough. This is the highest-leverage authorization argument to bring to a line review: the velocity proof already exists. ';
}
if(rationalize.length > 0){
callout += '<strong>' + rationalize.map(function(f){return f.name;}).join(' and ') + '</strong> ' + (rationalize.length > 1 ? 'are' : 'is') + ' broadly distributed but below-average velocity \u2014 the assortment is carrying weight it hasn\'t earned. These are the delisting candidates that free facings for the expand-quadrant formats.';
}
document.getElementById('catman-quadrant-callout').innerHTML = callout;
}

function renderCatmanAssortment(){
const el = document.getElementById('catman-assortment');
if(!el) return;
const maxSku = Math.max.apply(null, CATMAN_FORMATS.map(function(f){return f.skuIdx;}));
const maxVel = Math.max.apply(null, CATMAN_FORMATS.map(function(f){return f.velPerSku;}));
// Sort by velocity per SKU descending (most efficient first)
const sorted = CATMAN_FORMATS.slice().sort(function(a,b){ return b.velPerSku - a.velPerSku; });
let html = '';
sorted.forEach(function(f){
// Classify assortment efficiency. Online/DTC carries a long tail by design
// (infinite shelf), so it's not "bloat" the way a physical format's tail is.
let tag, tagCls;
if(f.name === 'Online / DTC'){ tag = 'Long tail by design'; tagCls = 'broad'; }
else if(f.velPerSku >= 1.5){ tag = 'Tight & fast'; tagCls = 'tight'; }
else if(f.skuIdx >= 250 || (f.skuIdx >= 150 && f.velPerSku < 0.6)){ tag = 'Over-assorted'; tagCls = 'bloated'; }
else { tag = 'Broad'; tagCls = 'broad'; }
html += '<div class="catman-assort-row">' +
'<span class="catman-assort-name">' + f.name + '</span>' +
'<div class="catman-assort-bars">' +
'<div class="catman-assort-bar-track"><div class="catman-assort-bar-sku" style="width:' + (f.skuIdx / maxSku * 100) + '%;"></div></div>' +
'<div class="catman-assort-bar-track"><div class="catman-assort-bar-vel" style="width:' + (f.velPerSku / maxVel * 100) + '%;"></div></div>' +
'<div class="catman-assort-meta">' + f.skuIdx + ' SKU idx \u00b7 ' + f.velPerSku.toFixed(2) + ' vel/SKU</div>' +
'</div>' +
'<span class="catman-assort-tag ' + tagCls + '">' + tag + '</span>' +
'</div>';
});
html += '<div class="catman-assort-legend">' +
'<span class="catman-assort-legend-item"><span class="catman-assort-legend-swatch" style="background:#6b7280;"></span>SKU count (breadth)</span>' +
'<span class="catman-assort-legend-item"><span class="catman-assort-legend-swatch" style="background:#2e7d57;"></span>velocity per SKU (efficiency)</span>' +
'</div>';
el.innerHTML = html;
// Callout — only physical-shelf formats are rationalization candidates (DTC's tail is by design)
const bloated = sorted.filter(function(f){ return f.name !== 'Online / DTC' && (f.skuIdx >= 250 || (f.skuIdx >= 150 && f.velPerSku < 0.6)); });
const tightest = sorted[0];
let callout = '<strong>The assortment-efficiency trade-off:</strong> <strong>' + tightest.name + '</strong> runs the tightest set \u2014 ' + tightest.velPerSku.toFixed(2) + ' velocity per SKU, the discipline of a curated shelf. ';
if(bloated.length > 0){
callout += '<strong>' + bloated.map(function(f){return f.name;}).join(', ') + '</strong> carr' + (bloated.length > 1 ? 'y' : 'ies') + ' a long tail \u2014 broad SKU counts diluting velocity per facing. For the chain team, these formats are where a SKU-rationalization conversation creates room without losing volume: trim the slowest decile, redeploy the facings to the expand-quadrant categories.';
}
document.getElementById('catman-assortment-callout').innerHTML = callout;
}

function renderCatmanDecomp(){
const el = document.getElementById('catman-decomp');
if(!el) return;
// Sort by total growth descending
const sorted = CATMAN_FORMATS.slice().sort(function(a,b){ return b.growth - a.growth; });
const maxAbs = Math.max.apply(null, CATMAN_FORMATS.map(function(f){ return Math.abs(f.distGrowth) + Math.abs(f.velGrowth); }));
let html = '';
sorted.forEach(function(f){
const totalCls = f.growth >= 0 ? 'pos' : 'neg';
const distW = Math.abs(f.distGrowth) / maxAbs * 100;
const velW = Math.abs(f.velGrowth) / maxAbs * 100;
// Dominant driver tag
let driver;
if(f.growth < 0) driver = 'Losing doors';
else if(f.distGrowth > f.velGrowth * 1.5) driver = 'Distribution-led';
else if(f.velGrowth > f.distGrowth * 1.5) driver = 'Velocity-led';
else driver = 'Balanced';
let barHtml;
if(f.growth < 0){
const negW = (Math.abs(f.distGrowth) + Math.abs(f.velGrowth)) / maxAbs * 100;
barHtml = '<div class="catman-decomp-neg" style="width:' + Math.max(negW, 12) + '%;">' + f.distGrowth + 'pt doors</div>';
}else{
barHtml = '<div class="catman-decomp-dist" style="width:' + Math.max(distW, 6) + '%;">' + (f.distGrowth > 0 ? '+' : '') + f.distGrowth + '</div>' +
'<div class="catman-decomp-vel" style="width:' + Math.max(velW, 6) + '%;">' + (f.velGrowth > 0 ? '+' : '') + f.velGrowth + '</div>';
}
html += '<div class="catman-decomp-row">' +
'<div class="catman-decomp-head">' +
'<span class="catman-decomp-name">' + f.name + ' <span class="catman-decomp-tag">\u00b7 ' + driver + '</span></span>' +
'<span class="catman-decomp-total ' + totalCls + '">' + (f.growth > 0 ? '+' : '') + f.growth + '%</span>' +
'</div>' +
'<div class="catman-decomp-bar">' + barHtml + '</div>' +
'</div>';
});
html += '<div class="catman-decomp-legend">' +
'<span class="catman-decomp-legend-item"><span class="catman-decomp-legend-swatch" style="background:var(--dash-accent,#4E79A7);"></span>distribution growth (more doors)</span>' +
'<span class="catman-decomp-legend-item"><span class="catman-decomp-legend-swatch" style="background:#4cb8a4;"></span>velocity growth (more turns/door)</span>' +
'</div>';
el.innerHTML = html;
// Callout
const distLed = CATMAN_FORMATS.filter(function(f){ return f.growth > 0 && f.distGrowth > f.velGrowth * 1.5; }).sort(function(a,b){return b.distGrowth - a.distGrowth;});
const velLed = CATMAN_FORMATS.filter(function(f){ return f.growth > 0 && f.velGrowth > f.distGrowth * 1.5; }).sort(function(a,b){return b.velGrowth - a.velGrowth;});
let callout = '<strong>Where the growth is actually coming from:</strong> ';
if(distLed.length > 0){
callout += '<strong>' + distLed[0].name + '</strong> is distribution-led (+' + distLed[0].distGrowth + 'pt from new doors) \u2014 the runway is still in placement, and that runway eventually runs out. ';
}
if(velLed.length > 0){
callout += '<strong>' + velLed[0].name + '</strong> is velocity-led (+' + velLed[0].velGrowth + 'pt from deeper turns per existing door) \u2014 a more durable, defensible source of growth since it doesn\'t depend on winning more authorizations. ';
}
callout += 'For the chain team, distribution-led formats are where to push placement now before the runway closes; velocity-led formats are where the product is already proving itself and merit premium-tier breadth.';
document.getElementById('catman-decomp-callout').innerHTML = callout;
}

function renderCatmanIncrementality(cat){
const el = document.getElementById('catman-incrementality');
if(!el) return;
const data = CATMAN_INCREMENTALITY[cat] || CATMAN_INCREMENTALITY.all_spirits;
const tagLabel = {incremental:'Incremental', mixed:'Mixed', cannibalizing:'Cannibalizing', donor:'Donor'};
let html = '';
data.forEach(function(d){
const gCls = d.growth >= 0 ? 'pos' : 'neg';
html += '<div class="catman-incr-row">' +
'<span class="catman-incr-seg">' + d.seg + '</span>' +
'<span class="catman-incr-growth ' + gCls + '">' + (d.growth > 0 ? '+' : '') + d.growth + '%</span>' +
'<div class="catman-incr-detail">' +
'<span class="catman-incr-tag ' + d.type + '">' + tagLabel[d.type] + '</span>' +
'<span class="catman-incr-note">' + d.note + '</span>' +
'</div>' +
'</div>';
});
el.innerHTML = html;
// Callout
const incremental = data.filter(function(d){ return d.type === 'incremental'; });
const cannibalizing = data.filter(function(d){ return d.type === 'cannibalizing'; });
let callout = '<strong>The authorization question a buyer actually cares about:</strong> ';
if(incremental.length > 0){
callout += '<strong>' + incremental.map(function(d){return d.seg;}).join(' and ') + '</strong> ' + (incremental.length > 1 ? 'are' : 'is') + ' growing the category, not reshuffling it \u2014 authorizing ' + (incremental.length > 1 ? 'these' : 'this') + ' grows total category dollars, which is the argument that wins shelf space. ';
}
if(cannibalizing.length > 0){
callout += '<strong>' + cannibalizing.map(function(d){return d.seg;}).join(', ') + '</strong> grow' + (cannibalizing.length === 1 ? 's' : '') + ' by stealing from adjacent segments \u2014 a buyer should weight ' + (cannibalizing.length > 1 ? 'these' : 'this') + ' against the margin of what ' + (cannibalizing.length > 1 ? 'they' : 'it') + ' displaces, not treat the headline growth at face value.';
}else{
callout += 'No pure cannibalizing segments in this cut \u2014 the growth is largely additive to the category.';
}
document.getElementById('catman-incrementality-callout').innerHTML = callout;
}

function renderCatmanInsights(cat){
const el = document.getElementById('catman-insights');
if(!el) return;
const catLabel = {all_spirits:'All spirits', all_wine:'All wine', whiskey:'Whiskey', vodka:'Vodka', tequila:'Tequila', rum:'Rum', rtd:'RTD'}[cat] || 'the category';
// Compute the three headline takeaways from the data
const expandOpp = CATMAN_FORMATS.filter(function(f){ return f.dist < 70 && f.velIdx >= 110; }).sort(function(a,b){return b.velIdx - a.velIdx;})[0];
const rationalize = CATMAN_FORMATS.filter(function(f){ return f.dist >= 70 && f.velIdx < 110; });
const data = CATMAN_INCREMENTALITY[cat] || CATMAN_INCREMENTALITY.all_spirits;
const topIncremental = data.filter(function(d){ return d.type === 'incremental'; }).sort(function(a,b){return b.growth - a.growth;})[0];
const donor = data.filter(function(d){ return d.type === 'donor'; }).sort(function(a,b){return a.growth - b.growth;})[0];
const velLed = CATMAN_FORMATS.filter(function(f){ return f.growth > 0 && f.velGrowth > f.distGrowth * 1.5; }).sort(function(a,b){return b.velGrowth - a.velGrowth;})[0];
let html = '<div class="ki-block-title">Chain-team playbook \u00b7 ' + catLabel + '</div><div class="ki-grid">';
// Item 1: the authorization argument
if(expandOpp && topIncremental){
html += '<div class="ki-item"><div class="ki-item-label">The line-review argument &middot; ' + expandOpp.name + ' &times; ' + topIncremental.seg + '</div>' +
'<div class="ki-item-body">' + expandOpp.name + ' has velocity index ' + expandOpp.velIdx + ' on just ' + expandOpp.dist + '% distribution \u2014 the product pulls but isn\'t placed widely. Pair that with <strong>' + topIncremental.seg + '</strong> (+' + topIncremental.growth + '%, incremental to the category) and you have a clean authorization case: proven velocity, category-expanding, not a zero-sum reshuffle.</div></div>';
}
// Item 2: the rationalization argument
if(rationalize.length > 0){
html += '<div class="ki-item"><div class="ki-item-label">The facings-funding argument &middot; ' + rationalize.map(function(f){return f.name;}).join(' / ') + '</div>' +
'<div class="ki-item-body">' + rationalize.map(function(f){return f.name;}).join(' and ') + ' carr' + (rationalize.length > 1 ? 'y' : 'ies') + ' broad distribution at below-average velocity \u2014 the assortment is paying rent it doesn\'t earn. Trimming the slowest decile here funds the expand-quadrant placements without a net facings increase, which is the version of the ask a buyer can say yes to.</div></div>';
}
// Item 3: durable vs fragile growth
if(velLed){
html += '<div class="ki-item"><div class="ki-item-label">Durable vs fragile growth &middot; ' + velLed.name + '</div>' +
'<div class="ki-item-body">' + velLed.name + '\u2019s growth is velocity-led (+' + velLed.velGrowth + 'pt from deeper turns per door, not new doors) \u2014 the most durable kind, because it doesn\u2019t depend on winning the next authorization. Lead the QBR with this: it\u2019s the format where the product has already won the consumer, so premium-tier breadth is the natural next ask.</div></div>';
}
// Item 4: the donor watch
if(donor){
html += '<div class="ki-item"><div class="ki-item-label">Donor-segment watch &middot; ' + donor.seg + '</div>' +
'<div class="ki-item-body"><strong>' + donor.seg + '</strong> (' + donor.growth + '%) is the donor funding the trade-up in this category. It\u2019s declining, but it\u2019s also still the volume base \u2014 manage the decline deliberately rather than abandoning the facings, because a too-fast delist pushes those buyers out of the category entirely rather than up into the premium tiers.</div></div>';
}
html += '</div>';
el.innerHTML = html;
}



