function renderHomeCard(card, idx){
const unit=card.unit!==undefined?card.unit:'%';
const baseline=card.baseline||0;
const maxAbs=Math.max.apply(null,card.rows.map(function(r){return Math.abs(r.value);}));
let rowsHtml='';
card.rows.forEach(function(r){
let fillHtml='';
if(card.composition){
const pct=Math.abs(r.value)/maxAbs*100;
fillHtml='<span class="home-row-bar-fill" style="left:0;width:'+pct+'%;background:#4cb8a4;"></span>';
}else{
const pct=Math.abs(r.value)/maxAbs*50;
if(r.value>=0){fillHtml='<span class="home-row-bar-fill" style="left:50%;width:'+pct+'%;background:#4cb8a4;"></span>';}
else{fillHtml='<span class="home-row-bar-fill" style="right:50%;width:'+pct+'%;background:#e07b5f;"></span>';}
fillHtml+='<span class="home-row-bar-zero"></span>';
}
const valClass=r.value>=0?'pos':'neg';
let displayText;
if(baseline){displayText=(baseline+r.value)+unit;}
else if(card.composition){displayText=r.value+unit;}
else{const sign=r.value>0?'+':'';displayText=sign+r.value+unit;}
rowsHtml+='<div class="home-row"><span class="home-row-label">'+r.label+'</span><span class="home-row-bar">'+fillHtml+'</span><span class="home-row-value '+valClass+'">'+displayText+'</span></div>';
});
const timeClass=card.override?'home-card-time override':'home-card-time';
const dot=card.override?'• ':'';
return '<div class="home-card" data-card-idx="'+idx+'" title="Click to open in Report Builder"><div class="home-card-head"><div class="home-card-title">'+card.title+'</div><div class="'+timeClass+'">'+dot+card.time+' ▾</div></div>'+rowsHtml+'<div class="home-card-open-hint">Open in builder →</div></div>';
}

// Apply a home-card's builder config to RB_STATE and navigate to the Report Builder.
function openHomeCardInBuilder(card){
// Defaults — overridden by card.builder
const defaults = {
rows: ['category'],
columns: [],
filters: [],
measures: ['volume_growth'],
viz: 'hbar',
timeInterval: 'single',
mod: 'growth',
sort: 'desc'
};
const b = Object.assign({}, defaults, card.builder || {});
// Build the target sheet's state object — don't touch RB_STATE yet (the rbOpenAsSheet
// helper handles snapshotting current sheet + loading the new one)
const targetState = rbCloneState(RB_DEFAULT);
targetState.rows = b.rows.slice();
targetState.columns = b.columns.slice();
targetState.filters = b.filters.slice();
targetState.measures = b.measures.slice();
targetState.viz = b.viz;
targetState.timeInterval = b.timeInterval;
targetState.calculated = [];
if(b.mod && b.mod !== 'growth'){
targetState.measures = targetState.measures.map(function(m){
return typeof m === 'string' ? {key: m, mod: b.mod} : Object.assign({}, m, {mod: b.mod});
});
}
if(b.sort){ targetState.sortBy = {measureIdx: 0, dir: b.sort}; }
// Navigate to builder first so tab bar is in the DOM
const navLink = document.querySelector('.nav-subitem[data-view="builder"]');
if(navLink) navLink.click();
// Open as a new sheet — preserves current work, dedupes if this card is already open
rbOpenAsSheet({ id: 'home_card_' + (card.title || '').replace(/\s+/g, '_'), name: card.title || 'Report', state: targetState });
}

function renderHome(){
const grid = document.getElementById('home-grid');
grid.innerHTML = HOME_CARDS.map(function(card, i){ return renderHomeCard(card, i); }).join('');
grid.querySelectorAll('.home-card').forEach(function(el){
el.addEventListener('click', function(){
const idx = parseInt(el.dataset.cardIdx, 10);
const card = HOME_CARDS[idx];
if(card) openHomeCardInBuilder(card);
});
});
renderRecommended();
}

