function qbrFontStack(name){
  if(!name) name='Calibri';
  const cat=QBR_FONT_CAT[name]||'sans';
  const fb = cat==='serif' ? "Georgia, 'Times New Roman', serif"
    : cat==='mono' ? "Consolas, 'Courier New', monospace"
    : cat==='script' ? "'Segoe Script', 'Comic Sans MS', cursive"
    : cat==='display' ? "Impact, 'Arial Black', sans-serif"
    : cat==='symbol' ? "'Segoe UI Symbol', sans-serif"
    : "'Segoe UI', system-ui, Arial, sans-serif";
  return "'"+name+"', "+fb;
}
function qbrFontOptionsHtml(selected, includeTheme){
  const t=(QBR_STATE&&QBR_STATE.template&&QBR_STATE.template.theme)||{};
  let h='';
  if(includeTheme) h+='<option value=""'+(((selected||'')==='')?' selected':'')+'>(theme default)</option>';
  const tf=[]; if(t.headFont) tf.push([t.headFont,'headings']); if(t.bodyFont && t.bodyFont!==t.headFont) tf.push([t.bodyFont,'body']);
  if(tf.length){ h+='<optgroup label="Theme fonts">'+tf.map(function(p){ return '<option value="'+p[0]+'"'+(selected===p[0]?' selected':'')+'>'+p[0]+' \u00b7 '+p[1]+'</option>'; }).join('')+'</optgroup>'; }
  h+='<optgroup label="All fonts">'+QBR_FONTS.map(function(f){ return '<option value="'+f+'"'+(selected===f?' selected':'')+'>'+f+'</option>'; }).join('')+'</optgroup>';
  return h;
}
