function qbrUid(){ return 'el_'+Math.random().toString(36).slice(2,9); }
function qbrSlideUid(){ return 's_'+Math.random().toString(36).slice(2,9); }
// Element factories — every slide is a free canvas of positioned elements (fractions 0..1 of a 16:9 slide)
function qbrElText(o){ return Object.assign({id:qbrUid(), type:'text', x:0.1,y:0.1,w:0.5,h:0.12, text:'Text', size:18, bold:false, italic:false, underline:false, color:'auto', font:null, fontRole:'body', align:'l', valign:'t'}, o||{}); }
function qbrElShape(shape){ return {id:qbrUid(), type:'shape', x:0.35,y:0.4,w:0.3,h:0.2, shape:shape||'rect', fill:'#4E7CA1', stroke:null, strokeW:1}; }
function qbrElImage(src){ return {id:qbrUid(), type:'image', x:0.36,y:0.3,w:0.28,h:0.32, src:src||null}; }
var QBR_BRIDGE_DEFAULT=[{label:'Base velocity',val:2.1},{label:'New distribution',val:1.8},{label:'Premium mix',val:1.4},{label:'Lapsed accounts',val:-1.2},{label:'Promotion timing',val:1.0}];
function qbrElBridge(){ return {id:qbrUid(), type:'bridge', x:0.08,y:0.26,w:0.84,h:0.6, steps:QBR_BRIDGE_DEFAULT.map(function(d){return {label:d.label,val:d.val};}), showTotal:true, totalLabel:'Net', unit:'pt'}; }
function qbrBridgeGeo(el){ var steps=(el.steps&&el.steps.length)?el.steps:QBR_BRIDGE_DEFAULT; var cum=0,out=[],maxC=0,minC=0; steps.forEach(function(b){ var v=parseFloat(b.val)||0; var start=cum,end=cum+v; cum=end; maxC=Math.max(maxC,start,end); minC=Math.min(minC,start,end); out.push({label:b.label||'',val:v,type:v<0?'neg':'pos',start:start,end:end,hi:Math.max(start,end),lo:Math.min(start,end)}); }); if(el.showTotal!==false){ out.push({label:el.totalLabel||'Net',val:cum,type:'total',start:0,end:cum,hi:Math.max(0,cum),lo:Math.min(0,cum)}); maxC=Math.max(maxC,cum,0); minC=Math.min(minC,cum,0); } return {steps:out,max:maxC,min:minC}; }
