// Placeholders (el.ph) are owned by the layout and shown as editable boxes in master view,
// so a layout is never blank. They are NOT painted as static ghost on real slides — a slide
// gets its own editable copy via qbrLayoutSeed. Chrome (non-ph) repeats on every slide.
function qbrLayoutChrome(L){ return (L && L.elements) ? L.elements.filter(function(e){ return !e.ph; }) : []; }
// --- Header & Footer (deck-level date / footer / slide-number band) ---
function qbrHf(){
if(!QBR_STATE.hf) QBR_STATE.hf = {on:false, footer:'', showDate:false, dateAuto:true, dateText:'', showPage:true, skipTitle:true};
return QBR_STATE.hf;
}
function qbrIsTitleSlide(slide){
if(!slide) return false;
if(QBR_STATE.slides.indexOf(slide) === 0) return true;
const lid = String(slide.layout || ((typeof qbrLayoutFor === 'function' ? qbrLayoutFor(slide) : null) || {}).id || '').toLowerCase();
return lid === 'title' || lid === 'cover';
}
function qbrHfDateText(){
const hf = qbrHf();
if(!hf.dateAuto && hf.dateText) return hf.dateText;
try{ return new Date().toLocaleDateString(undefined, {year:'numeric', month:'long', day:'numeric'}); }catch(e){ return ''; }
}
function qbrHfElements(slide){
const hf = qbrHf();
if(!hf.on || !slide) return [];
if(hf.skipTitle && qbrIsTitleSlide(slide)) return [];
const pageNum = QBR_STATE.slides.indexOf(slide) + 1;
const els = [];
const base = {type:'text', y:0.944, h:0.044, size:9.5, color:'#6b7280', font:null, fontRole:'body', bold:false, italic:false, valign:'m', _hf:true};
if(hf.showDate){ els.push(Object.assign({}, base, {id:'_hf_date', x:0.045, w:0.30, align:'l', text:qbrHfDateText()})); }
if(hf.footer){ els.push(Object.assign({}, base, {id:'_hf_foot', x:0.35, w:0.30, align:'ctr', text:hf.footer})); }
if(hf.showPage){ els.push(Object.assign({}, base, {id:'_hf_page', x:0.655, w:0.30, align:'r', text:String(pageNum)})); }
return els;
}
function qbrLayoutPlaceholders(L){ return (L && L.elements) ? L.elements.filter(function(e){ return e.ph; }) : []; }
function qbrLayoutSeed(id){
var L=(QBR_STATE&&QBR_STATE.template&&QBR_STATE.template.layouts)?QBR_STATE.template.layouts.find(function(x){return x.id===id;}):null;
return qbrLayoutPlaceholders(L).map(function(e){ var c=JSON.parse(JSON.stringify(e)); c.id=qbrUid(); c.ovr={}; return c; });
}
function qbrLayoutFor(slide){ const id=slide&&slide.layout; return (QBR_STATE.template.layouts||[]).find(function(x){return x.id===id;})||null; }
// ===== Placeholder linkage (PowerPoint inheritance) =====
// A slide placeholder (el.ph) inherits geometry + styling from its layout's matching
// placeholder. Coarse override flags decouple a facet once the user changes it on the slide:
//   ovr.geo  set when the slide box is moved/resized/repositioned
//   ovr.fmt  set when its font/colour/paragraph styling is changed
// Content (text/runs) is always the slide's own. "Reset to layout" clears ovr and re-inherits.
var QBR_PH_GEO=['x','y','w','h','rot'];
var QBR_PH_FMT=['size','color','font','fontRole','bold','italic','underline','strike','script','case','charSpacing','highlight','align','valign','lineSpacing','listStyle','listLevel','bullet'];
function qbrPhLabel(p){ return ({title:'Title', subtitle:'Subtitle', body:'Body', body2:'Body'})[p]||'Placeholder'; }
function qbrPhSource(slide, ph){ var L=qbrLayoutFor(slide); if(!L) return null; return qbrLayoutPlaceholders(L).filter(function(e){return e.ph===ph;})[0]||null; }
// Write inherited layout values into the stored slide elements so the canvas, thumbnails,
