    let slide = (typeof qbrActiveSlide === 'function') ? qbrActiveSlide() : null;
    if(!slide){ slide = { id: qbrSlideUid(), layout:'content', elements:[] }; QBR_STATE.slides.push(slide); QBR_STATE.selected = QBR_STATE.slides.length - 1; }
