const period=QBR_PERIOD_LABELS[QBR_STATE.period.window]||'R12';
const vg=qbrNum(sc.metrics.volume_growth), rev=qbrNum(sc.metrics.revenue_growth), pod=qbrNum(sc.metrics.pod_growth), hr=qbrNum(sc.metrics.headroom_pt);
const out=[];
out.push('Open with the headline — '+sc.label+' is '+((vg!=null&&vg<0)?'down':'up')+' '+sc.metrics.volume_growth+' on 9L volume over '+period+(sc.peerCount>1?', '+qbrOrdinal(sc.rank)+' of '+sc.peerCount+' in the review set.':'.'));
if(rev!=null&&vg!=null){ if(rev>vg+0.5) out.push('Premiumization point: revenue ('+sc.metrics.revenue_growth+') is outpacing volume — mix is working; lean into the assortment story.'); else if(rev<vg-0.5) out.push('Flag the pressure: revenue ('+sc.metrics.revenue_growth+') trails volume — be ready to discuss price or mix headwinds.'); else out.push('Revenue and volume are moving in step ('+sc.metrics.revenue_growth+') — stable price and mix.'); }
