return '--qbr-title-color:#'+t.titleColor+';--qbr-body-color:#'+t.bodyColor+';--qbr-muted-color:#'+t.mutedColor+';--qbr-accent:#'+t.accent+';--qbr-head-font:'+qbrFontStack(t.headFont)+';--qbr-body-font:'+qbrFontStack(t.bodyFont)+';';
