el.innerHTML='<div class="qbr-tpl-swatches">'+sw+'</div><div class="qbr-tpl-meta"><div class="qbr-tpl-name">'+t.name+'</div><div class="qbr-tpl-detail">theme ingested · 16:9 · click to replace</div></div>';
