const useTheme = theme || JSON.parse(JSON.stringify(QBR_STATE.template.theme));
// Commit the theme the instant it parses, so a later chrome-parse hiccup can never block the re-theme.
if(theme){ QBR_STATE.template.theme=theme; if(QBR_FONTS.indexOf(theme.headFont)<0) QBR_FONTS.push(theme.headFont); if(QBR_FONTS.indexOf(theme.bodyFont)<0) QBR_FONTS.push(theme.bodyFont); }
let masterPart='ppt/slideMasters/slideMaster1.xml';
if(!entries[masterPart]){ const k=Object.keys(entries).filter(function(n){return /^ppt\/slideMasters\/slideMaster\d+\.xml$/.test(n);})[0]; if(k) masterPart=k; }
let masterChrome={elements:[], background:null};
