const masterEls=masterChrome.elements.slice();
// keep pagination: if nothing imported carries a [page] token, add a discreet page number
const hasPage = masterEls.concat(Object.keys(importedLayouts).reduce(function(a,k){return a.concat(importedLayouts[k]);},[])).some(function(e){return e.type==='text'&&/\[page\]/i.test(e.text||'');});
if(!hasPage) masterEls.push(qbrElText({x:0.78,y:0.915,w:0.175,h:0.05, text:'[page]', size:9, color:'muted', align:'r', valign:'ctr'}));
QBR_STATE.template.master={ background: masterChrome.background, elements: masterEls };
(QBR_STATE.template.layouts||[]).forEach(function(L){ if(importedLayouts[L.id]) L.elements=importedLayouts[L.id]; });
