try{ importedSlides = await qbrIngestSlides(entries, useTheme, sldW, sldH); }catch(e){ if(window.console) console.warn('QBR: slide ingest skipped —', e); }
if(importedSlides.length){ QBR_STATE.slides=importedSlides; QBR_STATE.selected=0; QBR_STATE.selEl=null; }
