if(_showM) inner+=(master.elements||[]).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
if(_showLC) inner+=qbrLayoutChrome(layoutObj).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
