function qbrRemoveActiveAnim(){ var aa=qbrActiveAnim(); if(!aa.el||!aa.anim) return; qbrSnapshot(); aa.el.anim.splice(aa.idx,1); QBR_STATE.animSel=Math.max(0,aa.idx-1); qbrRenderCanvas(); if(QBR_STATE.animPane) qbrRenderAnimPane(); }
function qbrMoveAnim(dir){ var slide=qbrActiveSlide(); var seq=qbrSlideAnims(slide); var aa=qbrActiveAnim(); if(!aa.anim) return; var i=seq.findIndex(function(s){return s.anim===aa.anim;}); var j=i+dir; if(j<0||j>=seq.length) return; qbrSnapshot(); var t=seq[i].anim.seq; seq[i].anim.seq=seq[j].anim.seq; seq[j].anim.seq=t; qbrRenderCanvas(); if(QBR_STATE.animPane) qbrRenderAnimPane(); }
