function qbrAnimDirVec(dir, exit){ var v=({l:['-120%','0'],r:['120%','0'],t:['0','-120%'],b:['0','120%']})[dir||'l']; return v; }
function qbrAnimPlay(node, a){ if(!node) return; var f=QBR_ANIM_FX[a.fx]; if(!f) return; var dur=a.dur||500; if(a.fx==='fly'||a.fx==='flyout'){ var v=qbrAnimDirVec(a.dir); node.style.setProperty('--qa-tx',v[0]); node.style.setProperty('--qa-ty',v[1]); } if(a.fx==='wipe'){ var w=({t:'inset(100% 0 0 0)',b:'inset(0 0 100% 0)',l:'inset(0 100% 0 0)',r:'inset(0 0 0 100%)'})[a.dir||'t']; node.style.setProperty('--qa-wipe',w); } if(f.kind==='entrance') node.style.visibility='visible'; node.style.animation='none'; void node.offsetWidth; node.style.animation='qa-'+f.css+' '+dur+'ms '+(f.kind==='emphasis'?'ease-in-out':'cubic-bezier(.22,.61,.36,1)')+' both'; if(f.kind==='exit'){ var done=function(){ node.style.visibility='hidden'; node.removeEventListener('animationend',done); }; node.addEventListener('animationend',done); } }
function qbrPreviewAnims(){ var slide=qbrActiveSlide(); if(!slide) return; var stage=document.getElementById('qbr-canvas-wrap')||document.getElementById('qbr-canvas-stage'); var steps=qbrBuildSteps(slide); (slide.elements||[]).forEach(function(el){ if((el.anim||[]).some(function(a){return (QBR_ANIM_FX[a.fx]||{}).kind==='entrance';})){ var n=stage.querySelector('[data-elid="'+el.id+'"]'); if(n) n.style.visibility='hidden'; } }); var t=0; steps.forEach(function(step){ (function(step,t0){ setTimeout(function(){ qbrPlaySeq(step, stage); },t0); })(step,t); var d=0; step.forEach(function(it){ d+=(it.anim.start==='withPrev')?0:(it.anim.dur||500)+(it.anim.delay||0); }); t+=Math.max(600,d)+350; }); setTimeout(function(){ (slide.elements||[]).forEach(function(el){ var n=stage.querySelector('[data-elid="'+el.id+'"]'); if(n){ n.style.animation=''; n.style.visibility=(el.anim||[]).some(function(a){return (QBR_ANIM_FX[a.fx]||{}).kind==='exit';})?n.style.visibility:'visible'; n.style.visibility='visible'; } }); }, t+400); }
function qbrPlaySeq(step, root){ var prevStart=0,prevEnd=0; step.forEach(function(it,i){ var a=it.anim,st; if(i===0) st=a.delay||0; else if(a.start==='withPrev') st=prevStart+(a.delay||0); else st=prevEnd+(a.delay||0); var node=root.querySelector('[data-elid="'+it.el.id+'"]'); (function(node,a,st){ setTimeout(function(){ qbrAnimPlay(node,a); },st); })(node,a,st); prevStart=st; prevEnd=st+(a.dur||500); }); }
// ribbon emitters
