function qbrEmitAnimTimingGroup(p){ var aa=qbrActiveAnim(); var a=aa.anim; if(!a) return qbrRibGroup('Timing','<span class="qbr-fb-cap2">No effect yet</span>'); var starts=[['click','On click'],['withPrev','With previous'],['afterPrev','After previous']]; var h='<select class="qbr-fb-sel" data-anim-start="1" title="Start">'+starts.map(function(s){return '<option value="'+s[0]+'"'+(a.start===s[0]?' selected':'')+'>'+s[1]+'</option>';}).join('')+'</select>'; h+='<span class="qbr-fb-cap2">Dur</span><span class="qbr-fb-stepper"><button data-anim-dur="-1">−</button><input class="qbr-fb-num" data-anim-durv="1" value="'+((a.dur||500)/1000).toFixed(1)+'"><button data-anim-dur="1">+</button></span>'; h+='<span class="qbr-fb-cap2">Delay</span><span class="qbr-fb-stepper"><button data-anim-delay="-1">−</button><input class="qbr-fb-num" data-anim-delayv="1" value="'+((a.delay||0)/1000).toFixed(1)+'"><button data-anim-delay="1">+</button></span>'; h+='<button class="qbr-fb-b" data-anim-move="-1" title="Move earlier">▲</button><button class="qbr-fb-b" data-anim-move="1" title="Move later">▼</button><button class="qbr-fb-b" data-anim-remove="1" title="Remove">🗑</button>'; return qbrRibGroup('Timing', h); }
function qbrOpenAnimGallery(anchor){ var secs=[['entrance','Entrance'],['emphasis','Emphasis'],['exit','Exit']]; var h=''; secs.forEach(function(sec){ h+='<div class="qbr-pop-sec">'+sec[1]+'</div><div class="qbr-anim-pop-grid">'; Object.keys(QBR_ANIM_FX).forEach(function(fx){ if(QBR_ANIM_FX[fx].kind===sec[0]) h+='<button class="qbr-anim-popbtn" data-anim-add="'+fx+'" title="'+QBR_ANIM_FX[fx].n+'">'+qbrAnimIcon(fx)+'<span>'+QBR_ANIM_FX[fx].n+'</span></button>'; }); h+='</div>'; }); var pop=qbrOpenPopover(anchor,h,'qbr-anim-pop'); if(!pop) return; pop.querySelectorAll('[data-anim-add]').forEach(function(b){ b.addEventListener('click',function(){ qbrApplyAnim(b.dataset.animAdd,false); qbrClosePopover(); }); }); }
function qbrEmitTransitionGroup(slide){ var t=(slide&&slide.transition)||{type:'none'}; var keys=['none','fade','push','wipe','cover','split','zoom']; var sw=keys.map(function(k){ var on=(t.type||'none')===k; return '<button class="qbr-trans-chip'+(on?' on':'')+'" data-trans="'+k+'" title="'+QBR_TRANS[k].n+'">'+qbrTransIcon(k)+'<span>'+QBR_TRANS[k].n+'</span></button>'; }).join(''); var def=QBR_TRANS[t.type||'none']; var dirSel=(def&&def.dir)?'<select class="qbr-fb-sel" data-trans-dir="1" title="Direction">'+[['l','◀'],['r','▶'],['t','▲'],['b','▼']].map(function(d){return '<option value="'+d[0]+'"'+((t.dir||'l')===d[0]?' selected':'')+'>'+d[1]+'</option>';}).join('')+'</select>':''; var dur='<span class="qbr-fb-cap2">Dur</span><span class="qbr-fb-stepper"><button data-trans-dur="-1">−</button><input class="qbr-fb-num" data-trans-durv="1" value="'+(((t.dur||700)/1000).toFixed(1))+'"><button data-trans-dur="1">+</button></span>'; return qbrRibGroup('Transition to this slide','<div class="qbr-anim-gallery">'+sw+'</div>'+dirSel+dur+'<button class="qbr-fb-txt" data-trans-all="1" title="Apply to all slides">Apply to all</button>'); }
function qbrTransIcon(k){ return ({none:'\u2298',fade:'\u25d0',cut:'\u2702',push:'\u2794',wipe:'\u25a4',cover:'\u25a5',split:'\u25ab',reveal:'\u25e7',dissolve:'\u2592',zoom:'\u2299',flip:'\u21c4',cube:'\u25f0',fall:'\u2b07',ripple:'\u2248',pan:'\u2b0c',rotate:'\u21bb',gallery:'\u25a6'})[k]||'\u25a2'; }
function qbrEmitSlideshowStart(){ return qbrRibGroup('Start slide show','<button class="qbr-fb-txt" data-present="start" title="Present from the first slide">▷ From start</button><button class="qbr-fb-txt" data-present="current" title="Present from the current slide">▷ From current</button><button class="qbr-fb-txt" data-present="presenter" title="Open presenter view in a new window">Presenter view</button>'); }
