function qbrEmitTransitionAdvance(slide){ var s=slide||{}; var af=s.advanceAfter||0; var clickOn=s.advanceClick!==false; return qbrRibGroup('Advance slide','<label class="qbr-anim-check"><input type="checkbox" data-adv-click="1"'+(clickOn?' checked':'')+'> On mouse click</label><label class="qbr-anim-check"><input type="checkbox" data-adv-after="1"'+(af>0?' checked':'')+'> After</label><span class="qbr-fb-stepper"><button data-adv-aftd="-1">−</button><input class="qbr-fb-num" data-adv-afterv="1" value="'+(af?af.toFixed(0):'5')+'"'+(af>0?'':' disabled')+'><button data-adv-aftd="1">+</button></span><span class="qbr-fb-cap2">sec</span>'); }
// Animation pane
function qbrTogglePane(){ QBR_STATE.animPane=!QBR_STATE.animPane; qbrRenderAnimPane(); qbrRenderRibbon(); }
function qbrRenderAnimPane(){ var ex=document.getElementById('qbr-anim-pane'); if(!QBR_STATE.animPane){ if(ex) ex.remove(); return; } var host=document.querySelector('#view-qbr .qbr-canvas'); if(!host) return; var slide=qbrActiveSlide(); var anims=slide?qbrSlideAnims(slide):[]; var pane=ex||document.createElement('div'); pane.id='qbr-anim-pane'; pane.className='qbr-anim-pane'; var rows=anims.map(function(it,i){ var f=QBR_ANIM_FX[it.anim.fx]||{}; var nm=qbrElDefaultName(it.el,(slide.elements||[]).indexOf(it.el)+1); var startIc=it.anim.start==='click'?'🖱':(it.anim.start==='withPrev'?'⏵':'⏱'); var sel=(QBR_STATE.selEl===it.el.id); return '<div class="qbr-anim-row'+(sel?' sel':'')+'" data-anim-row="'+it.el.id+'" data-anim-idx="'+it.animIdx+'"><span class="qbr-anim-seq">'+(i+1)+'</span><span class="qbr-anim-ic '+f.kind+'">'+qbrAnimIcon(it.anim.fx)+'</span><span class="qbr-anim-meta"><b>'+f.n+'</b><small>'+startIc+' '+nm+'</small></span><button class="qbr-anim-rowdel" data-anim-rowdel="'+it.el.id+'|'+it.animIdx+'">×</button></div>'; }).join(''); pane.innerHTML='<div class="qbr-anim-pane-head">Animation Pane <button id="qbr-anim-pane-x" title="Close">×</button></div><div class="qbr-anim-pane-body">'+(rows||'<div class="qbr-anim-empty">No animations on this slide yet. Select an element and pick an effect.</div>')+'</div><div class="qbr-anim-pane-foot"><button class="qbr-fb-txt" data-anim-preview="1">▸ Play all</button></div>'; if(!ex) host.appendChild(pane); pane.querySelector('#qbr-anim-pane-x').addEventListener('click', qbrTogglePane); pane.querySelectorAll('[data-anim-row]').forEach(function(r){ r.addEventListener('click',function(e){ if(e.target.dataset.animRowdel!=null) return; QBR_STATE.selEl=r.dataset.animRow; QBR_STATE.selEls=[r.dataset.animRow]; QBR_STATE.animSel=+r.dataset.animIdx; qbrRenderCanvas(); }); }); pane.querySelectorAll('[data-anim-rowdel]').forEach(function(b){ b.addEventListener('click',function(e){ e.stopPropagation(); var parts=b.dataset.animRowdel.split('|'); var slide=qbrActiveSlide(); var el=(slide.elements||[]).find(function(x){return x.id===parts[0];}); if(el&&el.anim){ qbrSnapshot(); el.anim.splice(+parts[1],1); qbrRenderCanvas(); qbrRenderAnimPane(); } }); }); var pv=pane.querySelector('[data-anim-preview]'); if(pv) pv.addEventListener('click', qbrPreviewAnims); }
// ===== Slide-out Animations panel =====
function qbrAnimThumbPreview(node, fx){ if(!node) return; var f=QBR_ANIM_FX[fx]; if(!f) return; if(fx==='fly'||fx==='flyout'){ node.style.setProperty('--qa-tx','-55%'); node.style.setProperty('--qa-ty','0'); } if(fx==='wipe'){ node.style.setProperty('--qa-wipe','inset(0 100% 0 0)'); } node.style.visibility='visible'; node.style.animation='none'; void node.offsetWidth; node.style.animation='qa-'+f.css+' 720ms '+(f.kind==='emphasis'?'ease-in-out':'cubic-bezier(.22,.61,.36,1)')+' both'; }
function qbrAnimTune(mut){ var aa=qbrActiveAnim(); if(!aa.anim) return; mut(aa.anim); qbrRenderAnimStudio(); }
function qbrCloseAnimStudio(){ var p=document.getElementById('qbr-animsx'); if(p) p.classList.remove('open'); }
function qbrRenderAnimStudio(){
var host=document.querySelector('#view-qbr .qbr-canvas'); if(!host) return;
var panel=document.getElementById('qbr-animsx'); var fresh=false;
if(!panel){ panel=document.createElement('div'); panel.id='qbr-animsx'; panel.className='qbr-animsx'; host.appendChild(panel); fresh=true; }
var slide=qbrActiveSlide();
var objs=qbrSelObjs(); var primary=null;
if(QBR_STATE.selEl && slide){ primary=(slide.elements||[]).find(function(x){return x.id===QBR_STATE.selEl;}); }
if(!primary && objs.length) primary=objs[0];
var aa=qbrActiveAnim();
var body='';
if(!primary){
body='<div class="qbr-animsx-empty"><div class="qbr-animsx-empty-ico">\u2726</div><div class="qbr-animsx-empty-txt">Select an object on the slide to animate it. Choose an entrance, emphasis, or exit effect \u2014 then fine-tune timing and order right here.</div></div>';
} else {
var nm=qbrElDefaultName(primary,(slide.elements||[]).indexOf(primary)+1);
body+='<div class="qbr-animsx-elname">Animating <b>'+String(nm).replace(/</g,'&lt;')+'</b></div>';
[['entrance','Entrance'],['emphasis','Emphasis'],['exit','Exit']].forEach(function(sec){
var fxs=Object.keys(QBR_ANIM_FX).filter(function(k){return QBR_ANIM_FX[k].kind===sec[0];});
body+='<div class="qbr-animsx-sec">'+sec[1]+'</div><div class="qbr-animsx-grid">';
fxs.forEach(function(fx){ var f=QBR_ANIM_FX[fx]; var on=(primary.anim||[]).some(function(a){return a.fx===fx;}); body+='<div class="qbr-animsx-fx'+(on?' on':'')+'" data-animsx-add="'+fx+'" data-kind="'+f.kind+'" title="Add '+f.n+'">'+(on?'<span class="qbr-animsx-fx-on">\u2713</span>':'')+'<span class="qbr-animsx-ico" data-animsx-ico="'+fx+'">'+qbrAnimIcon(fx)+'</span><span>'+f.n+'</span></div>'; });
body+='</div>';
});
if(aa.anim){
var a=aa.anim; var f=QBR_ANIM_FX[a.fx]||{};
body+='<div class="qbr-animsx-sec">Effect options</div>';
if(f.dir){ var dm={t:'\u25b2',b:'\u25bc',l:'\u25c0',r:'\u25b6'}; var dn={l:'left',r:'right',t:'top',b:'bottom'}; var cell=function(d){ return d?('<button class="qbr-animsx-dir'+((a.dir||'l')===d?' on':'')+'" data-animsx-dir="'+d+'" title="From '+dn[d]+'">'+dm[d]+'</button>'):'<span class="qbr-animsx-dir spacer"></span>'; }; body+='<div class="qbr-animsx-dirs">'+cell('')+cell('t')+cell('')+cell('l')+cell('')+cell('r')+cell('')+cell('b')+cell('')+'</div>'; }
else { body+='<div class="qbr-animsx-none">No direction options for this effect.</div>'; }
body+='<div class="qbr-animsx-sec">Start</div><div class="qbr-animsx-seg">'+[['click','On click'],['withPrev','With prev'],['afterPrev','After prev']].map(function(s){return '<button class="'+((a.start||'click')===s[0]?'on':'')+'" data-animsx-start="'+s[0]+'">'+s[1]+'</button>';}).join('')+'</div>';
body+='<div class="qbr-animsx-sec">Timing</div>';
body+='<div class="qbr-animsx-slider"><label>Duration</label><input type="range" min="0.1" max="3" step="0.1" value="'+((a.dur||500)/1000)+'" data-animsx-dur="1"><span class="val" data-animsx-durval>'+((a.dur||500)/1000).toFixed(1)+'s</span></div>';
body+='<div class="qbr-animsx-slider"><label>Delay</label><input type="range" min="0" max="3" step="0.1" value="'+((a.delay||0)/1000)+'" data-animsx-delay="1"><span class="val" data-animsx-delayval>'+((a.delay||0)/1000).toFixed(1)+'s</span></div>';
}
var seq=slide?qbrSlideAnims(slide):[];
body+='<div class="qbr-animsx-sec">Sequence</div>';
if(!seq.length){ body+='<div class="qbr-animsx-seqempty">No effects on this slide yet. Pick one above to begin building the sequence.</div>'; }
else { body+='<div class="qbr-animsx-seq">'; seq.forEach(function(it,i){ var ff=QBR_ANIM_FX[it.anim.fx]||{}; var rn=qbrElDefaultName(it.el,(slide.elements||[]).indexOf(it.el)+1); var sl=({click:'On click',withPrev:'With prev',afterPrev:'After prev'})[it.anim.start||'click']; var sel=(aa.el&&aa.el.id===it.el.id&&aa.anim===it.anim); body+='<div class="qbr-animsx-seqrow'+(sel?' sel':'')+'" data-animsx-row="'+it.el.id+'" data-animsx-idx="'+it.animIdx+'"><span class="qbr-animsx-seqnum">'+(i+1)+'</span><span class="qbr-animsx-seqic '+ff.kind+'">'+qbrAnimIcon(it.anim.fx)+'</span><span class="qbr-animsx-seqmeta"><b>'+ff.n+'</b><small>'+sl+' \u00b7 '+String(rn).replace(/</g,'&lt;')+' \u00b7 '+((it.anim.dur||500)/1000).toFixed(1)+'s</small></span><span class="qbr-animsx-seqbtns"><button data-animsx-move="-1|'+it.el.id+'|'+it.animIdx+'" title="Move earlier">\u25b2</button><button data-animsx-move="1|'+it.el.id+'|'+it.animIdx+'" title="Move later">\u25bc</button><button data-animsx-del="'+it.el.id+'|'+it.animIdx+'" title="Remove">\u00d7</button></span></div>'; }); body+='</div>'; }
body+='<button class="qbr-animsx-playall" data-anim-preview="1">\u25b8 Play all on this slide</button>';
}
panel.innerHTML='<div class="qbr-animsx-head"><span class="qbr-animsx-head-title"><span class="sp">\u2726</span> Animations</span><span class="qbr-animsx-head-sp"></span><button class="qbr-animsx-play" data-anim-preview="1" title="Play all">\u25b8 Play</button><button class="qbr-animsx-x" title="Close panel">\u00d7</button></div><div class="qbr-animsx-body">'+body+'</div>';
if(fresh){ void panel.offsetWidth; }
panel.classList.add('open');
qbrWireAnimStudio(panel);
}
function qbrWireAnimStudio(panel){
var x=panel.querySelector('.qbr-animsx-x'); if(x) x.addEventListener('click', function(){ QBR_STATE.ribbonTab='home'; qbrRenderRibbonTabs(); qbrRenderRibbon(); });
panel.querySelectorAll('[data-anim-preview]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); qbrPreviewAnims(); }); });
panel.querySelectorAll('[data-animsx-add]').forEach(function(c){ c.addEventListener('click', function(){ qbrApplyAnim(c.dataset.animsxAdd, false); qbrRenderAnimStudio(); }); var ico=c.querySelector('[data-animsx-ico]'); c.addEventListener('mouseenter', function(){ qbrAnimThumbPreview(ico, c.dataset.animsxAdd); }); });
panel.querySelectorAll('[data-animsx-dir]').forEach(function(b){ b.addEventListener('click', function(){ qbrAnimTune(function(a){ a.dir=b.dataset.animsxDir; }); }); });
panel.querySelectorAll('[data-animsx-start]').forEach(function(b){ b.addEventListener('click', function(){ qbrAnimTune(function(a){ a.start=b.dataset.animsxStart; }); }); });
var dur=panel.querySelector('[data-animsx-dur]'); if(dur){ dur.addEventListener('input', function(){ var v=parseFloat(dur.value); var aa=qbrActiveAnim(); if(aa.anim) aa.anim.dur=Math.round(v*1000); var lab=panel.querySelector('[data-animsx-durval]'); if(lab) lab.textContent=v.toFixed(1)+'s'; }); dur.addEventListener('change', function(){ qbrSnapshot(); qbrRenderAnimStudio(); }); }
var del=panel.querySelector('[data-animsx-delay]'); if(del){ del.addEventListener('input', function(){ var v=parseFloat(del.value); var aa=qbrActiveAnim(); if(aa.anim) aa.anim.delay=Math.round(v*1000); var lab=panel.querySelector('[data-animsx-delayval]'); if(lab) lab.textContent=v.toFixed(1)+'s'; }); del.addEventListener('change', function(){ qbrSnapshot(); qbrRenderAnimStudio(); }); }
panel.querySelectorAll('[data-animsx-row]').forEach(function(r){ r.addEventListener('click', function(e){ if(e.target.closest('[data-animsx-move]')||e.target.closest('[data-animsx-del]')) return; QBR_STATE.selEl=r.dataset.animsxRow; QBR_STATE.selEls=[r.dataset.animsxRow]; QBR_STATE.animSel=+r.dataset.animsxIdx; qbrRenderCanvas(); }); });
panel.querySelectorAll('[data-animsx-move]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); var p=b.dataset.animsxMove.split('|'); QBR_STATE.selEl=p[1]; QBR_STATE.selEls=[p[1]]; QBR_STATE.animSel=+p[2]; qbrMoveAnim(+p[0]); }); });
panel.querySelectorAll('[data-animsx-del]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); var p=b.dataset.animsxDel.split('|'); var slide=qbrActiveSlide(); var el=(slide.elements||[]).find(function(x){return x.id===p[0];}); if(el&&el.anim){ qbrSnapshot(); el.anim.splice(+p[1],1); qbrRenderCanvas(); } }); });
}
// ===== Slide-out Transitions panel =====
function qbrCloseTransStudio(){ var p=document.getElementById('qbr-transx'); if(p) p.classList.remove('open'); }
function qbrTransFrom(type,dir){ dir=dir||'l';
if(type==='push'||type==='cover') return {l:'translateX(-100%)',r:'translateX(100%)',t:'translateY(-100%)',b:'translateY(100%)'}[dir];
if(type==='pan') return {l:'translateX(-160%)',r:'translateX(160%)',t:'translateY(-160%)',b:'translateY(160%)'}[dir];
if(type==='reveal') return {l:'translateX(-40px)',r:'translateX(40px)',t:'translateY(-40px)',b:'translateY(40px)'}[dir];
if(type==='flip') return {l:'perspective(1400px) rotateY(92deg)',r:'perspective(1400px) rotateY(-92deg)',t:'perspective(1400px) rotateX(-92deg)',b:'perspective(1400px) rotateX(92deg)'}[dir];
if(type==='cube') return {l:'perspective(1400px) translateX(55%) rotateY(-72deg)',r:'perspective(1400px) translateX(-55%) rotateY(72deg)',t:'perspective(1400px) translateY(55%) rotateX(72deg)',b:'perspective(1400px) translateY(-55%) rotateX(-72deg)'}[dir];
if(type==='gallery') return {l:'perspective(1600px) translateX(50%) rotateY(42deg)',r:'perspective(1600px) translateX(-50%) rotateY(-42deg)',t:'perspective(1600px) translateY(50%) rotateX(-42deg)',b:'perspective(1600px) translateY(-50%) rotateX(42deg)'}[dir];
return ''; }
function qbrTransClip(dir){ return {l:'inset(0 100% 0 0)',r:'inset(0 0 0 100%)',t:'inset(100% 0 0 0)',b:'inset(0 0 100% 0)'}[dir||'l']; }
function qbrPreviewTransition(){ var slide=qbrActiveSlide(); if(!slide) return; var node=document.getElementById('qbr-slide-canvas'); if(!node) return; var t=slide.transition; if(!t||!t.type||t.type==='none') return; var def=QBR_TRANS[t.type]; if(!def||!def.css) return; node.style.removeProperty('--qtr-tf'); node.style.removeProperty('--qtr-clip'); if(def.dir){ var tf=qbrTransFrom(t.type,t.dir); if(tf) node.style.setProperty('--qtr-tf',tf); if(t.type==='wipe') node.style.setProperty('--qtr-clip',qbrTransClip(t.dir)); } var dur=(t.type==='cut')?130:(t.dur||700); var ease=(t.type==='cut')?'steps(1,end)':'cubic-bezier(.22,.61,.36,1)'; node.style.animation='none'; void node.offsetWidth; node.style.animation='qa-'+def.css+' '+dur+'ms '+ease+' both'; var clr=function(){ node.style.animation=''; node.removeEventListener('animationend',clr); }; node.addEventListener('animationend',clr); }
function qbrRenderTransStudio(){
var host=document.querySelector('#view-qbr .qbr-canvas'); if(!host) return;
var panel=document.getElementById('qbr-transx'); var fresh=false;
if(!panel){ panel=document.createElement('div'); panel.id='qbr-transx'; panel.className='qbr-transx'; host.appendChild(panel); fresh=true; }
var slide=qbrActiveSlide();
var t=(slide&&slide.transition)||{type:'none'}; var cur=t.type||'none'; var def=QBR_TRANS[cur]||{};
var body='';
[['subtle','Subtle'],['exciting','Exciting'],['dynamic','Dynamic']].forEach(function(c){
var keys=Object.keys(QBR_TRANS).filter(function(k){return (QBR_TRANS[k].cat||'subtle')===c[0];}); if(!keys.length) return;
body+='<div class="qbr-animsx-sec">'+c[1]+'</div><div class="qbr-animsx-grid">';
keys.forEach(function(k){ var d=QBR_TRANS[k]; var on=(cur===k); body+='<div class="qbr-animsx-fx'+(on?' on':'')+'" data-transx-set="'+k+'" title="'+d.n+'">'+(on?'<span class="qbr-animsx-fx-on">\u2713</span>':'')+'<span class="qbr-animsx-ico">'+qbrTransIcon(k)+'</span><span>'+d.n+'</span></div>'; });
body+='</div>';
});
if(cur!=='none' && def.dir){
body+='<div class="qbr-animsx-sec">Effect options</div>';
var dm={t:'\u25b2',b:'\u25bc',l:'\u25c0',r:'\u25b6'}; var dn={l:'left',r:'right',t:'top',b:'bottom'};
var cell=function(dd){ return dd?('<button class="qbr-animsx-dir'+((t.dir||'l')===dd?' on':'')+'" data-transx-dir="'+dd+'" title="From '+dn[dd]+'">'+dm[dd]+'</button>'):'<span class="qbr-animsx-dir spacer"></span>'; };
body+='<div class="qbr-animsx-dirs">'+cell('')+cell('t')+cell('')+cell('l')+cell('')+cell('r')+cell('')+cell('b')+cell('')+'</div>';
}
if(cur!=='none'){ body+='<div class="qbr-animsx-sec">Duration</div><div class="qbr-animsx-slider"><label>Speed</label><input type="range" min="0.1" max="5" step="0.1" value="'+((t.dur||700)/1000)+'" data-transx-dur="1"><span class="val" data-transx-durval>'+((t.dur||700)/1000).toFixed(1)+'s</span></div>'; }
var clickOn=(slide?slide.advanceClick!==false:true); var af=(slide&&slide.advanceAfter)||0;
body+='<div class="qbr-animsx-sec">Advance slide</div>';
body+='<div class="qbr-transx-toggle"><input type="checkbox" data-transx-advclick="1"'+(clickOn?' checked':'')+'><label>On mouse click</label></div>';
body+='<div class="qbr-transx-toggle"><input type="checkbox" data-transx-advafter="1"'+(af>0?' checked':'')+'><label>After</label><span class="qbr-transx-stepper"><button data-transx-aftd="-1">\u2212</button><input data-transx-afterv="1" value="'+(af>0?af:5)+'"'+(af>0?'':' disabled')+'><button data-transx-aftd="1">+</button></span><span class="qbr-transx-sec-unit">sec</span></div>';
body+='<div class="qbr-transx-btns"><button data-trans-preview="1" class="primary">\u25b8 Preview</button><button data-transx-all="1" title="Apply transition &amp; timing to every slide">Apply to all</button></div>';
panel.innerHTML='<div class="qbr-animsx-head"><span class="qbr-animsx-head-title"><span class="sp">\u2726</span> Transitions</span><span class="qbr-animsx-head-sp"></span><button class="qbr-animsx-play" data-trans-preview="1" title="Preview on this slide">\u25b8 Preview</button><button class="qbr-animsx-x" title="Close panel">\u00d7</button></div><div class="qbr-animsx-body">'+body+'</div>';
if(fresh){ void panel.offsetWidth; }
panel.classList.add('open');
qbrWireTransStudio(panel);
}
function qbrWireTransStudio(panel){
var x=panel.querySelector('.qbr-animsx-x'); if(x) x.addEventListener('click', function(){ QBR_STATE.ribbonTab='home'; qbrRenderRibbonTabs(); qbrRenderRibbon(); });
panel.querySelectorAll('[data-trans-preview]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); qbrPreviewTransition(); }); });
panel.querySelectorAll('[data-transx-set]').forEach(function(c){ c.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(!slide) return; qbrSnapshot(); var k=c.dataset.transxSet; if(k==='none'){ delete slide.transition; } else { slide.transition=slide.transition||{}; slide.transition.type=k; if(!slide.transition.dur) slide.transition.dur=700; if(QBR_TRANS[k].dir&&!slide.transition.dir) slide.transition.dir='l'; } qbrRenderTransStudio(); qbrPreviewTransition(); }); });
panel.querySelectorAll('[data-transx-dir]').forEach(function(b){ b.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(slide&&slide.transition){ qbrSnapshot(); slide.transition.dir=b.dataset.transxDir; qbrRenderTransStudio(); qbrPreviewTransition(); } }); });
var dur=panel.querySelector('[data-transx-dur]'); if(dur){ dur.addEventListener('input', function(){ var v=parseFloat(dur.value); var slide=qbrActiveSlide(); if(slide&&slide.transition) slide.transition.dur=Math.round(v*1000); var lab=panel.querySelector('[data-transx-durval]'); if(lab) lab.textContent=v.toFixed(1)+'s'; }); dur.addEventListener('change', function(){ qbrSnapshot(); qbrRenderTransStudio(); }); }
panel.querySelectorAll('.qbr-transx-toggle').forEach(function(row){ row.addEventListener('click', function(e){ if(e.target.closest('.qbr-transx-stepper')||e.target.tagName==='INPUT') return; var cb=row.querySelector('input[type=checkbox]'); if(cb){ cb.checked=!cb.checked; cb.dispatchEvent(new Event('change',{bubbles:true})); } }); });
var ac=panel.querySelector('[data-transx-advclick]'); if(ac) ac.addEventListener('change', function(){ var slide=qbrActiveSlide(); if(slide){ qbrSnapshot(); slide.advanceClick=ac.checked; } });
var aaf=panel.querySelector('[data-transx-advafter]'); if(aaf) aaf.addEventListener('change', function(){ var slide=qbrActiveSlide(); if(!slide) return; qbrSnapshot(); if(aaf.checked){ var iv=panel.querySelector('[data-transx-afterv]'); slide.advanceAfter=Math.max(1,parseFloat(iv&&iv.value)||5); } else { delete slide.advanceAfter; } qbrRenderTransStudio(); });
panel.querySelectorAll('[data-transx-aftd]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); var slide=qbrActiveSlide(); if(!slide||!slide.advanceAfter) return; qbrSnapshot(); slide.advanceAfter=Math.max(1,Math.min(600,slide.advanceAfter+(+b.dataset.transxAftd))); qbrRenderTransStudio(); }); });
var av=panel.querySelector('[data-transx-afterv]'); if(av) av.addEventListener('change', function(){ var slide=qbrActiveSlide(); var v=parseFloat(av.value); if(slide&&!isNaN(v)){ qbrSnapshot(); slide.advanceAfter=Math.max(1,Math.min(600,v)); qbrRenderTransStudio(); } });
var all=panel.querySelector('[data-transx-all]'); if(all) all.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(!slide) return; qbrSnapshot(); var tr=slide.transition?JSON.parse(JSON.stringify(slide.transition)):null; var ac2=slide.advanceClick; var af2=slide.advanceAfter; QBR_STATE.slides.forEach(function(s){ if(tr) s.transition=JSON.parse(JSON.stringify(tr)); else delete s.transition; s.advanceClick=ac2; if(af2) s.advanceAfter=af2; else delete s.advanceAfter; }); if(typeof showActionToast==='function') showActionToast('Applied to all '+QBR_STATE.slides.length+' slides'); qbrRenderTransStudio(); });
}
