+".pw-tbtn{border:1px solid #cfd6dd;background:#fff;border-radius:7px;padding:5px 12px;font-size:13px;cursor:pointer;color:#33485c;}"
+".pw-tbtn:hover{background:#eef2f6;}"
+".pw-counter{font-size:14px;font-weight:600;color:#46586a;}"
+".pw-cur{position:relative;overflow:hidden;border:1px solid #d8dde2;border-radius:8px;background:#fff;box-shadow:0 2px 10px rgba(15,30,45,.08);}"
+".pw-scale{position:absolute;top:0;left:0;transform-origin:top left;}"
+".pw-thumbs{display:flex;align-items:flex-end;gap:18px;margin-top:16px;}"
+".pw-thumb-lbl{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8a949d;margin-bottom:5px;}"
+".pw-thumb-frame{position:relative;overflow:hidden;border:1px solid #dfe3e8;border-radius:6px;background:#fff;}"
+".pw-nav{display:flex;gap:8px;align-items:flex-end;flex:1;justify-content:flex-end;}"
+".pw-navbtn{border:1px solid #cfd6dd;background:#fff;border-radius:8px;padding:9px 16px;font-size:14px;font-weight:600;cursor:pointer;color:#1a2530;}"
