+".pw-tab{border:none;background:transparent;font:inherit;font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#8a949d;cursor:pointer;padding:9px 12px;border-bottom:2px solid transparent;}"
+".pw-tab:hover{color:#46586a;}"
