function qbrFmtElapsed(ms){ var t=Math.floor(ms/1000); var h=Math.floor(t/3600); t-=h*3600; var m=Math.floor(t/60); t-=m*60; var pad=function(n){return (n<10?'0':'')+n;}; return (h>0?h+':':'')+pad(m)+':'+pad(t); }

function qbrSlideStaticHtml(idx){
  var slide=QBR_STATE.slides[idx]; if(!slide) return '';
  var scs=qbrSafeScards(); var sc=(scs&&scs.map)?scs.map[QBR_STATE.previewVal]:null;
  var master=QBR_STATE.template.master||{elements:[]};
  var layoutObj=qbrLayoutFor(slide);
  var bg=qbrEffBg(slide, layoutObj)||'#fff';
  var showM=!(slide.hideBg||(layoutObj&&layoutObj.hideBg)); var showLC=!slide.hideBg;
  QBR_STATE._slideFilter=slide.filter||null;
  var html='<div class="qbr-present-slide qbr-freecanvas" style="position:relative;width:960px;height:540px;background:'+bg+';">';
  try{
    if(showM) html+=(master.elements||[]).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
    if(showLC) html+=qbrLayoutChrome(layoutObj).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
    if(showLC) html+=qbrHfElements(slide).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
    html+=(slide.elements||[]).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join('');
  }catch(e){}
  QBR_STATE._slideFilter=null;
  html+='</div>'; return html;
}

function qbrPresenterGo(dir){ if(!QBR_PRESENT) return; qbrPresenterGoTo(QBR_PRESENT.idx+dir); }
function qbrPresenterGoTo(ni){
  if(!QBR_PRESENT||ni<0||ni>=QBR_STATE.slides.length) return;
  if(document.getElementById('qbr-present-stage')){ var ns=QBR_STATE.slides[ni]; qbrPresentShow(ni,(ns&&ns.transition&&ns.transition.type)||'none'); }
  else { QBR_PRESENT.idx=ni; QBR_STATE.selected=ni; try{ if(typeof qbrRenderCanvas==='function') qbrRenderCanvas(); }catch(e){} qbrPresenterSync(); }
}

function qbrPresenterTick(){
  var w=QBR_PRESENT&&QBR_PRESENT.win; if(!w||w.closed){ if(QBR_PRESENT&&QBR_PRESENT._pwTimer){clearInterval(QBR_PRESENT._pwTimer);QBR_PRESENT._pwTimer=null;} return; }
  var el=w.document.getElementById('pw-timer'); if(!el) return;
  var ms = QBR_PRESENT._paused ? (QBR_PRESENT._pausedAcc||0) : ((QBR_PRESENT._pausedAcc||0) + (Date.now()-(QBR_PRESENT._t0||Date.now())));
  el.textContent=qbrFmtElapsed(ms);
}

function qbrPresenterSync(){
  var w=QBR_PRESENT&&QBR_PRESENT.win; if(!w||w.closed) return;
  var root=w.document.getElementById('pw-root'); if(!root) return;
  var idx=QBR_PRESENT.idx, total=QBR_STATE.slides.length;
  var slide=QBR_STATE.slides[idx];
  var scs=qbrSafeScards(); var sc=(scs&&scs.map)?scs.map[QBR_STATE.previewVal]:null;
  var tab=QBR_PRESENT._pwTab||'notes';
  var nf=QBR_PRESENT._notesFont||18;
  var curHtml=qbrSlideStaticHtml(idx);
  var prevHtml=(idx>0)?qbrSlideStaticHtml(idx-1):'';
  var nextHtml=(idx<total-1)?qbrSlideStaticHtml(idx+1):'';
  var notes='';
  try{ if(slide){ if(slide.notesAuto){ notes=qbrAutoNotes(sc, scs).map(function(x){return '\u2022 '+x;}).join('\n'); } else if(slide.notes){ notes=qbrResolveTokens(qbrResolvePage(slide.notes, idx+1, total), sc, false); } } }catch(e){}
  var notesHtml=(notes&&notes.trim())?_qbrEsc(notes).replace(/\n/g,'<br>'):'<span class="pw-empty">No speaker notes for this slide.</span>';
  var dd; try{ dd=qbrSlideDeepDive(slide, sc, scs); }catch(e){ dd={panels:[]}; }
  var paneW=Math.max(360,(w.innerWidth||1180)*0.6-56);
  var sCur=paneW/960, fh=Math.round(540*sCur);
  var tW=Math.max(150,paneW/2-12), sT=tW/960, th=Math.round(540*sT);
  var opts=''; for(var n=0;n<total;n++){ opts+='<option value="'+n+'"'+(n===idx?' selected':'')+'>Slide '+(n+1)+'</option>'; }
  var thumb=function(html,lbl,which,hasIt){ return '<div class="pw-thumb'+(hasIt?'':' pw-thumb-empty')+'" data-pw-thumb="'+which+'"><div class="pw-thumb-lbl">'+lbl+'</div><div class="pw-thumb-frame" style="width:'+Math.round(tW)+'px;height:'+th+'px;">'+(hasIt?('<div class="pw-scale" style="transform:scale('+sT+');">'+html+'</div>'):'<div class="pw-thumb-none">'+(which==='prev'?'Start':'End')+'</div>')+'</div></div>'; };
  var rightContent='';
  if(tab==='data'){ rightContent='<div class="pw-data">'+qbrRefPanelsHtml(dd)+'</div>'; }
  else if(tab==='audience'){ rightContent='<div class="pw-aud">Audience tools (live Q&amp;A) aren\u2019t part of this build \u2014 Speaker notes and slide Data are on the other tabs.</div>'; }
  else { rightContent='<div class="pw-notes" id="pw-notes" style="font-size:'+nf+'px;">'+notesHtml+'</div>'; }
  var fontBtns=(tab==='notes')?'<div class="pw-fontbtns"><button class="pw-fontbtn" id="pw-font-dn">\u2212</button><button class="pw-fontbtn" id="pw-font-up">+</button></div>':'';
  root.innerHTML=
    '<div class="pw-left">'
    +'<div class="pw-topbar"><div class="pw-timer-wrap"><span class="pw-timer" id="pw-timer">00:00</span>'
    +'<button class="pw-tbtn" id="pw-pause">'+(QBR_PRESENT._paused?'Resume':'Pause')+'</button><button class="pw-tbtn" id="pw-reset">Reset</button></div></div>'
    +'<select class="pw-slidesel" id="pw-slidesel">'+opts+'</select>'
    +'<div class="pw-cur" style="width:'+Math.round(paneW)+'px;height:'+fh+'px;"><div class="pw-scale" style="transform:scale('+sCur+');">'+curHtml+'</div></div>'
    +'<div class="pw-thumbs">'+thumb(prevHtml,'Previous','prev',idx>0)+thumb(nextHtml,'Next','next',idx<total-1)+'</div>'
    +'</div>'
    +'<div class="pw-right">'
    +'<div class="pw-tabs"><button class="pw-tab'+(tab==='audience'?' on':'')+'" data-pw-tab="audience">Audience tools</button><button class="pw-tab'+(tab==='notes'?' on':'')+'" data-pw-tab="notes">Speaker notes</button><button class="pw-tab'+(tab==='data'?' on':'')+'" data-pw-tab="data">Data</button></div>'
    +'<div class="pw-right-top"><div class="pw-counter">Slide '+(idx+1)+' of '+total+'</div>'+fontBtns+'</div>'
    +rightContent
    +'</div>';
  var d=w.document;
  var bind=function(id,fn){ var b=d.getElementById(id); if(b) b.onclick=fn; };
  bind('pw-pause', function(){ if(QBR_PRESENT._paused){ QBR_PRESENT._t0=Date.now(); QBR_PRESENT._paused=false; } else { QBR_PRESENT._pausedAcc=(QBR_PRESENT._pausedAcc||0)+(Date.now()-(QBR_PRESENT._t0||Date.now())); QBR_PRESENT._paused=true; } qbrPresenterSync(); });
  bind('pw-reset', function(){ QBR_PRESENT._t0=Date.now(); QBR_PRESENT._pausedAcc=0; QBR_PRESENT._paused=false; qbrPresenterTick(); });
  bind('pw-font-up', function(){ QBR_PRESENT._notesFont=Math.min(34,(QBR_PRESENT._notesFont||18)+2); qbrPresenterSync(); });
  bind('pw-font-dn', function(){ QBR_PRESENT._notesFont=Math.max(12,(QBR_PRESENT._notesFont||18)-2); qbrPresenterSync(); });
  var sel=d.getElementById('pw-slidesel'); if(sel) sel.onchange=function(){ var ni=parseInt(sel.value,10); if(!isNaN(ni)){ qbrPresenterGoTo(ni); } };
  d.querySelectorAll('[data-pw-tab]').forEach(function(b){ b.onclick=function(){ QBR_PRESENT._pwTab=b.getAttribute('data-pw-tab'); qbrPresenterSync(); }; });
  d.querySelectorAll('[data-pw-thumb]').forEach(function(b){ b.onclick=function(){ qbrPresenterGo(b.getAttribute('data-pw-thumb')==='prev'?-1:1); }; });
  qbrPresenterTick();
}

function qbrOpenPresenter(){
  if(!QBR_PRESENT){ QBR_PRESENT={idx:(QBR_STATE.selected||0),step:0,steps:[],ref:false,editorMode:true}; }
  if(QBR_PRESENT.win && !QBR_PRESENT.win.closed){ try{QBR_PRESENT.win.focus();}catch(e){} return; }
  var w=window.open('', '_blank', 'width=1200,height=780');
  if(!w){ if(typeof showActionToast==='function') showActionToast('Allow pop-ups to open the presenter view'); else { try{alert('Allow pop-ups to open the presenter view.');}catch(e){} } return; }
  var styles=''; document.querySelectorAll('style').forEach(function(st){ styles+='<style>'+st.textContent+'</style>'; });
  try{ w.document.open(); w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Presenter view</title>'+styles+'<style>'+QBR_PRESENTER_CSS+'</style></head><body class="pw-body"><div class="pw-root" id="pw-root"></div></body></html>'); w.document.close(); }catch(e){ return; }
  QBR_PRESENT.win=w; try{w.focus();}catch(e){} QBR_PRESENT._t0=Date.now(); QBR_PRESENT._pausedAcc=0; QBR_PRESENT._paused=false;
  try{ w.addEventListener('beforeunload', function(){ if(QBR_PRESENT){ QBR_PRESENT.win=null; if(QBR_PRESENT._pwTimer){clearInterval(QBR_PRESENT._pwTimer);QBR_PRESENT._pwTimer=null;} if(QBR_PRESENT.editorMode && !document.getElementById('qbr-present-stage')){ QBR_PRESENT=null; } } }); }catch(e){}
  try{ w.addEventListener('resize', function(){ qbrPresenterSync(); }); }catch(e){}
  if(QBR_PRESENT._pwTimer) clearInterval(QBR_PRESENT._pwTimer);
  QBR_PRESENT._pwTimer=setInterval(qbrPresenterTick,500);
  qbrPresenterSync();
}

function qbrEndPresent(){ if(QBR_PRESENT&&QBR_PRESENT._advTimer){ clearTimeout(QBR_PRESENT._advTimer); } var ov=document.getElementById('qbr-present'); if(ov) ov.remove(); document.removeEventListener('keydown', qbrPresentKey, true); window.removeEventListener('resize', qbrPresentFit); if(QBR_PRESENT){ if(QBR_PRESENT._pwTimer){clearInterval(QBR_PRESENT._pwTimer);} if(QBR_PRESENT.win&&!QBR_PRESENT.win.closed){try{QBR_PRESENT.win.close();}catch(e){}} } QBR_PRESENT=null; }
function qbrPresentNextSlide(){ if(!QBR_PRESENT) return; if(QBR_PRESENT.idx<QBR_STATE.slides.length-1){ var ns=QBR_STATE.slides[QBR_PRESENT.idx+1]; qbrPresentShow(QBR_PRESENT.idx+1,(ns.transition&&ns.transition.type)||'none'); } else if(QBR_STATE.showSetup&&QBR_STATE.showSetup.loop){ qbrPresentShow(0,'fade'); } else { qbrEndPresent(); } }
function qbrPresentFit(){ var stage=document.getElementById('qbr-present-stage'); var sl=document.getElementById('qbr-present-slide'); if(!stage||!sl) return; var sc=Math.min((window.innerWidth-40)/960,(window.innerHeight-90)/540); sl.style.transform='scale('+sc+')'; }
function qbrPresentShow(idx, transType){ var stage=document.getElementById('qbr-present-stage'); if(!stage||!QBR_PRESENT) return; setTimeout(qbrMountPresentRef,0); var slide=QBR_STATE.slides[idx]; if(!slide) return; qbrSyncSlidePlaceholders(slide); QBR_PRESENT.idx=idx; QBR_PRESENT.step=0; var scs=qbrSafeScards(); var sc=scs&&scs.map[QBR_STATE.previewVal]; var master=QBR_STATE.template.master||{elements:[]}; var layoutObj=qbrLayoutFor(slide); var bg='background:'+(qbrEffBg(slide, layoutObj)||'#fff')+';'; var _pShowM=!(slide.hideBg||(layoutObj&&layoutObj.hideBg)); var _pShowLC=!slide.hideBg; var html='<div class="qbr-present-slide qbr-freecanvas" id="qbr-present-slide" style="'+bg+'">'; if(_pShowM) html+=(master.elements||[]).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join(''); if(_pShowLC) html+=qbrLayoutChrome(layoutObj).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join(''); if(_pShowLC) html+=qbrHfElements(slide).map(function(el){return qbrRenderElement(el,sc,scs,false);}).join(''); var ln=qbrSlideAnims(slide).length; QBR_STATE._slideFilter=slide.filter||null; html+=(slide.elements||[]).map(function(el,i){return qbrRenderElement(el,sc,scs,false);}).join(''); QBR_STATE._slideFilter=null; html+='</div>'; stage.innerHTML=html; qbrPresentFit(); var sl=document.getElementById('qbr-present-slide'); if(transType&&transType!=='none'){ var t=QBR_TRANS[transType]; if(t&&t.css){ var trd=(slide.transition&&slide.transition.dir)||'l'; sl.style.removeProperty('--qtr-tf'); sl.style.removeProperty('--qtr-clip'); if(t.dir){ var _tf=qbrTransFrom(transType,trd); if(_tf) sl.style.setProperty('--qtr-tf',_tf); if(transType==='wipe') sl.style.setProperty('--qtr-clip',qbrTransClip(trd)); } var dur=(transType==='cut')?130:((slide.transition&&slide.transition.dur)||700); var _ease=(transType==='cut')?'steps(1,end)':'cubic-bezier(.22,.61,.36,1)'; sl.style.animation='qa-'+t.css+' '+dur+'ms '+_ease+' both'; } } QBR_PRESENT.steps=qbrBuildSteps(slide); (slide.elements||[]).forEach(function(el){ if((el.anim||[]).some(function(a){return (QBR_ANIM_FX[a.fx]||{}).kind==='entrance';})){ var n=sl.querySelector('[data-elid="'+el.id+'"]'); if(n) n.style.visibility='hidden'; } }); var num=document.getElementById('qbr-present-num'); if(num) num.textContent=(idx+1)+' / '+QBR_STATE.slides.length; try{qbrPresenterSync();}catch(e){} if(QBR_PRESENT._advTimer){ clearTimeout(QBR_PRESENT._advTimer); QBR_PRESENT._advTimer=null; } if(slide.advanceAfter>0){ QBR_PRESENT._advTimer=setTimeout(qbrPresentNextSlide, slide.advanceAfter*1000); } }
function qbrPresentAdvance(dir){ if(!QBR_PRESENT) return; if(QBR_PRESENT._advTimer){ clearTimeout(QBR_PRESENT._advTimer); QBR_PRESENT._advTimer=null; } if(dir>0){ if(QBR_PRESENT.step<QBR_PRESENT.steps.length){ var sl=document.getElementById('qbr-present-slide'); qbrPlaySeq(QBR_PRESENT.steps[QBR_PRESENT.step], sl); QBR_PRESENT.step++; var cur=QBR_STATE.slides[QBR_PRESENT.idx]; if(cur&&cur.advanceAfter>0&&QBR_PRESENT.step>=QBR_PRESENT.steps.length){ QBR_PRESENT._advTimer=setTimeout(qbrPresentNextSlide, cur.advanceAfter*1000); } } else { qbrPresentNextSlide(); } } else { if(QBR_PRESENT.idx>0){ qbrPresentShow(QBR_PRESENT.idx-1,'none'); var sl=document.getElementById('qbr-present-slide'); if(sl) sl.querySelectorAll('[data-elid]').forEach(function(n){ n.style.visibility='visible'; }); QBR_PRESENT.step=QBR_PRESENT.steps.length; } } }
function qbrRenderRibbonTabs(){
const el=document.getElementById('qbr-ribbon-tabs'); if(!el) return;
const editing = QBR_STATE.designMode || QBR_STATE.mode!=='preview';
if(!editing){ el.style.display='none'; el.innerHTML=''; return; } el.style.display='';
const tab=QBR_STATE.ribbonTab||'home';
const tabs=[['home','Home'],['insert','Insert'],['transitions','Transitions'],['animate','Animations'],['slideshow','Slideshow'],['arrange','Arrange']];
el.innerHTML=tabs.map(function(t){return '<button class="qbr-rtab'+(tab===t[0]?' on':'')+'" data-rtab="'+t[0]+'">'+t[1]+'</button>';}).join('');
el.querySelectorAll('[data-rtab]').forEach(function(b){ b.addEventListener('click', function(){ QBR_STATE.ribbonTab=b.dataset.rtab; qbrRenderRibbonTabs(); qbrRenderRibbon(); }); });
}
function qbrRenderRibbon(){
const rb=document.getElementById('qbr-ribbon'); if(!rb) return;
const editing = QBR_STATE.designMode || QBR_STATE.mode!=='preview';
if(!editing){ rb.style.display='none'; rb.innerHTML=''; qbrCloseAnimStudio(); qbrCloseTransStudio(); qbrCloseArrangeStudio(); qbrCloseElemStudio(); return; } rb.style.display='';
const tab=QBR_STATE.ribbonTab||'home';
const objs=qbrSelObjs(); let primary=null;
if(QBR_STATE.selEl){ const slide=qbrActiveSlide(); primary=(slide.elements||[]).find(function(x){return x.id===QBR_STATE.selEl;}); }
if(!primary && objs.length) primary=objs[0];
const multi=objs.length>1; const sameType=objs.length<=1||(primary&&objs.every(function(o){return o.type===primary.type;})); const type=(sameType&&primary)?primary.type:null;
const pdef = primary || {align:'l',size:18,font:'',case:'',listStyle:'none',listLevel:0};
let h='';
if(tab==='home'){
h+=qbrEmitClipboardGroup();
if(!type || type==='text'){ h+=qbrEmitQuickStyleGroup(); h+=qbrEmitFontGroup(pdef); h+=qbrEmitParaGroup(pdef); }
if(type && type!=='text' && type!=='kpi') h+=qbrEmitContextGroup(pdef, type);
if(type==='shape'){ h+=qbrEmitEffectsGroup(pdef); h+=qbrEmitShapeStyleGroup(); }
if(!primary) h+='<div class="qbr-ribbon-hint">Select an element to format, or use the Insert tab to add one</div>';
} else if(tab==='insert'){
h+=qbrEmitInsertGroups();
h+=qbrRibGroup('Symbols','<button class="qbr-fb-txt" data-symbol-open="1" title="Insert symbol or special character">Ω Symbol</button>');
} else if(tab==='transitions'){
h+=qbrRibGroup('Transitions','<button class="qbr-fb-txt" data-trans-preview="1" title="Preview the transition on this slide">\u25b8 Preview</button>');
h+='<div class="qbr-ribbon-hint">Effects, direction, timing &amp; advance are in the Transitions panel \u2192</div>';
} else if(tab==='animate'){
h+=qbrRibGroup('Animations','<button class="qbr-fb-txt" data-anim-preview="1" title="Play all animations on this slide">\u25b8 Play all</button>');
h+='<div class="qbr-ribbon-hint">Effects, timing &amp; sequence are in the Animations panel \u2192</div>';
} else if(tab==='slideshow'){
h+=qbrEmitSlideshowStart();
h+=qbrEmitSetupGroup();
} else if(tab==='arrange'){
h+='<div class="qbr-ribbon-hint">Position, order, align, rotate &amp; group are in the Arrange panel \u2192</div>';
}
rb.innerHTML=h;
qbrWireFormatBar(rb); qbrWireRibbon(rb);
if(tab==='animate'){ qbrRenderAnimStudio(); } else { qbrCloseAnimStudio(); }
if(tab==='transitions'){ qbrRenderTransStudio(); } else { qbrCloseTransStudio(); }
if(tab!=='insert'){ qbrCloseElemStudio(); }
if(tab==='arrange'){ qbrRenderArrangeStudio(); } else { qbrCloseArrangeStudio(); }
}
function qbrWireRibbon(rb){
rb.querySelectorAll('[data-ins]').forEach(function(b){ b.addEventListener('click', function(){ qbrInsertEl(b.dataset.ins); }); });
rb.querySelectorAll('[data-ins-shape]').forEach(function(b){ b.addEventListener('click', function(){ qbrInsertShape(b.dataset.insShape); }); });
rb.querySelectorAll('[data-ins-lib]').forEach(function(b){ b.addEventListener('click', function(){ qbrRenderElemStudio(); }); });
rb.querySelectorAll('[data-el-picker]').forEach(function(b){ b.addEventListener('click', function(){ qbrOpenElPicker(); }); });
rb.querySelectorAll('[data-fb-cmenu]').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); qbrOpenColorMenu(b, b.dataset.fbCmenu); }); });
rb.querySelectorAll('[data-textstyle]').forEach(function(s){ s.addEventListener('change', function(){ var i=+s.value; var st=qbrTextStyles()[i]; if(!st||i===0) return; qbrApplySel(function(el){ if(el.type!=='text') return; if(st.size!=null) el.size=st.size; el.bold=!!st.bold; if(st.color!=null) el.color=st.color; }); }); });
rb.querySelectorAll('[data-shapestyle]').forEach(function(b){ b.addEventListener('click', function(){ var st=qbrShapeStyles()[+b.dataset.shapestyle]; if(!st) return; qbrApplySel(function(el){ if(el.type!=='shape') return; el.fill=st.fill; el.stroke=st.stroke; el.strokeW=st.strokeW||1; if(el.gradient) delete el.gradient; }); }); });
var symo=rb.querySelector('[data-symbol-open]'); if(symo) symo.addEventListener('click', function(e){ e.stopPropagation(); qbrOpenSymbolMenu(symo); });
var grado=rb.querySelector('[data-fb-gradient]'); if(grado) grado.addEventListener('click', function(e){ e.stopPropagation(); qbrOpenGradientMenu(grado); });
rb.querySelectorAll('[data-anim-set]').forEach(function(b){ b.addEventListener('click', function(){ qbrApplyAnim(b.dataset.animSet, true); }); });
var ag=rb.querySelector('[data-anim-gallery]'); if(ag) ag.addEventListener('click', function(e){ e.stopPropagation(); qbrOpenAnimGallery(ag); });
var adir=rb.querySelector('[data-anim-dir]'); if(adir) adir.addEventListener('change', function(){ qbrEditActiveAnim(function(a){ a.dir=adir.value; }); });
var astart=rb.querySelector('[data-anim-start]'); if(astart) astart.addEventListener('change', function(){ qbrEditActiveAnim(function(a){ a.start=astart.value; }); });
rb.querySelectorAll('[data-anim-dur]').forEach(function(b){ var d=+b.dataset.animDur; b.addEventListener('click', function(){ qbrEditActiveAnim(function(a){ a.dur=Math.max(100,Math.min(10000,(a.dur||500)+d*250)); }); }); });
var adurv=rb.querySelector('[data-anim-durv]'); if(adurv) adurv.addEventListener('change', function(){ var v=parseFloat(adurv.value); if(!isNaN(v)) qbrEditActiveAnim(function(a){ a.dur=Math.max(100,Math.min(10000,Math.round(v*1000))); }); });
rb.querySelectorAll('[data-anim-delay]').forEach(function(b){ var d=+b.dataset.animDelay; b.addEventListener('click', function(){ qbrEditActiveAnim(function(a){ a.delay=Math.max(0,Math.min(20000,(a.delay||0)+d*250)); }); }); });
var adlv=rb.querySelector('[data-anim-delayv]'); if(adlv) adlv.addEventListener('change', function(){ var v=parseFloat(adlv.value); if(!isNaN(v)) qbrEditActiveAnim(function(a){ a.delay=Math.max(0,Math.min(20000,Math.round(v*1000))); }); });
rb.querySelectorAll('[data-anim-move]').forEach(function(b){ b.addEventListener('click', function(){ qbrMoveAnim(+b.dataset.animMove); }); });
var arem=rb.querySelector('[data-anim-remove]'); if(arem) arem.addEventListener('click', qbrRemoveActiveAnim);
var apv=rb.querySelector('[data-anim-preview]'); if(apv) apv.addEventListener('click', qbrPreviewAnims);
var apane=rb.querySelector('[data-anim-pane]'); if(apane) apane.addEventListener('click', qbrTogglePane);
rb.querySelectorAll('[data-trans]').forEach(function(b){ b.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(!slide) return; qbrSnapshot(); var k=b.dataset.trans; if(k==='none'){ delete slide.transition; } else { slide.transition=slide.transition||{}; slide.transition.type=k; if(!slide.transition.dur) slide.transition.dur=700; if(QBR_TRANS[k].dir&&!slide.transition.dir) slide.transition.dir='l'; } qbrRenderCanvas(); }); });
rb.querySelectorAll('[data-trans-preview]').forEach(function(b){ b.addEventListener('click', function(){ qbrPreviewTransition(); }); });
var tdir=rb.querySelector('[data-trans-dir]'); if(tdir) tdir.addEventListener('change', function(){ var slide=qbrActiveSlide(); if(slide&&slide.transition){ qbrSnapshot(); slide.transition.dir=tdir.value; qbrRenderCanvas(); } });
rb.querySelectorAll('[data-trans-dur]').forEach(function(b){ var d=+b.dataset.transDur; b.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(slide&&slide.transition){ qbrSnapshot(); slide.transition.dur=Math.max(200,Math.min(5000,(slide.transition.dur||700)+d*250)); qbrRenderCanvas(); } }); });
var tdurv=rb.querySelector('[data-trans-durv]'); if(tdurv) tdurv.addEventListener('change', function(){ var v=parseFloat(tdurv.value); var slide=qbrActiveSlide(); if(!isNaN(v)&&slide&&slide.transition){ qbrSnapshot(); slide.transition.dur=Math.max(200,Math.min(5000,Math.round(v*1000))); qbrRenderCanvas(); } });
var tall=rb.querySelector('[data-trans-all]'); if(tall) tall.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(!slide||!slide.transition) return; qbrSnapshot(); var tr=JSON.parse(JSON.stringify(slide.transition)); QBR_STATE.slides.forEach(function(s){ s.transition=JSON.parse(JSON.stringify(tr)); }); if(typeof showActionToast==='function') showActionToast('Transition applied to all '+QBR_STATE.slides.length+' slides'); qbrRenderCanvas(); });
rb.querySelectorAll('[data-present]').forEach(function(b){ b.addEventListener('click', function(){ if(b.dataset.present==='presenter'){ qbrOpenPresenter(); } else { qbrStartPresent(b.dataset.present==='current'); } }); });
var sloop=rb.querySelector('[data-show-loop]'); if(sloop) sloop.addEventListener('change', function(){ QBR_STATE.showSetup=QBR_STATE.showSetup||{}; QBR_STATE.showSetup.loop=sloop.checked; });
var advc=rb.querySelector('[data-adv-click]'); if(advc) advc.addEventListener('change', function(){ var slide=qbrActiveSlide(); if(slide){ qbrSnapshot(); slide.advanceClick=advc.checked; } });
var adva=rb.querySelector('[data-adv-after]'); if(adva) adva.addEventListener('change', function(){ var slide=qbrActiveSlide(); if(!slide) return; qbrSnapshot(); if(adva.checked){ var iv=rb.querySelector('[data-adv-afterv]'); slide.advanceAfter=Math.max(1,parseFloat(iv&&iv.value)||5); } else { delete slide.advanceAfter; } qbrRenderRibbon(); });
rb.querySelectorAll('[data-adv-aftd]').forEach(function(b){ var d=+b.dataset.advAftd; b.addEventListener('click', function(){ var slide=qbrActiveSlide(); if(!slide||!slide.advanceAfter) return; qbrSnapshot(); slide.advanceAfter=Math.max(1,Math.min(600,slide.advanceAfter+d)); qbrRenderRibbon(); }); });
var advv=rb.querySelector('[data-adv-afterv]'); if(advv) advv.addEventListener('change', function(){ var slide=qbrActiveSlide(); var v=parseFloat(advv.value); if(slide&&!isNaN(v)){ qbrSnapshot(); slide.advanceAfter=Math.max(1,Math.min(600,v)); } });
rb.querySelectorAll('[data-fb-radius]').forEach(function(b){ var d=+b.dataset.fbRadius; b.addEventListener('click', function(){ qbrApplySel(function(el){ if(el.type!=='shape') return; el.radius=Math.max(0,Math.min(0.5,(el.radius!=null?el.radius:0.12)+d*0.04)); }); }); });
rb.querySelectorAll('input[data-fb-radiuspct]').forEach(function(inp){ inp.addEventListener('change', function(){ var v=parseFloat(inp.value); if(isNaN(v)) return; qbrApplySel(function(el){ if(el.type!=='shape') return; el.radius=Math.max(0,Math.min(0.5,v/100)); }); }); });
rb.querySelectorAll('[data-fb-clip]').forEach(function(b){ b.addEventListener('click', function(){ const op=b.dataset.fbClip;
if(op==='copy'){ const o=qbrSelObjs(); if(o.length) QBR_CLIP=JSON.parse(JSON.stringify(o)); }
else if(op==='cut'){ const o=qbrSelObjs(); if(o.length){ QBR_CLIP=JSON.parse(JSON.stringify(o)); qbrSnapshot(); const slide=qbrActiveSlide(); const ids=o.map(function(x){return x.id;}); slide.elements=(slide.elements||[]).filter(function(x){return ids.indexOf(x.id)<0;}); qbrSelClear(); qbrRenderCanvas(); qbrRenderInspector(); } }
else if(op==='paste'){ if(QBR_CLIP&&QBR_CLIP.length) qbrPasteClip(); }
else if(op==='painter'){ if(qbrCopyFormat()&&typeof showActionToast==='function') showActionToast('Formatting copied — select a target, then ⌘⇧V to apply'); }
}); });
}
function qbrInsertShape(shape){ const slide=qbrActiveSlide(); if(!slide) return; let el; if(shape==='line'){ el=qbrElShape('line'); el.x=0.3; el.y=0.5; el.w=0.4; el.h=0.02; el.fill=null; el.stroke='#4E79A7'; el.strokeW=2; } else { el=qbrElShape(shape); } qbrSnapshot(); slide.elements.push(el); QBR_STATE.selEl=el.id; QBR_STATE.selEls=[el.id]; QBR_STATE.editingEl=null; QBR_STATE.mode='edit'; qbrRenderCanvas(); qbrRenderInspector(); }
// ---- popover infra ----
var QBR_POP_ANCHOR=null, QBR_POP_CLOSED={anchor:null,t:0};
function qbrClosePopover(){ var p=document.getElementById('qbr-pop'); if(p){ p.remove(); QBR_POP_CLOSED={anchor:QBR_POP_ANCHOR,t:Date.now()}; } QBR_POP_ANCHOR=null; document.removeEventListener('mousedown', qbrPopOutside, true); }
function qbrPopOutside(e){ var p=document.getElementById('qbr-pop'); if(!p) return; if(QBR_POP_ANCHOR && (e.target===QBR_POP_ANCHOR || (QBR_POP_ANCHOR.contains && QBR_POP_ANCHOR.contains(e.target)))) return; if(!p.contains(e.target)) qbrClosePopover(); }
function qbrOpenPopover(anchor, html, cls){ var ex=document.getElementById('qbr-pop'); if(ex && QBR_POP_ANCHOR===anchor){ qbrClosePopover(); return null; } if(QBR_POP_CLOSED.anchor===anchor && (Date.now()-QBR_POP_CLOSED.t)<350){ QBR_POP_CLOSED={anchor:null,t:0}; return null; } qbrClosePopover(); var pop=document.createElement('div'); pop.id='qbr-pop'; pop.className='qbr-pop '+(cls||''); pop.innerHTML=html; document.body.appendChild(pop); QBR_POP_ANCHOR=anchor; var r=anchor.getBoundingClientRect(); var left=Math.max(8, Math.min(window.innerWidth-pop.offsetWidth-8, r.left)); var top=r.bottom+5; if(top+pop.offsetHeight>window.innerHeight-8) top=Math.max(8, r.top-pop.offsetHeight-5); pop.style.left=left+'px'; pop.style.top=top+'px'; setTimeout(function(){ document.addEventListener('mousedown', qbrPopOutside, true); },0); return pop; }
function qbrTint(hex, t){ hex=String(hex||'#888888').replace('#',''); if(hex.length===3) hex=hex.split('').map(function(c){return c+c;}).join(''); var r=parseInt(hex.slice(0,2),16)||0,g=parseInt(hex.slice(2,4),16)||0,b=parseInt(hex.slice(4,6),16)||0; r=Math.round(r+(255-r)*t); g=Math.round(g+(255-g)*t); b=Math.round(b+(255-b)*t); return '#'+[r,g,b].map(function(x){return ('0'+x.toString(16)).slice(-2);}).join(''); }
// ---- color menu (theme + standard palette) ----
function qbrThemeColorList(){ var t=(QBR_STATE.template&&QBR_STATE.template.theme)||{}; var list=[{v:'accent',css:qbrResolveShapeColor('accent'),n:'Accent'},{v:'title',css:qbrResolveShapeColor('title'),n:'Title'},{v:'muted',css:qbrResolveShapeColor('muted'),n:'Muted'},{v:'#2E7D32',css:'#2E7D32',n:'Positive'},{v:'#C62828',css:'#C62828',n:'Negative'},{v:'#C9A227',css:'#C9A227',n:'Gold'}]; (t.accents||[]).slice(0,6).forEach(function(a){ list.push({v:'#'+a,css:'#'+a,n:'Theme'}); }); return list; }
var QBR_STD_COLORS=['#000000','#3A3A3A','#6E6E6E','#9A9A9A','#C8C8C8','#FFFFFF','#C62828','#E8833A','#C9A227','#2E7D32','#1A6F8B','#3B5BA5','#6B4FA0','#A84E8B'];
function qbrColorBtn(prop, css, title, isStroke){ return '<button class="qbr-fb-color" data-fb-cmenu="'+prop+'" title="'+title+'"><span style="'+(isStroke?('border:2px solid '+(css||'#999')+';background:#fff;'):('background:'+(css||'#fff')+';'))+'"></span></button>'; }
function qbrOpenColorMenu(anchor, prop){
var allowNone=(prop==='fill'||prop==='stroke'||prop==='highlight');
var th=qbrThemeColorList().map(function(s){return '<button class="qbr-sw" data-c="'+s.v+'" title="'+s.n+'" style="background:'+s.css+'"></button>';}).join('');
var st=QBR_STD_COLORS.map(function(c){return '<button class="qbr-sw" data-c="'+c+'" title="'+c+'" style="background:'+c+'"></button>';}).join('');
var h='<div class="qbr-pop-sec">Theme colors</div><div class="qbr-sw-row">'+th+'</div><div class="qbr-pop-sec">Standard</div><div class="qbr-sw-row">'+st+'</div>';
if(prop==='color') h+='<button class="qbr-pop-item" data-set="auto">↺ Automatic (theme)</button>';
if(allowNone) h+='<button class="qbr-pop-item" data-set="__none__">⊘ No '+(prop==='highlight'?'highlight':(prop==='fill'?'fill':'outline'))+'</button>';
h+='<label class="qbr-pop-item">＋ More colors…<input type="color" data-custom="1" style="margin-left:auto;width:26px;height:22px;border:none;background:none;padding:0;"></label>';
var pop=qbrOpenPopover(anchor, h, 'qbr-color-pop'); if(!pop) return;
pop.querySelectorAll('[data-c]').forEach(function(b){ b.addEventListener('click', function(){ var v=b.dataset.c; qbrApplySel(function(el){ el[prop]=v; if(prop==='fill'&&el.gradient) delete el.gradient; }); qbrClosePopover(); }); });
pop.querySelectorAll('[data-set]').forEach(function(b){ b.addEventListener('click', function(){ var v=b.dataset.set==='__none__'?null:b.dataset.set; qbrApplySel(function(el){ el[prop]=v; if(prop==='fill'&&el.gradient) delete el.gradient; }); qbrClosePopover(); }); });
var cu=pop.querySelector('[data-custom]'); if(cu) cu.addEventListener('input', function(){ qbrApplySel(function(el){ el[prop]=cu.value; if(prop==='fill'&&el.gradient) delete el.gradient; }); });
}
// ---- shape style presets ----
function qbrShapeStyles(){ var ac=qbrResolveShapeColor('accent'), ti=qbrResolveShapeColor('title'); return [
{fill:ac,stroke:null,strokeW:0,n:'Accent fill'},
{fill:qbrTint(ac,0.84),stroke:ac,strokeW:1,n:'Light tint'},
{fill:null,stroke:ac,strokeW:2,n:'Outline'},
{fill:'#F4F6F8',stroke:'#D8DCE1',strokeW:1,n:'Subtle'},
{fill:ti,stroke:null,strokeW:0,n:'Dark'},
{fill:'#C9A227',stroke:null,strokeW:0,n:'Gold'},
{fill:'#2E7D32',stroke:null,strokeW:0,n:'Positive'},
{fill:'#C62828',stroke:null,strokeW:0,n:'Negative'}
]; }
function qbrEmitShapeStyleGroup(){
var sw=qbrShapeStyles().map(function(s,i){ var bg=s.fill?('background:'+s.fill+';'):'background:#fff;'; var bd=s.stroke?('border:'+(s.strokeW>1?2:1)+'px solid '+s.stroke+';'):'border:1px solid rgba(0,0,0,0.12);'; return '<button class="qbr-shapestyle" data-shapestyle="'+i+'" title="'+s.n+'" style="'+bg+bd+'"></button>'; }).join('');
return qbrRibGroup('Shape styles', sw);
}
// ---- shape effects: shadow presets, gradient fill, corner radius ----
function qbrEmitEffectsGroup(p){
var shLab={'':'No shadow','soft':'Soft shadow','medium':'Shadow','strong':'Strong shadow','glow':'Glow'};
var cur=p.shadow===true?'medium':(p.shadow||'');
var h='<select class="qbr-fb-sel" data-fb="shadow" title="Shadow effect">'+['','soft','medium','strong','glow'].map(function(k){return '<option value="'+k+'"'+(cur===k?' selected':'')+'>◍ '+shLab[k]+'</option>';}).join('')+'</select>';
h+='<button class="qbr-fb-b'+(p.gradient?' on':'')+'" data-fb-gradient="1" title="Gradient fill">▰</button>';
if(p.shape==='roundRect') h+='<span class="qbr-fb-stepper" title="Corner radius %"><button data-fb-radius="-1">−</button><input class="qbr-fb-num" data-fb-radiuspct="1" value="'+Math.round((p.radius!=null?p.radius:0.12)*100)+'"><button data-fb-radius="1">+</button></span>';
return qbrRibGroup('Effects', h);
}
function qbrGradientPresets(){ var ac=qbrResolveShapeColor('accent'), ti=qbrResolveShapeColor('title'); return [
{n:'Accent fade',a:ac,b:qbrTint(ac,0.55),angle:90},
{n:'Deep',a:ti,b:ac,angle:90},
{n:'Gold sheen',a:'#C9A227',b:qbrTint('#C9A227',0.5),angle:120},
{n:'Steel',a:'#5B6770',b:qbrTint('#5B6770',0.5),angle:90},
{n:'Positive',a:'#2E7D32',b:qbrTint('#2E7D32',0.55),angle:90},
{n:'Subtle',a:'#FFFFFF',b:'#E9EDF1',angle:135}
]; }
function qbrOpenGradientMenu(anchor){
var sw=qbrGradientPresets().map(function(g,i){return '<button class="qbr-shapestyle" data-grad="'+i+'" title="'+g.n+'" style="background:linear-gradient('+g.angle+'deg,'+g.a+','+g.b+');"></button>';}).join('');
var pop=qbrOpenPopover(anchor,'<div class="qbr-pop-sec">Gradient fill</div><div class="qbr-sw-row">'+sw+'</div><button class="qbr-pop-item" data-grad="none">⊘ No gradient (solid)</button>','qbr-grad-pop'); if(!pop) return;
pop.querySelectorAll('[data-grad]').forEach(function(b){ b.addEventListener('click',function(){ var v=b.dataset.grad; if(v==='none'){ qbrApplySel(function(el){ if(el.gradient) delete el.gradient; }); } else { var g=qbrGradientPresets()[+v]; qbrApplySel(function(el){ if(el.type==='shape'){ el.gradient={a:g.a,b:g.b,angle:g.angle}; } }); } qbrClosePopover(); }); });
}
// ---- text quick styles ----
function qbrTextStyles(){ return [
{n:'Style…'},
{n:'Title',size:32,bold:true,color:'title'},
{n:'Heading',size:24,bold:true,color:'title'},
{n:'Subheading',size:18,bold:false,color:'muted'},
{n:'Body',size:14,bold:false,color:'auto'},
{n:'Caption',size:11,bold:false,color:'muted'},
{n:'Emphasis',size:16,bold:true,color:'accent'},
{n:'Big number',size:40,bold:true,color:'accent'}
]; }
function qbrEmitQuickStyleGroup(){
var opts=qbrTextStyles().map(function(s,i){return '<option value="'+i+'">'+s.n+'</option>';}).join('');
return qbrRibGroup('Quick styles','<select class="qbr-fb-sel" data-textstyle="1" title="Apply a text style" style="min-width:104px;">'+opts+'</select>');
}
// ---- symbols / special characters ----
var QBR_SYMBOLS=['×','÷','±','≈','≠','≤','≥','∞','→','←','↑','↓','↔','↗','↘','•','◦','▪','§','¶','©','®','™','°','′','″','€','£','¥','¢','½','¼','¾','⅓','№','✓','✗','★','☆','▲','▼','◆','●','■','–','—','…','✦'];
function qbrOpenSymbolMenu(anchor){
var grid=QBR_SYMBOLS.map(function(s){return '<button class="qbr-sym" data-symbol="'+s+'">'+s+'</button>';}).join('');
var pop=qbrOpenPopover(anchor, '<div class="qbr-pop-sec">Insert symbol</div><div class="qbr-sym-grid">'+grid+'</div>', 'qbr-sym-pop'); if(!pop) return;
pop.querySelectorAll('[data-symbol]').forEach(function(b){ b.addEventListener('click', function(){ qbrInsertSymbol(b.dataset.symbol); qbrClosePopover(); }); });
}
function qbrInsertSymbol(sym){
var ce=document.querySelector('.qbr-ce[data-elid]');
if(ce && QBR_STATE.editingEl){ ce.focus(); try{ document.execCommand('insertText',false,sym); }catch(e){ ce.textContent=(ce.textContent||'')+sym; } var el0=(qbrActiveSlide().elements||[]).find(function(x){return x.id===QBR_STATE.editingEl;}); if(el0) qbrCommitRuns(el0, ce); return; }
var slide=qbrActiveSlide(); if(!slide) return;
var sel=QBR_STATE.selEl&&(slide.elements||[]).find(function(x){return x.id===QBR_STATE.selEl;});
if(sel && sel.type==='text' && !sel.auto){ qbrSnapshot(); sel.text=(sel.text||'')+sym; if(sel.runs) delete sel.runs; qbrRenderCanvas(); qbrRenderInspector(); return; }
var el=qbrElText({x:0.45,y:0.45,w:0.12,h:0.1,text:sym,size:28}); qbrSnapshot(); slide.elements.push(el); QBR_STATE.selEl=el.id; QBR_STATE.selEls=[el.id]; QBR_STATE.mode='edit'; qbrRenderCanvas(); qbrRenderInspector(); }
/* ===== Slide-text variable autocomplete — type "[" while editing text to get a live token picker. ===== */
function qbrACTokens(){ return [
  {t:'supplier', g:'Loop', d:'Current loop value \u2014 the supplier/category being previewed'},
  {t:'period', g:'Context', d:'Reporting period label (e.g. R12)'},
  {t:'rank', g:'Context', d:'Rank within the peer set (ordinal)'},
  {t:'peer_count', g:'Context', d:'Number of peers in the comparison set'},
  {t:'volume_growth', g:'Metric', d:'9L volume growth %'},
  {t:'revenue_growth', g:'Metric', d:'Revenue growth %'},
  {t:'pod_growth', g:'Metric', d:'Points-of-distribution growth %'},
  {t:'headroom_pt', g:'Metric', d:'Distribution headroom remaining'}
]; }
let _qbrAC = null;
function qbrACEl(){ let d=document.getElementById('qbr-ac'); if(!d){ d=document.createElement('div'); d.id='qbr-ac'; d.className='qbr-ac'; document.body.appendChild(d); } return d; }
function qbrACClose(){ const d=document.getElementById('qbr-ac'); if(d) d.style.display='none'; _qbrAC=null; }
function qbrACScan(ce){
  const sel=window.getSelection(); if(!sel||!sel.rangeCount) return null;
  const r=sel.getRangeAt(0); if(!r.collapsed||!ce.contains(r.startContainer)) return null;
  const node=r.startContainer; if(node.nodeType!==3) return null;
  const before=node.textContent.slice(0, r.startOffset);
  const m=/\[([a-z_]*)$/i.exec(before); if(!m) return null;
  return {partial:m[1].toLowerCase(), node:node, offset:r.startOffset, brk:m.index};
}
function qbrACRect(scan){
  try{ const node=scan.node, off=scan.offset; const r=document.createRange();
    if(off>0){ r.setStart(node, off-1); r.setEnd(node, off); } else { r.setStart(node, 0); r.setEnd(node, Math.min(1,node.textContent.length)); }
    const rects=r.getClientRects(); if(rects&&rects.length){ const rc=rects[rects.length-1]; return {left:(off>0?rc.right:rc.left), top:rc.top, bottom:rc.bottom}; }
  }catch(e){}
  return null;
}
function qbrACShow(ce){
  const sc=qbrACScan(ce); if(!sc){ qbrACClose(); return; }
  const p=sc.partial; let items=qbrACTokens().filter(function(x){ return x.t.indexOf(p)>=0 || x.d.toLowerCase().indexOf(p)>=0; });
  items.sort(function(a,b){ return (a.t.indexOf(p)===0?0:1)-(b.t.indexOf(p)===0?0:1); });
  if(!items.length){ qbrACClose(); return; }
  _qbrAC={ce:ce, items:items, sel:0, scan:sc}; qbrACRender();
}
function qbrACRender(){
  if(!_qbrAC) return; const d=qbrACEl();
  d.innerHTML=_qbrAC.items.map(function(x,i){ return '<div class="qbr-ac-item'+(i===_qbrAC.sel?' on':'')+'" data-aci="'+i+'"><div><span class="qbr-ac-tok">['+x.t+']</span><span class="qbr-ac-grp">'+x.g+'</span></div><div class="qbr-ac-desc">'+_qbrEsc(x.d)+'</div></div>'; }).join('');
  let rect=qbrACRect(_qbrAC.scan) || _qbrAC.ce.getBoundingClientRect();
  d.style.display='block';
  const dw=Math.min(320, Math.max(230, d.offsetWidth||260)), dh=Math.min(264, d.offsetHeight||(_qbrAC.items.length*52+10));
  let left=rect.left, top=(rect.bottom||rect.top)+5;
  if(left+dw>window.innerWidth-8) left=window.innerWidth-8-dw;
  if(top+dh>window.innerHeight-8) top=(rect.top||rect.bottom)-dh-5;
  d.style.left=Math.max(8,left)+'px'; d.style.top=Math.max(8,top)+'px';
  d.querySelectorAll('.qbr-ac-item').forEach(function(it){
    it.addEventListener('mousedown', function(e){ e.preventDefault(); qbrACInsert(_qbrAC.ce, _qbrAC.items[+it.dataset.aci]); });
    it.addEventListener('mouseenter', function(){ _qbrAC.sel=+it.dataset.aci; qbrACHi(); });
  });
}
function qbrACHi(){ const d=document.getElementById('qbr-ac'); if(!d||!_qbrAC) return; d.querySelectorAll('.qbr-ac-item').forEach(function(it,i){ it.classList.toggle('on', i===_qbrAC.sel); }); }
function qbrACInsert(ce, item){
  if(!_qbrAC||!item) return; const sc=_qbrAC.scan, node=sc.node;
  if(node && node.nodeType===3){
    const txt=node.textContent, tok='['+item.t+']';
    node.textContent=txt.slice(0,sc.brk)+tok+txt.slice(sc.offset);
    const pos=sc.brk+tok.length;
    try{ const r=document.createRange(); r.setStart(node, Math.min(pos,node.textContent.length)); r.collapse(true); const sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r); }catch(e){}
  }
  qbrACClose();
  try{ const el=(qbrActiveSlide().elements||[]).find(function(x){return x.id===ce.dataset.elid;}); if(el) qbrCommitRuns(el, ce); }catch(e){}
}
function qbrACKey(ce, e){
  if(!_qbrAC) return false;
  if(e.key==='ArrowDown'){ e.preventDefault(); _qbrAC.sel=(_qbrAC.sel+1)%_qbrAC.items.length; qbrACHi(); return true; }
  if(e.key==='ArrowUp'){ e.preventDefault(); _qbrAC.sel=(_qbrAC.sel-1+_qbrAC.items.length)%_qbrAC.items.length; qbrACHi(); return true; }
  if(e.key==='Enter'||e.key==='Tab'){ e.preventDefault(); e.stopPropagation(); qbrACInsert(ce, _qbrAC.items[_qbrAC.sel]); return true; }
  if(e.key==='Escape'){ e.preventDefault(); e.stopPropagation(); qbrACClose(); return true; }
  return false;
}
function qbrACWire(ce){
  if(ce.dataset.acWired) return; ce.dataset.acWired='1';
  ce.addEventListener('input', function(){ qbrACShow(ce); });
  ce.addEventListener('keydown', function(e){ qbrACKey(ce, e); }, true);
  ce.addEventListener('keyup', function(e){ if(['ArrowLeft','ArrowRight','Home','End'].indexOf(e.key)>=0) qbrACShow(ce); });
  ce.addEventListener('blur', function(){ setTimeout(qbrACClose, 150); });
}
function qbrEnterTextEdit(id, replaceChar){
const slide=qbrActiveSlide(); if(!slide) return; const el=(slide.elements||[]).find(function(x){return x.id===id;});
if(!el||el.type!=='text') return;
qbrSnapshot();
// An auto narrative is generated, not typed. On first edit, detach it into normal editable
// text seeded with the current generated copy so the user can edit it like any text box.
if(el.auto){ try{ var _scs=qbrSafeScards(); var _sc=_scs&&_scs.map[QBR_STATE.previewVal]; el.text=qbrAutoNarrative(_sc, _scs&&_scs.medians).join('\n\n'); }catch(_e){ el.text=el.text||''; } if(el.runs) delete el.runs; el.auto=false; }
QBR_STATE.selEl=id; QBR_STATE.selEls=[id]; QBR_STATE.editingEl=id; QBR_STATE.mode='edit';
if(replaceChar!=null){ el.text=replaceChar; if(el.runs) delete el.runs; }
qbrRenderCanvas(); qbrRenderInspector();
var _c=document.querySelector('.qbr-ce[data-elid="'+id+'"]'); if(_c){ _c.focus(); qbrPlaceCaretEnd(_c); }
setTimeout(function(){ const c=document.querySelector('.qbr-ce[data-elid="'+id+'"]'); if(c && document.activeElement!==c){ c.focus(); qbrPlaceCaretEnd(c); } },0);
}
function qbrInsertEl(kind, opts){
const slide=qbrActiveSlide(); if(!slide) return;
if(typeof QBR_CFG_KINDS!=='undefined' && QBR_CFG_KINDS[kind] && !(opts&&opts._cfg)){ qbrOpenChartCfg(kind); return; }
let el;
if(kind==='icon'){ qbrOpenIconPicker(function(name){ if(!name) return; const e2=qbrElIcon(name); qbrSnapshot(); slide.elements.push(e2); QBR_STATE.selEl=e2.id; QBR_STATE.selEls=[e2.id]; QBR_STATE.editingEl=null; QBR_STATE.mode='edit'; qbrRenderCanvas(); qbrRenderInspector(); }); return; }
if(kind==='text') el=qbrElText({x:0.3,y:0.42,w:0.4,h:0.12, text:'', size:20});
else if(kind==='image') el=qbrElImage();
else if(kind==='table') el=qbrElTable();
else if(kind==='datatable'){ el=qbrElTable(); el.style='tight'; el.totalRow=true; }
else if(kind==='callout') el=qbrElCallout();
else if(kind==='statrow') el=qbrElStatRow();
else if(kind==='titleblock') el=qbrElTitleBlock();
else if(kind && kind.indexOf('dgm_')===0) el=qbrElDiagram(kind.slice(4));
else if(kind==='rect') el=qbrElShape('rect');
else if(kind==='ellipse') el=qbrElShape('ellipse');
else if(kind==='line'){ el=qbrElShape('line'); el.x=0.3; el.y=0.5; el.w=0.4; el.h=0.02; el.fill=null; el.stroke='#4E79A7'; el.strokeW=2; }
else if(kind==='chart') el=qbrElChart();
else if(kind==='kpi') el=qbrElKpi();
else if(kind==='bridge') el=qbrElBridge();
else if(kind==='matrix') el=qbrElMatrix();
else if(kind==='placeholder') el=qbrElPlaceholder();
if(!el) return;
qbrSnapshot();
slide.elements.push(el); QBR_STATE.selEl=el.id; QBR_STATE.selEls=[el.id]; QBR_STATE.editingEl=null; QBR_STATE.mode='edit';
qbrRenderCanvas(); qbrRenderInspector();
if(kind==='text') qbrEnterTextEdit(el.id);
else if(kind==='image') qbrPickImage(el);
}
function qbrPickImage(el){
const inp=document.createElement('input'); inp.type='file'; inp.accept='image/png,image/jpeg,image/gif';
inp.onchange=function(){ const f=inp.files&&inp.files[0]; if(!f) return; const rd=new FileReader(); rd.onload=function(){ el.src=rd.result; qbrRenderCanvas(); qbrRenderInspector(); }; rd.readAsDataURL(f); };
inp.click();
}
function qbrElColorCss(c){ const t=QBR_STATE.template.theme; if(!c||c==='auto') return '#'+t.bodyColor; if(c==='title') return '#'+t.titleColor; if(c==='accent') return '#'+t.accent; if(c==='muted') return '#'+t.mutedColor; return String(c).charAt(0)==='#'?c:'#'+c; }
