let html=lines.map(function(l,i){ const pfx=lst==='bullet'?'\u2022\u00a0':(lst==='number'?((i+1)+'.\u00a0'):''); let t=pfx+l; if(el.highlight) t='<span style="background:'+el.highlight+';border-radius:2px;padding:0 1px;box-decoration-break:clone;-webkit-box-decoration-break:clone;">'+t+'</span>'; return t; }).join('<br>');
