var bf=qbrFontStack(t.bodyFont);
var acc='#'+String(t.accent||'1A3A5C').replace('#','');
var items=qbrDiagramItems(el); var n=items.length; var V=el.variant||'process';
var VBW=1000, VBH=520;
function esc(x){ return _qbrEsc(String(x==null?'':x)); }
