// A plain-English READ of the slide's numbers (what stands out vs the spirits composite) — value-add
// context for the talk track, NOT a re-print of the Supporting-detail table (which stays in the right drawer).
function qbrDataContext(slide, sc, scs){
  if(!sc || !sc.metrics || !Object.keys(sc.metrics).length) return '<div class="qbr-ref-empty">Add a KPI or chart to this slide — a plain-English read of the numbers appears here (the full figures live in Supporting detail).</div>';
  var meds=(scs&&scs.medians)||{};
  var subject=(sc.label||QBR_STATE.previewVal||'This segment');
  var num=function(x){ if(typeof x==='number') return x; if(x==null||x==='') return NaN; return parseFloat(String(x).replace(/[^0-9.\-]/g,'')); };
  var rows=[]; Object.keys(sc.metrics).forEach(function(k){ var v=num(sc.metrics[k]), m=num(meds[k]); if(isNaN(v)||isNaN(m)) return; rows.push({label:qbrMeasureLabel(k), delta:+(v-m).toFixed(1)}); });
  if(!rows.length) return '<div class="qbr-ref-empty">No set-comparable metrics on this slide yet.</div>';
  var below=rows.filter(function(r){return r.delta<0;}), atAbove=rows.filter(function(r){return r.delta>=0;});
  var sorted=rows.slice().sort(function(a,b){return a.delta-b.delta;}), worst=sorted[0], best=sorted[sorted.length-1];
  function pt(d){ return (d>0?'+':'')+d+'pt'; }
  var lead=(below.length>atAbove.length)
    ? _qbrEsc(subject)+' trails the spirits composite on '+below.length+' of '+rows.length+' metrics.'
    : _qbrEsc(subject)+' is at or ahead of the composite on '+atAbove.length+' of '+rows.length+' metrics.';
  var h='<div class="qbr-ctx"><div class="qbr-ctx-lead">'+lead+'</div><ul class="qbr-ctx-pts">';
  if(worst && worst.delta<0) h+='<li><span class="qbr-ctx-dn">▾</span> <b>Biggest gap:</b> '+_qbrEsc(worst.label)+' '+pt(worst.delta)+' vs set avg.</li>';
  if(best && best.delta>0) h+='<li><span class="qbr-ctx-up">▴</span> <b>Bright spot:</b> '+_qbrEsc(best.label)+' '+pt(best.delta)+' vs set avg.</li>';
  h+='<li>'+atAbove.length+' at/above · '+below.length+' below the set average.</li>';
  h+='</ul><div class="qbr-ctx-note">A read of what stands out — exact figures are in <b>Supporting detail</b> (right). Use it to shape the speaker notes.</div></div>';
  return h;
}
// Build the right-edge reference drawer used in both the studio canvas and the present viewer.
// host: the positioned container to mount into. open: whether the body starts revealed.
// onToggle(nowOpen): called when the arrow tab is clicked.
function qbrBuildRefDrawer(host, dd, open, onToggle){
var old=host.querySelector(':scope > .qbr-ref-drawer'); if(old) old.parentNode.removeChild(old);
var node=document.createElement('div'); node.className='qbr-ref-drawer'+(open?' open':'');
node.innerHTML='<button class="qbr-ref-tab" type="button" title="Supporting detail \u2014 the data behind this slide" aria-label="Supporting detail">'+(open?'\u203A':'\u2039')+'</button>'
  +'<div class="qbr-ref-body"><div class="qbr-ref-hd">Supporting detail</div>'+qbrRefPanelsHtml(dd)+'</div>';
host.appendChild(node);
var tab=node.querySelector('.qbr-ref-tab');
if(tab) tab.addEventListener('click', function(e){ e.stopPropagation(); var nowOpen=!node.classList.contains('open'); node.classList.toggle('open', nowOpen); tab.innerHTML=nowOpen?'\u203A':'\u2039'; if(typeof onToggle==='function') onToggle(nowOpen); });
return node;
}
