function qbrFitCanvas(){ const wrap=document.getElementById('qbr-canvas-wrap'), cv=document.getElementById('qbr-slide-canvas'); if(!wrap||!cv) return;
const stage=document.getElementById('qbr-canvas-stage');
// The app shell is height:100vh but sits below a fixed suite header, so it overshoots the fold by a
// few dozen px — enough to clip the bottom notes pane. Cap the studio to its visible height (maxHeight
// bounds even a flex:1 child); keyed to innerHeight (not element size) so there's no resize loop.
var _studio=document.querySelector('#view-qbr .qbr-studio');
if(_studio){ var _avail=(window.innerHeight||0) - _studio.getBoundingClientRect().top - 4; if(_avail>220) _studio.style.maxHeight=_avail+'px'; }
let availW=860, availH=480;
if(stage){ const cs=getComputedStyle(stage); const padX=(parseFloat(cs.paddingLeft)||0)+(parseFloat(cs.paddingRight)||0); const padY=(parseFloat(cs.paddingTop)||0)+(parseFloat(cs.paddingBottom)||0); availW=Math.max(200, stage.clientWidth-padX); availH=Math.max(140, stage.clientHeight-padY);
  // The stage can LAY OUT taller than the visible viewport (fixed chrome above it clips at 100vh),
  // which would scale the slide to a height that renders below the fold. Fit to what's actually visible.
  var visH=(window.innerHeight||0) - stage.getBoundingClientRect().top - padY - 10;
  if(visH>140) availH=Math.min(availH, visH);
}
availW=Math.min(availW, 1100);
const s=Math.min(availW/960, availH/540);
cv.style.transformOrigin='top left'; cv.style.transform='scale('+s+')';
wrap.style.width=(960*s)+'px'; wrap.style.height=(540*s)+'px'; wrap.style.maxWidth='none'; }
