 +'<button class="qbr-notes-tab'+(tab==='notes'?' on':'')+'" data-notes-tab="notes" title="Talking points for this slide">Speaker notes</button>'
 +'<button class="qbr-notes-tab'+(tab==='data'?' on':'')+'" data-notes-tab="data" title="A plain-English read of what stands out in this slide’s data">Data context</button>'
 +'</div><div class="qbr-notes-tools">';
if(open && tab==='notes'){ h+='<div class="qbr-seg qbr-seg-sm"><button class="qbr-seg-btn'+(!auto?' on':'')+'" data-notesmode="manual">Write my own</button><button class="qbr-seg-btn'+(auto?' on':'')+'" data-notesmode="auto">\u2728 Auto</button></div>'; }
h+='<button class="qbr-notes-collapse" data-notes-collapse title="'+(open?'Hide panel':'Show panel')+'">'+(open?'\u25BE':'\u25B8')+'</button></div></div>';
