h+='<div class="qbr-color-row" style="margin-top:8px;"><label>Fit</label><select class="qbr-sel" id="qbr-img-fit" style="flex:1.5;"><option value="contain"'+((el.fit||'contain')==='contain'?' selected':'')+'>Fit (contain)</option><option value="cover"'+(el.fit==='cover'?' selected':'')+'>Fill (cover)</option></select></div>';
if(el.src){ h+='<div class="qbr-fmt-row" style="margin-top:8px;"><button class="qbr-mini-btn" id="qbr-img-crop" style="flex:1;">\u2702\ufe0e Crop</button>'+(el.crop?'<button class="qbr-mini-btn" id="qbr-img-uncrop" style="flex:1;">Reset crop</button>':'')+'</div>'; }
h+='<div class="qbr-rb-note">Logos, photos, anything you’d paste into PowerPoint. Embeds into the .pptx natively.</div></div>';
