var w=_qbrGenProgEl();
w.innerHTML='<div class="qbr-gp-head"><div class="qbr-gp-spin"></div><div class="qbr-gp-title">Generating decks</div></div>'
+'<div class="qbr-gp-sub" id="qbr-gp-sub">Preparing '+total+' deck'+(total===1?'':'s')+'\u2026 you can keep working.</div>'
+'<div class="qbr-gp-track"><div class="qbr-gp-fill" id="qbr-gp-fill"></div></div>';
