w.innerHTML='<div class="qbr-gp-head"><svg class="qbr-gp-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg><div class="qbr-gp-title">'+count+' deck'+(count===1?'':'s')+' ready</div></div>'
+'<div class="qbr-gp-sub">Native PowerPoint, bundled into one zip.</div>'
+'<div class="qbr-gp-actions"><button class="qbr-gp-btn qbr-gp-btn-ghost" id="qbr-gp-dismiss">Dismiss</button><button class="qbr-gp-btn qbr-gp-btn-primary" id="qbr-gp-view">View decks</button></div>';
var dz=document.getElementById('qbr-gp-dismiss'); if(dz) dz.addEventListener('click', qbrGenProgHide);
var vw=document.getElementById('qbr-gp-view'); if(vw) vw.addEventListener('click', function(){ qbrGenProgHide(); if(_qbrGenResult) qbrShowGenResult(_qbrGenResult.files, _qbrGenResult.exc, _qbrGenResult.scs); });
