function showView(id){
const _scroller = document.querySelector('.content');
if(_scroller) _scroller.scrollTop = 0;
try { document.body.setAttribute('data-active-view', id); } catch(_){}
if(id!=='mydashboard'){ try{ if(typeof dashSetActive==='function' && dashActiveId()!=='mydash') dashSetActive('mydash'); if(typeof MYDASH_XF!=='undefined') MYDASH_XF=null; }catch(_){} }
navItems.forEach(function(item){item.classList.toggle('active',item.dataset.view===id);});
var _actNav=document.querySelector('.nav-subitem[data-view="'+id+'"]'); if(_actNav){ var _c=_actNav.closest('.nav-cat'); if(_c) _c.classList.remove('collapsed'); }
views.forEach(function(v){v.classList.toggle('active',v.id==='view-'+id);});
// Always-rerender whitelist: views whose data can change between visits (other tabs add to
// these, or the user toggles state that affects them). For those we re-run the renderer
// every visit; for others we keep the first-time-only gate to avoid wasteful work.
const alwaysRerender = {mydashboard:1,demographics:1,teamdashboard:1,savedreports:1,scheduler:1,connectors:1,premium:1,actionqueue:1,home:1,ai:1,qbr:1,quickreports:1,trust:1};
const isFirstVisit = !rendered[id];
if(isFirstVisit || alwaysRerender[id]){
if(id==='home')renderHome();
else if(id==='ai')renderAI();
else if(id==='onprem')renderOnprem();
else if(id==='offprem')renderOffprem();
else if(id==='chains')renderChains();
else if(id==='dist')renderDist();
else if(id==='actionqueue')renderActionQueue();
else if(id==='demographics')renderDemographics();
else if(id==='builder'){setupReportBuilder();}
else if(id==='quickreports'){renderQuickReports();}
else if(id==='mydashboard'){renderMyDashboard();}
else if(id==='teamdashboard'){renderTeamDashboard();}
else if(id==='savedreports'){renderSavedReports();}
else if(id==='scheduler'){renderScheduler();}
else if(id==='qbr'){renderQBR();}
else if(id==='overlay'){setupOverlayView();}
else if(id==='connectors'){wireConnectorsView();}
else if(id==='qa'){setupQA();}
else if(id==='headroom'){setupHeadroom();renderHeadroom();}
else if(id==='dealtiming')renderDealTiming();
else if(id==='radar')renderRadar();
else if(id==='position'){renderBackbar();renderShelf();}
else if(id==='anchor')renderAnchor();
else if(id==='acceleration')renderAcceleration();
else if(id==='waterfall')renderWaterfall();
else if(id==='clustering')renderClustering();
else if(id==='premium')renderPremium();
else if(id==='quality')renderQuality();
else if(id==='leadlag')renderLeadLag();
else if(id==='trajectories')renderTrajectories();
else if(id==='metrics')renderMetrics();
else if(id==='trust'){ if(typeof rbRenderTrustCertified==='function') rbRenderTrustCertified(); }
if(isFirstVisit){
rendered[id]=true;
setTimeout(function(){ wireExportButtons(); wireActionSurfaceForView(id); renderTeamActivity(id); }, 50);
}
}
if(typeof appUpdateToolSwitch==='function') appUpdateToolSwitch(id);
if(typeof appDecorateClickables==='function') appDecorateClickables();
}

navItems.forEach(function(item){
// Accessibility: these are <a> without href acting as buttons — give them real
// button semantics and keyboard operability (Enter/Space), not click-only.
if(!item.getAttribute('role')) item.setAttribute('role','button');
if(!item.hasAttribute('tabindex')) item.setAttribute('tabindex','0');
item.addEventListener('click',function(e){
e.preventDefault();
showView(item.dataset.view);
});
item.addEventListener('keydown',function(e){
if(e.key==='Enter'||e.key===' '||e.key==='Spacebar'){
e.preventDefault();
showView(item.dataset.view);
}
});
});
(function(){ const sw=document.getElementById('app-toolswitch'); if(sw){ sw.querySelectorAll('[data-toolview]').forEach(function(b){ b.addEventListener('click',function(){ showView(b.dataset.toolview); }); }); } })();

if(typeof appSetupKeyboard==='function') appSetupKeyboard();
showView('quickreports');

// Global filter panel
function gfpOpen(){
document.getElementById('gfp').classList.add('open');
document.getElementById('gfp-backdrop').classList.add('open');
}
function gfpClose(){
document.getElementById('gfp').classList.remove('open');
document.getElementById('gfp-backdrop').classList.remove('open');
}
function gfpTab(name){
document.querySelectorAll('.gfp-tab').forEach(function(t){t.classList.toggle('active',t.dataset.tab===name);});
document.querySelectorAll('.gfp-tab-panel').forEach(function(p){p.style.display=p.dataset.tab===name?'block':'none';});
}
function gfpSection(el){
el.parentElement.classList.toggle('expanded');
}
function gfpApply(){
gfpClose();
const toast=document.createElement('div');
toast.className='gfp-applied-toast';
toast.textContent='Filters applied — refreshing views';
document.body.appendChild(toast);
setTimeout(function(){toast.remove();},1600);
}
document.getElementById('gfp-open-btn').addEventListener('click',gfpOpen);
document.getElementById('gfp-backdrop').addEventListener('click',gfpClose);
document.getElementById('gfp-cancel-btn').addEventListener('click',gfpClose);
document.getElementById('gfp-apply-btn').addEventListener('click',gfpApply);
document.querySelectorAll('.gfp-tab').forEach(function(t){t.addEventListener('click',function(){gfpTab(this.dataset.tab);});});
document.querySelectorAll('.gfp-section-head').forEach(function(h){h.addEventListener('click',function(){gfpSection(this);});});
document.addEventListener('keydown',function(e){if(e.key==='Escape')gfpClose();});

// Sidebar collapse / expand
(function(){
const app = document.querySelector('.app');
const collapseBtn = document.getElementById('sidebar-collapse');
const expandBtn = document.getElementById('sidebar-expand');
if(!app) return;
function setCollapsed(c){
app.classList.toggle('sidebar-collapsed', !!c);
try { localStorage.setItem('rb_sidebar_collapsed', c ? '1' : '0'); } catch(_){}
}
// Restore preference
try { if(localStorage.getItem('rb_sidebar_collapsed') === '1') setCollapsed(true); } catch(_){}
if(collapseBtn) collapseBtn.addEventListener('click', function(){ setCollapsed(true); });
if(expandBtn) expandBtn.addEventListener('click', function(){ setCollapsed(false); });
// Keyboard shortcut: Ctrl/Cmd + B
document.addEventListener('keydown', function(e){
if((e.ctrlKey || e.metaKey) && (e.key === 'b' || e.key === 'B')){
e.preventDefault();
setCollapsed(!app.classList.contains('sidebar-collapsed'));
}
});
})();
