function qaFindAnswer(query){
const match = QA_KB.find(function(kb){return kb.match.test(query);});
if(match) return match.answer();
// Fall through to the smart synthesizer — handles any free-form question
// by extracting intent + computing real values from the synthetic data engine
try {
const intent = qaParseIntent(query);
if(intent && intent.understood){
return qaSynthesizeAnswer(intent, query);
}
} catch(err) {
console.warn('qaSynthesize failed:', err);
}
// Final fallback — only if intent parser couldn't extract anything actionable
return {
para: '<p>I would need more specifics to give you a precise answer. Try naming a category (whiskey, tequila, vodka, rum, RTD), a region (Northeast, South, Midwest, West), or a channel (on-prem, off-prem, chain, casual dining). For example: <em>"How is tequila doing in the Southeast?"</em> or <em>"Show me whiskey headroom in chain accounts."</em></p>',
chart: null,
followups: ['How is tequila growing nationally?','Show me RTD headroom in chains','Compare whiskey premium vs standard'],
_needAnalyst: true   // the deterministic parser couldn't classify it → hand to the live Claude analyst
};
}

// =====================================================================
// Smart Q&A intent parser
// Extracts: measure, category, region, channel, account_class, comparison, question_type
// Returns: { understood: bool, measure, category, region, channel, ... }
// Built specifically for natural distributor questions like:
//   "How is whiskey doing in Texas?"
//   "Where is tequila growing fastest?"
//   "Show me vodka headroom in chain accounts"
//   "Compare whiskey premium vs standard"
// =====================================================================
function qaParseIntent(query){
const q = (query || '').toLowerCase().trim();
if(q.length === 0) return { understood: false };
const intent = { understood: false, query: q };

// MEASURE — what is being asked about
const measurePatterns = [
{re: /\b(growth|growing|grow|trend|trending|trajectory|momentum|performing|how is|how are|how's)\b/, key: 'volume_growth'},
{re: /\b(revenue|sales|dollar|dollars|monetiz)/, key: 'revenue_growth'},
{re: /\b(pod|distribution|distribute|distributing|points of distribution)\b/, key: 'pod_growth'},
{re: /\b(headroom|opportunity|gap|upside|untapped|realization gap|realized vs)/, key: 'headroom_pt'},
{re: /\b(velocity|throughput|depth|rate of sale|cs per|cases per|per account)/, key: 'velocity_idx'},
{re: /\b(premium index|premium idx|premiumization|premium tier|premium share)/, key: 'premium_idx'},
{re: /\b(realiz|achievable)/, key: 'realized_pct'},
{re: /\b(share of|share index|market share|category share)/, key: 'share_pct'},
{re: /\b(account count|accounts sold|active accounts|carrying base)/, key: 'account_count'}
];
for(const p of measurePatterns){
if(p.re.test(q)){ intent.measure = p.key; break; }
}

// CATEGORY
const categoryPatterns = [
{re: /\b(bourbon|rye|american whisk(ey|y)|scotch|irish|whisk(ey|y))\b/, key: 'whiskey'},
{re: /\b(tequila|mezcal|agave)\b/, key: 'tequila'},
{re: /\bvodka\b/, key: 'vodka'},
{re: /\brum\b/, key: 'rum'},
{re: /\b(rtd|ready.to.drink|ready to drink|canned cocktail|hard seltzer|seltzer)\b/, key: 'rtd'},
{re: /\bwine\b/, key: 'wine'},
{re: /\b(spirits|all spirits|spirit category)\b/, key: 'all_spirits'}
];
for(const p of categoryPatterns){
if(p.re.test(q)){ intent.category = p.key; break; }
}

// REGION — Census regions + division aliases + state names + key state abbreviations
const regionPatterns = [
{re: /\b(northeast|new england|mid.atlantic|north east|ne us)\b/, key: 'northeast'},
{re: /\b(southeast|south atlantic|south east|deep south|south)\b/, key: 'south'},
{re: /\b(midwest|mid.west|north central|great lakes|heartland)\b/, key: 'midwest'},
{re: /\b(west coast|pacific|west|mountain|rockies)\b/, key: 'west'}
];
for(const p of regionPatterns){
if(p.re.test(q)){ intent.region = p.key; break; }
}

// STATE — common states that distributors actually ask about
const statePatterns = {
'texas': 'TX', 'california': 'CA', 'florida': 'FL', 'new york': 'NY', 'illinois': 'IL',
'pennsylvania': 'PA', 'ohio': 'OH', 'georgia': 'GA', 'north carolina': 'NC', 'michigan': 'MI',
'new jersey': 'NJ', 'virginia': 'VA', 'washington': 'WA', 'massachusetts': 'MA', 'arizona': 'AZ',
'tennessee': 'TN', 'indiana': 'IN', 'missouri': 'MO', 'maryland': 'MD', 'colorado': 'CO',
'wisconsin': 'WI', 'minnesota': 'MN', 'kentucky': 'KY', 'oregon': 'OR', 'louisiana': 'LA',
'nevada': 'NV', 'connecticut': 'CT', 'south carolina': 'SC'
};
for(const name in statePatterns){
if(q.indexOf(name) >= 0){ intent.state = statePatterns[name]; break; }
}

// CHANNEL — primary on/off prem split
const channelPatterns = [
{re: /\b(on.prem|on premise|on-prem|bar|restaurant|hospitality|hotel|casino|fine dining|casual dining|country club|full.bar)\b/, key: 'onprem'},
{re: /\b(off.prem|off premise|off-prem|retail|grocery|liquor store|chain|independent)\b/, key: 'offprem'}
];
for(const p of channelPatterns){
if(p.re.test(q)){ intent.channel = p.key; break; }
}

// ACCOUNT CLASS — premium vs standard split
if(/\b(a.class|class a|premium tier|premium account|high.end|top tier)/.test(q)) intent.account_class = 'A';
else if(/\b(b.class|class b|mid.tier)/.test(q)) intent.account_class = 'B';
else if(/\b(c.class|class c|standard|standard tier|mainstream)/.test(q)) intent.account_class = 'C';
else if(/\b(d.class|class d|value tier|low tier)/.test(q)) intent.account_class = 'D';

// QUESTION TYPE — affects how the answer is framed
if(/\b(where|which (region|state|channel|market))\b/.test(q)) intent.qtype = 'where';
else if(/\b(why|reason|cause|what's driving|what is driving|driver)\b/.test(q)) intent.qtype = 'why';
else if(/\b(compare|comparison|vs\b|versus|against)\b/.test(q)) intent.qtype = 'compare';
else if(/\b(how much|how many|what.*(value|number|growth|share))/.test(q)) intent.qtype = 'quantity';
else if(/\b(show me|give me|find|list)\b/.test(q)) intent.qtype = 'list';
else intent.qtype = 'general';

// SUPERLATIVE — "fastest growing", "biggest opportunity", "best"
intent.superlative = /\b(fastest|highest|biggest|largest|most|best|strongest|leading|top)\b/.test(q) ? 'high'
: /\b(slowest|lowest|smallest|least|worst|weakest|declining)\b/.test(q) ? 'low' : null;

// Treat as understood if we extracted EITHER a measure OR a category — those carry intent
intent.understood = !!(intent.measure || intent.category || intent.region || intent.state || intent.channel);
// Sensible defaults: if no measure, default to growth (most-asked metric)
if(intent.understood && !intent.measure) intent.measure = 'volume_growth';
// If no category and superlative is "where" or "fastest", default to all_spirits
if(intent.understood && !intent.category) intent.category = 'all_spirits';
return intent;
}

// =====================================================================
// Smart Q&A answer synthesizer
// Uses rbComputeMeasure to pull synthetic values matching the parsed intent,
// builds stat cards + paragraph (with drill-through qa-cite spans) + chart + followups
// =====================================================================
function qaSynthesizeAnswer(intent, originalQuery){
const dims = {};
if(intent.category) dims.category = intent.category;
if(intent.region) dims.region = intent.region;
if(intent.state) dims.state = intent.state;
if(intent.channel) dims.channel = intent.channel;
if(intent.account_class) dims.account_class = intent.account_class;
const measureKey = intent.measure;
const measureDef = RB_FIELDS.measures.find(function(m){return m.key === measureKey;}) || {label: measureKey, unit: '', signed: true};

// Helper: format a value with the measure's unit + sign convention
function fmt(val){
if(val === '—' || val === null || val === undefined) return '—';
const n = parseFloat(String(val).replace(/[+%,pt\s]/g, ''));
if(isNaN(n)) return String(val);
const sign = (measureDef.signed && n > 0) ? '+' : '';
const unit = measureDef.unit || (measureKey.indexOf('_idx') >= 0 ? '' : '');
return sign + n.toFixed(Math.abs(n) >= 10 ? 1 : 1) + unit;
}
// Helper: pull a value at a given dim combination
function pull(extraDims){
const merged = Object.assign({}, dims, extraDims || {});
const raw = rbComputeMeasure(measureKey, merged);
return { raw: raw, formatted: fmt(raw), num: parseFloat(String(raw).replace(/[+%,pt\s]/g, '')) || 0 };
}
function cite(val, extraDims){
const merged = Object.assign({}, dims, extraDims || {});
return '<span class="qa-cite" data-measure="' + measureKey + '" data-dims=\'' + JSON.stringify(merged).replace(/'/g, '&#39;') + '\' data-value="' + val.formatted + '">' + val.formatted + '</span>';
}

// Pull the headline value (what was asked) + comparison baselines
const focus = pull();
const usAvg = pull({region: undefined, state: undefined, channel: undefined, account_class: undefined});
const usAvgClean = pull({}); // No region/state filter
const delta = focus.num - usAvgClean.num;

// Build stat cards depending on intent type
const stats = [];
const focusLabel = qaBuildScopeLabel(intent, measureDef);
stats.push({label: focusLabel, value: focus.formatted, delta: delta !== 0 ? (delta > 0 ? '+' : '') + delta.toFixed(1) + (measureDef.unit || 'pt') + ' vs US avg' : 'matches US avg', deltaCls: Math.abs(delta) < 0.5 ? '' : (delta > 0 ? 'pos' : 'neg'), measureKey: measureKey, dims: Object.assign({}, dims)});
stats.push({label: 'US ' + (intent.category || 'category') + ' avg', value: usAvgClean.formatted, delta: 'baseline', deltaCls: '', measureKey: measureKey, dims: {category: intent.category}});

// Comparison stat — pick the most natural cross-cut
if(intent.region || intent.state){
// Compare to other regions in the same category
const cmpRegions = ['northeast','south','midwest','west'].filter(function(r){return r !== intent.region;});
let best = null, bestNum = -Infinity, worst = null, worstNum = Infinity;
cmpRegions.forEach(function(r){
const v = pull({region: r, state: undefined});
if(v.num > bestNum){ bestNum = v.num; best = {r: r, v: v}; }
if(v.num < worstNum){ worstNum = v.num; worst = {r: r, v: v}; }
});
if(best){
const rLabel = ({northeast:'Northeast', south:'South', midwest:'Midwest', west:'West'})[best.r];
stats.push({label: 'Strongest peer region: ' + rLabel, value: best.v.formatted, delta: (bestNum - focus.num).toFixed(1) + (measureDef.unit || 'pt') + ' vs ' + (intent.region || intent.state), deltaCls: bestNum > focus.num ? 'pos' : 'neg', measureKey: measureKey, dims: {category: intent.category, region: best.r}});
}
} else {
// No geo specified — show sub-channel split
const subA = pull({channel: 'onprem'});
const subB = pull({channel: 'offprem'});
stats.push({label: 'On-premise', value: subA.formatted, delta: (subA.num - subB.num >= 0 ? '+' : '') + (subA.num - subB.num).toFixed(1) + (measureDef.unit || 'pt') + ' vs off-prem', deltaCls: subA.num > subB.num ? 'pos' : 'neg', measureKey: measureKey, dims: Object.assign({}, dims, {channel: 'onprem'})});
stats.push({label: 'Off-premise', value: subB.formatted, delta: subB.num > subA.num ? '+' + (subB.num - subA.num).toFixed(1) + (measureDef.unit || 'pt') : '', deltaCls: subB.num > subA.num ? 'pos' : '', measureKey: measureKey, dims: Object.assign({}, dims, {channel: 'offprem'})});
}

// If we have only 3 stats so far and there's headroom to compute, add a tier-class stat
if(stats.length < 4 && !intent.account_class){
const premium = pull({account_class: 'A'});
const standard = pull({account_class: 'C'});
const tierGap = premium.num - standard.num;
stats.push({label: 'A-class premium tier', value: premium.formatted, delta: (tierGap > 0 ? '+' : '') + tierGap.toFixed(1) + (measureDef.unit || 'pt') + ' vs C-class', deltaCls: tierGap > 0.5 ? 'pos' : (tierGap < -0.5 ? 'neg' : ''), measureKey: measureKey, dims: Object.assign({}, dims, {account_class: 'A'})});
}

// Trim to 4 stats
while(stats.length > 4) stats.pop();

// Compose the paragraph — uses the actual focus value + comparison
const catName = qaCatLabel(intent.category);
const scopeName = qaBuildScopeLabel(intent, measureDef, true);
const measureName = (measureDef.label || measureKey).toLowerCase();
let para = '<p>' + qaCapitalize(scopeName) + ' is at ' + cite(focus) + ' on ' + measureName + ' in the latest R12';
if(Math.abs(delta) >= 0.5){
para += ', ' + (delta > 0 ? 'ahead of' : 'behind') + ' the US ' + catName + ' average of ' + cite(usAvgClean, {region: undefined, state: undefined, channel: undefined, account_class: undefined}) + ' by <strong>' + Math.abs(delta).toFixed(1) + (measureDef.unit || 'pt') + '</strong>.';
} else {
para += ', roughly matching the US ' + catName + ' average of ' + cite(usAvgClean, {region: undefined, state: undefined, channel: undefined, account_class: undefined}) + '.';
}
para += '</p>';

// Second paragraph — adds context based on intent type
if(intent.qtype === 'where' || intent.superlative === 'high'){
// "Where" question — surface the geographic peak
const allRegions = ['northeast','south','midwest','west'];
let peak = null, peakVal = -Infinity;
allRegions.forEach(function(r){
const v = pull({region: r, state: undefined});
if(v.num > peakVal){ peakVal = v.num; peak = {r: r, v: v}; }
});
if(peak){
const peakLabel = ({northeast:'Northeast', south:'South', midwest:'Midwest', west:'West'})[peak.r];
para += '<p>The peak is in the <strong>' + peakLabel + '</strong> at ' + cite(peak.v, {region: peak.r, state: undefined}) + '. ';
if(intent.region && peak.r !== intent.region){
para += 'That region is running <strong>' + (peakVal - focus.num).toFixed(1) + (measureDef.unit || 'pt') + ' higher</strong> than the area you asked about. ';
}
para += 'Drill any cell above to see the underlying account-class split + sub-channel decomposition.</p>';
}
} else if(intent.qtype === 'why' || intent.qtype === 'compare'){
// "Why" or "compare" — surface the on/off-prem split
const onPrem = pull({channel: 'onprem'});
const offPrem = pull({channel: 'offprem'});
const channelGap = onPrem.num - offPrem.num;
para += '<p>Channel decomposition: on-prem is at ' + cite(onPrem, {channel: 'onprem'}) + ' versus off-prem at ' + cite(offPrem, {channel: 'offprem'}) + ', a <strong>' + Math.abs(channelGap).toFixed(1) + (measureDef.unit || 'pt') + '</strong> gap. ';
if(channelGap > 1){
para += 'On-premise is leading the trend — typical for premiumizing categories where the bar/restaurant channel signals consumer migration before retail follows.';
} else if(channelGap < -1){
para += 'Off-premise is leading — meaning retail is the engine, with on-prem still catching up.';
} else {
para += 'Both channels are moving in lockstep, signaling category-wide momentum rather than channel-specific drift.';
}
para += '</p>';
} else {
// General — surface the account-class split
const premium = pull({account_class: 'A'});
const standard = pull({account_class: 'C'});
const tierGap = premium.num - standard.num;
para += '<p>Premium vs standard tier within this cut: A-class accounts ' + cite(premium, {account_class: 'A'}) + ' versus C-class ' + cite(standard, {account_class: 'C'}) + '. ';
if(tierGap > 1.5){
para += 'A clear premiumization signal — A-class is outperforming C-class by <strong>' + tierGap.toFixed(1) + (measureDef.unit || 'pt') + '</strong>, meaning consumer trade-up is the dominant dynamic.';
} else if(tierGap < -1.5){
para += 'Inverted premium signal — C-class is actually outperforming A-class. The category is deflating in this segment.';
} else {
para += 'Roughly flat across tiers, so the trend is broad-based rather than premiumization-driven.';
}
para += '</p>';
}

// Build the dynamic chart — small SVG bar chart showing the relevant decomposition
const chart = qaSynthesizeChart(intent, dims, measureKey, measureDef, focus, fmt);

// Generate sensible followups
const followups = qaSynthesizeFollowups(intent);

return { stats: stats, para: para, chart: chart, chartKey: null, followups: followups };
}

function qaCatLabel(key){
return ({whiskey:'whiskey', tequila:'tequila', vodka:'vodka', rum:'rum', rtd:'RTD', wine:'wine', all_spirits:'spirits'})[key] || key || 'category';
}
function qaCapitalize(s){
return s.charAt(0).toUpperCase() + s.slice(1);
}
function qaBuildScopeLabel(intent, measureDef, narrative){
let parts = [];
if(intent.account_class) parts.push(intent.account_class + '-class');
if(intent.category) parts.push(qaCatLabel(intent.category));
if(intent.channel) parts.push(intent.channel === 'onprem' ? 'on-premise' : 'off-premise');
if(intent.state) {
const stateLbl = Object.keys({texas:'TX',california:'CA',florida:'FL',georgia:'GA'}).reduce(function(acc, k){ return acc; }, null);
parts.push('in ' + intent.state);
}
else if(intent.region) parts.push('in the ' + ({northeast:'Northeast', south:'South', midwest:'Midwest', west:'West'})[intent.region]);
const label = parts.join(' ');
if(narrative) return label || (qaCatLabel(intent.category) || 'category');
return label.length > 0 ? label : 'Category total';
}

function qaSynthesizeChart(intent, dims, measureKey, measureDef, focus, fmt){
// Decide the right chart cut. Priority:
//  1. If region/state set → show regional comparison
//  2. If channel set → show sub-channel breakdown
//  3. Else → show category comparison
const W = 480, H = 110;
const padL = 32, padR = 8, padT = 22, padB = 28;
const chartW = W - padL - padR;
const chartH = H - padT - padB;
function bar(items, title){
const maxAbs = Math.max.apply(null, items.map(function(d){return Math.abs(d.num);}).concat([1]));
const yZero = padT + chartH * 0.65;
const barW = (chartW / items.length) * 0.7;
const gap = (chartW / items.length) * 0.3;
let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;font-family:-apple-system,sans-serif;">';
svg += '<text x="0" y="14" font-size="10.5" font-weight="700" fill="#5f6368">' + title + '</text>';
svg += '<line x1="' + padL + '" y1="' + yZero + '" x2="' + (W - padR) + '" y2="' + yZero + '" stroke="#d4d4d8" stroke-width="1"/>';
items.forEach(function(d, i){
const x = padL + i * (chartW / items.length) + gap / 2;
const h = Math.abs(d.num) / maxAbs * (chartH * 0.55);
const y = d.num >= 0 ? yZero - h : yZero;
const fill = d.num >= 1 ? '#2e7d57' : (d.num <= -1 ? '#b8402b' : (d.highlight ? '#4E79A7' : '#6b7280'));
const opac = d.highlight ? '1' : '0.85';
svg += '<rect x="' + x + '" y="' + y + '" width="' + barW + '" height="' + Math.max(2, h) + '" fill="' + fill + '" opacity="' + opac + '" rx="2"/>';
// Value label
const labelY = d.num >= 0 ? y - 4 : y + h + 11;
svg += '<text x="' + (x + barW / 2) + '" y="' + labelY + '" text-anchor="middle" font-size="9.5" font-weight="700" style="fill:var(--dash-accent,#4E79A7)">' + d.label + '</text>';
// Category label
svg += '<text x="' + (x + barW / 2) + '" y="' + (H - 8) + '" text-anchor="middle" font-size="9" fill="#5f6368">' + d.name + '</text>';
});
svg += '</svg>';
return svg;
}
let items = [];
let title = '';
if(intent.region || intent.state){
title = (measureDef.label || measureKey) + ' \u00b7 regional comparison';
['northeast','south','midwest','west'].forEach(function(r){
const v = rbComputeMeasure(measureKey, Object.assign({}, dims, {region: r, state: undefined}));
const num = parseFloat(String(v).replace(/[+%,pt\s]/g, '')) || 0;
items.push({name: ({northeast:'NE', south:'South', midwest:'MW', west:'West'})[r], label: fmt(v), num: num, highlight: r === intent.region});
});
} else if(intent.channel){
title = (measureDef.label || measureKey) + ' \u00b7 channel split';
['onprem','offprem'].forEach(function(ch){
const v = rbComputeMeasure(measureKey, Object.assign({}, dims, {channel: ch}));
const num = parseFloat(String(v).replace(/[+%,pt\s]/g, '')) || 0;
items.push({name: ch === 'onprem' ? 'On-prem' : 'Off-prem', label: fmt(v), num: num, highlight: ch === intent.channel});
});
} else if(intent.account_class){
title = (measureDef.label || measureKey) + ' \u00b7 by account class';
['A','B','C','D'].forEach(function(cls){
const v = rbComputeMeasure(measureKey, Object.assign({}, dims, {account_class: cls}));
const num = parseFloat(String(v).replace(/[+%,pt\s]/g, '')) || 0;
items.push({name: 'Class ' + cls, label: fmt(v), num: num, highlight: cls === intent.account_class});
});
} else {
// Cross-category comparison
title = (measureDef.label || measureKey) + ' \u00b7 by category';
['whiskey','tequila','vodka','rum','rtd'].forEach(function(cat){
const v = rbComputeMeasure(measureKey, Object.assign({}, dims, {category: cat}));
const num = parseFloat(String(v).replace(/[+%,pt\s]/g, '')) || 0;
items.push({name: ({whiskey:'Whisk',tequila:'Tequila',vodka:'Vodka',rum:'Rum',rtd:'RTD'})[cat], label: fmt(v), num: num, highlight: cat === intent.category});
});
}
return bar(items, title);
}

function qaSynthesizeFollowups(intent){
const fups = [];
const catLbl = qaCatLabel(intent.category);
if(intent.region || intent.state){
fups.push('How does ' + catLbl + ' look in other regions?');
fups.push('What\'s driving the headroom in ' + catLbl + '?');
fups.push('Show me ' + catLbl + ' by account class');
} else if(intent.channel){
fups.push('How is ' + catLbl + ' doing in the opposite channel?');
fups.push('Where is ' + catLbl + ' headroom highest?');
fups.push('Compare to other categories in the same channel');
} else if(intent.account_class){
fups.push('How does ' + intent.account_class + '-class compare across categories?');
fups.push('Show me the channel split for this segment');
fups.push('What\'s the headroom in ' + intent.account_class + '-class ' + catLbl + '?');
} else if(intent.category && intent.category !== 'all_spirits'){
fups.push('Where is ' + catLbl + ' strongest geographically?');
fups.push('What\'s the on-prem vs off-prem split?');
fups.push('Compare ' + catLbl + ' to ' + (intent.category === 'whiskey' ? 'tequila' : 'whiskey'));
} else {
fups.push('Show me growth by category');
fups.push('Where is the biggest opportunity right now?');
fups.push('What categories are declining?');
}
return fups.slice(0, 3);
}

